#[derive(Default)]
struct CapturedOutputInner {
    stdout: Vec<u8>,
    stderr: Vec<u8>,
}

#[derive(Clone)]
// TODO-HUMAN-REVIEW(PR-172): Review cross-thread captured-output ownership.
pub(crate) struct CapturedOutput {
    inner: Arc<Mutex<CapturedOutputInner>>,
    identities: Arc<CapturedPipeIdentities>,
}

#[cfg(test)]
impl Default for CapturedOutput {
    fn default() -> Self {
        Self::try_new().expect("prepare test capture identities")
    }
}

impl CapturedOutput {
    pub(crate) fn try_new() -> std::io::Result<Self> {
        // Root setup calls this before consuming the image or initializing the
        // Tool. Failure never publishes partial output or a fallback identity.
        let identities = Arc::new(CapturedPipeIdentities::try_new()?);
        Ok(Self {
            inner: Arc::new(Mutex::new(CapturedOutputInner::default())),
            identities,
        })
    }

    fn metadata(&self) -> CaptureMetadata {
        self.identities.metadata()
    }

    pub(crate) fn take(&mut self) -> (Vec<u8>, Vec<u8>) {
        let mut inner = self.inner.lock().expect("captured output lock poisoned");
        (
            std::mem::take(&mut inner.stdout),
            std::mem::take(&mut inner.stderr),
        )
    }

    fn append(&self, stderr: bool, bytes: &[u8]) -> bool {
        let mut inner = self.inner.lock().expect("captured output lock poisoned");
        let destination = if stderr {
            &mut inner.stderr
        } else {
            &mut inner.stdout
        };
        if destination
            .len()
            .checked_add(bytes.len())
            .is_none_or(|length| length > MAX_CAPTURED_OUTPUT)
        {
            return false;
        }
        destination.extend_from_slice(bytes);
        true
    }
}

pub(crate) enum ProcessAction {
    Fork {
        child_pid: i32,
        child_stack: Option<u64>,
        // AUTONOMOUS-BOT-IMPLEMENTED: Model legacy process-clone TID bookkeeping.
        // TODO-HUMAN-REVIEW(#89): Review clone TID timing and clear-pointer lifecycle.
        parent_tid: Option<u64>,
        child_tid: Option<u64>,
        clear_child_tid: Option<u64>,
        // TODO-HUMAN-REVIEW(PR-92): Review CLONE_CLEAR_SIGHAND child state.
        clear_sighand: bool,
        // `vfork` and its clone variants share the parent's address space until exec.
        share_address_space: bool,
    },
    // TODO-HUMAN-REVIEW(PR-132): Review cooperative single-vCPU thread cloning.
    Thread {
        child_tid: i32,
        child_stack: u64,
        parent_tid: Option<u64>,
        child_tid_address: Option<u64>,
        clear_child_tid: Option<u64>,
        tls: Option<u64>,
    },
    Exec {
        executable_path: std::path::PathBuf,
        executable_file: Option<Arc<std::fs::File>>,
        image: Vec<u8>,
        argv: Vec<String>,
        envp: Vec<String>,
    },
}

impl ProcessAction {
    pub(crate) fn returns_to_original_image(&self) -> bool {
        match self {
            Self::Fork { .. } | Self::Thread { .. } => true,
            Self::Exec { .. } => false,
        }
    }
}

