// TODO-HUMAN-REVIEW(#54): Confirm guest-fd ownership and pipe2 flag boundaries.
// TODO-HUMAN-REVIEW(PR-136): Review pipe object-identity allocation and cleanup.
fn pipe2(
    memory: &mut GuestMemory,
    state: &mut LoadedStaticElf,
    address: u64,
    raw_flags: u64,
) -> i64 {
    let flags = raw_flags as libc::c_int;
    let allowed_flags = libc::O_CLOEXEC | libc::O_DIRECT | libc::O_NONBLOCK | libc::O_EXCL;
    if flags & !allowed_flags != 0 {
        return negative_errno(libc::EINVAL);
    }
    let mut host_fds = [-1; 2];
    // Host descriptors are internal implementation details and must never leak through a
    // supervisor exec. Guest close-on-exec state will need separate modeling when KVM gains exec.
    let host_flags = flags | libc::O_CLOEXEC;
    // SAFETY: host_fds has room for both descriptors and flags were validated above.
    if unsafe { libc::pipe2(host_fds.as_mut_ptr(), host_flags) } != 0 {
        return io_error(std::io::Error::last_os_error());
    }
    // SAFETY: pipe2 returned two new owned descriptors on success.
    let read_end = unsafe { std::fs::File::from_raw_fd(host_fds[0]) };
    // SAFETY: pipe2 returned two new owned descriptors on success.
    let write_end = unsafe { std::fs::File::from_raw_fd(host_fds[1]) };
    insert_file_pair(
        memory,
        state,
        address,
        [read_end, write_end],
        flags & libc::O_CLOEXEC != 0,
    )
}

// TODO-HUMAN-REVIEW(PR-205): Review paired guest-descriptor rollback and identity cleanup.
fn insert_file_pair(
    memory: &mut GuestMemory,
    state: &mut LoadedStaticElf,
    address: u64,
    files: [std::fs::File; 2],
    close_on_exec: bool,
) -> i64 {
    let [first_file, second_file] = files.map(|file| state.file_retirement.stage(file));
    let first_fd = insert_file_with_flags(state, first_file.into_file(), close_on_exec, None);
    if first_fd < 0 {
        return first_fd;
    }
    let second_fd = insert_file_with_flags(state, second_file.into_file(), close_on_exec, None);
    if second_fd < 0 {
        remove_inserted_file(state, first_fd as libc::c_int);
        return second_fd;
    }

    let fds = [first_fd as libc::c_int, second_fd as libc::c_int];
    let mut bytes = [0; std::mem::size_of::<[libc::c_int; 2]>()];
    bytes[..std::mem::size_of::<libc::c_int>()].copy_from_slice(&fds[0].to_ne_bytes());
    bytes[std::mem::size_of::<libc::c_int>()..].copy_from_slice(&fds[1].to_ne_bytes());
    if memory.user().write(address, &bytes).is_err() {
        for fd in fds {
            remove_inserted_file(state, fd);
        }
        return negative_errno(libc::EFAULT);
    }
    0
}

fn remove_inserted_file(state: &mut LoadedStaticElf, fd: libc::c_int) {
    let retired = state.remove_file(fd);
    state.file_retirement.retire(retired);
    state.fd_object_inodes.remove(&fd);
    state.cloexec_fds.remove(&fd);
    cleanup_fd_object_inodes(state);
}

#[derive(Clone, Copy)]
#[repr(C)]
struct Pselect6SigmaskArg {
    sigmask: u64,
    sigsetsize: u64,
}

/// Reproduces Linux's non-mutating `pselect6` argument-validation boundary.
///
/// Detcore owns deterministic retries, virtual deadlines, and temporary signal
/// masks. The KVM executor cannot yet service a valid probe without crossing
/// that scheduler boundary, so it fails closed with `ENOSYS` only after every
/// access and value check that Linux performs before selecting descriptors.
/// In particular, this lets Detcore's deliberately malformed-timeout probe
/// distinguish an inaccessible outer wrapper from an inaccessible inner mask.
/// This helper never calls host `pselect`, installs a host signal mask, writes
/// guest memory, or mutates executor state.
fn pselect6_validation_preflight(memory: &GuestMemory, args: &[u64; 6]) -> i64 {
    // Linux first copies the complete outer { sigmask, sigsetsize } wrapper.
    let sigmask_argument = if args[5] == 0 {
        None
    } else {
        match read_guest_struct::<Pselect6SigmaskArg>(memory, args[5]) {
            Ok(argument) => Some(argument),
            Err(error) => return error,
        }
    };

    // do_pselect reads and validates the timeout before inspecting the inner
    // signal-mask pointer or size.
    if args[4] != 0 {
        let timeout = match read_guest_struct::<libc::timespec>(memory, args[4]) {
            Ok(timeout) => timeout,
            Err(error) => return error,
        };
        if timeout.tv_sec < 0 || !(0..1_000_000_000).contains(&timeout.tv_nsec) {
            return negative_errno(libc::EINVAL);
        }
    }

    // set_user_sigmask ignores sigsetsize when the inner pointer is NULL.
    if let Some(argument) = sigmask_argument
        && argument.sigmask != 0
    {
        if argument.sigsetsize != KERNEL_SIGSET_SIZE as u64 {
            return negative_errno(libc::EINVAL);
        }
        let mut mask = [0; KERNEL_SIGSET_SIZE];
        if memory.user().read(argument.sigmask, &mut mask).is_err() {
            return negative_errno(libc::EFAULT);
        }
    }

    // The raw syscall argument is an `int`; Linux observes its low 32 bits.
    let nfds = args[0] as libc::c_int;
    if nfds < 0 {
        return negative_errno(libc::EINVAL);
    }

    // Linux clamps this copy to the live fd-table capacity, which KVM does not
    // model yet. One machine word is exact for every fresh Linux table and for
    // Detcore's internal pselect probes. Refuse larger calls before touching
    // their fd sets rather than over-reading up to GUEST_NOFILE_LIMIT and
    // manufacturing an EFAULT that Linux would not return.
    if nfds > u64::BITS as libc::c_int {
        return negative_errno(libc::ENOSYS);
    }
    let word_count = (nfds as usize).div_ceil(u64::BITS as usize);
    let byte_length = word_count * std::mem::size_of::<u64>();
    let mut fd_set = vec![0; byte_length];
    if byte_length != 0 {
        for address in &args[1..4] {
            if *address != 0 && memory.user().read(*address, &mut fd_set).is_err() {
                return negative_errno(libc::EFAULT);
            }
        }
    }

    negative_errno(libc::ENOSYS)
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-205): Review deterministic select readiness and timeout semantics.
fn select(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let Ok(nfds) = libc::c_int::try_from(args[0]) else {
        return negative_errno(libc::EINVAL);
    };
    if !(0..=GUEST_NOFILE_LIMIT).contains(&nfds) {
        return negative_errno(libc::EINVAL);
    }
    let word_count = (nfds as usize).div_ceil(u64::BITS as usize);
    let byte_length = word_count * std::mem::size_of::<u64>();
    if byte_length > MAX_HOST_IO {
        return negative_errno(libc::EINVAL);
    }

    let mut sets = [Vec::new(), Vec::new(), Vec::new()];
    for (set, address) in sets.iter_mut().zip(&args[1..4]) {
        *set = vec![0_u64; word_count];
        if *address != 0 && byte_length != 0 {
            // SAFETY: the vector contains initialized u64 words and the byte
            // view is exactly bounded to its allocation.
            let bytes = unsafe {
                std::slice::from_raw_parts_mut(set.as_mut_ptr().cast::<u8>(), byte_length)
            };
            if memory.user().read(*address, bytes).is_err() {
                return negative_errno(libc::EFAULT);
            }
        }
    }

    if args[4] != 0 {
        let timeout = match read_guest_struct::<libc::timeval>(memory, args[4]) {
            Ok(timeout) => timeout,
            Err(error) => return error,
        };
        if timeout.tv_sec < 0 || !(0..1_000_000).contains(&timeout.tv_usec) {
            return negative_errno(libc::EINVAL);
        }
    }

    let mut poll_fds = Vec::new();
    let mut requested = Vec::new();
    for guest_fd in 0..nfds {
        let membership = sets.each_ref().map(|set| fd_set_contains(set, guest_fd));
        if !membership.into_iter().any(|present| present) {
            continue;
        }
        let Some(host_fd) = host_fd(state, guest_fd) else {
            return negative_errno(libc::EBADF);
        };
        let virtual_signalfd = signalfd_mask(state, guest_fd).is_some();
        let mut events = 0;
        if membership[0] {
            events |= libc::POLLIN;
        }
        if membership[1] && !virtual_signalfd {
            events |= libc::POLLOUT;
        }
        if membership[2] && !virtual_signalfd {
            events |= libc::POLLPRI;
        }
        poll_fds.push(libc::pollfd {
            fd: host_fd,
            events,
            revents: 0,
        });
        requested.push((guest_fd, membership, virtual_signalfd));
    }

    // Detcore owns guest time. Preserve readiness that exists now without
    // blocking the supervisor on host wall time for a guest timeout.
    let ready = unsafe { libc::poll(poll_fds.as_mut_ptr(), poll_fds.len() as libc::nfds_t, 0) };
    if ready < 0 {
        return io_error(std::io::Error::last_os_error());
    }

    let mut ready_sets = [
        vec![0_u64; word_count],
        vec![0_u64; word_count],
        vec![0_u64; word_count],
    ];
    let mut ready_count = 0_i64;
    for (poll_fd, (guest_fd, membership, virtual_signalfd)) in poll_fds.iter().zip(requested) {
        let ready = if virtual_signalfd {
            // The host eventfd is only a private carrier for virtual signal
            // readiness. A Linux signalfd is read-only and never reports the
            // eventfd's unconditional POLLOUT readiness.
            [poll_fd.revents & libc::POLLIN != 0, false, false]
        } else {
            [
                poll_fd.revents & (libc::POLLIN | libc::POLLHUP | libc::POLLERR) != 0,
                poll_fd.revents & (libc::POLLOUT | libc::POLLERR) != 0,
                poll_fd.revents & libc::POLLPRI != 0,
            ]
        };
        for index in 0..ready_sets.len() {
            if membership[index] && ready[index] {
                fd_set_insert(&mut ready_sets[index], guest_fd);
                ready_count += 1;
            }
        }
    }

    for (address, ready_set) in args[1..4].iter().zip(&ready_sets) {
        if *address == 0 || byte_length == 0 {
            continue;
        }
        // SAFETY: the vector contains initialized u64 words and the byte view
        // is exactly bounded to its allocation.
        let bytes =
            unsafe { std::slice::from_raw_parts(ready_set.as_ptr().cast::<u8>(), byte_length) };
        if memory.user().write(*address, bytes).is_err() {
            return negative_errno(libc::EFAULT);
        }
    }
    if args[4] != 0 {
        let timeout = libc::timeval {
            tv_sec: 0,
            tv_usec: 0,
        };
        if write_struct(memory, args[4], &timeout) != 0 {
            return negative_errno(libc::EFAULT);
        }
    }
    ready_count
}

fn fd_set_contains(set: &[u64], fd: libc::c_int) -> bool {
    let fd = fd as usize;
    set.get(fd / u64::BITS as usize)
        .is_some_and(|word| word & (1_u64 << (fd % u64::BITS as usize)) != 0)
}

fn fd_set_insert(set: &mut [u64], fd: libc::c_int) {
    let fd = fd as usize;
    set[fd / u64::BITS as usize] |= 1_u64 << (fd % u64::BITS as usize);
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-92): Review guest descriptor translation and deterministic nonblocking poll semantics.
fn poll(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    poll_with_timeout(memory, state, args, 0)
}

// TODO-HUMAN-REVIEW(PR-172): Review host-blocking KVM ppoll timeout and signal-mask semantics.
fn ppoll(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    // Validate the timeout up front for every ppoll, mirroring detcore's
    // handle_ppoll (hermit detcore/src/syscalls/io.rs:824-828): the kernel
    // rejects a malformed timeout (bad pointer or out-of-range nanoseconds)
    // regardless of whether a signal mask is present.
    let timeout = if args[2] == 0 {
        -1
    } else {
        let timeout = match read_guest_struct::<libc::timespec>(memory, args[2]) {
            Ok(timeout) => timeout,
            Err(error) => return error,
        };
        if timeout.tv_sec < 0 || !(0..1_000_000_000).contains(&timeout.tv_nsec) {
            return negative_errno(libc::EINVAL);
        }
        let milliseconds = (timeout.tv_sec as u128)
            .saturating_mul(1_000)
            .saturating_add((timeout.tv_nsec as u128).div_ceil(1_000_000));
        milliseconds.min(libc::c_int::MAX as u128) as libc::c_int
    };
    if args[3] != 0 {
        if args[4] != KERNEL_SIGSET_SIZE as u64 {
            return negative_errno(libc::EINVAL);
        }
        // The kernel copies the signal mask out of user space (copy_from_user)
        // before it polls, so an unreadable mask pointer must fault with EFAULT
        // rather than return a readiness result. Detcore's golden
        // prepare_ppoll_probe does the same via read_value(signal_mask)? (hermit
        // detcore/src/syscalls/io.rs:874-892). Observe the mask here to
        // reproduce that fault semantics; its value is deliberately not applied
        // across the wait (see the note below), but a bogus pointer can never be
        // serviced as ready.
        let mut signal_mask = [0u8; KERNEL_SIGSET_SIZE];
        if memory.user().read(args[3], &mut signal_mask).is_err() {
            return negative_errno(libc::EFAULT);
        }
        // A masked ppoll mirrors detcore's handle_internal_ppoll (hermit
        // detcore/src/syscalls/io.rs:922-939): a zero-timeout probe can honor a
        // temporary signal mask atomically, but keeping the mask active across a
        // parked wait would require scheduler-level pending-signal state. So
        // probe non-blocking and fail closed with ENOSYS only when the call
        // would have blocked (nothing ready). The mask cannot affect an
        // instantaneous poll, so a plain non-blocking poll reproduces the kernel
        // result: a ready descriptor returns its count exactly as the unmasked
        // path would, and a poll/read error propagates unchanged.
        let ready = poll_with_timeout(memory, state, args, 0);
        if ready == 0 {
            return negative_errno(libc::ENOSYS);
        }
        return ready;
    }
    poll_with_timeout(memory, state, args, timeout)
}

fn poll_with_timeout(
    memory: &mut GuestMemory,
    state: &LoadedStaticElf,
    args: &[u64; 6],
    timeout: libc::c_int,
) -> i64 {
    // Both Linux syscall entrypoints declare nfds as unsigned int, even on
    // x86-64 where the raw syscall register and host nfds_t are wider.
    let count = args[1] as u32 as usize;
    if count > GUEST_NOFILE_LIMIT as usize {
        return negative_errno(libc::EINVAL);
    }
    let Some(byte_length) = count.checked_mul(std::mem::size_of::<libc::pollfd>()) else {
        return negative_errno(libc::EINVAL);
    };
    if byte_length > MAX_HOST_IO {
        return negative_errno(libc::EINVAL);
    }

    let mut poll_fds = vec![
        libc::pollfd {
            fd: -1,
            events: 0,
            revents: 0,
        };
        count
    ];
    {
        // SAFETY: poll_fds is initialized plain ABI data and the byte view is
        // exactly bounded to the vector allocation.
        let bytes = unsafe {
            std::slice::from_raw_parts_mut(poll_fds.as_mut_ptr().cast::<u8>(), byte_length)
        };
        if memory.user().read(args[0], bytes).is_err() {
            return negative_errno(libc::EFAULT);
        }
    }

    let guest_fds = poll_fds
        .iter()
        .map(|poll_fd| poll_fd.fd)
        .collect::<Vec<_>>();
    let guest_events = poll_fds
        .iter()
        .map(|poll_fd| poll_fd.events)
        .collect::<Vec<_>>();
    let virtual_signalfds = guest_fds
        .iter()
        .map(|fd| *fd >= 0 && signalfd_mask(state, *fd).is_some())
        .collect::<Vec<_>>();
    let virtual_signalfd_wait = timeout != 0 && virtual_signalfds.iter().any(|present| *present);
    let mut invalid = vec![false; count];
    for (index, poll_fd) in poll_fds.iter_mut().enumerate() {
        poll_fd.revents = 0;
        if poll_fd.fd < 0 {
            continue;
        }
        if virtual_signalfds[index] {
            // A signalfd exposes only the carrier's synthetic readable state.
            poll_fd.events &= libc::POLLIN;
        }
        match host_fd(state, poll_fd.fd) {
            Some(host_fd) => poll_fd.fd = host_fd,
            None => {
                poll_fd.fd = -1;
                invalid[index] = true;
            }
        }
    }

    // SYS_poll remains nonblocking for deterministic personality calls. The
    // concurrent KVM ppoll path may block in the host so QEMU's root event loop
    // can wait for worker eventfds without spinning on virtual clock reads.
    // A virtual signalfd is different: readiness is guest state, so probe it
    // without blocking and fail closed below only when no event is ready.
    // A missing guest descriptor is already ready with POLLNVAL. Still probe
    // the other descriptors, but never wait for them before reporting it.
    let host_timeout = if virtual_signalfd_wait || invalid.iter().any(|invalid| *invalid) {
        0
    } else {
        timeout
    };
    let ready = unsafe { libc::poll(poll_fds.as_mut_ptr(), count as libc::nfds_t, host_timeout) };
    if ready < 0 {
        return io_error(std::io::Error::last_os_error());
    }
    for (index, poll_fd) in poll_fds.iter_mut().enumerate() {
        poll_fd.fd = guest_fds[index];
        poll_fd.events = guest_events[index];
        if invalid[index] {
            poll_fd.revents = libc::POLLNVAL;
        } else if virtual_signalfds[index] {
            poll_fd.revents &= libc::POLLIN;
        }
    }
    let ready_count = poll_fds
        .iter()
        .filter(|poll_fd| poll_fd.revents != 0)
        .count() as libc::c_int;
    if virtual_signalfd_wait && ready_count == 0 {
        // poll/ppoll ignores O_NONBLOCK. A real wait here would park the host
        // vCPU outside Detcore's scheduler and race readiness publication.
        // Refuse before changing the guest pollfd array.
        return negative_errno(libc::ENOSYS);
    }
    // Linux writes only revents, one field at a time in array order. The
    // caller may change fd/events while a host-owned wait is blocked, and a
    // later output fault must retain earlier successful field stores.
    for (index, poll_fd) in poll_fds.iter().enumerate() {
        let offset = index * std::mem::size_of::<libc::pollfd>()
            + std::mem::offset_of!(libc::pollfd, revents);
        let Some(address) = args[0].checked_add(offset as u64) else {
            return negative_errno(libc::EFAULT);
        };
        if memory
            .user()
            .put_user_i16(address, poll_fd.revents)
            .is_err()
        {
            return negative_errno(libc::EFAULT);
        }
    }
    i64::from(ready_count)
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-92): Review deterministic event-loop and AF_UNIX syscall boundaries.
fn epoll_create1(state: &mut LoadedStaticElf, raw_flags: u64) -> i64 {
    let flags = raw_flags as libc::c_int;
    if flags & !libc::EPOLL_CLOEXEC != 0 {
        return negative_errno(libc::EINVAL);
    }
    // Keep the supervisor descriptor private even when the guest did not ask
    // for close-on-exec; guest descriptor flags are modeled separately.
    let host_fd = unsafe { libc::epoll_create1(libc::EPOLL_CLOEXEC) };
    if host_fd < 0 {
        return io_error(std::io::Error::last_os_error());
    }
    // SAFETY: epoll_create1 returned a new owned descriptor.
    let file = unsafe { std::fs::File::from_raw_fd(host_fd) };
    insert_file_with_flags(state, file, flags & libc::EPOLL_CLOEXEC != 0, None)
}

// TODO-HUMAN-REVIEW(PR-92): Review this KVM compatibility implementation.
fn epoll_ctl(memory: &GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let Some(epoll_fd) = host_fd(state, args[0] as libc::c_int) else {
        return negative_errno(libc::EBADF);
    };
    let Some(target_fd) = host_fd(state, args[2] as libc::c_int) else {
        return negative_errno(libc::EBADF);
    };
    let operation = args[1] as libc::c_int;
    let mut event = if operation == libc::EPOLL_CTL_DEL {
        libc::epoll_event { events: 0, u64: 0 }
    } else {
        match read_guest_struct::<libc::epoll_event>(memory, args[3]) {
            Ok(event) => event,
            Err(error) => return error,
        }
    };
    if matches!(operation, libc::EPOLL_CTL_ADD | libc::EPOLL_CTL_MOD)
        && signalfd_mask(state, args[2] as libc::c_int).is_some()
    {
        // Otherwise a blocking ppoll of this epoll descriptor could wait on
        // virtual signal readiness without carrying signalfd metadata itself.
        return negative_errno(libc::ENOSYS);
    }
    // SAFETY: both descriptors were translated from live guest descriptors;
    // event is initialized and Linux validates the requested operation.
    zero_or_errno(unsafe { libc::epoll_ctl(epoll_fd, operation, target_fd, &mut event) })
}

// TODO-HUMAN-REVIEW(PR-92): Review this KVM compatibility implementation.
fn epoll_wait(
    memory: &mut GuestMemory,
    state: &LoadedStaticElf,
    args: &[u64; 6],
    pwait: bool,
) -> i64 {
    if pwait && args[4] != 0 {
        if args[5] != KERNEL_SIGSET_SIZE as u64 {
            return negative_errno(libc::EINVAL);
        }
        let mut signal_mask = [0; KERNEL_SIGSET_SIZE];
        if memory.user().read(args[4], &mut signal_mask).is_err() {
            return negative_errno(libc::EFAULT);
        }
    }
    let Some(epoll_fd) = host_fd(state, args[0] as libc::c_int) else {
        return negative_errno(libc::EBADF);
    };
    let Ok(max_events) = libc::c_int::try_from(args[2]) else {
        return negative_errno(libc::EINVAL);
    };
    if max_events <= 0 {
        return negative_errno(libc::EINVAL);
    }
    let Ok(count) = usize::try_from(max_events) else {
        return negative_errno(libc::EINVAL);
    };
    let Some(byte_length) = count.checked_mul(std::mem::size_of::<libc::epoll_event>()) else {
        return negative_errno(libc::EINVAL);
    };
    if byte_length > MAX_HOST_IO {
        return negative_errno(libc::EINVAL);
    }
    let mut events = vec![libc::epoll_event { events: 0, u64: 0 }; count];
    // A real-time host timeout is not a deterministic guest clock. Readiness
    // for already-available descriptor events is preserved with a zero timeout.
    // Guest signal masks are modeled in guest state and must not alter the
    // supervisor thread. With a zero timeout there is no guest blocking window.
    // SAFETY: the event array is writable for max_events entries.
    let ready = unsafe { libc::epoll_wait(epoll_fd, events.as_mut_ptr(), max_events, 0) };
    if ready < 0 {
        return io_error(std::io::Error::last_os_error());
    }
    let ready = ready as usize;
    if ready == 0 {
        return 0;
    }
    let bytes = unsafe {
        std::slice::from_raw_parts(
            events.as_ptr().cast::<u8>(),
            ready * std::mem::size_of::<libc::epoll_event>(),
        )
    };
    match memory.user().write(args[1], bytes) {
        Ok(()) => ready as i64,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

// TODO-HUMAN-REVIEW(PR-92): Review this KVM compatibility implementation.
fn eventfd2(state: &mut LoadedStaticElf, initial: u64, raw_flags: u64) -> i64 {
    let flags = raw_flags as libc::c_int;
    let allowed = libc::EFD_CLOEXEC | libc::EFD_NONBLOCK | libc::EFD_SEMAPHORE;
    if flags & !allowed != 0 || initial > u64::from(u32::MAX) {
        return negative_errno(libc::EINVAL);
    }
    let host_fd = unsafe { libc::eventfd(initial as libc::c_uint, flags | libc::EFD_CLOEXEC) };
    if host_fd < 0 {
        return io_error(std::io::Error::last_os_error());
    }
    // SAFETY: eventfd returned a new owned descriptor.
    let file = unsafe { std::fs::File::from_raw_fd(host_fd) };
    insert_file_with_flags(state, file, flags & libc::EFD_CLOEXEC != 0, None)
}

fn set_signalfd_ready(file: &std::fs::File, ready: bool) -> Result<(), i64> {
    let mut poll_fd = libc::pollfd {
        fd: file.as_raw_fd(),
        events: libc::POLLIN,
        revents: 0,
    };
    // SAFETY: poll_fd points to one initialized descriptor and timeout zero
    // never blocks the supervisor.
    let poll_result = unsafe { libc::poll(&mut poll_fd, 1, 0) };
    if poll_result < 0 {
        return Err(io_error(std::io::Error::last_os_error()));
    }
    if poll_result > 0 && poll_fd.revents & libc::POLLIN != 0 {
        let mut counter = 0u64;
        // SAFETY: counter is writable and eventfd reads exactly one u64.
        if unsafe {
            libc::read(
                file.as_raw_fd(),
                std::ptr::from_mut(&mut counter).cast::<libc::c_void>(),
                std::mem::size_of::<u64>(),
            )
        } < 0
        {
            return Err(io_error(std::io::Error::last_os_error()));
        }
    }
    if ready {
        let counter = 1u64;
        // SAFETY: counter is readable and eventfd writes exactly one u64.
        if unsafe {
            libc::write(
                file.as_raw_fd(),
                std::ptr::from_ref(&counter).cast::<libc::c_void>(),
                std::mem::size_of::<u64>(),
            )
        } < 0
        {
            return Err(io_error(std::io::Error::last_os_error()));
        }
    }
    Ok(())
}

// TODO-HUMAN-REVIEW(PR-235): Review virtual signalfd creation and mask updates.
fn signalfd(
    memory: &GuestMemory,
    state: &mut LoadedStaticElf,
    args: &[u64; 6],
    raw_flags: u64,
) -> i64 {
    let _retirement = state.file_retirement.hold();
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    if args[2] != KERNEL_SIGSET_SIZE as u64 {
        return negative_errno(libc::EINVAL);
    }
    let mut mask = match read_guest_bytes::<KERNEL_SIGSET_SIZE>(memory, args[1]) {
        Ok(mask) => KernelSigset::from_bytes(mask),
        Err(error) => return error,
    };
    mask.clear_unmaskable();
    let Ok(flags) = libc::c_int::try_from(raw_flags) else {
        return negative_errno(libc::EINVAL);
    };
    let allowed = libc::SFD_CLOEXEC | libc::SFD_NONBLOCK;
    if flags & !allowed != 0 {
        return negative_errno(libc::EINVAL);
    }

    let requested_fd = args[0] as libc::c_int;
    if requested_fd == -1 && flags & libc::SFD_NONBLOCK == 0 {
        return negative_errno(libc::ENOSYS);
    }

    let update_aliases = if requested_fd != -1 {
        if flags != 0 {
            return negative_errno(libc::EINVAL);
        }
        let process_signals = state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(description) = process_signals.signalfd_masks.get(&requested_fd).cloned() else {
            return negative_errno(libc::EINVAL);
        };
        if !state.files.contains_key(&requested_fd) {
            return negative_errno(libc::EINVAL);
        }
        // A signalfd mask belongs to the open file description. Descriptor
        // aliases share this exact Arc, while independently created signalfds
        // receive distinct Arcs even when their masks happen to be equal.
        Some(
            process_signals
                .signalfd_masks
                .iter()
                .filter_map(|(&fd, candidate)| Arc::ptr_eq(candidate, &description).then_some(fd))
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };

    // One shared eventfd cannot encode per-caller readiness. Signalfd is fully
    // modeled for a single-thread process; setup/update remains refused once a
    // sibling exists, and thread creation is refused while a signalfd is open.
    if state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .has_live_sibling(state.tid, state.pid)
    {
        return negative_errno(libc::ENOSYS);
    }

    if let Some(alias_fds) = update_aliases {
        let ready = {
            let mut process_signals = state
                .process_signals
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let description = Arc::new(mask);
            for &fd in &alias_fds {
                process_signals
                    .signalfd_masks
                    .insert(fd, description.clone());
            }
            let generations = &process_signals.pending_generations;
            state
                .thread_signals
                .lock()
                .pending
                .any_matching(mask, generations)
                || process_signals
                    .shared_pending
                    .any_matching(mask, generations)
        };
        for fd in alias_fds {
            let file = state
                .files
                .get(&fd)
                .expect("signalfd alias disappeared during mask update");
            if let Err(error) = set_signalfd_ready(file, ready) {
                return error;
            }
        }
        return i64::from(requested_fd);
    }

    let (guest_fd, carrier) = if requested_fd == -1 {
        let event_flags = libc::EFD_CLOEXEC
            | if flags & libc::SFD_NONBLOCK != 0 {
                libc::EFD_NONBLOCK
            } else {
                0
            };
        // SAFETY: eventfd validates its bounded flags and returns a new owned fd.
        let host_fd = unsafe { libc::eventfd(0, event_flags) };
        if host_fd < 0 {
            return io_error(std::io::Error::last_os_error());
        }
        // SAFETY: eventfd returned a new owned descriptor.
        let file = unsafe { std::fs::File::from_raw_fd(host_fd) };
        // Stage the only extra host descriptor before either guest-table or
        // signal-state insertion. Failure leaves no guest-visible descriptor.
        let carrier = match crate::signal::SignalFdCarrier::pin_eventfd(&file) {
            Ok(carrier) => carrier,
            Err(error) => {
                state.file_retirement.retire([file]);
                return io_error(error);
            }
        };
        let guest_fd = insert_file_with_flags(state, file, flags & libc::SFD_CLOEXEC != 0, None);
        if guest_fd < 0 {
            return guest_fd;
        }
        (guest_fd as libc::c_int, carrier)
    } else {
        unreachable!("existing signalfd updates return above")
    };

    let ready = {
        let mut process_signals = state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        process_signals.signalfd_carriers.insert(guest_fd, carrier);
        process_signals
            .signalfd_masks
            .insert(guest_fd, Arc::new(mask));
        let generations = &process_signals.pending_generations;
        state
            .thread_signals
            .lock()
            .pending
            .any_matching(mask, generations)
            || process_signals
                .shared_pending
                .any_matching(mask, generations)
    };
    let file = state
        .files
        .get(&guest_fd)
        .expect("virtual signalfd disappeared after insertion");
    match set_signalfd_ready(file, ready) {
        Ok(()) => i64::from(guest_fd),
        Err(error) => error,
    }
}

fn queue_signal_event(
    state: &mut LoadedStaticElf,
    event: reverie::SignalEvent,
    process_directed: bool,
) -> Result<(), i64> {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    queue_signal_event_locked(state, event, process_directed)
}

fn queue_signal_event_locked(
    state: &mut LoadedStaticElf,
    event: reverie::SignalEvent,
    process_directed: bool,
) -> Result<(), i64> {
    let signal = event.signal();
    let matching_fds = {
        // Queue insertion and disposition-driven generation changes share this
        // lock. A sibling therefore cannot invalidate a private entry between
        // reading its generation and publishing it.
        let mut process_signals = state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let generation = process_signals.pending_generation(signal);
        let inserted = if process_directed {
            process_signals.shared_pending.enqueue(event, generation)
        } else {
            state
                .thread_signals
                .lock()
                .pending
                .enqueue(event, generation)
        }
        .map_err(|errno| negative_errno(errno.into_raw()))?;
        if !inserted {
            return Ok(());
        }

        // Thread-private readiness is exact because the process cannot acquire
        // a sibling while a signalfd description exists (prepare_thread above).
        if process_directed || state.thread_signals.lock().blocked.contains(signal) {
            process_signals
                .signalfd_masks
                .iter()
                .filter_map(|(&fd, mask)| mask.contains(signal).then_some(fd))
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        }
    };
    for fd in matching_fds {
        let Some(file) = state.files.get(&fd) else {
            continue;
        };
        set_signalfd_ready(file, true)?;
    }
    Ok(())
}

const SIGNALFD_RECORD_SIZE: usize = std::mem::size_of::<libc::signalfd_siginfo>();
struct GuestWriteCursor<'a> {
    vectors: &'a [GuestIoVec],
    index: usize,
    offset: usize,
}

impl GuestWriteCursor<'_> {
    fn write(&mut self, memory: &mut GuestMemory, mut bytes: &[u8]) -> Result<(), ()> {
        while !bytes.is_empty() {
            while self.index < self.vectors.len() && self.offset == self.vectors[self.index].length
            {
                self.index += 1;
                self.offset = 0;
            }
            let vector = self.vectors.get(self.index).ok_or(())?;
            let count = bytes.len().min(vector.length - self.offset);
            let address = vector.base + self.offset as u64;
            let writable = memory
                .user()
                .user_writable_prefix(address, count)
                .map_err(|_| ())?;
            if writable != 0 {
                memory
                    .user()
                    .write(address, &bytes[..writable])
                    .map_err(|_| ())?;
                self.offset += writable;
                bytes = &bytes[writable..];
            }
            if writable < count {
                return Err(());
            }
        }
        Ok(())
    }
}

fn encode_signalfd_siginfo(event: reverie::SignalEvent) -> [u8; SIGNALFD_RECORD_SIZE] {
    // SAFETY: signalfd_siginfo is a plain Linux ABI structure and zero is a
    // valid value for every field not populated by this process-local model.
    let mut info = unsafe { std::mem::zeroed::<libc::signalfd_siginfo>() };
    let raw = event.siginfo();
    info.ssi_signo = event.signal() as u32;
    info.ssi_errno = i32::from_ne_bytes(raw[4..8].try_into().expect("siginfo errno"));
    info.ssi_code = i32::from_ne_bytes(raw[8..12].try_into().expect("siginfo code"));
    if info.ssi_code == libc::SI_TIMER {
        info.ssi_tid = u32::from_ne_bytes(raw[16..20].try_into().expect("siginfo timer id"));
        info.ssi_overrun =
            u32::from_ne_bytes(raw[20..24].try_into().expect("siginfo timer overrun"));
        let value = u64::from_ne_bytes(raw[24..32].try_into().expect("siginfo timer value"));
        info.ssi_ptr = value;
        info.ssi_int = value as i32;
    } else if info.ssi_signo == libc::SIGCHLD as u32
        && matches!(
            info.ssi_code,
            libc::CLD_EXITED | libc::CLD_KILLED | libc::CLD_DUMPED
        )
    {
        info.ssi_pid = u32::from_ne_bytes(raw[16..20].try_into().expect("siginfo child pid"));
        info.ssi_uid = u32::from_ne_bytes(raw[20..24].try_into().expect("siginfo child uid"));
        info.ssi_status = i32::from_ne_bytes(raw[24..28].try_into().expect("siginfo child status"));
        info.ssi_utime = u64::from_ne_bytes(raw[32..40].try_into().expect("siginfo child utime"));
        info.ssi_stime = u64::from_ne_bytes(raw[40..48].try_into().expect("siginfo child stime"));
    } else {
        // SI_USER, SI_TKILL, and the accepted SIGALRM/SI_KERNEL producer use
        // the kill-style pid/uid arm of siginfo_t.
        info.ssi_pid = u32::from_ne_bytes(raw[16..20].try_into().expect("siginfo pid"));
        info.ssi_uid = u32::from_ne_bytes(raw[20..24].try_into().expect("siginfo uid"));
    }
    let mut bytes = [0; SIGNALFD_RECORD_SIZE];
    // SAFETY: both objects are live for exactly the size of signalfd_siginfo.
    unsafe {
        std::ptr::copy_nonoverlapping(
            std::ptr::from_ref(&info).cast::<u8>(),
            bytes.as_mut_ptr(),
            SIGNALFD_RECORD_SIZE,
        );
    }
    bytes
}

fn refresh_all_signalfd_readiness_locked(state: &LoadedStaticElf) -> Result<(), i64> {
    refresh_signalfd_readiness_for_signal_locked(state, None)
}

fn refresh_signalfd_readiness_for_signal_locked(
    state: &LoadedStaticElf,
    signal: Option<i32>,
) -> Result<(), i64> {
    refresh_signalfd_readiness_from_files_locked(state, signal, &state.files)
}

fn refresh_signalfd_readiness_from_files_locked(
    state: &LoadedStaticElf,
    signal: Option<i32>,
    files: &std::collections::BTreeMap<i32, std::fs::File>,
) -> Result<(), i64> {
    let readiness = {
        let process_signals = state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        process_signals
            .signalfd_masks
            .iter()
            .filter(|(_, mask)| signal.is_none_or(|signal| mask.contains(signal)))
            .map(|(&fd, mask)| {
                (
                    fd,
                    state
                        .thread_signals
                        .lock()
                        .pending
                        .any_matching(**mask, &process_signals.pending_generations)
                        || process_signals
                            .shared_pending
                            .any_matching(**mask, &process_signals.pending_generations),
                )
            })
            .collect::<Vec<_>>()
    };
    for (fd, ready) in readiness {
        let file = files.get(&fd).ok_or_else(|| negative_errno(libc::EBADF))?;
        set_signalfd_ready(file, ready)?;
    }
    Ok(())
}

/// Requires the process signal transaction. Only dedicated eventfd keepers
/// cross this boundary, so no authoritative file-table acquisition or ordinary
/// last-owner descriptor destruction can block a scheduler-selected return.
fn refresh_signalfd_readiness_from_carriers_locked(
    state: &LoadedStaticElf,
    signal: Option<i32>,
) -> Result<(), i64> {
    let readiness = {
        let process = state
            .process_signals
            .lock()
            .unwrap_or_else(|p| p.into_inner());
        let thread = state.thread_signals.lock();
        process
            .signalfd_masks
            .iter()
            .filter(|(_, mask)| signal.is_none_or(|signal| mask.contains(signal)))
            .map(|(fd, mask)| {
                let carrier = process
                    .signalfd_carriers
                    .get(fd)
                    .cloned()
                    .ok_or_else(|| negative_errno(libc::EBADF))?;
                let ready = thread
                    .pending
                    .any_matching(**mask, &process.pending_generations)
                    || process
                        .shared_pending
                        .any_matching(**mask, &process.pending_generations);
                Ok((carrier, ready))
            })
            .collect::<Result<Vec<_>, i64>>()?
    };
    for (carrier, ready) in readiness {
        set_signalfd_ready(carrier.file(), ready)?;
    }
    Ok(())
}

/// Each real consumer selects under the same lifecycle -> process -> thread locks.
/// Reserve the journal slot and sequence before mutating either pending set.
enum SignalSelection {
    Delivery,
    SignalFd(KernelSigset),
    TimedWait(KernelSigset),
}

#[cfg(test)]
fn take_signal_event(
    state: &mut LoadedStaticElf,
    selection: SignalSelection,
) -> Result<Option<PendingSignal>, reverie::syscalls::Errno> {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    take_signal_event_locked(state, selection)
}

fn take_signal_event_locked(
    state: &mut LoadedStaticElf,
    selection: SignalSelection,
) -> Result<Option<PendingSignal>, reverie::syscalls::Errno> {
    use reverie::syscalls::Errno;
    if let Some(errno) = state.signal_dequeue_failure {
        return Err(errno);
    }
    let lifecycle = state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let mut process = state
        .process_signals
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let mut thread = state.thread_signals.lock();
    let generations = process.pending_generations;
    let blocked = thread.blocked;
    let eligible = |pending: &crate::signal::StandardPendingSignals| match selection {
        SignalSelection::Delivery => pending.any_eligible(blocked, &generations),
        SignalSelection::SignalFd(mask) | SignalSelection::TimedWait(mask) => {
            pending.any_matching(mask, &generations)
        }
    };
    if !eligible(&thread.pending) && !eligible(&process.shared_pending) {
        return Ok(None);
    }
    let identity = if process.dequeue_enabled {
        let admission = (|| {
            let admitted = thread.dequeue_identity.ok_or(Errno::ESRCH)?;
            let task = lifecycle.get(state.tid).ok_or(Errno::ESRCH)?;
            if task.tgid != state.pid
                || admitted.tid.as_raw() != state.tid
                || admitted.process.tgid.as_raw() != state.pid
                || task.generation != admitted.task_generation
                || task.process_generation != admitted.process.generation
            {
                return Err(Errno::ESRCH);
            }
            if process.dequeue_journal.len() == 64 {
                return Err(Errno::EOVERFLOW);
            }
            process
                .dequeue_sequence
                .checked_add(1)
                .ok_or(Errno::EOVERFLOW)?;
            process
                .dequeue_journal
                .try_reserve(1)
                .map_err(|_| Errno::ENOMEM)?;
            Ok(admitted)
        })();
        match admission {
            Ok(admitted) => Some(admitted),
            Err(errno) => {
                // Raw syscall helpers have an i64 interface. Keep the actual
                // internal refusal separately: both injected and unsubscribed
                // execution must flush this typed failure before resuming any
                // Tool or guest with the intermediate raw result. In particular,
                // a partial signalfd read cannot hide a later bookkeeping fault.
                state.signal_dequeue_failure = Some(errno);
                return Err(errno);
            }
        }
    } else {
        None
    };
    let take = |pending: &mut crate::signal::StandardPendingSignals| match selection {
        SignalSelection::Delivery => pending.take_eligible(blocked, &generations),
        SignalSelection::SignalFd(mask) => pending.take_signalfd_matching(mask, &generations),
        SignalSelection::TimedWait(mask) => pending.take_matching(mask, &generations),
    };
    let pending = if let Some(event) = take(&mut thread.pending) {
        PendingSignal {
            event,
            domain: PendingSignalDomain::Thread,
        }
    } else if let Some(event) = take(&mut process.shared_pending) {
        PendingSignal {
            event,
            domain: PendingSignalDomain::Process,
        }
    } else {
        return Ok(None);
    };
    if let Some(identity) = identity {
        process.dequeue_sequence += 1;
        let sequence = process.dequeue_sequence;
        process
            .dequeue_journal
            .push_back(crate::signal::OwnedSignalDequeue {
                owner: identity,
                wake: thread.dequeue_wake.clone(),
                effect: reverie::SignalDequeue {
                    process: identity.process,
                    sequence,
                    consumer: match selection {
                        SignalSelection::Delivery => reverie::SignalConsumer::ReturnToUser,
                        SignalSelection::SignalFd(_) => reverie::SignalConsumer::SignalFd,
                        SignalSelection::TimedWait(_) => reverie::SignalConsumer::SignalTimedWait,
                    },
                    domain: match pending.domain {
                        PendingSignalDomain::Thread => reverie::PendingDomain::Thread,
                        PendingSignalDomain::Process => reverie::PendingDomain::Process,
                    },
                    event: pending.event,
                },
            });
    }
    Ok(Some(pending))
}

fn take_signalfd_event(
    state: &mut LoadedStaticElf,
    mask: KernelSigset,
) -> Result<Option<reverie::SignalEvent>, i64> {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    let pending = take_signal_event_locked(state, SignalSelection::SignalFd(mask))
        .map_err(|errno| -(i64::from(errno.into_raw())))?;
    refresh_all_signalfd_readiness_locked(state)?;
    Ok(pending.map(|pending| pending.event))
}

fn signalfd_read_stream(
    memory: &mut GuestMemory,
    state: &mut LoadedStaticElf,
    fd: libc::c_int,
    vectors: &[GuestIoVec],
    vector_zero_semantics: bool,
    force_nonblocking: bool,
) -> Option<i64> {
    let mask = state
        .process_signals
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .signalfd_masks
        .get(&fd)
        .map(|mask| **mask)?;
    let file = state.files.get(&fd)?;
    if let Err(error) = ensure_read_capable(file).and_then(|()| ensure_readable(file)) {
        return Some(error);
    }
    let raw_fd = file.as_raw_fd();
    let status_flags = match fd_status_flags(raw_fd) {
        Ok(flags) => flags,
        Err(error) => return Some(error),
    };
    if !force_nonblocking && status_flags & libc::O_NONBLOCK == 0 {
        // A host wait would escape Detcore's scheduler and race the readiness
        // publication. Creation and F_SETFL prevent this state; keep the read
        // path fail-closed as a defensive invariant.
        return Some(negative_errno(libc::ENOSYS));
    }
    let total = vectors
        .iter()
        .try_fold(0usize, |total, vector| total.checked_add(vector.length));
    let Some(total) = total else {
        return Some(negative_errno(libc::EINVAL));
    };
    if total == 0 && vector_zero_semantics {
        return Some(0);
    }
    if total < SIGNALFD_RECORD_SIZE {
        return Some(negative_errno(libc::EINVAL));
    }
    let capacity = total / SIGNALFD_RECORD_SIZE;
    let mut cursor = GuestWriteCursor {
        vectors,
        index: 0,
        offset: 0,
    };
    let mut completed = 0usize;
    loop {
        let event = match take_signalfd_event(state, mask) {
            Ok(event) => event,
            Err(error) => {
                return Some(if completed == 0 {
                    error
                } else {
                    (completed * SIGNALFD_RECORD_SIZE) as i64
                });
            }
        };
        let Some(event) = event else {
            if completed != 0 {
                return Some((completed * SIGNALFD_RECORD_SIZE) as i64);
            }
            return Some(negative_errno(libc::EAGAIN));
        };
        let record = encode_signalfd_siginfo(event);
        if cursor.write(memory, &record).is_err() {
            return Some(if completed == 0 {
                negative_errno(libc::EFAULT)
            } else {
                (completed * SIGNALFD_RECORD_SIZE) as i64
            });
        }
        completed += 1;
        if completed == capacity {
            return Some((completed * SIGNALFD_RECORD_SIZE) as i64);
        }
    }
}

// TODO-HUMAN-REVIEW(PR-235): Review virtual signalfd aggregate dequeue semantics.
fn signalfd_read(
    memory: &mut GuestMemory,
    state: &mut LoadedStaticElf,
    fd: libc::c_int,

    address: u64,
    length: usize,
) -> Option<i64> {
    signalfd_read_stream(
        memory,
        state,
        fd,
        &[GuestIoVec {
            base: address,
            length,
        }],
        false,
        false,
    )
}
// TODO-HUMAN-REVIEW(PR-235): Review host-backed KVM timerfd creation semantics.
fn timerfd_create(state: &mut LoadedStaticElf, raw_clock_id: u64, raw_flags: u64) -> i64 {
    let Ok(clock_id) = libc::c_int::try_from(raw_clock_id) else {
        return negative_errno(libc::EINVAL);
    };
    let Ok(flags) = libc::c_int::try_from(raw_flags) else {
        return negative_errno(libc::EINVAL);
    };
    let allowed = libc::TFD_CLOEXEC | libc::TFD_NONBLOCK;
    if flags & !allowed != 0 {
        return negative_errno(libc::EINVAL);
    }

    // Keep the supervisor descriptor private even if the guest did not request
    // CLOEXEC; guest descriptor flags are modeled separately.
    let host_fd = unsafe { libc::timerfd_create(clock_id, flags | libc::TFD_CLOEXEC) };
    if host_fd < 0 {
        return io_error(std::io::Error::last_os_error());
    }
    // SAFETY: timerfd_create returned a new owned descriptor.
    let file = unsafe { std::fs::File::from_raw_fd(host_fd) };
    insert_file_with_flags(state, file, flags & libc::TFD_CLOEXEC != 0, None)
}

