// TODO-HUMAN-REVIEW(PR-227): Review no-xattr removal validation and result.
fn removexattr(memory: &GuestMemory, state: &LoadedStaticElf, number: u64, args: &[u64; 6]) -> i64 {
    match validate_xattr_target_and_name(memory, state, number, args) {
        Ok(()) => negative_errno(libc::ENODATA),
        Err(error) => error,
    }
}

fn brk(memory: &mut GuestMemory, state: &mut LoadedStaticElf, requested: u64) -> i64 {
    if requested == 0 {
        return state.program_break as i64;
    }
    if requested < BOOT_RESERVED_END || requested >= state.brk_limit {
        return state.program_break as i64;
    }
    let previous = state.program_break;
    if requested > previous {
        let Ok(length) = usize::try_from(requested - previous) else {
            return state.program_break as i64;
        };
        let Ok(reservation) = memory.reserve_region(previous, length as u64, RegionKind::Heap)
        else {
            return state.program_break as i64;
        };
        if memory.zero_raw(previous, length).is_err()
            || memory
                .map_user_range(previous, requested - previous, false)
                .is_err()
        {
            return state.program_break as i64;
        }
        reservation.commit();
    } else if requested < previous {
        let Some(unmap_start) = align_up(requested, PAGE_SIZE) else {
            return state.program_break as i64;
        };
        let Some(unmap_end) = align_up(previous, PAGE_SIZE) else {
            return state.program_break as i64;
        };
        if unmap_end > unmap_start
            && memory
                .unmap_user_range(unmap_start, unmap_end - unmap_start)
                .is_err()
        {
            return state.program_break as i64;
        }
    }
    state.program_break = requested;
    requested as i64
}

// TODO-HUMAN-REVIEW(PR-235): Review deterministic hole-first mmap allocation.
fn find_mmap_address(memory: &GuestMemory, state: &LoadedStaticElf, length: u64) -> Option<u64> {
    let next = state.mmap_next.clamp(state.mmap_base, state.mmap_limit);
    memory
        .find_unmapped_user_range(state.mmap_base, next, length)
        .or_else(|| memory.find_unmapped_user_range(next, state.mmap_limit, length))
}

fn mmap(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if args[3] & libc::MAP_ANONYMOUS as u64 == 0
        && let Some(random) = state.random_device_descriptions.get(&(args[4] as i32))
    {
        return random_device_mmap(memory, state, args, random);
    }
    if args[1] == 0 {
        return negative_errno(libc::EINVAL);
    }
    let flags = args[3];
    let is_anonymous = flags & libc::MAP_ANONYMOUS as u64 != 0;
    let is_private = flags & libc::MAP_PRIVATE as u64 != 0;
    let is_shared = flags & libc::MAP_SHARED as u64 != 0;
    let allowed_protection = (libc::PROT_READ | libc::PROT_WRITE | libc::PROT_EXEC) as u64;
    if args[2] & !allowed_protection != 0 {
        return negative_errno(libc::EINVAL);
    }
    if !is_private && !is_shared {
        return negative_errno(libc::EINVAL);
    }

    let Some(length) = align_up(args[1], PAGE_SIZE) else {
        return negative_errno(libc::ENOMEM);
    };
    let fixed = flags & libc::MAP_FIXED as u64 != 0;
    if fixed && !args[0].is_multiple_of(PAGE_SIZE) {
        return negative_errno(libc::EINVAL);
    }
    if !is_anonymous && !args[5].is_multiple_of(PAGE_SIZE) {
        return negative_errno(libc::EINVAL);
    }
    if !is_anonymous && signalfd_mask(state, args[4] as libc::c_int).is_some() {
        // Do not expose the non-mappable eventfd carrier's ESPIPE result.
        return negative_errno(libc::ENODEV);
    }
    // Linux treats a nonfixed address as a hint. This bounded personality uses
    // its deterministic allocator rather than risking an occupied mapping.
    let address = if fixed {
        args[0]
    } else {
        let Some(address) = find_mmap_address(memory, state, length) else {
            return negative_errno(libc::ENOMEM);
        };
        address
    };
    let Some(end) = address.checked_add(length) else {
        return negative_errno(libc::ENOMEM);
    };
    if address < BOOT_RESERVED_END || end > state.mmap_limit {
        return negative_errno(libc::ENOMEM);
    }
    let Ok(length) = usize::try_from(length) else {
        return negative_errno(libc::ENOMEM);
    };
    let file_bytes = if !is_anonymous {
        // Linux syscall argument decoding consumes only the low descriptor word.
        let fd = args[4] as libc::c_int;
        let Some(file) = state.files.get(&fd) else {
            return negative_errno(libc::EBADF);
        };
        if is_shared && args[2] & libc::PROT_WRITE as u64 != 0 {
            let status = match file_status_flags(file) {
                Ok(status) => status,
                Err(error) => return error,
            };
            if status & libc::O_PATH != 0 {
                return negative_errno(libc::EBADF);
            }
            if status & libc::O_ACCMODE != libc::O_RDWR {
                return negative_errno(libc::EACCES);
            }
            // The backend copies file-backed mappings into guest memory rather
            // than asking host mmap to validate the descriptor. Preserve the
            // host's write-seal rejection before creating that writable copy.
            // SAFETY: file owns a live descriptor and F_GET_SEALS has no third argument.
            let seals = unsafe { libc::fcntl(file.as_raw_fd(), libc::F_GET_SEALS) };
            if seals >= 0 && seals & (libc::F_SEAL_WRITE | libc::F_SEAL_FUTURE_WRITE) != 0 {
                return negative_errno(libc::EPERM);
            }
            if seals < 0 {
                let error = std::io::Error::last_os_error();
                if error.raw_os_error() != Some(libc::EINVAL) {
                    return io_error(error);
                }
            }
        }
        let mut bytes = vec![0; length];
        let mut count = 0;
        while count < length {
            #[cfg(test)]
            entry_host_wait_tests::observe_mmap_file_read();
            match file.read_at(&mut bytes[count..], args[5].saturating_add(count as u64)) {
                Ok(0) => break,
                Ok(read) => count += read,
                Err(error) => return io_error(error),
            }
        }
        Some(bytes)
    } else if args[4] as i32 != -1 {
        return negative_errno(libc::EINVAL);
    } else {
        None
    };

    let Ok(reservation) = memory.reserve_region(address, length as u64, RegionKind::Mmap) else {
        return negative_errno(libc::ENOMEM);
    };
    if memory.zero_raw(address, length).is_err() {
        return negative_errno(libc::ENOMEM);
    }
    if let Some(bytes) = file_bytes
        && memory.write_raw(address, &bytes).is_err()
    {
        return negative_errno(libc::EFAULT);
    }
    if memory
        .map_user_permissions(
            address,
            length as u64,
            args[2] != libc::PROT_NONE as u64,
            args[2] & libc::PROT_WRITE as u64 != 0,
        )
        .is_err()
    {
        return negative_errno(libc::ENOMEM);
    }

    reservation.commit();
    if !fixed {
        state.mmap_next = state.mmap_next.max(end);
    }
    address as i64
}

fn munmap(memory: &mut GuestMemory, address: u64, length: u64) -> i64 {
    let Some(length) = align_up(length, PAGE_SIZE) else {
        return negative_errno(libc::EINVAL);
    };
    if address < BOOT_RESERVED_END
        || !address.is_multiple_of(PAGE_SIZE)
        || length == 0
        || !range_is_valid(memory, address, length)
    {
        return negative_errno(libc::EINVAL);
    }
    let Ok(length) = usize::try_from(length) else {
        return negative_errno(libc::EINVAL);
    };
    match memory.zero_raw(address, length) {
        Ok(()) => match memory.unmap_user_range(address, length as u64) {
            Ok(()) => 0,
            Err(_) => negative_errno(libc::EINVAL),
        },
        Err(_) => negative_errno(libc::EINVAL),
    }
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-227): Review in-memory mapping synchronization semantics.
fn msync(memory: &GuestMemory, args: &[u64; 6]) -> i64 {
    let address = args[0];
    let requested_length = args[1];
    let flags = args[2] as libc::c_int;
    let allowed_flags = libc::MS_ASYNC | libc::MS_SYNC | libc::MS_INVALIDATE;
    if !address.is_multiple_of(PAGE_SIZE)
        || flags & !allowed_flags != 0
        || flags & libc::MS_ASYNC != 0 && flags & libc::MS_SYNC != 0
    {
        return negative_errno(libc::EINVAL);
    }
    if requested_length == 0 {
        return 0;
    }
    let Some(length) = align_up(requested_length, PAGE_SIZE) else {
        return negative_errno(libc::ENOMEM);
    };
    if !range_is_valid(memory, address, length) || !memory.user_range_is_mapped(address, length) {
        return negative_errno(libc::ENOMEM);
    }

    // File-backed mappings are deterministic snapshots copied into guest
    // memory by mmap. There is no host page cache to flush, so a valid msync
    // completes once the mapped-range contract above has been checked.
    0
}

// TODO-HUMAN-REVIEW(PR-132): Review KVM mprotect user-copy enforcement.
fn mprotect(memory: &GuestMemory, args: &[u64; 6]) -> i64 {
    let address = args[0];
    let requested_length = args[1];
    let protection = args[2];
    let allowed_protection = (libc::PROT_READ | libc::PROT_WRITE | libc::PROT_EXEC) as u64;
    if !address.is_multiple_of(PAGE_SIZE) || protection & !allowed_protection != 0 {
        return negative_errno(libc::EINVAL);
    }
    if requested_length == 0 {
        return 0;
    }
    let Some(length) = align_up(requested_length, PAGE_SIZE) else {
        return negative_errno(libc::ENOMEM);
    };
    if !range_is_valid(memory, address, length) || !memory.user_range_is_mapped(address, length) {
        return negative_errno(libc::ENOMEM);
    }
    match memory.map_user_permissions(
        address,
        length,
        protection != libc::PROT_NONE as u64,
        protection & libc::PROT_WRITE as u64 != 0,
    ) {
        Ok(()) => 0,
        Err(_) => negative_errno(libc::ENOMEM),
    }
}

fn mremap(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let old_address = args[0];
    let Some(old_length) = align_up(args[1], PAGE_SIZE) else {
        return negative_errno(libc::EINVAL);
    };
    let Some(new_length) = align_up(args[2], PAGE_SIZE) else {
        return negative_errno(libc::ENOMEM);
    };
    let flags = args[3];
    let allowed_flags = (libc::MREMAP_MAYMOVE | libc::MREMAP_FIXED) as u64;
    if old_length == 0
        || new_length == 0
        || !old_address.is_multiple_of(PAGE_SIZE)
        || flags & !allowed_flags != 0
        || flags & libc::MREMAP_FIXED as u64 != 0 && flags & libc::MREMAP_MAYMOVE as u64 == 0
        || !range_is_valid(memory, old_address, old_length)
        || !memory.user_range_is_mapped(old_address, old_length)
    {
        return negative_errno(libc::EINVAL);
    }

    if flags & libc::MREMAP_FIXED as u64 == 0 && new_length <= old_length {
        if new_length < old_length {
            let tail = old_address + new_length;
            let Ok(length) = usize::try_from(old_length - new_length) else {
                return negative_errno(libc::ENOMEM);
            };
            if memory.zero_raw(tail, length).is_err() {
                return negative_errno(libc::EFAULT);
            }
        }
        if memory
            .remap_user_range(old_address, old_length, old_address, new_length)
            .is_err()
        {
            return negative_errno(libc::EFAULT);
        }
        return old_address as i64;
    }

    let old_end = old_address + old_length;
    if flags & libc::MREMAP_FIXED as u64 == 0 {
        let Some(new_end) = old_address.checked_add(new_length) else {
            return negative_errno(libc::ENOMEM);
        };
        let extension_length = new_length - old_length;
        if new_end <= state.mmap_limit
            && memory.find_unmapped_user_range(old_end, new_end, extension_length) == Some(old_end)
        {
            let Ok(extension) = usize::try_from(new_length - old_length) else {
                return negative_errno(libc::ENOMEM);
            };
            let Ok(reservation) = memory.reserve_remap_region(old_end, extension as u64) else {
                return negative_errno(libc::ENOMEM);
            };
            if memory.zero_raw(old_end, extension).is_err() {
                return negative_errno(libc::ENOMEM);
            }
            if memory
                .remap_user_range(old_address, old_length, old_address, new_length)
                .is_err()
            {
                return negative_errno(libc::ENOMEM);
            }
            reservation.commit();
            state.mmap_next = state.mmap_next.max(new_end);
            return old_address as i64;
        }
    }

    if flags & libc::MREMAP_MAYMOVE as u64 == 0 {
        return negative_errno(libc::ENOMEM);
    }
    let destination = if flags & libc::MREMAP_FIXED as u64 != 0 {
        args[4]
    } else {
        let Some(destination) = find_mmap_address(memory, state, new_length) else {
            return negative_errno(libc::ENOMEM);
        };
        destination
    };
    let Some(destination_end) = destination.checked_add(new_length) else {
        return negative_errno(libc::ENOMEM);
    };
    if destination < BOOT_RESERVED_END
        || !destination.is_multiple_of(PAGE_SIZE)
        || destination_end > state.mmap_limit
        || destination < old_end && old_address < destination_end
    {
        return negative_errno(libc::EINVAL);
    }

    let copy_length = old_length.min(new_length);
    let Ok(copy_length) = usize::try_from(copy_length) else {
        return negative_errno(libc::ENOMEM);
    };
    let Ok(old_length_usize) = usize::try_from(old_length) else {
        return negative_errno(libc::ENOMEM);
    };
    let Ok(new_length_usize) = usize::try_from(new_length) else {
        return negative_errno(libc::ENOMEM);
    };
    let Ok(reservation) = memory.reserve_region(destination, new_length, RegionKind::Mmap) else {
        return negative_errno(libc::EFAULT);
    };
    let mut bytes = vec![0; copy_length];
    if memory.read_raw(old_address, &mut bytes).is_err()
        || memory.zero_raw(destination, new_length_usize).is_err()
        || memory.write_raw(destination, &bytes).is_err()
        || memory.zero_raw(old_address, old_length_usize).is_err()
        || memory
            .remap_user_range(old_address, old_length, destination, new_length)
            .is_err()
    {
        return negative_errno(libc::EFAULT);
    }
    reservation.commit();
    if flags & libc::MREMAP_FIXED as u64 == 0 {
        state.mmap_next = state.mmap_next.max(destination_end);
    }
    destination as i64
}

fn validate_range(memory: &GuestMemory, address: u64, length: u64) -> i64 {
    if length == 0 || !range_is_valid(memory, address, length) {
        negative_errno(libc::EINVAL)
    } else {
        0
    }
}

// TODO-HUMAN-REVIEW(PR-145): Review flat guest-memory munlock validation semantics.
fn munlock_guest_range(memory: &GuestMemory, address: u64, length: u64) -> i64 {
    let page_start = address & !(PAGE_SIZE - 1);
    let page_offset = address - page_start;
    let page_length =
        length.wrapping_add(page_offset).wrapping_add(PAGE_SIZE - 1) & !(PAGE_SIZE - 1);
    let page_end = page_start.wrapping_add(page_length);
    if page_end < page_start {
        return negative_errno(libc::EINVAL);
    }
    if page_length != 0 && !range_is_valid(memory, page_start, page_length) {
        return negative_errno(libc::ENOMEM);
    }
    0
}

fn mincore(memory: &mut GuestMemory, args: &[u64; 6]) -> i64 {
    let address = args[0];
    let length = args[1];
    if length == 0 || !address.is_multiple_of(PAGE_SIZE) || !range_is_valid(memory, address, length)
    {
        return negative_errno(libc::EINVAL);
    }
    if !memory.user_range_is_mapped(address, length) {
        return negative_errno(libc::ENOMEM);
    }
    let Some(page_count) = length.checked_add(PAGE_SIZE - 1).map(|n| n / PAGE_SIZE) else {
        return negative_errno(libc::ENOMEM);
    };
    let Ok(page_count) = usize::try_from(page_count) else {
        return negative_errno(libc::ENOMEM);
    };
    let residency = vec![1_u8; page_count];
    match memory.user().write(args[2], &residency) {
        Ok(()) => 0,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

fn getcpu(memory: &mut GuestMemory, args: &[u64; 6]) -> i64 {
    if args[0] != 0 {
        let result = write_struct(memory, args[0], &0_u32);
        if result != 0 {
            return result;
        }
    }
    if args[1] != 0 {
        return write_struct(memory, args[1], &0_u32);
    }
    0
}

fn sched_getaffinity(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let requested_pid = args[0] as i64;
    if requested_pid != 0 && requested_pid != i64::from(state.pid) {
        return negative_errno(libc::ESRCH);
    }
    const MASK_BYTES: usize = std::mem::size_of::<libc::c_ulong>();
    let Ok(capacity) = usize::try_from(args[1]) else {
        return negative_errno(libc::EINVAL);
    };
    if capacity < MASK_BYTES {
        return negative_errno(libc::EINVAL);
    }
    let mut mask = [0_u8; MASK_BYTES];
    mask[0] = 1;
    match memory.user().write(args[2], &mask) {
        Ok(()) => MASK_BYTES as i64,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

// SCHED_RESET_ON_FORK may be ORed into the policy passed to sched_setscheduler.
const SCHED_RESET_ON_FORK: libc::c_int = 0x4000_0000;
const SCHED_DEADLINE: libc::c_int = 6;
const SCHED_EXT: libc::c_int = 7;
const IOPRIO_WHO_PROCESS: libc::c_int = 1;
const IOPRIO_WHO_PGRP: libc::c_int = 2;
const IOPRIO_WHO_USER: libc::c_int = 3;
const IOPRIO_CLASS_SHIFT: libc::c_int = 13;
const IOPRIO_CLASS_RT: libc::c_int = 1;
const IOPRIO_CLASS_BE: libc::c_int = 2;
const IOPRIO_CLASS_IDLE: libc::c_int = 3;
const IOPRIO_LEVEL_MASK: libc::c_int = 0x7;

// TODO-HUMAN-REVIEW(PR-119): Review guest scheduler pid validation and lookup.
fn sched_pid_value(raw_pid: u64) -> Result<libc::c_int, i64> {
    let pid = raw_pid as u32 as libc::c_int;
    if pid < 0 {
        Err(negative_errno(libc::EINVAL))
    } else {
        Ok(pid)
    }
}

fn sched_target_result(state: &LoadedStaticElf, pid: libc::c_int) -> Result<(), i64> {
    if pid == 0 || pid == state.pid {
        Ok(())
    } else {
        Err(negative_errno(libc::ESRCH))
    }
}

// TODO-HUMAN-REVIEW(PR-119): Review guest sched_param memory validation.
fn read_sched_param(memory: &GuestMemory, address: u64) -> Result<libc::c_int, i64> {
    if address == 0 {
        return Err(negative_errno(libc::EINVAL));
    }
    let mut priority = [0; std::mem::size_of::<libc::c_int>()];
    memory
        .user()
        .read(address, &mut priority)
        .map_err(|_| negative_errno(libc::EFAULT))?;
    Ok(libc::c_int::from_ne_bytes(priority))
}

// TODO-HUMAN-REVIEW(PR-119): Review guest sched_param output validation.
fn write_sched_param(memory: &mut GuestMemory, address: u64, priority: libc::c_int) -> i64 {
    match memory.user().write(address, &priority.to_ne_bytes()) {
        Ok(()) => 0,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

// TODO-HUMAN-REVIEW(PR-119): Review settable policy and priority validation.
fn sched_policy_settable(policy: libc::c_int) -> bool {
    matches!(
        policy,
        libc::SCHED_OTHER
            | libc::SCHED_FIFO
            | libc::SCHED_RR
            | libc::SCHED_BATCH
            | libc::SCHED_IDLE
    )
}

fn sched_priority_valid(policy: libc::c_int, priority: libc::c_int) -> bool {
    match policy {
        libc::SCHED_FIFO | libc::SCHED_RR => (1..=99).contains(&priority),
        libc::SCHED_OTHER | libc::SCHED_BATCH | libc::SCHED_IDLE => priority == 0,
        _ => false,
    }
}

// TODO-HUMAN-REVIEW(PR-110): Review scheduler policy priority bounds.
// TODO-HUMAN-REVIEW(PR-119): Review modern policy-bound compatibility.
fn sched_priority_bound(policy: u64, want_max: bool) -> i64 {
    let policy = policy as u32 as libc::c_int;
    match policy {
        libc::SCHED_FIFO | libc::SCHED_RR => {
            if want_max {
                99
            } else {
                1
            }
        }
        libc::SCHED_OTHER | libc::SCHED_BATCH | libc::SCHED_IDLE | SCHED_DEADLINE | SCHED_EXT => 0,
        _ => negative_errno(libc::EINVAL),
    }
}

// TODO-HUMAN-REVIEW(PR-110): Review virtual sched_getscheduler behavior.
// TODO-HUMAN-REVIEW(PR-119): Review stateful scheduler query behavior.
fn sched_getscheduler(state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let pid = match sched_pid_value(args[0]) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    if let Err(error) = sched_target_result(state, pid) {
        return error;
    }
    let reset = if state.sched_reset_on_fork {
        SCHED_RESET_ON_FORK
    } else {
        0
    };
    i64::from(state.sched_policy | reset)
}

// TODO-HUMAN-REVIEW(PR-110): Review virtual sched_setscheduler behavior.
// TODO-HUMAN-REVIEW(PR-119): Review stateful scheduler mutation and errno ordering.
fn sched_setscheduler(memory: &GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let pid = match sched_pid_value(args[0]) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    let policy_with_flags = args[1] as u32 as libc::c_int;
    if policy_with_flags < 0 {
        return negative_errno(libc::EINVAL);
    }
    let priority = match read_sched_param(memory, args[2]) {
        Ok(priority) => priority,
        Err(error) => return error,
    };
    if let Err(error) = sched_target_result(state, pid) {
        return error;
    }
    let policy = policy_with_flags & !SCHED_RESET_ON_FORK;
    if !sched_policy_settable(policy) || !sched_priority_valid(policy, priority) {
        return negative_errno(libc::EINVAL);
    }
    state.sched_policy = policy;
    state.sched_priority = priority;
    state.sched_reset_on_fork = policy_with_flags & SCHED_RESET_ON_FORK != 0;
    0
}

// TODO-HUMAN-REVIEW(PR-110): Review virtual sched_getparam behavior.
// TODO-HUMAN-REVIEW(PR-119): Review scheduler parameter query errno ordering.
fn sched_getparam(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let pid = match sched_pid_value(args[0]) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    if args[1] == 0 {
        return negative_errno(libc::EINVAL);
    }
    if let Err(error) = sched_target_result(state, pid) {
        return error;
    }
    write_sched_param(memory, args[1], state.sched_priority)
}

// TODO-HUMAN-REVIEW(PR-110): Review virtual sched_setparam behavior.
// TODO-HUMAN-REVIEW(PR-119): Review scheduler parameter mutation errno ordering.
fn sched_setparam(memory: &GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let pid = match sched_pid_value(args[0]) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    let priority = match read_sched_param(memory, args[1]) {
        Ok(priority) => priority,
        Err(error) => return error,
    };
    if let Err(error) = sched_target_result(state, pid) {
        return error;
    }
    if !sched_priority_valid(state.sched_policy, priority) {
        return negative_errno(libc::EINVAL);
    }
    state.sched_priority = priority;
    0
}

// TODO-HUMAN-REVIEW(PR-119): Review single-process ioprio target validation.
// Group and user selectors deterministically address the current KVM executor only;
// this is a one-task approximation and does not claim cross-executor group updates.
fn ioprio_target_result(state: &LoadedStaticElf, which: u64, who: u64) -> Result<(), i64> {
    let which = which as u32 as libc::c_int;
    let who = who as u32;
    let target_matches = match which {
        IOPRIO_WHO_PROCESS | IOPRIO_WHO_PGRP => who == 0 || who == state.pid as u32,
        IOPRIO_WHO_USER => who == 0,
        _ => return Err(negative_errno(libc::EINVAL)),
    };
    if target_matches {
        Ok(())
    } else {
        Err(negative_errno(libc::ESRCH))
    }
}

// TODO-HUMAN-REVIEW(PR-119): Review policy-derived effective ioprio defaults.
fn ioprio_effective_default(state: &LoadedStaticElf) -> libc::c_int {
    let class = match state.sched_policy {
        libc::SCHED_IDLE => IOPRIO_CLASS_IDLE,
        libc::SCHED_FIFO | libc::SCHED_RR | SCHED_DEADLINE => IOPRIO_CLASS_RT,
        _ => IOPRIO_CLASS_BE,
    };
    (class << IOPRIO_CLASS_SHIFT) | 4
}

// TODO-HUMAN-REVIEW(PR-110): Review virtual ioprio_get behavior.
// TODO-HUMAN-REVIEW(PR-119): Review raw versus effective ioprio query results.
fn ioprio_get(state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if let Err(error) = ioprio_target_result(state, args[0], args[1]) {
        return error;
    }
    if state.ioprio >> IOPRIO_CLASS_SHIFT == 0
        && args[0] as u32 as libc::c_int != IOPRIO_WHO_PROCESS
    {
        i64::from(ioprio_effective_default(state))
    } else {
        i64::from(state.ioprio)
    }
}

// TODO-HUMAN-REVIEW(PR-110): Review virtual ioprio_set behavior.
// TODO-HUMAN-REVIEW(PR-119): Review modern class, level, and hint payload handling.
fn ioprio_set(state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let ioprio = args[2] as u32 as libc::c_int;
    if ioprio < 0 {
        return negative_errno(libc::EINVAL);
    }
    let class = ioprio >> IOPRIO_CLASS_SHIFT;
    let valid = match class {
        0 => ioprio & IOPRIO_LEVEL_MASK == 0,
        IOPRIO_CLASS_RT | IOPRIO_CLASS_BE | IOPRIO_CLASS_IDLE => true,
        _ => false,
    };
    if !valid {
        return negative_errno(libc::EINVAL);
    }
    if let Err(error) = ioprio_target_result(state, args[0], args[1]) {
        return error;
    }
    state.ioprio = ioprio;
    0
}

#[repr(C)]
#[derive(Clone, Copy)]
struct SchedAttr {
    size: u32,
    sched_policy: u32,
    sched_flags: u64,
    sched_nice: i32,
    sched_priority: u32,
    sched_runtime: u64,
    sched_deadline: u64,
    sched_period: u64,
    sched_util_min: u32,
    sched_util_max: u32,
}

// The pid/target argument must name the guest process (0 or its own pid).
fn is_self_target(raw_pid: u64, state: &LoadedStaticElf) -> bool {
    let pid = raw_pid as u32 as libc::pid_t;
    pid == 0 || pid == state.pid
}

// TODO-HUMAN-REVIEW(PR-92): Review stateful virtual nice queries.
fn getpriority(state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if args[0] as u32 != libc::PRIO_PROCESS {
        return negative_errno(libc::EINVAL);
    }
    if !is_self_target(args[1], state) {
        return negative_errno(libc::ESRCH);
    }
    i64::from(20 - state.nice)
}

// TODO-HUMAN-REVIEW(PR-92): Review stateful virtual nice mutation and clamping.
fn setpriority(state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if args[0] as u32 != libc::PRIO_PROCESS {
        return negative_errno(libc::EINVAL);
    }
    if !is_self_target(args[1], state) {
        return negative_errno(libc::ESRCH);
    }
    state.nice = (args[2] as u32 as libc::c_int).clamp(-20, 19);
    0
}

// TODO-HUMAN-REVIEW(PR-92): Review bounded sched_getattr ABI writes.
fn sched_getattr(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let size = args[2] as u32 as usize;
    if !(48..=PAGE_SIZE as usize).contains(&size) || args[3] as u32 != 0 {
        return negative_errno(libc::EINVAL);
    }
    if !is_self_target(args[0], state) {
        return negative_errno(libc::ESRCH);
    }
    let attr = SchedAttr {
        size: std::mem::size_of::<SchedAttr>() as u32,
        sched_policy: state.sched_policy as u32,
        sched_flags: u64::from(state.sched_reset_on_fork),
        sched_nice: state.nice,
        sched_priority: state.sched_priority as u32,
        sched_runtime: 2_800_000,
        sched_deadline: 0,
        sched_period: 0,
        sched_util_min: 0,
        sched_util_max: 0,
    };
    let length = size.min(std::mem::size_of::<SchedAttr>());
    // SAFETY: attr is initialized repr(C) data and length is bounded to it.
    let bytes =
        unsafe { std::slice::from_raw_parts((&attr as *const SchedAttr).cast::<u8>(), length) };
    match memory.user().write(args[1], bytes) {
        Ok(()) => 0,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

// TODO-HUMAN-REVIEW(PR-180): Review virtual-TID random stream separation.
fn getrandom(
    memory: &mut GuestMemory,
    state: &mut LoadedStaticElf,
    address: u64,
    length: u64,
) -> i64 {
    let Ok(length) = usize::try_from(length) else {
        return negative_errno(libc::EINVAL);
    };
    if length > MAX_HOST_IO {
        return negative_errno(libc::E2BIG);
    }
    let Some(next_offset) = state.getrandom_offset.checked_add(length as u64) else {
        return negative_errno(libc::EOVERFLOW);
    };
    let bytes = deterministic_random_bytes(
        state.tid,
        state.random_seed,
        state.getrandom_offset,
        length,
        17,
        0x5a,
    );
    match memory.user().write(address, &bytes) {
        Ok(()) => {
            state.getrandom_offset = next_offset;
            length as i64
        }
        Err(_) => negative_errno(libc::EFAULT),
    }
}

fn deterministic_random_bytes(
    tid: i32,
    seed: u64,
    offset: u64,
    length: usize,
    byte_stride: u8,
    first_byte: u8,
) -> Vec<u8> {
    const BLOCK_DOMAIN: u64 = 0xd1b5_4a32_d192_ed03;
    const SEED_DOMAIN: u64 = 0xa076_1d64_78bd_642f;
    // Preserve the first 256 bytes for seed zero. The odd multiplier gives
    // every 32-bit virtual TID a distinct eight-byte salt at a fixed position.
    let thread_stream = u64::from(tid as u32)
        .wrapping_sub(1)
        .wrapping_mul(0x9e37_79b9_7f4a_7c15);
    let seed_stream = deterministic_random_salt(seed, SEED_DOMAIN);
    let mut block = offset / 256;
    let mut stream = thread_stream ^ seed_stream ^ deterministic_random_salt(block, BLOCK_DOMAIN);
    (0..length)
        .map(|index| {
            // The caller checks the complete range before generation. Use the
            // absolute position so splitting a read never changes its bytes.
            let index = offset + index as u64;
            if index / 256 != block {
                block = index / 256;
                stream =
                    thread_stream ^ seed_stream ^ deterministic_random_salt(block, BLOCK_DOMAIN);
            }
            let stream_byte = stream.rotate_right(((index % 8) * 8) as u32) as u8;
            (index as u8)
                .wrapping_mul(byte_stride)
                .wrapping_add(first_byte)
                ^ stream_byte
        })
        .collect()
}

fn deterministic_random_salt(value: u64, domain: u64) -> u64 {
    // SplitMix64's bijective finalizer, with separate domains for the seed and
    // byte block. Normalization maps zero to zero without losing bijectivity.
    fn mix(mut value: u64) -> u64 {
        value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        value ^ (value >> 31)
    }
    mix(value.wrapping_add(domain)) ^ mix(domain)
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-228): Review cross-backend random-device stream parity.
fn deterministic_random_device_bytes(seed: u64, length: usize) -> Vec<u8> {
    (0..length)
        .map(|index| deterministic_random_device_byte(seed, index as u64))
        .collect()
}

fn deterministic_random_device_byte(seed: u64, index: u64) -> u8 {
    const BYTE_STRIDE: u8 = 73;
    const FIRST_BYTE: u8 = 41;
    let seed_byte = seed.rotate_right(((index % 8) * 8) as u32) as u8;
    (index as u8)
        .wrapping_mul(BYTE_STRIDE)
        .wrapping_add(FIRST_BYTE)
        ^ seed_byte
}

// Child processes and guest workers bypass Detcore's virtual scheduler. Validate
// their sleep requests, but do not block the supervisor on host wall time;
// subscribed root-process sleeps continue to use Detcore's time model.
// TODO-HUMAN-REVIEW(PR-182): Review nonblocking KVM child sleeps.
fn nanosleep(memory: &GuestMemory, args: &[u64; 6]) -> i64 {
    validate_sleep_request(memory, args[0])
}

fn clock_nanosleep(memory: &GuestMemory, args: &[u64; 6]) -> i64 {
    let clock_id = args[0] as libc::clockid_t;
    if clock_id == libc::CLOCK_THREAD_CPUTIME_ID {
        return negative_errno(libc::EOPNOTSUPP);
    }
    if !matches!(
        clock_id,
        libc::CLOCK_REALTIME
            | libc::CLOCK_MONOTONIC
            | libc::CLOCK_PROCESS_CPUTIME_ID
            | libc::CLOCK_BOOTTIME
            | libc::CLOCK_TAI
    ) {
        return negative_errno(libc::EINVAL);
    }
    validate_sleep_request(memory, args[2])
}

fn validate_sleep_request(memory: &GuestMemory, address: u64) -> i64 {
    if address == 0 {
        return negative_errno(libc::EFAULT);
    }
    let request = match read_guest_struct::<libc::timespec>(memory, address) {
        Ok(request) => request,
        Err(error) => return error,
    };
    if request.tv_sec < 0 || !(0..1_000_000_000).contains(&request.tv_nsec) {
        negative_errno(libc::EINVAL)
    } else {
        0
    }
}

fn clock_gettime(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let nanoseconds = state.logical_clock_ns;
    let time = libc::timespec {
        tv_sec: (nanoseconds / 1_000_000_000) as libc::time_t,
        tv_nsec: (nanoseconds % 1_000_000_000) as libc::c_long,
    };
    let result = write_struct(memory, args[1], &time);
    if result == 0 {
        state.logical_clock_ns = state.logical_clock_ns.saturating_add(1);
    }
    result
}

fn gettimeofday(memory: &mut GuestMemory, args: &[u64; 6]) -> i64 {
    if args[0] != 0 {
        let timeval = libc::timeval {
            tv_sec: 0,
            tv_usec: 0,
        };
        let result = write_struct(memory, args[0], &timeval);
        if result != 0 {
            return result;
        }
    }
    if args[1] != 0 {
        return write_bytes(
            memory,
            args[1],
            &[0; std::mem::size_of::<libc::c_int>() * 2],
        );
    }
    0
}

// TODO-HUMAN-REVIEW(PR-136): Review shared readlink guest path handling.
fn readlink(
    memory: &mut GuestMemory,
    state: &LoadedStaticElf,
    args: &[u64; 6],
    capture: Option<CaptureMetadata>,
) -> i64 {
    readlink_at_impl(
        memory,
        state,
        libc::AT_FDCWD,
        args[0],
        args[1],
        args[2],
        capture,
    )
}

// TODO-HUMAN-REVIEW(PR-136): Review readlinkat guest-dirfd and procfd semantics.
fn readlinkat(
    memory: &mut GuestMemory,
    state: &LoadedStaticElf,
    args: &[u64; 6],
    capture: Option<CaptureMetadata>,
) -> i64 {
    readlink_at_impl(
        memory,
        state,
        args[0] as libc::c_int,
        args[1],
        args[2],
        args[3],
        capture,
    )
}

// TODO-HUMAN-REVIEW(PR-136): Review shared readlinkat implementation semantics.
fn readlink_at_impl(
    memory: &mut GuestMemory,
    state: &LoadedStaticElf,
    guest_dirfd: libc::c_int,
    path_address: u64,
    output_address: u64,
    raw_capacity: u64,
    capture: Option<CaptureMetadata>,
) -> i64 {
    let path = match read_c_string(memory, path_address, 4096) {
        Ok(path) => path,
        Err(error) => return read_c_string_errno(error),
    };
    let Ok(requested_capacity) = usize::try_from(raw_capacity) else {
        return negative_errno(libc::EINVAL);
    };
    if requested_capacity == 0 {
        return negative_errno(libc::EINVAL);
    }
    let capacity = requested_capacity.min(MAX_HOST_IO);

    if let Some(guest_fd) = guest_fd_path(state, &path) {
        let target = match guest_fd_link_target(state, guest_fd, capture) {
            Ok(target) => target,
            Err(error) => return error,
        };
        let count = capacity.min(target.len());
        return match memory.user().write(output_address, &target[..count]) {
            Ok(()) => count as i64,
            Err(_) => negative_errno(libc::EFAULT),
        };
    }

    let normalized = normalize_proc_path(state, &path);
    let executable_target = match guest_proc_exe_path(state, &path) {
        Some(true) => match state.executable_file.as_ref() {
            Some(file) => match canonical_fd_path(file.as_raw_fd()) {
                Ok(path) => Some(path.into_os_string().into_vec()),
                Err(error) => return error,
            },
            None => Some(state.executable_path.as_os_str().as_bytes().to_vec()),
        },
        Some(false) => return negative_errno(libc::ENOENT),
        None => None,
    };
    let proc_link_target: Option<&[u8]> = if let Some(target) = executable_target.as_deref() {
        Some(target)
    } else {
        match normalized.as_deref() {
            Some(b"/proc/self/cwd") => Some(state.cwd.as_os_str().as_bytes()),
            Some(b"/proc/self/root") => Some(b"/"),
            _ => None,
        }
    };
    if let Some(target) = proc_link_target {
        let count = capacity.min(target.len());
        let copied = if executable_target.is_some() {
            memory.user().copy_to_user(output_address, &target[..count])
        } else {
            memory.user().write(output_address, &target[..count])
        };
        return match copied {
            Ok(()) => count as i64,
            Err(_) => negative_errno(libc::EFAULT),
        };
    }
    // /proc/self (and /proc/<pid>) is a symlink to the numeric pid directory.
    if path == b"/proc/self" || path == format!("/proc/{}", state.pid).as_bytes() {
        let target = state.pid.to_string().into_bytes();
        let count = capacity.min(target.len());
        return match memory.user().write(output_address, &target[..count]) {
            Ok(()) => count as i64,
            Err(_) => negative_errno(libc::EFAULT),
        };
    }

    let opened_file;
    let link_fd = if path.is_empty() {
        if guest_dirfd == libc::AT_FDCWD {
            return negative_errno(libc::ENOENT);
        }
        let Some(host_fd) = host_fd(state, guest_dirfd) else {
            return negative_errno(libc::EBADF);
        };
        host_fd
    } else {
        opened_file = match open_metadata_path(state, guest_dirfd, &path, true) {
            Ok(file) => file,
            Err(error) => return error,
        };
        opened_file.as_raw_fd()
    };
    match fd_mode(link_fd) {
        Ok(mode) if mode & libc::S_IFMT == libc::S_IFLNK => {}
        Ok(_) if path.is_empty() => return negative_errno(libc::ENOENT),
        Ok(_) => return negative_errno(libc::EINVAL),
        Err(error) => return error,
    }
    let empty_path = b"\0";
    let mut bytes = vec![0; capacity];
    // SAFETY: empty_path is NUL-terminated, link_fd is an O_PATH descriptor for
    // the symlink itself, and bytes is writable for capacity bytes.
    let count = unsafe {
        libc::readlinkat(
            link_fd,
            empty_path.as_ptr().cast(),
            bytes.as_mut_ptr().cast(),
            bytes.len(),
        )
    };
    if count < 0 {
        return io_error(std::io::Error::last_os_error());
    }
    let count = count as usize;
    match memory.user().write(output_address, &bytes[..count]) {
        Ok(()) => count as i64,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

fn uname(memory: &mut GuestMemory, address: u64) -> i64 {
    let mut utsname = [0; 65 * 6];
    for (index, value) in [
        b"Linux".as_slice(),
        b"reverie-kvm".as_slice(),
        b"6.0.0".as_slice(),
        b"#1".as_slice(),
        b"x86_64".as_slice(),
        b"(none)".as_slice(),
    ]
    .into_iter()
    .enumerate()
    {
        let start = index * 65;
        utsname[start..start + value.len()].copy_from_slice(value);
    }
    write_bytes(memory, address, &utsname)
}

fn prlimit64(memory: &mut GuestMemory, args: &[u64; 6]) -> i64 {
    if args[2] != 0 {
        return negative_errno(libc::EPERM);
    }
    if args[3] == 0 {
        return 0;
    }
    let limit = if args[1] as libc::c_uint == libc::RLIMIT_NOFILE as libc::c_uint {
        GUEST_NOFILE_LIMIT as u64
    } else {
        STACK_LIMIT
    };
    let mut bytes = [0; 16];
    bytes[..8].copy_from_slice(&limit.to_le_bytes());
    bytes[8..].copy_from_slice(&limit.to_le_bytes());
    write_bytes(memory, args[3], &bytes)
}

fn rt_sigaction(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    if args[3] != KERNEL_SIGSET_SIZE as u64 {
        return negative_errno(libc::EINVAL);
    }
    let Ok(signal) = libc::c_int::try_from(args[0]) else {
        return negative_errno(libc::EINVAL);
    };
    if !(1..=64).contains(&signal) {
        return negative_errno(libc::EINVAL);
    }
    let mut action = if args[1] == 0 {
        None
    } else {
        match read_guest_bytes::<KERNEL_SIGACTION_SIZE>(memory, args[1]) {
            Ok(action) => Some(KernelSigaction::decode(action)),
            Err(error) => return error,
        }
    };
    if let Some(action) = &mut action {
        action.mask.clear_unmaskable();
    }
    if action.is_some() && matches!(signal, libc::SIGKILL | libc::SIGSTOP) {
        return negative_errno(libc::EINVAL);
    }
    // Installing a real SIGCHLD handler is ACCEPTED, not refused. Linux implements
    // this call and both the native host and the ptrace backend return 0; hermit's
    // tests/c/kvm_exact_child_waits.c requires success. Recording the action is also
    // harmless for the auto-reap decision below: `sigchld_auto_reaps` matches only
    // SIG_IGN and SA_NOCLDWAIT, so a real handler correctly yields false and the
    // child stays waitable. Whether KVM should additionally DELIVER that handler is
    // a separate, still-open question; accepting the installation does not answer it
    // and does not claim delivery.

    let discards_pending = action.is_some_and(|action| {
        action.handler == libc::SIG_IGN as u64
            || action.handler == libc::SIG_DFL as u64
                && default_signal_disposition(signal) == SignalDisposition::Ignore
    });
    // Linux discards every instance that predates an ignored disposition.
    // A process-shared generation makes old entries in every private queue
    // ineligible atomically without walking and locking each live sibling.
    // A blocked signal generated after this transition uses the new generation
    // and may remain pending if a handler is installed before it is unblocked.
    let (previous, readiness) = {
        let mut process_signals = state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let previous = process_signals
            .dispositions
            .get(&signal)
            .copied()
            .unwrap_or_default();
        if discards_pending {
            if let Err(error) = process_signals.advance_pending_generation(signal) {
                return negative_errno(error.into_raw());
            }
            state.thread_signals.lock().pending.remove(signal);
            process_signals.shared_pending.remove(signal);
        }
        if let Some(action) = action {
            process_signals.dispositions.insert(signal, action);
        }
        let readiness = if discards_pending {
            let generations = &process_signals.pending_generations;
            process_signals
                .signalfd_masks
                .iter()
                .filter_map(|(&fd, mask)| {
                    let mask = **mask;
                    mask.contains(signal).then_some((
                        fd,
                        state
                            .thread_signals
                            .lock()
                            .pending
                            .any_matching(mask, generations)
                            || process_signals
                                .shared_pending
                                .any_matching(mask, generations),
                    ))
                })
                .collect()
        } else {
            Vec::new()
        };
        (previous, readiness)
    };
    for (fd, ready) in readiness {
        if let Some(file) = state.files.get(&fd)
            && let Err(error) = set_signalfd_ready(file, ready)
        {
            return error;
        }
    }
    if args[2] != 0 {
        return write_bytes(memory, args[2], &previous.encode());
    }
    0
}

fn prospective_sigprocmask(
    memory: &GuestMemory,
    current: KernelSigset,
    args: &[u64; 6],
) -> Result<Option<KernelSigset>, i64> {
    if args[3] != KERNEL_SIGSET_SIZE as u64 {
        return Err(negative_errno(libc::EINVAL));
    }
    if args[1] == 0 {
        return Ok(None);
    }
    let requested =
        KernelSigset::from_bytes(read_guest_bytes::<KERNEL_SIGSET_SIZE>(memory, args[1])?);
    let mut next = current;
    match args[0] as libc::c_int {
        libc::SIG_BLOCK => next.union_with(requested),
        libc::SIG_UNBLOCK => next.remove_all(requested),
        libc::SIG_SETMASK => next = requested,
        _ => return Err(negative_errno(libc::EINVAL)),
    }
    next.clear_unmaskable();
    Ok(Some(next))
}

fn rt_sigprocmask(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    let previous = state.thread_signals.lock().blocked;
    match prospective_sigprocmask(memory, previous, args) {
        Ok(Some(next)) => state.thread_signals.lock().blocked = next,
        Ok(None) => {}
        Err(error) => return error,
    }
    if args[2] != 0 {
        return write_bytes(memory, args[2], &previous.to_bytes());
    }
    0
}

// TODO-HUMAN-REVIEW(PR-543): Review shared/thread pending masks and bounded copyout.
fn rt_sigpending(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if args[1] > KERNEL_SIGSET_SIZE as u64 {
        return negative_errno(libc::EINVAL);
    }
    if args[1] == 0 {
        return 0;
    }
    let process_signals = state
        .process_signals
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let generations = &process_signals.pending_generations;
    let mut pending = state
        .thread_signals
        .lock()
        .pending
        .pending_mask(generations);
    pending.union_with(process_signals.shared_pending.pending_mask(generations));
    // Linux reports only signals that are both pending and blocked.
    pending.intersect_with(state.thread_signals.lock().blocked);
    match memory
        .user()
        .copy_to_user(args[0], &pending.to_bytes()[..args[1] as usize])
    {
        Ok(()) => 0,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

/// Effective action for a signal after honoring any handler installed through
/// `rt_sigaction`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum SignalDisposition {
    /// Default action terminates the process.
    Terminate,
    /// Signal is ignored (default or `SIG_IGN`).
    Ignore,
    /// Default action stops the process.
    Stop,
    /// A user handler is installed for deferred delivery at a user boundary.
    Handled,
}

/// Emulates `kill`/`tkill`/`tgkill` for the bounded virtual process tree and
/// explicitly refuses delivery that requires cross-process recipient fanout.
///
/// Supported standard signals directed to the current task are queued for the
/// backend's next return-to-user delivery boundary. This lets a Tool inspect,
/// replace, or suppress an event before its current disposition is applied.
/// Blocked signals remain pending. Ignored signals are queued long enough for
/// the Tool hook to observe them, then discarded at that return boundary; an
/// unchanged fatal default disposition terminates with the conventional
/// `128 + signo` status. Stopped-state scheduling, queued real-time siginfo,
/// and cross-process delivery remain unsupported. Same-process thread-directed
/// signals use the named receiver's private queue and return boundary.
// TODO-HUMAN-REVIEW(#95): Review self-signal termination and the default-disposition table.
fn kill_signal(state: &mut LoadedStaticElf, number: u64, args: &[u64; 6]) -> SyscallAction {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    let is_kill = number == libc::SYS_kill as u64;
    let is_tgkill = number == libc::SYS_tgkill as u64;

    // ⚠️ DECODE THROUGH SIGNED `pid_t`, NOT `as i64`. The guest passes ids in
    // 64-bit registers but they are 32-bit `pid_t`. A guest that put -1 in a
    // 32-bit register delivers 0x00000000_FFFFFFFF here; widening that to i64
    // yields 4294967295, which is neither -1 nor any live id, so it would fall
    // through the id checks as an ordinary foreign positive. Truncating to
    // `pid_t` reproduces the kernel's own read of the register.
    let (tgid, target, raw_signal) = if is_tgkill {
        (
            Some(args[0] as libc::pid_t),
            args[1] as libc::pid_t,
            args[2],
        )
    } else {
        (None, args[0] as libc::pid_t, args[1])
    };

    let Ok(signal) = libc::c_int::try_from(raw_signal) else {
        return continue_with(negative_errno(libc::EINVAL));
    };
    if !(0..=64).contains(&signal) {
        return continue_with(negative_errno(libc::EINVAL));
    }

    if !is_kill {
        return send_thread_signal(state, tgid, target, signal);
    }

    let targets_self = {
        let processes: Vec<(i32, i32)> = state
            .task_lifecycle
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .processes()
            .collect();
        match target {
            // Process groups are distinct from thread groups. A fork inherits
            // its parent's PGID, so group delivery is supported only when the
            // selected group contains exactly this one process. Refuse a
            // multi-process fanout before mutating any pending set.
            0 => {
                let members: Vec<i32> = processes
                    .iter()
                    .filter_map(|&(tgid, pgid)| (pgid == state.pgid).then_some(tgid))
                    .collect();
                if members.is_empty() {
                    return continue_with(negative_errno(libc::ESRCH));
                }
                if signal == 0 {
                    return continue_with(0);
                }
                if members.as_slice() != [state.pid] {
                    return continue_with(negative_errno(libc::ENOSYS));
                }
                true
            }
            -1 => {
                // Linux kill(-1) excludes both the caller and PID 1. The
                // remaining cross-process fanout is deliberately unsupported.
                let eligible = processes
                    .iter()
                    .filter(|(tgid, _)| *tgid != state.pid && *tgid != 1)
                    .count();
                if eligible == 0 {
                    return continue_with(negative_errno(libc::ESRCH));
                }
                return continue_with(if signal == 0 {
                    0
                } else {
                    negative_errno(libc::ENOSYS)
                });
            }
            target if target < -1 => {
                let Some(group) = target.checked_abs() else {
                    return continue_with(negative_errno(libc::ESRCH));
                };
                let members: Vec<i32> = processes
                    .iter()
                    .filter_map(|&(tgid, pgid)| (pgid == group).then_some(tgid))
                    .collect();
                if members.is_empty() {
                    return continue_with(negative_errno(libc::ESRCH));
                }
                if signal == 0 {
                    return continue_with(0);
                }
                if members.as_slice() != [state.pid] {
                    return continue_with(negative_errno(libc::ENOSYS));
                }
                true
            }
            _ if target == state.pid => true,
            _ if !processes.iter().any(|(tgid, _)| *tgid == target) => {
                return continue_with(negative_errno(libc::ESRCH));
            }
            _ => {
                return continue_with(if signal == 0 {
                    0
                } else {
                    negative_errno(libc::ENOSYS)
                });
            }
        }
    };
    if !targets_self {
        return continue_with(negative_errno(libc::ESRCH));
    }

    // Signal 0 is a permission/liveness probe that delivers nothing.
    if signal == 0 {
        return continue_with(0);
    }

    // These producer classes require state this first foundation does not yet
    // model. Reject them before mask/disposition handling so a blocked or
    // ignored action cannot turn an unsupported delivery into false success.
    if signal > 31 || matches!(signal, libc::SIGCHLD | libc::SIGPIPE) {
        return continue_with(negative_errno(libc::ENOSYS));
    }

    // SIGKILL can never be caught, blocked, or ignored.
    if signal == libc::SIGKILL {
        return terminating_signal_status(signal, process_dumpable(state))
            .map(SyscallAction::Exit)
            .unwrap_or_else(|| continue_with(negative_errno(libc::ENOSYS)));
    }

    match signal_disposition(state, signal) {
        SignalDisposition::Stop => return continue_with(negative_errno(libc::ENOSYS)),
        SignalDisposition::Ignore | SignalDisposition::Terminate | SignalDisposition::Handled => {}
    }

    // A process-directed signal has no preselected recipient. With more than
    // one live thread, letting whichever host vCPU reaches a boundary first
    // take the shared event would make delivery depend on host scheduling.
    // Hermit's later deterministic scheduler will own that selection; this
    // foundation fails visibly until then.
    if is_kill
        && state
            .task_lifecycle
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .has_live_sibling(state.tid, state.pid)
    {
        return continue_with(negative_errno(libc::ENOSYS));
    }

    // Queue even an unblocked default-fatal signal. The same return boundary
    // immediately applies its disposition in the plain loop, while the Tool
    // loop first gets exactly one structured hook invocation (as ptrace does
    // at a signal-delivery stop). A blocked event simply remains pending.
    let event = if is_kill {
        event_for_process(signal, state.pid)
    } else {
        event_for_thread(signal, state.pid, state.tid)
    };
    let event = match event {
        Ok(event) => event,
        Err(errno) => return continue_with(negative_errno(errno.into_raw())),
    };
    match queue_signal_event_locked(state, event, is_kill) {
        Ok(()) => continue_with(0),
        Err(error) => continue_with(error),
    }
}

/// A thread-directed signal is published into the named receiver's one private
/// queue. The lifecycle lock binds publication to the live task incarnation;
/// process dispositions and the receiver mask are then inspected in that order.
fn send_thread_signal(
    state: &LoadedStaticElf,
    tgid: Option<libc::pid_t>,
    target: libc::pid_t,
    signal: libc::c_int,
) -> SyscallAction {
    if target <= 0 || tgid.is_some_and(|tgid| tgid <= 0) {
        return continue_with(negative_errno(libc::EINVAL));
    }
    {
        let lifecycle = state
            .task_lifecycle
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(task) = lifecycle.get(target) else {
            return continue_with(negative_errno(libc::ESRCH));
        };
        if tgid.is_some_and(|tgid| tgid != task.tgid) {
            return continue_with(negative_errno(libc::ESRCH));
        }
        if signal == 0 {
            return continue_with(0);
        }
        if task.tgid != state.pid {
            return continue_with(negative_errno(libc::ENOSYS));
        }
        if signal > 31 || matches!(signal, libc::SIGCHLD | libc::SIGPIPE) {
            return continue_with(negative_errno(libc::ENOSYS));
        }
        if signal == libc::SIGKILL {
            // A sibling may be parked outside any return boundary. Queuing
            // SIGKILL there would falsely promise actual group cancellation.
            if target != state.tid {
                return continue_with(negative_errno(libc::ENOSYS));
            }
            return terminating_signal_status(signal, task.dumpable)
                .map(SyscallAction::Exit)
                .unwrap_or_else(|| continue_with(negative_errno(libc::ENOSYS)));
        }
        let target_signals = if target == state.tid {
            // Loader-level self-signal callers need no borrowed sibling handle.
            state.thread_signals.clone()
        } else {
            let Some(target_signals) = lifecycle.signal_target(target) else {
                return continue_with(negative_errno(libc::ENOSYS));
            };
            target_signals
        };
        let process_signals = state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let disposition = signal_disposition_with_action(
            process_signals.dispositions.get(&signal).copied(),
            signal,
        );
        if disposition == SignalDisposition::Stop {
            return continue_with(negative_errno(libc::ENOSYS));
        }
        let mut target_signals = target_signals.lock();
        if disposition == SignalDisposition::Ignore
            && !target_signals.blocked.contains(signal)
            && !target_signals.observe_ignored
        {
            return continue_with(0);
        }
        let event = match event_for_thread(signal, state.pid, target) {
            Ok(event) => event,
            Err(errno) => return continue_with(negative_errno(errno.into_raw())),
        };
        if let Err(errno) = target_signals
            .pending
            .enqueue(event, process_signals.pending_generation(signal))
        {
            return continue_with(negative_errno(errno.into_raw()));
        }
    }
    // Threaded signalfd is already refused. The self-directed single-thread
    // case still updates its eventfd readiness, after every state lock is gone.
    if target == state.tid
        && let Err(error) = refresh_all_signalfd_readiness_locked(state)
    {
        return continue_with(error);
    }
    continue_with(0)
}

fn process_dumpable(state: &LoadedStaticElf) -> bool {
    state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(state.tid)
        .map_or(state.dumpable, |task| task.dumpable)
}

fn terminating_signal_status(signal: libc::c_int, dumpable: bool) -> Option<ExitStatus> {
    let signal_kind = Signal::try_from(signal).ok()?;
    let core_dumped = dumpable && signal_has_core_default(signal);
    Some(ExitStatus::Signaled(signal_kind, core_dumped))
}

fn signal_has_core_default(signal: libc::c_int) -> bool {
    matches!(
        signal,
        libc::SIGQUIT
            | libc::SIGILL
            | libc::SIGTRAP
            | libc::SIGABRT
            | libc::SIGBUS
            | libc::SIGFPE
            | libc::SIGSEGV
            | libc::SIGXCPU
            | libc::SIGXFSZ
            | libc::SIGSYS
    )
}

/// Resolves the effective disposition of `signal`, honoring any installed
/// handler before falling back to the kernel default action.
fn installed_signal_action(
    state: &LoadedStaticElf,
    signal: libc::c_int,
) -> Option<KernelSigaction> {
    state
        .process_signals
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .dispositions
        .get(&signal)
        .copied()
}

fn signal_disposition(state: &LoadedStaticElf, signal: libc::c_int) -> SignalDisposition {
    signal_disposition_with_action(installed_signal_action(state, signal), signal)
}

fn signal_disposition_with_action(
    action: Option<KernelSigaction>,
    signal: libc::c_int,
) -> SignalDisposition {
    if let Some(action) = action {
        const SIG_DFL: u64 = 0;
        const SIG_IGN: u64 = 1;
        match action.handler {
            SIG_DFL => {}
            SIG_IGN => return SignalDisposition::Ignore,
            _ => return SignalDisposition::Handled,
        }
    }
    default_signal_disposition(signal)
}

/// Linux discards a child's terminal wait status when the parent explicitly
/// ignores SIGCHLD or installs SA_NOCLDWAIT. The default SIGCHLD disposition is
/// also "ignore", but unlike an explicit SIG_IGN it still leaves a waitable
/// zombie, so inspect the installed action rather than the effective disposition.
fn sigchld_auto_reaps(state: &LoadedStaticElf) -> bool {
    installed_signal_action(state, libc::SIGCHLD).is_some_and(|action| {
        action.handler == libc::SIG_IGN as u64 || action.flags & libc::SA_NOCLDWAIT as u64 != 0
    })
}

/// The kernel default action for `signal` when no handler is installed.
fn default_signal_disposition(signal: libc::c_int) -> SignalDisposition {
    match signal {
        libc::SIGCHLD | libc::SIGURG | libc::SIGWINCH | libc::SIGCONT => SignalDisposition::Ignore,
        libc::SIGSTOP | libc::SIGTSTP | libc::SIGTTIN | libc::SIGTTOU => SignalDisposition::Stop,
        _ => SignalDisposition::Terminate,
    }
}

/// Reports whether `signal` is currently blocked by the guest's signal mask.
fn signal_is_blocked(state: &LoadedStaticElf, signal: libc::c_int) -> bool {
    state.thread_signals.lock().blocked.contains(signal)
}

fn validate_altstack_update(
    current: Option<GuestStack>,
    current_stack_pointer: Option<u64>,
    requested: GuestStack,
) -> Result<Option<GuestStack>, i64> {
    if current.is_some_and(|stack| {
        current_stack_pointer.is_some_and(|stack_pointer| stack.contains(stack_pointer))
    }) {
        return Err(negative_errno(libc::EPERM));
    }
    let allowed_flags = libc::SS_DISABLE | SS_AUTODISARM;
    let disabled = requested.flags & libc::SS_DISABLE != 0;
    if requested.flags & !allowed_flags != 0 || disabled && requested.flags & SS_AUTODISARM != 0 {
        // SS_ONSTACK is status-only and is never valid as input.
        return Err(negative_errno(libc::EINVAL));
    }
    if !disabled && requested.size < libc::MINSIGSTKSZ as u64 {
        return Err(negative_errno(libc::ENOMEM));
    }
    Ok(if disabled {
        None
    } else {
        Some(GuestStack {
            flags: requested.flags & SS_AUTODISARM,
            ..requested
        })
    })
}

fn sigaltstack(
    memory: &mut GuestMemory,
    state: &mut LoadedStaticElf,
    current_user_stack_pointer: Option<u64>,
    args: &[u64; 6],
) -> i64 {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    let requested = if args[0] == 0 {
        None
    } else {
        let stack = match read_guest_bytes::<24>(memory, args[0]) {
            Ok(stack) => GuestStack::decode(stack),
            Err(error) => return error,
        };
        Some(stack)
    };
    let previous = state.thread_signals.lock().altstack;
    let on_stack = previous.is_some_and(|stack| {
        current_user_stack_pointer.is_some_and(|stack_pointer| stack.contains(stack_pointer))
    });
    if let Some(requested) = requested {
        state.thread_signals.lock().altstack =
            match validate_altstack_update(previous, current_user_stack_pointer, requested) {
                Ok(stack) => stack,
                Err(error) => return error,
            };
    }
    if args[1] != 0 {
        if let Some(mut previous) = previous {
            if on_stack {
                previous.flags |= libc::SS_ONSTACK;
            }
            return write_bytes(memory, args[1], &previous.encode());
        }
        return write_bytes(
            memory,
            args[1],
            &GuestStack {
                sp: 0,
                flags: libc::SS_DISABLE,
                size: 0,
            }
            .encode(),
        );
    }
    0
}

/// Emulates `rt_sigtimedwait(set, info, timeout, sigsetsize)` for the guest.
///
/// Detcore converts every blockable syscall to its zero-timeout non-blocking
/// form before injecting it and then drives blocking and timeout resolution
/// itself against the deterministic virtual clock. This handler is therefore a
/// pure, non-blocking poll of the guest kernel's pending-signal set: it consumes
/// the pending signal that Linux's `next_signal()` ordering selects (the
/// synchronous-number class first, then ascending numbers) and returns its
/// number, or reports `EAGAIN` when nothing matches (which detcore reads as
/// "would have blocked" and reschedules deterministically). Before this route
/// the executor fell through to `ENOSYS`, so a guest that called
/// `sigtimedwait` diverged from the golden ptrace backend (which returns
/// `EAGAIN` for an empty zero-timeout wait). Selection within each pending
/// domain is deterministic.
// TODO-HUMAN-REVIEW(rrnewton/reverie#315): Review virtual rt_sigtimedwait dequeue semantics.
fn rt_sigtimedwait(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let transaction = state.signal_transaction.clone();
    let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
    if args[3] != KERNEL_SIGSET_SIZE as u64 {
        return negative_errno(libc::EINVAL);
    }
    let mut set = match read_guest_bytes::<KERNEL_SIGSET_SIZE>(memory, args[0]) {
        Ok(set) => KernelSigset::from_bytes(set),
        Err(error) => return error,
    };
    set.clear_unmaskable();
    let event = match take_signal_event_locked(state, SignalSelection::TimedWait(set)) {
        Ok(pending) => pending.map(|pending| pending.event),
        Err(errno) => return -(i64::from(errno.into_raw())),
    };
    let Some(event) = event else {
        return negative_errno(libc::EAGAIN);
    };
    if let Err(error) = refresh_signalfd_readiness_for_signal_locked(state, Some(event.signal())) {
        return error;
    }
    // Preserve all event metadata rather than synthesizing a second siginfo.
    if args[1] != 0 {
        if !range_is_valid(memory, args[1], reverie::SIGNAL_INFO_SIZE as u64) {
            return negative_errno(libc::EFAULT);
        }
        let info = event.siginfo();
        let written = write_bytes(memory, args[1], &info);
        if written < 0 {
            return written;
        }
    }
    event.signal() as i64
}

fn wait4_options_supported(raw: u64) -> bool {
    // Linux decodes options as int. WUNTRACED adds stopped-child eligibility;
    // it does not exclude the terminal statuses already represented here.
    // Terminal-only admission relies on stops remaining unsupported:
    // kill_signal/send_thread_signal refuse Stop, validate_deferred_signal_event
    // refuses SIGSTOP, and validate_child_exit_signal_event refuses CLD_STOPPED.
    // vm::deliver_selected_signal_at_boundary and parked_signal_runtime's
    // observe_parked_signal_impl also refuse a remaining Stop disposition.
    // Adding stopped children requires extending wait4 before changing the
    // wait4_wuntraced_requires_unsupported_stopped_children contract test.
    // WCONTINUED remains unsupported.
    let options = raw as libc::c_int;
    options & !(libc::WNOHANG | libc::WUNTRACED) == 0
}

fn wait_group_exit_status(state: &LoadedStaticElf) -> Option<ExitStatus> {
    let identity = state.children.task_identity().ok()?;
    if identity.tid.as_raw() != state.tid || identity.process.tgid.as_raw() != state.pid {
        return None;
    }
    state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .live_task_group_exit_status(identity)
}

fn parent_terminated_wait(state: &LoadedStaticElf) -> crate::Result<i64> {
    Err(match wait_group_exit_status(state) {
        Some(status) => crate::Error::ChildWaitGroupExit { status },
        None => crate::Error::RunAborted,
    })
}

fn wait4_result(
    memory: &GuestMemory,
    state: &mut LoadedStaticElf,
    args: &[u64; 6],
) -> crate::Result<i64> {
    // Linux pid_t is signed low32. Retain the existing raw backend's single
    // group selector approximation; this change does not add PGID support.
    let requested = args[0] as i32;
    if !wait4_options_supported(args[2]) {
        return Ok(negative_errno(libc::EINVAL));
    }
    let selected = match state.children.select(
        (requested > 0).then_some(requested),
        true,
        args[2] as libc::c_int & libc::WNOHANG != 0,
    )? {
        ChildWaitSelection::Ready(selected) => selected,
        ChildWaitSelection::ParentTerminated => return parent_terminated_wait(state),
        ChildWaitSelection::Pending => return Ok(0),
        ChildWaitSelection::NoChild => return Ok(negative_errno(libc::ECHILD)),
    };
    let child_pid = selected.child.tgid.as_raw();
    let status = selected.status.into_raw();
    // Selection already consumed the exact family edge. Preserve that receipt
    // through either output fault: status is nonpartial and precedes bulk usage.
    state.consumed_child_wait = selected.receipt;
    if args[1] != 0 && memory.user().put_user_i32(args[1], status).is_err() {
        return Ok(negative_errno(libc::EFAULT));
    }
    if args[3] != 0
        && memory
            .user()
            .copy_to_user(args[3], &[0; std::mem::size_of::<libc::rusage>()])
            .is_err()
    {
        return Ok(negative_errno(libc::EFAULT));
    }
    Ok(i64::from(child_pid))
}

#[cfg(test)]
fn wait4(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    wait4_result(memory, state, args).expect("raw wait4 fixture has a coherent family ledger")
}

#[repr(C)]
struct GuestWaitidSiginfo {
    si_signo: libc::c_int,
    si_errno: libc::c_int,
    si_code: libc::c_int,
    _union_alignment: libc::c_int,
    si_pid: libc::pid_t,
    si_uid: libc::uid_t,
    si_status: libc::c_int,
    _clock_alignment: libc::c_int,
    _si_utime: libc::c_long,
    _si_stime: libc::c_long,
    _padding: [u8; std::mem::size_of::<libc::siginfo_t>() - 48],
}

fn waitid_options_supported(raw: u64) -> bool {
    // Linux decodes options as int. Retain the existing terminal-only subset;
    // accepting stopped/continued events needs separate backend support.
    let options = raw as libc::c_int;
    let allowed = libc::WEXITED | libc::WNOHANG | libc::WNOWAIT;
    options & libc::WEXITED != 0 && options & !allowed == 0
}

fn finish_waitid(
    memory: &GuestMemory,
    args: &[u64; 6],
    event: Option<&GuestWaitidSiginfo>,
    result: i64,
) -> i64 {
    // Only a positive event writes rusage, before any siginfo field. Preserve
    // the backend's existing zero accounting and the writable-prefix copy.
    if event.is_some() && args[4] != 0 {
        let size = std::mem::size_of::<libc::rusage>();
        if validate_guest_iovec_address(args[4], size).is_err()
            || memory
                .user()
                .copy_to_user(args[4], &[0; std::mem::size_of::<libc::rusage>()])
                .is_err()
        {
            return negative_errno(libc::EFAULT);
        }
    }
    if args[2] == 0 {
        return result;
    }
    // x86-64 Linux's constant-size access_ok does not validate a full siginfo
    // span. Only the six scalar fields are accessed. The architectural guard
    // page still faults even if a synthetic GuestMemory arena maps beyond it.
    if args[2] >= X86_64_GUEST_USER_LIMIT {
        return negative_errno(libc::EFAULT);
    }
    let fields = event.map_or([0; 6], |info| {
        [
            info.si_signo,
            info.si_errno,
            info.si_code,
            info.si_pid,
            info.si_uid as libc::c_int,
            info.si_status,
        ]
    });
    for (offset, value) in [0_u64, 4, 8, 16, 20, 24].into_iter().zip(fields) {
        // The bounded starting address makes this addition nonoverflowing.
        // Stop before a scalar crosses the architectural guard: earlier fields
        // remain, and the failing scalar, padding and tail stay untouched.
        let address = args[2] + offset;
        if address + 4 > X86_64_GUEST_USER_LIMIT
            || memory.user().put_user_i32(address, value).is_err()
        {
            return negative_errno(libc::EFAULT);
        }
    }
    result
}

// AUTONOMOUS-BOT-IMPLEMENTED
// TODO-HUMAN-REVIEW(PR-227): Review serialized-child waitid ABI emulation.
fn waitid_result(
    memory: &GuestMemory,
    state: &mut LoadedStaticElf,
    args: &[u64; 6],
) -> crate::Result<i64> {
    if !waitid_options_supported(args[3]) {
        return Ok(finish_waitid(
            memory,
            args,
            None,
            negative_errno(libc::EINVAL),
        ));
    }
    let requested = match args[0] as libc::idtype_t {
        libc::P_PID => match i32::try_from(args[1]) {
            Ok(pid) => Some(pid),
            Err(_) => {
                return Ok(finish_waitid(
                    memory,
                    args,
                    None,
                    negative_errno(libc::ECHILD),
                ));
            }
        },
        libc::P_ALL | libc::P_PGID => None,
        _ => {
            return Ok(finish_waitid(
                memory,
                args,
                None,
                negative_errno(libc::EINVAL),
            ));
        }
    };
    let selected = match state.children.select(
        requested,
        args[3] as libc::c_int & libc::WNOWAIT == 0,
        args[3] as libc::c_int & libc::WNOHANG != 0,
    )? {
        ChildWaitSelection::Ready(selected) => selected,
        ChildWaitSelection::ParentTerminated => return parent_terminated_wait(state),
        ChildWaitSelection::Pending => return Ok(finish_waitid(memory, args, None, 0)),
        ChildWaitSelection::NoChild => {
            return Ok(finish_waitid(
                memory,
                args,
                None,
                negative_errno(libc::ECHILD),
            ));
        }
    };
    let child_pid = selected.child.tgid.as_raw();
    let status = selected.status;
    state.consumed_child_wait = selected.receipt;
    let (si_code, si_status) = match status {
        ExitStatus::Exited(code) => (libc::CLD_EXITED, code),
        ExitStatus::Signaled(signal, true) => (libc::CLD_DUMPED, signal as libc::c_int),
        ExitStatus::Signaled(signal, false) => (libc::CLD_KILLED, signal as libc::c_int),
    };
    let info = GuestWaitidSiginfo {
        si_signo: libc::SIGCHLD,
        si_errno: 0,
        si_code,
        _union_alignment: 0,
        si_pid: child_pid,
        si_uid: 0,
        si_status,
        _clock_alignment: 0,
        _si_utime: 0,
        _si_stime: 0,
        _padding: [0; std::mem::size_of::<libc::siginfo_t>() - 48],
    };
    Ok(finish_waitid(memory, args, Some(&info), 0))
}

#[cfg(test)]
fn waitid(memory: &mut GuestMemory, state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
    waitid_result(memory, state, args).expect("raw waitid fixture has a coherent family ledger")
}

fn write_u64(memory: &mut GuestMemory, address: u64, value: u64) -> i64 {
    write_bytes(memory, address, &value.to_le_bytes())
}

fn write_bytes(memory: &mut GuestMemory, address: u64, bytes: &[u8]) -> i64 {
    match memory.user().write(address, bytes) {
        Ok(()) => 0,
        Err(_) => negative_errno(libc::EFAULT),
    }
}

fn write_struct<T>(memory: &mut GuestMemory, address: u64, value: &T) -> i64 {
    // SAFETY: Linux ABI structs are initialized plain data. The byte view is
    // bounded to value and copied into guest memory before value is dropped.
    let bytes = unsafe {
        std::slice::from_raw_parts(
            std::ptr::from_ref(value).cast::<u8>(),
            std::mem::size_of::<T>(),
        )
    };
    write_bytes(memory, address, bytes)
}

fn read_guest_bytes<const N: usize>(memory: &GuestMemory, address: u64) -> Result<[u8; N], i64> {
    let mut bytes = [0; N];
    memory
        .user()
        .read(address, &mut bytes)
        .map_err(|_| negative_errno(libc::EFAULT))?;
    Ok(bytes)
}

fn read_guest_struct<T>(memory: &GuestMemory, address: u64) -> Result<T, i64> {
    let mut value = std::mem::MaybeUninit::<T>::zeroed();
    // SAFETY: value is writable for exactly size_of::<T>() bytes and is not
    // observed until guest memory has initialized the complete byte range.
    let bytes = unsafe {
        std::slice::from_raw_parts_mut(value.as_mut_ptr().cast::<u8>(), std::mem::size_of::<T>())
    };
    memory
        .user()
        .read(address, bytes)
        .map_err(|_| negative_errno(libc::EFAULT))?;
    // SAFETY: the entire plain-data Linux ABI value was initialized above.
    Ok(unsafe { value.assume_init() })
}

#[cfg(test)]
fn struct_bytes<T>(value: &T) -> Vec<u8> {
    // SAFETY: Linux ABI structs are initialized plain data and the returned
    // Vec owns its copy before value can be dropped.
    unsafe {
        std::slice::from_raw_parts(
            std::ptr::from_ref(value).cast::<u8>(),
            std::mem::size_of::<T>(),
        )
        .to_vec()
    }
}

fn zero_or_errno(result: libc::c_int) -> i64 {
    if result == 0 {
        0
    } else {
        io_error(std::io::Error::last_os_error())
    }
}

enum ReadCStringError {
    Fault,
    NameTooLong,
}

fn read_c_string_errno(error: ReadCStringError) -> i64 {
    match error {
        ReadCStringError::Fault => negative_errno(libc::EFAULT),
        ReadCStringError::NameTooLong => negative_errno(libc::ENAMETOOLONG),
    }
}

fn read_c_string(
    memory: &GuestMemory,
    address: u64,
    limit: usize,
) -> Result<Vec<u8>, ReadCStringError> {
    let mut result = Vec::new();
    for offset in 0..limit {
        let address = address
            .checked_add(offset as u64)
            .ok_or(ReadCStringError::Fault)?;
        let mut byte = [0];
        memory
            .user()
            .read(address, &mut byte)
            .map_err(|_| ReadCStringError::Fault)?;
        if byte[0] == 0 {
            return Ok(result);
        }
        result.push(byte[0]);
    }
    Err(ReadCStringError::NameTooLong)
}

fn validate_process_clone_flags(flags: u64) -> Result<(), i64> {
    let signal = flags & 0xff;
    if signal != 0 && signal != libc::SIGCHLD as u64 {
        return Err(negative_errno(libc::EINVAL));
    }
    let allowed = 0xff
        | libc::CLONE_VM as u64
        | libc::CLONE_VFORK as u64
        | libc::CLONE_PARENT_SETTID as u64
        | libc::CLONE_CHILD_SETTID as u64
        | libc::CLONE_CHILD_CLEARTID as u64
        // The fork action clears caught handlers in the child snapshot.
        | CLONE_CLEAR_SIGHAND;
    if flags & !allowed != 0 {
        return Err(negative_errno(libc::ENOTSUP));
    }
    let shared_address_space = flags & (libc::CLONE_VM as u64 | libc::CLONE_VFORK as u64);
    if shared_address_space != 0
        && shared_address_space != (libc::CLONE_VM as u64 | libc::CLONE_VFORK as u64)
    {
        return Err(negative_errno(libc::ENOTSUP));
    }
    if shared_address_space != 0 && flags & PROCESS_CLONE_TID_FLAGS != 0 {
        return Err(negative_errno(libc::ENOTSUP));
    }
    Ok(())
}

// TODO-HUMAN-REVIEW(PR-132): Review the accepted glibc pthread clone flag profile.
fn validate_thread_clone_flags(flags: u64) -> Result<(), i64> {
    if flags & 0xff != 0 {
        return Err(negative_errno(libc::EINVAL));
    }
    if flags & THREAD_CLONE_REQUIRED_FLAGS != THREAD_CLONE_REQUIRED_FLAGS {
        return Err(negative_errno(libc::EINVAL));
    }
    if flags & !THREAD_CLONE_ALLOWED_FLAGS != 0 {
        return Err(negative_errno(libc::ENOTSUP));
    }
    Ok(())
}

struct CloneRequest {
    flags: u64,
    child_stack: Option<u64>,
    parent_tid: Option<u64>,
    child_tid: Option<u64>,
    tls: Option<u64>,
}

fn read_clone3(memory: &GuestMemory, address: u64, size: u64) -> Result<CloneRequest, i64> {
    const REQUIRED_SIZE: usize = 64;
    const MAX_SIZE: usize = 88;

    let Ok(size) = usize::try_from(size) else {
        return Err(negative_errno(libc::E2BIG));
    };
    if size < REQUIRED_SIZE {
        return Err(negative_errno(libc::EINVAL));
    }
    if size > PAGE_SIZE as usize {
        return Err(negative_errno(libc::E2BIG));
    }
    let mut bytes = [0; MAX_SIZE];
    memory
        .user()
        .read(address, &mut bytes[..size.min(MAX_SIZE)])
        .map_err(|_| negative_errno(libc::EFAULT))?;
    if size > MAX_SIZE {
        let mut extension = vec![0; size - MAX_SIZE];
        memory
            .user()
            .read(address + MAX_SIZE as u64, &mut extension)
            .map_err(|_| negative_errno(libc::EFAULT))?;
        if extension.iter().any(|byte| *byte != 0) {
            return Err(negative_errno(libc::E2BIG));
        }
    }
    let field = |offset: usize| {
        u64::from_le_bytes(
            bytes[offset..offset + 8]
                .try_into()
                .expect("u64 clone3 field"),
        )
    };
    // clone3 ignores pidfd unless CLONE_PIDFD is set. glibc leaves that union
    // slot nonzero for pthread clones even though the flag is absent.
    if field(64) != 0 || field(72) != 0 || field(80) != 0 {
        return Err(negative_errno(libc::ENOTSUP));
    }
    let flags = field(0) | field(32);
    let stack = field(40);
    let stack_size = field(48);
    if (stack == 0) != (stack_size == 0) {
        return Err(negative_errno(libc::EINVAL));
    }
    let child_stack = if stack == 0 {
        None
    } else {
        stack.checked_add(stack_size)
    };
    if stack != 0 && child_stack.is_none() {
        return Err(negative_errno(libc::EINVAL));
    }
    Ok(CloneRequest {
        flags,
        child_stack,
        parent_tid: (field(24) != 0).then(|| field(24)),
        child_tid: (field(16) != 0).then(|| field(16)),
        tls: (flags & libc::CLONE_SETTLS as u64 != 0).then(|| field(56)),
    })
}

fn read_string_array(memory: &GuestMemory, address: u64) -> Result<Vec<String>, i64> {
    const MAX_ENTRIES: usize = 4096;
    const MAX_STRING_BYTES: usize = 128 * 1024;

    if address == 0 {
        return Ok(Vec::new());
    }
    let mut result = Vec::new();
    let mut total_bytes = 0;
    for index in 0..MAX_ENTRIES {
        let pointer_address = address
            .checked_add((index * std::mem::size_of::<u64>()) as u64)
            .ok_or_else(|| negative_errno(libc::EFAULT))?;
        let mut pointer = [0; 8];
        memory
            .user()
            .read(pointer_address, &mut pointer)
            .map_err(|_| negative_errno(libc::EFAULT))?;
        let pointer = u64::from_le_bytes(pointer);
        if pointer == 0 {
            return Ok(result);
        }
        let remaining = MAX_STRING_BYTES
            .checked_sub(total_bytes)
            .ok_or_else(|| negative_errno(libc::E2BIG))?;
        let bytes = read_c_string(memory, pointer, remaining).map_err(read_c_string_errno)?;
        total_bytes = total_bytes
            .checked_add(bytes.len() + 1)
            .ok_or_else(|| negative_errno(libc::E2BIG))?;
        result.push(String::from_utf8(bytes).map_err(|_| negative_errno(libc::EINVAL))?);
    }
    Err(negative_errno(libc::E2BIG))
}

fn range_is_valid(memory: &GuestMemory, address: u64, length: u64) -> bool {
    address >= memory.guest_base()
        && address
            .checked_add(length)
            .is_some_and(|end| end <= memory.guest_end())
}

fn align_up(value: u64, alignment: u64) -> Option<u64> {
    value
        .checked_add(alignment - 1)
        .map(|value| value & !(alignment - 1))
}

fn continue_with(result: i64) -> SyscallAction {
    SyscallAction::Continue {
        result,
        segment: None,
    }
}

fn io_error(error: std::io::Error) -> i64 {
    negative_errno(error.raw_os_error().unwrap_or(libc::EIO))
}

const fn negative_errno(errno: libc::c_int) -> i64 {
    -(errno as i64)
}

