    #[test]
    fn proc_root_real_receive_refusal_preserves_guest_buffers_and_fd_slots() {
        use std::os::unix::net::UnixDatagram;

        let directory = TestDir::new();
        for path in [
            "/proc/self",
            "/proc/self/task",
            "/proc/self/fd",
            "/proc/cpuinfo",
        ] {
            let mut state = test_state(&directory.0);
            let mut memory = GuestMemory::new(0, 0x2000).unwrap();
            let (sender, receiver) = UnixDatagram::pair().unwrap();
            let receiver_file = std::fs::File::from(std::os::fd::OwnedFd::from(receiver));
            assert_eq!(
                insert_file_with_flags(&mut state, receiver_file, false, None),
                3
            );
            let root_file = std::fs::File::open("/proc").unwrap();
            let unsupported_file = std::fs::File::open(path).unwrap();
            let descriptors = [root_file.as_raw_fd(), unsupported_file.as_raw_fd()];
            let mut control = [0_usize; 4];
            let mut payload = b'x';
            let mut vector = libc::iovec {
                iov_base: std::ptr::from_mut(&mut payload).cast(),
                iov_len: 1,
            };
            let mut message: libc::msghdr = unsafe { std::mem::zeroed() };
            message.msg_iov = &mut vector;
            message.msg_iovlen = 1;
            message.msg_control = control.as_mut_ptr().cast();
            message.msg_controllen = unsafe { libc::CMSG_SPACE(8) } as usize;
            unsafe {
                let header = libc::CMSG_FIRSTHDR(&message);
                (*header).cmsg_level = libc::SOL_SOCKET;
                (*header).cmsg_type = libc::SCM_RIGHTS;
                (*header).cmsg_len = libc::CMSG_LEN(8) as usize;
                std::ptr::copy_nonoverlapping(
                    descriptors.as_ptr().cast::<u8>(),
                    libc::CMSG_DATA(header),
                    8,
                );
                assert_eq!(libc::sendmsg(sender.as_raw_fd(), &message, 0), 1);
            }
            drop(root_file);
            drop(unsupported_file);
            memory.write(0, &[0xa5; 0x1000]).unwrap();
            let vector = libc::iovec {
                iov_base: 0x400_usize as *mut libc::c_void,
                iov_len: 128,
            };
            assert_eq!(write_struct(&mut memory, 0x200, &vector), 0);
            let mut guest_message: libc::msghdr = unsafe { std::mem::zeroed() };
            guest_message.msg_iov = 0x200_usize as *mut libc::iovec;
            guest_message.msg_iovlen = 1;
            guest_message.msg_control = 0x800_usize as *mut libc::c_void;
            guest_message.msg_controllen = 128;
            assert_eq!(write_struct(&mut memory, 0x100, &guest_message), 0);
            let mut expected = [0; 0x1000];
            memory.read(0, &mut expected).unwrap();
            expected[0x400] = b'x';
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_recvmsg,
                    [3, 0x100, libc::MSG_CMSG_CLOEXEC as u64, 0, 0, 0]
                ),
                negative_errno(libc::EACCES),
                "{path}"
            );
            let mut actual = [0; 0x1000];
            memory.read(0, &mut actual).unwrap();
            assert_eq!(
                actual, expected,
                "{path}: only the received payload byte may change"
            );
            assert_eq!(state.files.keys().copied().collect::<Vec<_>>(), vec![3]);
            assert!(state.proc_files.is_empty());
            assert!(state.cloexec_fds.is_empty());
            assert_eq!(
                state.fd_object_inodes.keys().copied().collect::<Vec<_>>(),
                vec![3]
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_recvmsg,
                    [3, 0x100, 0, 0, 0, 0]
                ),
                negative_errno(libc::EAGAIN)
            );
            memory.read(0, &mut actual).unwrap();
            assert_eq!(actual, expected);
            assert_eq!(
                insert_file_with_flags(&mut state, std::fs::File::open("/").unwrap(), false, None),
                4
            );
            assert!(!state.proc_files.contains_key(&4));
        }
    }

    struct TestDir(PathBuf);

    impl TestDir {
        fn new() -> Self {
            let id = NEXT_TEST_DIR.fetch_add(1, Ordering::Relaxed);
            // AF_UNIX paths are limited to 107 bytes on Linux. The validation
            // checkout deliberately has a long TMPDIR, so keep this fixture's
            // private, nonce-qualified directory directly under /tmp.
            let path =
                Path::new("/tmp").join(format!("reverie-kvm-fs-{}-{id}", std::process::id()));
            std::fs::create_dir(&path).unwrap();
            Self(path)
        }
    }

    impl Drop for TestDir {
        fn drop(&mut self) {
            std::fs::remove_dir_all(&self.0).unwrap();
        }
    }

    pub(super) fn test_state(cwd: &Path) -> LoadedStaticElf {
        let mut state = native_loaded_state(cwd);
        state.children = ChildWaitContext::test_root();
        state
    }

    fn prctl(state: &mut LoadedStaticElf, args: &[u64; 6]) -> i64 {
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        super::prctl(&mut memory, state, args)
    }

    fn test_signal_action(
        state: &LoadedStaticElf,
        signal: libc::c_int,
    ) -> Option<[u8; KERNEL_SIGACTION_SIZE]> {
        state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .dispositions
            .get(&signal)
            .copied()
            .map(KernelSigaction::encode)
    }

    fn test_signal_actions(
        state: &LoadedStaticElf,
    ) -> BTreeMap<libc::c_int, [u8; KERNEL_SIGACTION_SIZE]> {
        state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .dispositions
            .iter()
            .map(|(&signal, &action)| (signal, action.encode()))
            .collect()
    }

    fn test_install_signal_action(
        state: &LoadedStaticElf,
        signal: libc::c_int,
        action: [u8; KERNEL_SIGACTION_SIZE],
    ) {
        state
            .process_signals
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .dispositions
            .insert(signal, KernelSigaction::decode(action));
    }

    fn test_block_signal(state: &mut LoadedStaticElf, signal: libc::c_int) {
        state.thread_signals.lock().blocked.insert(signal);
    }

    fn test_blocked_mask(state: &LoadedStaticElf) -> [u8; KERNEL_SIGSET_SIZE] {
        state.thread_signals.lock().blocked.to_bytes()
    }

    fn syscall_result(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        number: libc::c_long,
        args: [u64; 6],
    ) -> i64 {
        match execute_basic_syscall(memory, state, &SyscallRequest::new(number as u64, args)) {
            SyscallAction::Continue {
                result,
                segment: None,
            } => result,
            SyscallAction::Continue {
                segment: Some(_), ..
            } => {
                panic!("filesystem syscall changed a segment base")
            }
            SyscallAction::Exit(code) => panic!("filesystem syscall exited with {code:?}"),
            SyscallAction::Failure(error) => {
                panic!("filesystem syscall failed internally: {error}")
            }
        }
    }

    fn syscall_result_with_output(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        output: &mut CapturedOutput,
        number: libc::c_long,
        args: [u64; 6],
    ) -> i64 {
        match execute_basic_syscall_with_output(
            memory,
            state,
            &SyscallRequest::new(number as u64, args),
            None,
            Some(output),
        ) {
            SyscallAction::Continue {
                result,
                segment: None,
            } => result,
            SyscallAction::Continue {
                segment: Some(_), ..
            } => panic!("filesystem syscall changed a segment base"),
            SyscallAction::Exit(code) => panic!("filesystem syscall exited with {code:?}"),
            SyscallAction::Failure(error) => {
                panic!("filesystem syscall failed internally: {error}")
            }
        }
    }

    fn read_struct<T>(memory: &GuestMemory, address: u64) -> T {
        let mut value = std::mem::MaybeUninit::<T>::zeroed();
        // SAFETY: value is writable for exactly size_of::<T>() bytes.
        let bytes = unsafe {
            std::slice::from_raw_parts_mut(
                value.as_mut_ptr().cast::<u8>(),
                std::mem::size_of::<T>(),
            )
        };
        memory.read(address, bytes).unwrap();
        // SAFETY: zeroed storage was fully initialized by memory.read.
        unsafe { value.assume_init() }
    }

    fn control_message(level: libc::c_int, kind: libc::c_int, data: &[u8]) -> Vec<u8> {
        let header_space = cmsg_align(std::mem::size_of::<libc::cmsghdr>()).unwrap();
        let message_length = header_space + data.len();
        let mut control = vec![0; cmsg_align(message_length).unwrap()];
        let header = libc::cmsghdr {
            cmsg_len: message_length,
            cmsg_level: level,
            cmsg_type: kind,
        };
        let header_bytes = struct_bytes(&header);
        control[..header_bytes.len()].copy_from_slice(&header_bytes);
        control[header_space..message_length].copy_from_slice(data);
        control
    }

    fn rights_control(fds: &[libc::c_int]) -> Vec<u8> {
        let bytes = fds
            .iter()
            .flat_map(|fd| fd.to_ne_bytes())
            .collect::<Vec<_>>();
        control_message(libc::SOL_SOCKET, libc::SCM_RIGHTS, &bytes)
    }

    fn assert_stream_peer_closed(peer: &UnixStream) {
        let mut byte = 0_u8;
        // SAFETY: peer owns a live socket and byte is writable for one byte.
        let received = unsafe {
            libc::recv(
                peer.as_raw_fd(),
                std::ptr::from_mut(&mut byte).cast(),
                1,
                libc::MSG_DONTWAIT,
            )
        };
        assert_eq!(
            received,
            0,
            "owned socket endpoint remains open: {:?}",
            std::io::Error::last_os_error()
        );
    }

    fn control_rights(control: &[u8]) -> Vec<libc::c_int> {
        control_messages(control)
            .unwrap()
            .into_iter()
            .filter(|message| message.level == libc::SOL_SOCKET && message.kind == libc::SCM_RIGHTS)
            .flat_map(|message| {
                (message.data_offset..message.end)
                    .step_by(std::mem::size_of::<libc::c_int>())
                    .map(|offset| read_control_fd(control, offset).unwrap())
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    fn write_c_string(memory: &mut GuestMemory, address: u64, value: &str) {
        let mut bytes = value.as_bytes().to_vec();
        bytes.push(0);
        memory.write(address, &bytes).unwrap();
    }

    fn write_guest_iovecs(memory: &mut GuestMemory, address: u64, vectors: &[(u64, usize)]) {
        for (index, &(base, length)) in vectors.iter().enumerate() {
            let entry = libc::iovec {
                iov_base: base as usize as *mut libc::c_void,
                iov_len: length,
            };
            assert_eq!(
                write_struct(
                    memory,
                    address + (index * std::mem::size_of::<libc::iovec>()) as u64,
                    &entry
                ),
                0
            );
        }
    }

    /// Read the emulated working directory back through `getcwd`.
    fn current_directory(memory: &mut GuestMemory, state: &mut LoadedStaticElf) -> PathBuf {
        let buffer_address = 0x800;
        let result = syscall_result(
            memory,
            state,
            libc::SYS_getcwd,
            [buffer_address, 0x400, 0, 0, 0, 0],
        );
        assert!(result > 0, "getcwd failed: {result}");
        let mut bytes = vec![0u8; result as usize];
        memory.read(buffer_address, &mut bytes).unwrap();
        // getcwd includes the trailing NUL in its returned length.
        assert_eq!(bytes.pop(), Some(0));
        PathBuf::from(std::ffi::OsString::from_vec(bytes))
    }

    #[test]
    fn clock_gettime_advances_private_logical_clock_after_successful_write() {
        const TIME: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        for expected_nanoseconds in [0, 1] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_clock_gettime,
                    [libc::CLOCK_MONOTONIC as u64, TIME, 0, 0, 0, 0],
                ),
                0
            );
            let time: libc::timespec = read_struct(&memory, TIME);
            assert_eq!(time.tv_sec, 0);
            assert_eq!(time.tv_nsec, expected_nanoseconds);
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_gettime,
                [libc::CLOCK_MONOTONIC as u64, PAGE_SIZE, 0, 0, 0, 0,],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(state.logical_clock_ns, 2);
    }

    #[test]
    fn chdir_updates_cwd_and_resolves_relative_paths() {
        let root = TestDir::new();
        std::fs::create_dir(root.0.join("sub")).unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x2000).unwrap();

        // Relative chdir into an existing subdirectory.
        write_c_string(&mut memory, 0x100, "sub");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chdir,
                [0x100, 0, 0, 0, 0, 0]
            ),
            0
        );
        let expected = std::fs::canonicalize(root.0.join("sub")).unwrap();
        assert_eq!(current_directory(&mut memory, &mut state), expected);

        // A relative create now resolves against the new working directory.
        write_c_string(&mut memory, 0x100, "created");
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                0x100,
                (libc::O_CREAT | libc::O_WRONLY) as u64,
                0o644,
                0,
                0,
            ],
        );
        assert!(fd >= 0, "openat failed: {fd}");
        assert!(root.0.join("sub").join("created").exists());

        // Absolute chdir back to the root.
        let root_path = std::fs::canonicalize(&root.0).unwrap();
        write_c_string(&mut memory, 0x100, root_path.to_str().unwrap());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chdir,
                [0x100, 0, 0, 0, 0, 0]
            ),
            0
        );
        assert_eq!(current_directory(&mut memory, &mut state), root_path);
    }

    #[test]
    fn chdir_rejects_missing_and_nondirectory_targets() {
        let root = TestDir::new();
        std::fs::write(root.0.join("file"), b"x").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        write_c_string(&mut memory, 0x100, "missing");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chdir,
                [0x100, 0, 0, 0, 0, 0]
            ),
            negative_errno(libc::ENOENT)
        );

        write_c_string(&mut memory, 0x100, "file");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chdir,
                [0x100, 0, 0, 0, 0, 0]
            ),
            negative_errno(libc::ENOTDIR)
        );

        // chdir("") is ENOENT, matching Linux.
        write_c_string(&mut memory, 0x100, "");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chdir,
                [0x100, 0, 0, 0, 0, 0]
            ),
            negative_errno(libc::ENOENT)
        );
    }

    #[test]
    fn fchdir_follows_open_directory_descriptor() {
        let root = TestDir::new();
        std::fs::create_dir(root.0.join("sub")).unwrap();
        std::fs::write(root.0.join("sub").join("inside"), b"y").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x2000).unwrap();

        // fchdir onto a regular-file descriptor is ENOTDIR; a stale fd is EBADF.
        write_c_string(&mut memory, 0x100, "sub/inside");
        let file_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
        );
        assert!(file_fd >= 0, "openat file failed: {file_fd}");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchdir,
                [file_fd as u64, 0, 0, 0, 0, 0]
            ),
            negative_errno(libc::ENOTDIR)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchdir,
                [9999, 0, 0, 0, 0, 0]
            ),
            negative_errno(libc::EBADF)
        );

        // Open the subdirectory as a guest directory descriptor and fchdir to it.
        write_c_string(&mut memory, 0x100, "sub");
        let dir_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                0x100,
                (libc::O_RDONLY | libc::O_DIRECTORY) as u64,
                0,
                0,
                0,
            ],
        );
        assert!(dir_fd >= 0, "openat dir failed: {dir_fd}");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchdir,
                [dir_fd as u64, 0, 0, 0, 0, 0]
            ),
            0
        );
        let expected = std::fs::canonicalize(root.0.join("sub")).unwrap();
        assert_eq!(current_directory(&mut memory, &mut state), expected);

        // The cwd handle is independent of the source fd: closing it leaves the
        // working directory usable for later relative resolution.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [dir_fd as u64, 0, 0, 0, 0, 0]
            ),
            0
        );
        write_c_string(&mut memory, 0x100, "inside");
        let reopened = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
        );
        assert!(
            reopened >= 0,
            "relative open after close failed: {reopened}"
        );
    }

    fn open_with_flags(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        path: &str,
        flags: libc::c_int,
    ) -> i64 {
        write_c_string(memory, 0x100, path);
        syscall_result(
            memory,
            state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, 0x100, flags as u64, 0, 0, 0],
        )
    }

    fn open_readonly(memory: &mut GuestMemory, state: &mut LoadedStaticElf, path: &str) -> i64 {
        open_with_flags(memory, state, path, libc::O_RDONLY)
    }

    fn native_open_error(path: &str, flags: libc::c_int) -> Option<libc::c_int> {
        let path = CString::new(path).unwrap();
        // SAFETY: path is NUL-terminated. Supplying mode is valid even when
        // O_CREAT is absent; every successful descriptor is closed below.
        let fd = unsafe { libc::open(path.as_ptr(), flags | libc::O_CLOEXEC, 0o600) };
        if fd < 0 {
            std::io::Error::last_os_error().raw_os_error()
        } else {
            // SAFETY: open returned a new owned descriptor.
            assert_eq!(unsafe { libc::close(fd) }, 0);
            None
        }
    }

    fn native_open_status(path: &str, flags: libc::c_int) -> Result<libc::c_int, libc::c_int> {
        let path = CString::new(path).unwrap();
        // SAFETY: path is NUL-terminated. Supplying mode is valid even when
        // O_CREAT is ignored under O_PATH.
        let fd = unsafe { libc::open(path.as_ptr(), flags | libc::O_CLOEXEC, 0o600) };
        if fd < 0 {
            return Err(std::io::Error::last_os_error()
                .raw_os_error()
                .unwrap_or(libc::EIO));
        }
        // SAFETY: fd is live and F_GETFL has no third argument.
        let status = unsafe { libc::fcntl(fd, libc::F_GETFL) };
        let status_error = (status < 0).then(|| {
            std::io::Error::last_os_error()
                .raw_os_error()
                .unwrap_or(libc::EIO)
        });
        // SAFETY: fd was returned by open and is closed exactly once.
        assert_eq!(unsafe { libc::close(fd) }, 0);
        if let Some(error) = status_error {
            Err(error)
        } else {
            Ok(status)
        }
    }

    fn read_fd_to_end(memory: &mut GuestMemory, state: &mut LoadedStaticElf, fd: i64) -> Vec<u8> {
        let buffer = 0x1000;
        let mut content = Vec::new();
        loop {
            let n = syscall_result(
                memory,
                state,
                libc::SYS_read,
                [fd as u64, buffer, 0x400, 0, 0, 0],
            );
            assert!(n >= 0, "read failed: {n}");
            if n == 0 {
                break;
            }
            let mut chunk = vec![0u8; n as usize];
            memory.read(buffer, &mut chunk).unwrap();
            content.extend_from_slice(&chunk);
        }
        content
    }

    #[test]
    fn close_range_closes_the_inclusive_descriptor_span() {
        const HIGH_WORD: u64 = 0x5a5a_5a5a_0000_0000;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        // Four live guest descriptors: 3, 4, 5, 6.
        let low = open_readonly(&mut memory, &mut state, "/proc/uptime");
        let mid = open_readonly(&mut memory, &mut state, "/proc/uptime");
        let high = open_readonly(&mut memory, &mut state, "/proc/uptime");
        let direct = open_readonly(&mut memory, &mut state, "/proc/uptime");
        assert_eq!([low, mid, high, direct], [3, 4, 5, 6]);

        // close consumes only the low descriptor word and removes the complete
        // synthetic-proc identity attached to the selected guest slot.
        assert_eq!(close(&mut state, HIGH_WORD | direct as u64), 0);
        assert!(!state.files.contains_key(&(direct as i32)));
        assert!(!state.proc_files.contains_key(&(direct as i32)));

        // close_range over [4, U32::MAX] closes both 4 and 5 but leaves 3 open.
        // High bits in both bounds and a high-only flags word are ignored, and
        // the open-ended bound must not iterate a four-billion-wide span.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [
                    HIGH_WORD | mid as u64,
                    HIGH_WORD | u64::from(u32::MAX),
                    HIGH_WORD,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert!(state.files.contains_key(&(low as i32)));
        assert!(!state.files.contains_key(&(mid as i32)));
        assert!(!state.files.contains_key(&(high as i32)));
        // Re-closing a descriptor the range already removed reports EBADF, the
        // same signal the syscall-quick-wins corpus cell probes via fcntl.
        assert_eq!(close(&mut state, mid as u64), negative_errno(libc::EBADF));

        // Truncation precedes bounds validation: this raw first value is greater
        // than last, but the low words are the same single-fd range.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [HIGH_WORD | low as u64, low as u64, 0, 0, 0, 0],
            ),
            0
        );
        assert!(state.files.is_empty());
    }

    #[test]
    fn close_range_validates_bounds_and_flags() {
        const HIGH_WORD: u64 = 0x5a5a_5a5a_0000_0000;
        const CLOSE_RANGE_CLOEXEC: u64 = 1 << 2;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        let low = open_readonly(&mut memory, &mut state, "/proc/uptime");
        let high = open_readonly(&mut memory, &mut state, "/proc/uptime");
        assert_eq!([low, high], [3, 4]);

        // Bounds are compared after truncation. Raw u64 ordering says the last
        // value is larger, but its low word is smaller, so neither live target
        // may be closed.
        let cloexec_before_invalid_order = state.cloexec_fds.clone();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [high as u64, HIGH_WORD | low as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert!(state.files.contains_key(&(low as i32)));
        assert!(state.files.contains_key(&(high as i32)));
        assert_eq!(state.cloexec_fds, cloexec_before_invalid_order);

        // An unknown low flag bit is rejected despite unrelated high bits, and
        // the rejected operation leaves every candidate descriptor untouched.
        let cloexec_before_invalid_flags = state.cloexec_fds.clone();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [
                    HIGH_WORD | low as u64,
                    HIGH_WORD | high as u64,
                    HIGH_WORD | 1,
                    0,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EINVAL)
        );
        assert!(state.files.contains_key(&(low as i32)));
        assert!(state.files.contains_key(&(high as i32)));
        assert_eq!(state.cloexec_fds, cloexec_before_invalid_flags);

        // A high-only flags word is zero after unsigned-int decoding.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [
                    HIGH_WORD | low as u64,
                    HIGH_WORD | low as u64,
                    HIGH_WORD,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert!(!state.files.contains_key(&(low as i32)));
        assert!(state.files.contains_key(&(high as i32)));

        // CLOSE_RANGE_CLOEXEC marks the span close-on-exec instead of closing it.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [
                    HIGH_WORD | high as u64,
                    HIGH_WORD | high as u64,
                    HIGH_WORD | CLOSE_RANGE_CLOEXEC,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert!(
            state.files.contains_key(&(high as i32)),
            "CLOSE_RANGE_CLOEXEC must not close the descriptor"
        );
        assert!(state.cloexec_fds.contains(&(high as i32)));

        // UINT_MAX..UINT_MAX is a valid empty range, including with high aliases.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close_range,
                [
                    HIGH_WORD | u64::from(u32::MAX),
                    u64::from(u32::MAX),
                    HIGH_WORD,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert!(
            state.files.contains_key(&(high as i32)),
            "an empty UINT_MAX range must not close another descriptor"
        );
        assert!(
            state.cloexec_fds.contains(&(high as i32)),
            "an empty UINT_MAX range must not clear an existing CLOEXEC mark"
        );
    }

    #[test]
    fn seccomp_reports_unsupported_matching_detcore() {
        const SECCOMP_SET_MODE_STRICT: u64 = 0;
        const SECCOMP_SET_MODE_FILTER: u64 = 1;
        const SECCOMP_GET_ACTION_AVAIL: u64 = 2;
        const SECCOMP_GET_NOTIF_SIZES: u64 = 3;
        const SECCOMP_FILTER_FLAG_TSYNC: u64 = 1;
        const ARGS_PTR: u64 = 0x1000;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        // The capability probe exercised by syscall_quick_wins.c: a
        // SECCOMP_GET_NOTIF_SIZES query with a non-null output buffer resolves
        // to EOPNOTSUPP, exactly as the golden ptrace/detcore backend reports.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [SECCOMP_GET_NOTIF_SIZES, 0, ARGS_PTR, 0, 0, 0],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );

        // An unknown operation is rejected with EINVAL before the unsupported
        // fallthrough.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [SECCOMP_GET_NOTIF_SIZES + 1, 0, ARGS_PTR, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );

        // SECCOMP_SET_MODE_STRICT must carry no flags and no args pointer.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [SECCOMP_SET_MODE_STRICT, 1, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [SECCOMP_SET_MODE_STRICT, 0, ARGS_PTR, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        // The strict-mode success path (no flags, no args) still reports the
        // backend-wide unsupported result rather than installing a policy.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [SECCOMP_SET_MODE_STRICT, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );

        // SECCOMP_SET_MODE_FILTER rejects unknown flag bits with EINVAL but
        // accepts the lone TSYNC flag (which then falls through to EFAULT on a
        // null program pointer, matching the kernel's argument ordering).
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [SECCOMP_SET_MODE_FILTER, 1 << 31, ARGS_PTR, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_seccomp,
                [
                    SECCOMP_SET_MODE_FILTER,
                    SECCOMP_FILTER_FLAG_TSYNC,
                    0,
                    0,
                    0,
                    0
                ],
            ),
            negative_errno(libc::EFAULT)
        );

        // Operations that require a non-null argument buffer report EFAULT when
        // it is null, ahead of the unsupported fallthrough.
        for op in [
            SECCOMP_SET_MODE_FILTER,
            SECCOMP_GET_ACTION_AVAIL,
            SECCOMP_GET_NOTIF_SIZES,
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_seccomp,
                    [op, 0, 0, 0, 0, 0],
                ),
                negative_errno(libc::EFAULT)
            );
        }
    }

    #[test]
    fn synthetic_proc_files_serve_deterministic_content() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        let fd = open_readonly(&mut memory, &mut state, "/proc/uptime");
        assert!(fd >= 0, "open /proc/uptime failed: {fd}");
        assert_eq!(read_fd_to_end(&mut memory, &mut state, fd), b"0.00 0.00\n");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [fd as u64, 0, 0, 0, 0, 0]
            ),
            0
        );
        // The descriptor is no longer tracked once closed.
        assert!(state.proc_files.is_empty());

        let fd = open_readonly(&mut memory, &mut state, "/proc/meminfo");
        assert!(fd >= 0);
        let content = read_fd_to_end(&mut memory, &mut state, fd);
        assert!(
            content.starts_with(b"MemTotal:"),
            "{}",
            String::from_utf8_lossy(&content)
        );
        assert!(
            content
                .windows(b"MemTotal:         976562 kB\n".len())
                .any(|line| { line == b"MemTotal:         976562 kB\n" })
        );
        assert!(
            content
                .windows(b"MemFree:          976562 kB\n".len())
                .any(|line| { line == b"MemFree:          976562 kB\n" })
        );
        assert!(
            content
                .windows(b"MemAvailable:     976562 kB\n".len())
                .any(|line| line == b"MemAvailable:     976562 kB\n")
        );
    }

    #[test]
    fn synthetic_proc_snapshot_has_required_seals_and_readonly_description() {
        const PATH: u64 = 0x100;
        const BUFFER: u64 = 0x200;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        write_c_string(&mut memory, PATH, "/proc/uptime");
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH,
                (libc::O_RDONLY | libc::O_CLOEXEC) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_ACCMODE),
            i64::from(libc::O_RDONLY)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        let host_fd = state.files[&(fd as libc::c_int)].as_raw_fd();
        let mut host_stat = std::mem::MaybeUninit::<libc::stat>::zeroed();
        assert_eq!(unsafe { libc::fstat(host_fd, host_stat.as_mut_ptr()) }, 0);
        assert_eq!(unsafe { host_stat.assume_init() }.st_mode & 0o777, 0o444);
        let required =
            libc::F_SEAL_WRITE | libc::F_SEAL_GROW | libc::F_SEAL_SHRINK | libc::F_SEAL_SEAL;
        let observed = unsafe { libc::fcntl(host_fd, libc::F_GET_SEALS) };
        assert!(
            observed == required || observed == (required | LINUX_F_SEAL_EXEC),
            "unexpected synthetic proc seal policy: {observed:#x}"
        );

        memory.write(BUFFER, b"x").unwrap();
        for (number, args, expected) in [
            (
                libc::SYS_write,
                [fd as u64, BUFFER, 1, 0, 0, 0],
                negative_errno(libc::EBADF),
            ),
            (
                libc::SYS_pwrite64,
                [(1_u64 << 32) | fd as u64, BUFFER, 1, 0, 0, 0],
                negative_errno(libc::ESPIPE),
            ),
            (
                libc::SYS_ftruncate,
                [(1_u64 << 32) | fd as u64, 0, 0, 0, 0, 0],
                negative_errno(libc::EINVAL),
            ),
            (
                libc::SYS_fallocate,
                [fd as u64, 0, 0, 1, 0, 0],
                negative_errno(libc::EBADF),
            ),
        ] {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                expected,
                "syscall {number} unexpectedly accepted the read-only snapshot"
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pwrite64,
                [fd as u64, u64::MAX, 1, u64::MAX, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "negative offset validation must precede procfs positioning refusal"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                [
                    0,
                    PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    libc::MAP_SHARED as u64,
                    fd as u64,
                    0,
                ],
            ),
            negative_errno(libc::EACCES)
        );

        let expected = b"0.00 0.00\n";
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pread64,
                [fd as u64, BUFFER, expected.len() as u64, 0, 0, 0],
            ),
            expected.len() as i64
        );
        let mut actual = vec![0; expected.len()];
        memory.read(BUFFER, &mut actual).unwrap();
        assert_eq!(actual, expected);
    }

    #[test]
    fn synthetic_proc_seal_policy_accepts_only_supported_kernel_shapes() {
        // Reserve a currently unused bit to prove that an unexpected future
        // implicit seal is rejected rather than silently broadening policy.
        const HYPOTHETICAL_FUTURE_IMPLICIT_SEAL: libc::c_int = 0x40;
        let required =
            libc::F_SEAL_WRITE | libc::F_SEAL_GROW | libc::F_SEAL_SHRINK | libc::F_SEAL_SEAL;
        assert!(supported_synthetic_proc_seals(required));
        assert!(supported_synthetic_proc_seals(required | LINUX_F_SEAL_EXEC));
        assert!(!supported_synthetic_proc_seals(
            required & !libc::F_SEAL_WRITE
        ));
        assert!(
            !supported_synthetic_proc_seals(required | HYPOTHETICAL_FUTURE_IMPLICIT_SEAL),
            "an unexpected future implicit seal must fail closed"
        );
    }

    #[test]
    fn synthetic_proc_every_regular_surface_matches_native_pwrite_result() {
        const BUFFER: u64 = 0x200;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();
        memory.write(BUFFER, b"x").unwrap();
        for &path in SYNTHETIC_REGULAR_PROC_PATHS {
            let path = std::str::from_utf8(path).unwrap();
            let expected = synthetic_proc_pwrite_errno(synthetic_proc_inode(path.as_bytes()));
            let native = std::fs::File::open(path).unwrap();
            for (count, offset, expected_errno) in
                [(1, 0, expected), (0, 0, expected), (0, -1, libc::EINVAL)]
            {
                // SAFETY: native is live, the one-byte buffer is readable, and
                // count never exceeds its size. This is an O_RDONLY proc fd, so
                // the oracle cannot mutate the host file.
                let result = unsafe {
                    libc::pwrite(
                        native.as_raw_fd(),
                        b"x".as_ptr().cast::<libc::c_void>(),
                        count,
                        offset,
                    )
                };
                assert_eq!(
                    result, -1,
                    "native pwrite unexpectedly succeeded for {path}"
                );
                assert_eq!(
                    std::io::Error::last_os_error().raw_os_error(),
                    Some(expected_errno),
                    "native pwrite count={count} offset={offset} for {path}"
                );
            }

            let fd = open_readonly(&mut memory, &mut state, path);
            assert_eq!(fd, 3, "open {path}");
            for (count, offset, expected_errno) in [
                (1, 0_u64, expected),
                (0, 0, expected),
                (0, u64::MAX, libc::EINVAL),
            ] {
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_pwrite64,
                        [fd as u64, BUFFER, count, offset, 0, 0],
                    ),
                    negative_errno(expected_errno),
                    "guest pwrite count={count} offset={offset:#x} for {path}"
                );
            }
            assert_eq!(close(&mut state, fd as u64), 0);
        }
    }

    #[test]
    fn direct_synthetic_proc_opath_preserves_descriptor_and_error_semantics() {
        const PATH: u64 = 0x100;
        const BUFFER: u64 = 0x200;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        write_c_string(&mut memory, PATH, "/proc/uptime");
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH,
                (libc::O_PATH | libc::O_CLOEXEC) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert!(state.proc_files.contains_key(&(fd as libc::c_int)));
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_PATH),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        let high_fd = (1_u64 << 32) | fd as u64;
        memory.write(BUFFER, b"x").unwrap();
        for (number, args) in [
            (libc::SYS_read, [fd as u64, BUFFER, 1, 0, 0, 0]),
            (libc::SYS_pwrite64, [high_fd, BUFFER, 1, 0, 0, 0]),
            (libc::SYS_ftruncate, [high_fd, 0, 0, 0, 0, 0]),
            (libc::SYS_fchmod, [high_fd, 0o666, 0, 0, 0, 0]),
        ] {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                negative_errno(libc::EBADF),
                "syscall {number} must reject a synthetic proc O_PATH descriptor"
            );
        }
        for (number, args) in [
            (libc::SYS_pwrite64, [u64::MAX, u64::MAX, 0, u64::MAX, 0, 0]),
            (libc::SYS_pwrite64, [high_fd, u64::MAX, 0, u64::MAX, 0, 0]),
            (libc::SYS_ftruncate, [u64::MAX, u64::MAX, 0, 0, 0, 0]),
            (libc::SYS_ftruncate, [high_fd, u64::MAX, 0, 0, 0, 0]),
        ] {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                negative_errno(libc::EINVAL),
                "signed range validation must precede descriptor admission for syscall {number}"
            );
        }
        for flags in [libc::MAP_PRIVATE, libc::MAP_SHARED] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_mmap,
                    [
                        0,
                        PAGE_SIZE,
                        (libc::PROT_READ | libc::PROT_WRITE) as u64,
                        flags as u64,
                        high_fd,
                        0,
                    ],
                ),
                negative_errno(libc::EBADF)
            );
        }
    }

    #[test]
    fn synthetic_proc_direct_open_flags_and_nofollow_lifecycle_match_linux() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();

        for flags in [
            libc::O_RDONLY | libc::O_DIRECTORY,
            libc::O_WRONLY | libc::O_DIRECTORY,
            libc::O_RDWR | libc::O_DIRECTORY,
            libc::O_PATH | libc::O_DIRECTORY,
        ] {
            assert_eq!(
                open_with_flags(&mut memory, &mut state, "/proc/uptime", flags),
                negative_errno(libc::ENOTDIR),
                "O_DIRECTORY precedence for flags {flags:#x}"
            );
        }
        for access in [libc::O_RDONLY, libc::O_WRONLY, libc::O_RDWR] {
            assert_eq!(
                open_with_flags(
                    &mut memory,
                    &mut state,
                    "/proc/uptime",
                    access | libc::O_TRUNC,
                ),
                negative_errno(libc::EACCES),
                "O_TRUNC access refusal for access mode {access}"
            );
        }
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                "/proc/uptime",
                libc::O_RDONLY | libc::O_DIRECT,
            ),
            negative_errno(libc::EINVAL)
        );

        let retained = libc::O_NONBLOCK | libc::O_APPEND | libc::O_SYNC;
        let fd = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/uptime",
            libc::O_RDONLY | retained,
        );
        assert_eq!(fd, 3);
        let observed = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
        ) as libc::c_int;
        assert_eq!(observed & retained, retained);
        assert_eq!(close(&mut state, fd as u64), 0);

        let fd = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/uptime",
            libc::O_RDONLY | libc::O_NOFOLLOW,
        );
        assert_eq!(fd, 3);
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NOFOLLOW),
            0
        );
        assert!(state.synthetic_proc_nofollow_fds.contains(&(fd as i32)));
        assert_eq!(close(&mut state, fd as u64), 0);
        assert!(!state.synthetic_proc_nofollow_fds.contains(&(fd as i32)));

        let fd = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/uptime",
            libc::O_RDONLY | libc::O_DSYNC,
        );
        assert_eq!(fd, 3);
        let observed = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
        ) as libc::c_int;
        assert_eq!(observed & libc::O_DSYNC, libc::O_DSYNC);
        assert_eq!(close(&mut state, fd as u64), 0);

        let ignored_with_path = libc::O_PATH
            | libc::O_TRUNC
            | libc::O_DIRECT
            | libc::O_APPEND
            | libc::O_SYNC
            | libc::O_NONBLOCK;
        let fd = open_with_flags(&mut memory, &mut state, "/proc/uptime", ignored_with_path);
        assert_eq!(fd, 3);
        let observed = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
        ) as libc::c_int;
        assert_ne!(observed & libc::O_PATH, 0);
        assert_eq!(observed & (retained | libc::O_DIRECT | libc::O_TRUNC), 0);
        assert!(!state.synthetic_proc_nofollow_fds.contains(&(fd as i32)));
        assert_eq!(close(&mut state, fd as u64), 0);

        let nofollow = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/uptime",
            ignored_with_path | libc::O_NOFOLLOW,
        );
        assert_eq!(nofollow, 3);
        let observed = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [nofollow as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
        ) as libc::c_int;
        assert_eq!(
            observed & (libc::O_PATH | libc::O_NOFOLLOW),
            libc::O_PATH | libc::O_NOFOLLOW
        );
        assert_eq!(observed & (retained | libc::O_DIRECT | libc::O_TRUNC), 0);
        assert_eq!(
            file_mode(&state.files[&(nofollow as i32)]).unwrap() & libc::S_IFMT,
            libc::S_IFREG
        );
        assert!(
            state
                .synthetic_proc_nofollow_fds
                .contains(&(nofollow as i32))
        );

        let duplicate = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [nofollow as u64, 0, 0, 0, 0, 0],
        );
        assert_eq!(duplicate, 4);
        assert!(
            state
                .synthetic_proc_nofollow_fds
                .contains(&(duplicate as i32))
        );
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [duplicate as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NOFOLLOW),
            0
        );
        let fcntl_copy = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [nofollow as u64, libc::F_DUPFD as u64, 6, 0, 0, 0],
        );
        assert_eq!(fcntl_copy, 6);
        assert!(
            state
                .synthetic_proc_nofollow_fds
                .contains(&(fcntl_copy as i32))
        );
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fcntl_copy as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NOFOLLOW),
            0
        );

        let cloexec_nofollow = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/uptime",
            libc::O_PATH | libc::O_NOFOLLOW | libc::O_CLOEXEC,
        );
        assert_eq!(cloexec_nofollow, 5);
        assert!(
            state
                .synthetic_proc_nofollow_fds
                .contains(&(cloexec_nofollow as i32))
        );

        let mut child = state.try_clone_for_fork(2).unwrap();
        assert!(
            child
                .synthetic_proc_nofollow_fds
                .contains(&(nofollow as i32))
        );
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut child,
                libc::SYS_fcntl,
                [nofollow as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NOFOLLOW),
            0
        );
        let mut replacement = test_state(&root.0);
        replacement.inherit_process_state(child);
        assert!(
            replacement
                .synthetic_proc_nofollow_fds
                .contains(&(nofollow as i32))
        );
        assert!(
            replacement
                .synthetic_proc_nofollow_fds
                .contains(&(fcntl_copy as i32))
        );
        assert!(!replacement.files.contains_key(&(cloexec_nofollow as i32)));
        assert!(
            !replacement
                .synthetic_proc_nofollow_fds
                .contains(&(cloexec_nofollow as i32))
        );
        assert_ne!(
            syscall_result(
                &mut memory,
                &mut replacement,
                libc::SYS_fcntl,
                [nofollow as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NOFOLLOW),
            0
        );
    }

    #[test]
    fn synthetic_proc_tmpfile_admission_precedes_every_path_and_descriptor_resolution() {
        fn call_openat(
            memory: &mut GuestMemory,
            state: &mut LoadedStaticElf,
            dirfd: libc::c_int,
            address: u64,
            flags: libc::c_int,
        ) -> i64 {
            syscall_result(
                memory,
                state,
                libc::SYS_openat,
                [dirfd as u64, address, flags as u64, 0, 0, 0],
            )
        }

        fn check_path(
            memory: &mut GuestMemory,
            state: &mut LoadedStaticElf,
            dirfd: libc::c_int,
            path: &str,
            flags: libc::c_int,
            expected: libc::c_int,
        ) {
            write_c_string(memory, 0x100, path);
            assert_eq!(
                call_openat(memory, state, dirfd, 0x100, flags),
                negative_errno(expected),
                "path={path:?} dirfd={dirfd} flags={flags:#x}"
            );
        }

        let root = TestDir::new();
        std::fs::write(root.0.join("ordinary"), b"x").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        let ordinary = open_with_flags(&mut memory, &mut state, "ordinary", libc::O_RDONLY);
        let proc_file = open_readonly(&mut memory, &mut state, "/proc/uptime");
        assert_eq!((ordinary, proc_file), (3, 4));

        let private_tmpfile = (libc::O_TMPFILE & !libc::O_DIRECTORY) as libc::c_int;
        let invalid = [
            libc::O_RDONLY | libc::O_TMPFILE,
            private_tmpfile,
            libc::O_WRONLY | private_tmpfile,
            libc::O_WRONLY | libc::O_TMPFILE | libc::O_CREAT,
            libc::O_RDWR | libc::O_TMPFILE | libc::O_CREAT,
            libc::O_ACCMODE | libc::O_TMPFILE | libc::O_CREAT,
        ];
        let controls = [
            libc::O_WRONLY | libc::O_TMPFILE,
            libc::O_RDWR | libc::O_TMPFILE,
            libc::O_ACCMODE | libc::O_TMPFILE,
            libc::O_PATH | libc::O_TMPFILE,
            libc::O_RDONLY | libc::O_DIRECTORY,
        ];

        let bad_address = state.mmap_limit + PAGE_SIZE;
        for flags in invalid {
            assert_eq!(
                call_openat(&mut memory, &mut state, libc::AT_FDCWD, bad_address, flags,),
                negative_errno(libc::EINVAL),
                "bad pointer invalid flags={flags:#x}"
            );
        }
        for flags in controls {
            assert_eq!(
                call_openat(&mut memory, &mut state, libc::AT_FDCWD, bad_address, flags,),
                negative_errno(libc::EFAULT),
                "bad pointer control flags={flags:#x}"
            );
        }

        for (path, dirfd, control_error) in [
            ("", libc::AT_FDCWD, libc::ENOENT),
            ("missing", GUEST_NOFILE_LIMIT, libc::EBADF),
            ("missing", libc::AT_FDCWD, libc::ENOENT),
            ("/proc/self/fdinfo/999", libc::AT_FDCWD, libc::ENOENT),
            ("/proc/self/fd/999", libc::AT_FDCWD, libc::ENOENT),
        ] {
            for flags in invalid {
                check_path(&mut memory, &mut state, dirfd, path, flags, libc::EINVAL);
            }
            for flags in controls {
                check_path(&mut memory, &mut state, dirfd, path, flags, control_error);
            }
        }

        for path in [
            "/proc/uptime".to_owned(),
            format!("/proc/self/fdinfo/{ordinary}"),
            format!("/proc/self/fd/{proc_file}"),
        ] {
            for flags in invalid {
                check_path(
                    &mut memory,
                    &mut state,
                    libc::AT_FDCWD,
                    &path,
                    flags,
                    libc::EINVAL,
                );
            }
            for flags in controls {
                check_path(
                    &mut memory,
                    &mut state,
                    libc::AT_FDCWD,
                    &path,
                    flags,
                    libc::ENOTDIR,
                );
            }
        }
    }

    #[test]
    fn synthetic_proc_ordinary_opath_ignored_flags_match_native() {
        let root = TestDir::new();
        let regular = root.0.join("ordinary");
        std::fs::write(&regular, b"x").unwrap();
        let regular = regular.to_str().unwrap();
        let directory = root.0.to_str().unwrap();
        let missing = root.0.join("missing");
        let missing = missing.to_str().unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        let private_tmpfile = libc::O_TMPFILE & !libc::O_DIRECTORY;
        let extras = [
            libc::O_WRONLY,
            libc::O_RDWR,
            libc::O_ACCMODE,
            libc::O_CREAT,
            libc::O_EXCL,
            libc::O_TRUNC,
            libc::O_DIRECT,
            libc::O_APPEND,
            libc::O_SYNC,
            libc::O_NONBLOCK,
            libc::O_NOATIME,
            private_tmpfile,
        ];

        let bad_address = state.mmap_limit + PAGE_SIZE;
        for extra in extras {
            let flags = libc::O_PATH | extra;
            // SAFETY: the intentionally invalid pointer is passed unchanged to
            // the kernel to establish native pathname-copy precedence.
            let native = unsafe {
                libc::syscall(
                    libc::SYS_openat,
                    libc::AT_FDCWD,
                    usize::MAX as *const libc::c_char,
                    flags,
                    0o600,
                )
            };
            assert_eq!(native, -1);
            assert_eq!(
                std::io::Error::last_os_error().raw_os_error(),
                Some(libc::EFAULT)
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_openat,
                    [
                        libc::AT_FDCWD as u64,
                        bad_address,
                        flags as u64,
                        0o600,
                        0,
                        0,
                    ],
                ),
                negative_errno(libc::EFAULT),
                "bad pointer O_PATH extra={extra:#x}"
            );

            assert_eq!(
                native_open_status(missing, flags),
                Err(libc::ENOENT),
                "native missing O_PATH extra={extra:#x}"
            );
            assert_eq!(
                open_with_flags(&mut memory, &mut state, missing, flags),
                negative_errno(libc::ENOENT),
                "guest missing O_PATH extra={extra:#x}"
            );

            for path in [regular, directory] {
                let native_status = native_open_status(path, flags).unwrap();
                let guest = open_with_flags(&mut memory, &mut state, path, flags);
                assert!(
                    guest >= 0,
                    "guest O_PATH path={path} extra={extra:#x}: {guest}"
                );
                let guest_status = syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_fcntl,
                    [guest as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
                );
                assert_eq!(
                    guest_status,
                    i64::from(native_status),
                    "O_PATH status path={path} extra={extra:#x}"
                );
                assert_eq!(close(&mut state, guest as u64), 0);
            }
        }

        for (path, flags) in [
            (regular, libc::O_PATH | libc::O_NOFOLLOW | libc::O_CLOEXEC),
            (directory, libc::O_PATH | libc::O_NOFOLLOW | libc::O_CLOEXEC),
            (
                directory,
                libc::O_PATH | libc::O_DIRECTORY | libc::O_CLOEXEC,
            ),
        ] {
            let path_c = CString::new(path).unwrap();
            // SAFETY: path_c is NUL-terminated and each successful descriptor
            // is closed below.
            let native = unsafe { libc::open(path_c.as_ptr(), flags, 0o600) };
            assert!(native >= 0, "native preserved O_PATH flags={flags:#x}");
            // SAFETY: native is live and these fcntl operations take no third
            // argument.
            let native_status = unsafe { libc::fcntl(native, libc::F_GETFL) };
            let native_descriptor = unsafe { libc::fcntl(native, libc::F_GETFD) };
            let guest = open_with_flags(&mut memory, &mut state, path, flags);
            assert!(
                guest >= 0,
                "guest preserved O_PATH flags={flags:#x}: {guest}"
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_fcntl,
                    [guest as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
                ),
                i64::from(native_status)
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_fcntl,
                    [guest as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
                ),
                i64::from(native_descriptor)
            );
            // SAFETY: native was returned by open and is closed exactly once.
            assert_eq!(unsafe { libc::close(native) }, 0);
            assert_eq!(close(&mut state, guest as u64), 0);
        }
        assert_eq!(
            native_open_status(regular, libc::O_PATH | libc::O_DIRECTORY),
            Err(libc::ENOTDIR)
        );
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                regular,
                libc::O_PATH | libc::O_DIRECTORY,
            ),
            negative_errno(libc::ENOTDIR)
        );
    }

    #[test]
    fn synthetic_proc_direct_combined_open_matrix_preserves_policy_and_native_ordering() {
        // Native EACCES rows are credential-sensitive. The KVM guest separately
        // models uid 0 and keeps its carriers immutable regardless of the
        // supervisor identity; compare those native rows only under non-root.
        // SAFETY: geteuid has no arguments or memory-safety preconditions.
        let supervisor_is_nonroot = unsafe { libc::geteuid() } != 0;
        const CASES: &[(&str, libc::c_int, Option<libc::c_int>, Option<libc::c_int>)] = &[
            (
                "read-nofollow",
                libc::O_RDONLY | libc::O_NOFOLLOW,
                None,
                Some(libc::ELOOP),
            ),
            (
                "write-nofollow",
                libc::O_WRONLY | libc::O_NOFOLLOW,
                Some(libc::EACCES),
                Some(libc::ELOOP),
            ),
            (
                "truncate-nofollow",
                libc::O_RDONLY | libc::O_TRUNC | libc::O_NOFOLLOW,
                Some(libc::EACCES),
                Some(libc::ELOOP),
            ),
            (
                "direct-nofollow",
                libc::O_RDONLY | libc::O_DIRECT | libc::O_NOFOLLOW,
                Some(libc::EINVAL),
                Some(libc::ELOOP),
            ),
            (
                "write-direct-nofollow",
                libc::O_WRONLY | libc::O_DIRECT | libc::O_NOFOLLOW,
                Some(libc::EACCES),
                Some(libc::ELOOP),
            ),
            (
                "read-directory-nofollow",
                libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "write-directory-nofollow",
                libc::O_WRONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "path-directory-nofollow",
                libc::O_PATH | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "readonly-tmpfile",
                libc::O_RDONLY | libc::O_TMPFILE,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "private-tmpfile-without-directory",
                libc::O_WRONLY | (libc::O_TMPFILE & !libc::O_DIRECTORY),
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "writeonly-tmpfile-create",
                libc::O_WRONLY | libc::O_TMPFILE | libc::O_CREAT,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "readwrite-tmpfile-create",
                libc::O_RDWR | libc::O_TMPFILE | libc::O_CREAT,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "access-three-tmpfile-create",
                libc::O_ACCMODE | libc::O_TMPFILE | libc::O_CREAT,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "readonly-tmpfile-nofollow",
                libc::O_RDONLY | libc::O_TMPFILE | libc::O_NOFOLLOW,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "readonly-tmpfile-truncate",
                libc::O_RDONLY | libc::O_TMPFILE | libc::O_TRUNC,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "readonly-tmpfile-direct",
                libc::O_RDONLY | libc::O_TMPFILE | libc::O_DIRECT,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "readonly-tmpfile-exclusive",
                libc::O_RDONLY | libc::O_TMPFILE | libc::O_EXCL,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "readonly-tmpfile-all-extras",
                libc::O_RDONLY
                    | libc::O_TMPFILE
                    | libc::O_NOFOLLOW
                    | libc::O_TRUNC
                    | libc::O_DIRECT
                    | libc::O_EXCL,
                Some(libc::EINVAL),
                Some(libc::EINVAL),
            ),
            (
                "writeonly-tmpfile",
                libc::O_WRONLY | libc::O_TMPFILE,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "readwrite-tmpfile",
                libc::O_RDWR | libc::O_TMPFILE,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "access-three-tmpfile",
                libc::O_ACCMODE | libc::O_TMPFILE,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "path-tmpfile",
                libc::O_PATH | libc::O_TMPFILE,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "path-tmpfile-all-extras",
                libc::O_PATH
                    | libc::O_TMPFILE
                    | libc::O_NOFOLLOW
                    | libc::O_TRUNC
                    | libc::O_DIRECT
                    | libc::O_EXCL,
                Some(libc::ENOTDIR),
                Some(libc::ENOTDIR),
            ),
            (
                "create-exclusive-read",
                libc::O_RDONLY | libc::O_CREAT | libc::O_EXCL,
                Some(libc::EEXIST),
                Some(libc::EEXIST),
            ),
            (
                "create-exclusive-write",
                libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL,
                Some(libc::EEXIST),
                Some(libc::EEXIST),
            ),
            (
                "create-exclusive-truncate",
                libc::O_RDONLY | libc::O_CREAT | libc::O_EXCL | libc::O_TRUNC,
                Some(libc::EEXIST),
                Some(libc::EEXIST),
            ),
            (
                "create-exclusive-direct-nofollow",
                libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL | libc::O_DIRECT | libc::O_NOFOLLOW,
                Some(libc::EEXIST),
                Some(libc::EEXIST),
            ),
            (
                "path-ignores-create-exclusive",
                libc::O_PATH
                    | libc::O_WRONLY
                    | libc::O_CREAT
                    | libc::O_EXCL
                    | libc::O_TRUNC
                    | libc::O_DIRECT,
                None,
                None,
            ),
        ];
        const CREATE_DIRECTORY_CASES: &[(&str, libc::c_int)] = &[
            (
                "create-directory",
                libc::O_RDONLY | libc::O_CREAT | libc::O_DIRECTORY,
            ),
            (
                "create-exclusive-directory-nofollow-direct",
                libc::O_RDWR
                    | libc::O_CREAT
                    | libc::O_EXCL
                    | libc::O_TRUNC
                    | libc::O_DIRECT
                    | libc::O_DIRECTORY
                    | libc::O_NOFOLLOW,
            ),
        ];

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        for &path in SYNTHETIC_REGULAR_PROC_PATHS {
            let path = std::str::from_utf8(path).unwrap();
            for &(label, flags, regular_error, mounts_error) in CASES {
                let expected = if path == "/proc/mounts" {
                    mounts_error
                } else {
                    regular_error
                };
                if expected != Some(libc::EACCES) || supervisor_is_nonroot {
                    let native_error = native_open_error(path, flags);
                    assert_eq!(
                        native_error, expected,
                        "native open matrix path={path} case={label}"
                    );
                }
                let guest = open_with_flags(&mut memory, &mut state, path, flags);
                match expected {
                    Some(error) => assert_eq!(
                        guest,
                        negative_errno(error),
                        "open matrix path={path} case={label}"
                    ),
                    None => {
                        assert!(guest >= 0, "open matrix path={path} case={label}: {guest}");
                        assert_eq!(close(&mut state, guest as u64), 0);
                    }
                }
            }
            for &(label, flags) in CREATE_DIRECTORY_CASES {
                let expected = synthetic_proc_create_directory_errno(
                    state.regular_create_directory_policy,
                    flags as u64,
                );
                assert_eq!(
                    native_open_error(path, flags),
                    Some(expected),
                    "native create-directory policy path={path} case={label}"
                );
                assert_eq!(
                    open_with_flags(&mut memory, &mut state, path, flags),
                    negative_errno(expected),
                    "guest create-directory policy path={path} case={label}"
                );
            }
        }
    }

    #[test]
    fn synthetic_proc_create_directory_policy_mapping_is_exact() {
        let plain = (libc::O_RDONLY | libc::O_CREAT | libc::O_DIRECTORY) as u64;
        let exclusive = plain | libc::O_EXCL as u64;
        let nofollow = plain | libc::O_NOFOLLOW as u64;

        for path in [b"/proc/uptime".as_slice(), b"/proc/mounts"] {
            for flags in [
                plain,
                exclusive,
                nofollow,
                exclusive | libc::O_NOFOLLOW as u64,
            ] {
                assert_eq!(
                    synthetic_proc_create_directory_errno(
                        RegularCreateDirectoryPolicy::EarlyEinval,
                        flags,
                    ),
                    libc::EINVAL,
                    "early policy path={} flags={flags:#x}",
                    String::from_utf8_lossy(path)
                );
            }
        }

        assert_eq!(
            synthetic_proc_create_directory_errno(
                RegularCreateDirectoryPolicy::LegacyLookup,
                plain,
            ),
            libc::ENOTDIR
        );
        assert_eq!(
            synthetic_proc_create_directory_errno(
                RegularCreateDirectoryPolicy::LegacyLookup,
                nofollow,
            ),
            libc::ENOTDIR
        );
        assert_eq!(
            synthetic_proc_create_directory_errno(
                RegularCreateDirectoryPolicy::LegacyLookup,
                plain,
            ),
            libc::ENOTDIR
        );
        assert_eq!(
            synthetic_proc_create_directory_errno(
                RegularCreateDirectoryPolicy::LegacyLookup,
                exclusive,
            ),
            libc::EEXIST
        );
        assert_eq!(
            synthetic_proc_create_directory_errno(
                RegularCreateDirectoryPolicy::LegacyLookup,
                nofollow,
            ),
            libc::ENOTDIR
        );
        assert_eq!(
            synthetic_proc_create_directory_errno(
                RegularCreateDirectoryPolicy::LegacyLookup,
                exclusive | libc::O_NOFOLLOW as u64,
            ),
            libc::EEXIST
        );
    }

    #[test]
    fn synthetic_proc_create_directory_policy_drives_guest_open() {
        let plain = libc::O_RDONLY | libc::O_CREAT | libc::O_DIRECTORY;
        let exclusive = plain | libc::O_EXCL;
        let nofollow = plain | libc::O_NOFOLLOW;
        for (policy, path, flags, expected) in [
            (
                RegularCreateDirectoryPolicy::EarlyEinval,
                "/proc/uptime",
                plain,
                libc::EINVAL,
            ),
            (
                RegularCreateDirectoryPolicy::EarlyEinval,
                "/proc/uptime",
                exclusive,
                libc::EINVAL,
            ),
            (
                RegularCreateDirectoryPolicy::EarlyEinval,
                "/proc/mounts",
                nofollow,
                libc::EINVAL,
            ),
            (
                RegularCreateDirectoryPolicy::LegacyLookup,
                "/proc/uptime",
                plain,
                libc::ENOTDIR,
            ),
            (
                RegularCreateDirectoryPolicy::LegacyLookup,
                "/proc/uptime",
                exclusive,
                libc::EEXIST,
            ),
            (
                RegularCreateDirectoryPolicy::LegacyLookup,
                "/proc/mounts",
                nofollow,
                libc::ENOTDIR,
            ),
            (
                RegularCreateDirectoryPolicy::LegacyLookup,
                "/proc/mounts",
                exclusive | libc::O_NOFOLLOW,
                libc::EEXIST,
            ),
        ] {
            let root = TestDir::new();
            let mut state = test_state(&root.0);
            state.regular_create_directory_policy = policy;
            let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
            assert_eq!(
                open_with_flags(&mut memory, &mut state, path, flags),
                negative_errno(expected),
                "policy={policy:?} path={path} flags={flags:#x}"
            );
        }

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        state.regular_create_directory_policy = RegularCreateDirectoryPolicy::LegacyLookup;
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                "/proc/mounts",
                libc::O_RDONLY | libc::O_NOFOLLOW,
            ),
            negative_errno(libc::ELOOP),
            "without O_DIRECTORY, /proc/mounts still reaches may_open's ELOOP"
        );
    }

    #[test]
    fn synthetic_proc_early_create_directory_precedes_every_resolution() {
        fn call_openat(
            memory: &mut GuestMemory,
            state: &mut LoadedStaticElf,
            dirfd: libc::c_int,
            address: u64,
            flags: libc::c_int,
        ) -> i64 {
            syscall_result(
                memory,
                state,
                libc::SYS_openat,
                [dirfd as u64, address, flags as u64, 0, 0, 0],
            )
        }

        fn check_path(
            memory: &mut GuestMemory,
            state: &mut LoadedStaticElf,
            dirfd: libc::c_int,
            path: &str,
            flags: libc::c_int,
            expected: libc::c_int,
        ) {
            write_c_string(memory, 0x100, path);
            assert_eq!(
                call_openat(memory, state, dirfd, 0x100, flags),
                negative_errno(expected),
                "path={path:?} dirfd={dirfd} flags={flags:#x}"
            );
        }

        let root = TestDir::new();
        std::fs::write(root.0.join("ordinary"), b"x").unwrap();
        let mut state = test_state(&root.0);
        state.regular_create_directory_policy = RegularCreateDirectoryPolicy::EarlyEinval;
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        let ordinary = open_with_flags(&mut memory, &mut state, "ordinary", libc::O_RDONLY);
        let proc_file = open_readonly(&mut memory, &mut state, "/proc/uptime");
        assert_eq!((ordinary, proc_file), (3, 4));

        let early = [
            libc::O_RDONLY | libc::O_CREAT | libc::O_DIRECTORY,
            libc::O_WRONLY | libc::O_CREAT | libc::O_DIRECTORY,
            libc::O_RDWR | libc::O_CREAT | libc::O_DIRECTORY,
            libc::O_ACCMODE | libc::O_CREAT | libc::O_DIRECTORY,
            libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL | libc::O_DIRECTORY,
        ];
        let path_control = libc::O_PATH | libc::O_CREAT | libc::O_DIRECTORY;
        let bad_address = state.mmap_limit + PAGE_SIZE;
        for flags in early {
            assert_eq!(
                call_openat(&mut memory, &mut state, libc::AT_FDCWD, bad_address, flags,),
                negative_errno(libc::EINVAL)
            );
        }
        assert_eq!(
            call_openat(
                &mut memory,
                &mut state,
                libc::AT_FDCWD,
                bad_address,
                path_control,
            ),
            negative_errno(libc::EFAULT)
        );

        for (path, dirfd, control_error) in [
            ("", libc::AT_FDCWD, libc::ENOENT),
            ("missing", GUEST_NOFILE_LIMIT, libc::EBADF),
            ("missing", libc::AT_FDCWD, libc::ENOENT),
            ("/proc/self/fdinfo/999", libc::AT_FDCWD, libc::ENOENT),
            ("/proc/self/fd/999", libc::AT_FDCWD, libc::ENOENT),
        ] {
            for flags in early {
                check_path(&mut memory, &mut state, dirfd, path, flags, libc::EINVAL);
            }
            check_path(
                &mut memory,
                &mut state,
                dirfd,
                path,
                path_control,
                control_error,
            );
        }
        for path in [
            "/proc/uptime".to_owned(),
            format!("/proc/self/fdinfo/{ordinary}"),
            format!("/proc/self/fd/{proc_file}"),
        ] {
            for flags in early {
                check_path(
                    &mut memory,
                    &mut state,
                    libc::AT_FDCWD,
                    &path,
                    flags,
                    libc::EINVAL,
                );
            }
            check_path(
                &mut memory,
                &mut state,
                libc::AT_FDCWD,
                &path,
                path_control,
                libc::ENOTDIR,
            );
        }
    }

    #[test]
    fn synthetic_proc_create_directory_policy_is_initialized_and_preserved() {
        let detected = initialize_regular_create_directory_policy().unwrap();
        assert_eq!(
            initialize_regular_create_directory_policy().unwrap(),
            detected
        );

        let root = TestDir::new();
        let state = test_state(&root.0);
        assert_eq!(state.regular_create_directory_policy, detected);
        let child = state.try_clone_for_fork(2).unwrap();
        assert_eq!(child.regular_create_directory_policy, detected);

        let mut replacement = test_state(&root.0);
        replacement.regular_create_directory_policy = match detected {
            RegularCreateDirectoryPolicy::EarlyEinval => RegularCreateDirectoryPolicy::LegacyLookup,
            RegularCreateDirectoryPolicy::LegacyLookup => RegularCreateDirectoryPolicy::EarlyEinval,
        };
        replacement.inherit_process_state(state);
        assert_eq!(replacement.regular_create_directory_policy, detected);
    }

    #[test]
    fn synthetic_proc_nofollow_metadata_tracks_replacement_and_shared_tables() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        let marked = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/uptime",
            libc::O_PATH | libc::O_NOFOLLOW,
        );
        let unmarked = open_with_flags(&mut memory, &mut state, "/proc/uptime", libc::O_PATH);
        assert_eq!((marked, unmarked), (3, 4));

        let marked_copy = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup3,
            [marked as u64, 5, 0, 0, 0, 0],
        );
        assert_eq!(marked_copy, 5);
        assert!(state.synthetic_proc_nofollow_fds.contains(&5));

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup2,
                [unmarked as u64, marked as u64, 0, 0, 0, 0],
            ),
            marked
        );
        assert!(!state.synthetic_proc_nofollow_fds.contains(&(marked as i32)));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [marked_copy as u64, unmarked as u64, 0, 0, 0, 0],
            ),
            unmarked
        );
        assert!(
            state
                .synthetic_proc_nofollow_fds
                .contains(&(unmarked as i32))
        );

        for (fd, expected) in [
            (marked, 0),
            (unmarked, libc::O_NOFOLLOW),
            (marked_copy, libc::O_NOFOLLOW),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_fcntl,
                    [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
                ) & i64::from(libc::O_NOFOLLOW),
                i64::from(expected),
                "replacement metadata for fd {fd}"
            );
        }

        let shared = FileTableState::try_from_elf(&state).unwrap();
        assert_eq!(
            shared.synthetic_proc_nofollow_fds,
            state.synthetic_proc_nofollow_fds
        );
        let mut round_trip = test_state(&root.0);
        shared.install(&mut round_trip).unwrap();
        assert_eq!(
            round_trip.synthetic_proc_nofollow_fds,
            state.synthetic_proc_nofollow_fds
        );
        for (fd, expected) in [
            (marked, 0),
            (unmarked, libc::O_NOFOLLOW),
            (marked_copy, libc::O_NOFOLLOW),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut round_trip,
                    libc::SYS_fcntl,
                    [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
                ) & i64::from(libc::O_NOFOLLOW),
                i64::from(expected),
                "shared-table metadata for fd {fd}"
            );
        }
    }

    #[test]
    fn synthetic_proc_open_clears_stale_nofollow_metadata_on_fd_reuse() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        let next_fd = 3;
        assert!(!state.files.contains_key(&next_fd));
        state.synthetic_proc_nofollow_fds.insert(next_fd);

        let fd = open_with_flags(&mut memory, &mut state, "/proc/uptime", libc::O_RDONLY);
        assert_eq!(fd, i64::from(next_fd));
        assert!(state.proc_files.contains_key(&next_fd));
        assert!(
            !state.synthetic_proc_nofollow_fds.contains(&next_fd),
            "a non-O_NOFOLLOW allocation must clear stale metadata for its reused fd"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            ) & i64::from(libc::O_NOFOLLOW),
            0
        );
    }

    #[test]
    fn synthetic_proc_dup_and_reopen_preserve_description_semantics_and_seals() {
        const PATH: u64 = 0x100;
        const BUFFER: u64 = 0x200;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();
        write_c_string(&mut memory, PATH, "/proc/uptime");
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH,
                (libc::O_RDONLY | libc::O_CLOEXEC) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [fd as u64, BUFFER, 2, 0, 0, 0],
            ),
            2
        );
        let duplicate = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [fd as u64, 0, 0, 0, 0, 0],
        );
        assert_eq!(duplicate, 4);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [duplicate as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            0,
            "dup must clear the descriptor-local close-on-exec bit"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [duplicate as u64, BUFFER, 3, 0, 0, 0],
            ),
            3
        );
        let mut shared_offset = [0; 3];
        memory.read(BUFFER, &mut shared_offset).unwrap();
        assert_eq!(&shared_offset, b"00 ");

        write_c_string(&mut memory, PATH, &format!("/proc/self/fd/{fd}"));
        let reopened = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH,
                (libc::O_RDONLY | libc::O_CLOEXEC) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(reopened, 5);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [reopened as u64, BUFFER, 2, 0, 0, 0],
            ),
            2
        );
        let mut fresh_offset = [0; 2];
        memory.read(BUFFER, &mut fresh_offset).unwrap();
        assert_eq!(&fresh_offset, b"0.");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [reopened as u64, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );

        let inode = state.proc_files[&(fd as libc::c_int)];
        for alias in [duplicate, reopened] {
            assert_eq!(state.proc_files.get(&(alias as libc::c_int)), Some(&inode));
            let host_fd = state.files[&(alias as libc::c_int)].as_raw_fd();
            let required =
                libc::F_SEAL_WRITE | libc::F_SEAL_GROW | libc::F_SEAL_SHRINK | libc::F_SEAL_SEAL;
            let observed = unsafe { libc::fcntl(host_fd, libc::F_GET_SEALS) };
            assert!(
                observed == required || observed == (required | LINUX_F_SEAL_EXEC),
                "unexpected alias seal policy: {observed:#x}"
            );
            assert_eq!(
                unsafe { libc::fcntl(host_fd, libc::F_GETFL) } & libc::O_ACCMODE,
                libc::O_RDONLY
            );
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmod,
                [(1_u64 << 32) | fd as u64, 0o666, 0, 0, 0, 0],
            ),
            negative_errno(libc::EPERM)
        );
        let host_fd = state.files[&(fd as libc::c_int)].as_raw_fd();
        let mut host_stat = std::mem::MaybeUninit::<libc::stat>::zeroed();
        assert_eq!(unsafe { libc::fstat(host_fd, host_stat.as_mut_ptr()) }, 0);
        assert_eq!(unsafe { host_stat.assume_init() }.st_mode & 0o777, 0o444);

        let path_only = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH,
                (libc::O_PATH | libc::O_CLOEXEC) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(path_only, 6);
        assert_eq!(
            state.proc_files.get(&(path_only as libc::c_int)),
            Some(&inode)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmod,
                [path_only as u64, 0o666, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "O_PATH validation must precede the synthetic procfs guard"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [path_only as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_openat,
                [
                    libc::AT_FDCWD as u64,
                    PATH,
                    (libc::O_RDWR | libc::O_CLOEXEC) as u64,
                    0,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EACCES),
            "a proc-fd reopen must preserve the synthetic file's read-only mode"
        );
        assert_eq!(
            state.files.keys().copied().collect::<Vec<_>>(),
            vec![3, 4, 5],
            "failed reopen must not allocate a guest descriptor"
        );
    }

    #[test]
    fn synthetic_proc_procfd_access_gate_is_dac_independent_and_directory_specific() {
        const PATH: u64 = 0x100;

        let root = TestDir::new();
        let carrier_path = root.0.join("permissive-carrier");
        std::fs::write(&carrier_path, b"payload").unwrap();
        std::fs::set_permissions(&carrier_path, std::fs::Permissions::from_mode(0o666)).unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(
            3,
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&carrier_path)
                .unwrap(),
        );
        state
            .proc_files
            .insert(3, synthetic_proc_inode(b"/proc/uptime"));
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_c_string(&mut memory, PATH, "/proc/self/fd/3");

        let native_source = std::fs::File::open("/proc/uptime").unwrap();
        let native_procfd = format!("/proc/self/fd/{}", native_source.as_raw_fd());
        // SAFETY: geteuid has no arguments or memory-safety preconditions.
        if unsafe { libc::geteuid() } != 0 {
            // SAFETY: native_source is live. This is an explicitly
            // credential-qualified native oracle; the guest assertion below
            // remains unconditional under its fixed uid-0 identity.
            assert_eq!(
                unsafe { libc::fchmod(native_source.as_raw_fd(), 0o600) },
                -1
            );
            assert_eq!(
                std::io::Error::last_os_error().raw_os_error(),
                Some(libc::EPERM)
            );
        }
        for (label, flags, expected) in [
            (
                "read-directory-nofollow",
                libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                libc::ENOTDIR,
            ),
            (
                "write-directory-nofollow",
                libc::O_WRONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                libc::ENOTDIR,
            ),
            (
                "rdwr-directory-nofollow",
                libc::O_RDWR | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                libc::ENOTDIR,
            ),
            (
                "path-directory-nofollow",
                libc::O_PATH | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                libc::ENOTDIR,
            ),
            (
                "truncate-directory-nofollow",
                libc::O_RDONLY | libc::O_TRUNC | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                libc::ENOTDIR,
            ),
            (
                "direct-directory-nofollow",
                libc::O_RDONLY | libc::O_DIRECT | libc::O_DIRECTORY | libc::O_NOFOLLOW,
                libc::ENOTDIR,
            ),
            (
                "write-nofollow",
                libc::O_WRONLY | libc::O_NOFOLLOW,
                libc::ELOOP,
            ),
            (
                "rdwr-nofollow",
                libc::O_RDWR | libc::O_NOFOLLOW,
                libc::ELOOP,
            ),
            (
                "truncate-nofollow",
                libc::O_RDONLY | libc::O_TRUNC | libc::O_NOFOLLOW,
                libc::ELOOP,
            ),
            (
                "direct-nofollow",
                libc::O_RDONLY | libc::O_DIRECT | libc::O_NOFOLLOW,
                libc::ELOOP,
            ),
            (
                "create-exclusive-write",
                libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL,
                libc::EEXIST,
            ),
            (
                "create-exclusive-rdwr",
                libc::O_RDWR | libc::O_CREAT | libc::O_EXCL,
                libc::EEXIST,
            ),
            (
                "create-exclusive-truncate",
                libc::O_RDONLY | libc::O_CREAT | libc::O_EXCL | libc::O_TRUNC,
                libc::EEXIST,
            ),
            (
                "create-exclusive-direct-nofollow",
                libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL | libc::O_DIRECT | libc::O_NOFOLLOW,
                libc::EEXIST,
            ),
        ] {
            assert_eq!(
                native_open_error(&native_procfd, flags),
                Some(expected),
                "native proc-fd matrix case={label}"
            );
            assert_eq!(
                open_with_flags(&mut memory, &mut state, "/proc/self/fd/3", flags),
                negative_errno(expected),
                "guest proc-fd matrix case={label}"
            );
        }
        assert_eq!(
            native_open_error(&native_procfd, libc::O_PATH | libc::O_NOFOLLOW),
            None,
            "native exposes the procfs magic link itself"
        );
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                "/proc/self/fd/3",
                libc::O_PATH | libc::O_NOFOLLOW,
            ),
            negative_errno(libc::ELOOP),
            "the guest must not expose a supervisor procfs magic-link inode"
        );
        assert_eq!(
            native_open_error(
                &native_procfd,
                libc::O_PATH
                    | libc::O_WRONLY
                    | libc::O_CREAT
                    | libc::O_EXCL
                    | libc::O_TRUNC
                    | libc::O_DIRECT,
            ),
            None
        );
        let ignored_path_flags = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/self/fd/3",
            libc::O_PATH
                | libc::O_WRONLY
                | libc::O_CREAT
                | libc::O_EXCL
                | libc::O_TRUNC
                | libc::O_DIRECT,
        );
        assert_eq!(ignored_path_flags, 4);
        assert_eq!(close(&mut state, ignored_path_flags as u64), 0);

        for access in [libc::O_WRONLY, libc::O_RDWR] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_openat,
                    [libc::AT_FDCWD as u64, PATH, access as u64, 0, 0, 0],
                ),
                negative_errno(libc::EACCES),
                "classified regular proc carrier accepted access mode {access}"
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmod,
                [3, 0o600, 0, 0, 0, 0],
            ),
            negative_errno(libc::EPERM),
            "classified carrier protection must not depend on its permissive host mode"
        );
        assert_eq!(
            std::fs::metadata(&carrier_path)
                .unwrap()
                .permissions()
                .mode()
                & 0o777,
            0o666,
            "refused guest fchmod unexpectedly changed the permissive host control"
        );
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                "/proc/self/fd/3",
                libc::O_RDONLY | libc::O_TRUNC,
            ),
            negative_errno(libc::EACCES),
            "O_TRUNC must not reach a permissive carrier"
        );
        assert_eq!(std::fs::read(&carrier_path).unwrap(), b"payload");
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                "/proc/self/fd/3",
                libc::O_RDONLY | libc::O_DIRECT,
            ),
            negative_errno(libc::EINVAL)
        );
        for flags in [
            libc::O_RDONLY | libc::O_DIRECTORY,
            libc::O_RDWR | libc::O_DIRECTORY,
            libc::O_PATH | libc::O_DIRECTORY,
        ] {
            assert_eq!(
                open_with_flags(&mut memory, &mut state, "/proc/self/fd/3", flags),
                negative_errno(libc::ENOTDIR),
                "wrong-type validation must remain host-owned for flags {flags:#x}"
            );
        }
        assert_eq!(
            open_with_flags(
                &mut memory,
                &mut state,
                "/proc/self/fd/3",
                libc::O_PATH | libc::O_NOFOLLOW,
            ),
            negative_errno(libc::ELOOP)
        );
        let path_only = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PATH,
                (libc::O_PATH | libc::O_CLOEXEC) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(path_only, 4, "O_PATH must bypass access-mode refusal");
        assert_eq!(close(&mut state, path_only as u64), 0);

        let retained = libc::O_NONBLOCK | libc::O_APPEND | libc::O_SYNC;
        let reopened = open_with_flags(
            &mut memory,
            &mut state,
            "/proc/self/fd/3",
            libc::O_RDONLY | retained,
        );
        assert_eq!(reopened, 4);
        let observed = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [reopened as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
        ) as libc::c_int;
        assert_eq!(observed & retained, retained);
        assert_eq!(close(&mut state, reopened as u64), 0);

        state.files.insert(4, std::fs::File::open("/proc").unwrap());
        state.proc_files.insert(4, synthetic_proc_inode(b"/proc"));
        write_c_string(&mut memory, PATH, "/proc/self/fd/4");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_openat,
                [libc::AT_FDCWD as u64, PATH, libc::O_RDWR as u64, 0, 0, 0,],
            ),
            negative_errno(libc::EISDIR),
            "synthetic proc directories retain native directory precedence"
        );
    }

    #[test]
    fn file_mutation_guards_preserve_access_mode_and_memfd_seal_results() {
        let root = TestDir::new();
        let path = root.0.join("mmap-access");
        std::fs::write(&path, vec![0xa5; PAGE_SIZE as usize]).unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, state.mmap_limit as usize).unwrap();

        state.files.insert(3, std::fs::File::open(&path).unwrap());
        state.files.insert(
            4,
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path)
                .unwrap(),
        );
        let c_path = CString::new(path.as_os_str().as_bytes()).unwrap();
        // SAFETY: c_path is NUL-terminated and names the live fixture file.
        let path_fd = unsafe { libc::open(c_path.as_ptr(), libc::O_PATH | libc::O_CLOEXEC) };
        assert!(path_fd >= 0, "{}", std::io::Error::last_os_error());
        // SAFETY: open returned a new descriptor owned by this test.
        state
            .files
            .insert(5, unsafe { std::fs::File::from_raw_fd(path_fd) });

        // SAFETY: the name is a valid NUL-terminated C string.
        let sealed_fd = unsafe {
            libc::memfd_create(
                c"reverie-kvm-sealed-mmap-test".as_ptr(),
                libc::MFD_CLOEXEC | libc::MFD_ALLOW_SEALING,
            )
        };
        assert!(sealed_fd >= 0, "{}", std::io::Error::last_os_error());
        // SAFETY: memfd_create returned a new descriptor owned by this test.
        let sealed = unsafe { std::fs::File::from_raw_fd(sealed_fd) };
        // SAFETY: sealed_fd is a live writable memfd and the length is nonnegative.
        assert_eq!(
            unsafe { libc::ftruncate(sealed_fd, PAGE_SIZE as libc::off_t) },
            0
        );
        assert_eq!(
            unsafe {
                libc::fcntl(
                    sealed_fd,
                    libc::F_ADD_SEALS,
                    libc::F_SEAL_WRITE
                        | libc::F_SEAL_GROW
                        | libc::F_SEAL_SHRINK
                        | libc::F_SEAL_SEAL,
                )
            },
            0
        );
        state.files.insert(6, sealed);

        // A FUTURE_WRITE-only seal has the same new-mapping prohibition as
        // F_SEAL_WRITE while leaving writes through the existing description
        // available. The KVM mmap admission must honor that distinct shape.
        let future_write_fd = unsafe {
            libc::memfd_create(
                c"reverie-kvm-future-write-mmap-test".as_ptr(),
                libc::MFD_CLOEXEC | libc::MFD_ALLOW_SEALING,
            )
        };
        assert!(future_write_fd >= 0, "{}", std::io::Error::last_os_error());
        // SAFETY: future_write_fd is a live writable memfd and the length is nonnegative.
        assert_eq!(
            unsafe { libc::ftruncate(future_write_fd, PAGE_SIZE as libc::off_t) },
            0
        );
        assert_eq!(
            unsafe {
                libc::fcntl(
                    future_write_fd,
                    libc::F_ADD_SEALS,
                    libc::F_SEAL_FUTURE_WRITE,
                )
            },
            0
        );
        // SAFETY: memfd_create returned a new descriptor owned by this test.
        state
            .files
            .insert(7, unsafe { std::fs::File::from_raw_fd(future_write_fd) });

        memory.write(0x100, b"x").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pwrite64,
                [(1_u64 << 32) | 3, 0x100, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "ordinary O_RDONLY files retain their non-proc positioned-write result"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ftruncate,
                [3, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "an O_RDONLY ordinary file follows Linux ftruncate access semantics"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ftruncate,
                [(1_u64 << 32) | 5, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "an O_PATH description remains unusable for ftruncate"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ftruncate,
                [(1_u64 << 32) | 4, 2048, 0, 0, 0, 0],
            ),
            0,
            "a writable ordinary file must remain truncatable"
        );
        assert_eq!(std::fs::metadata(&path).unwrap().len(), 2048);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmod,
                [(1_u64 << 32) | 4, 0o640, 0, 0, 0, 0],
            ),
            0,
            "an ordinary writable file must remain chmod-capable"
        );
        assert_eq!(std::fs::metadata(&path).unwrap().mode() & 0o777, 0o640);

        let shared_write = |fd| {
            [
                0,
                PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                libc::MAP_SHARED as u64,
                fd,
                0,
            ]
        };
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                shared_write((1_u64 << 32) | 3),
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                shared_write((1_u64 << 32) | 5),
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                shared_write((1_u64 << 32) | 6),
            ),
            negative_errno(libc::EPERM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                shared_write((1_u64 << 32) | 7),
            ),
            negative_errno(libc::EPERM)
        );
        let expected_address = state.mmap_next;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mmap,
                shared_write((1_u64 << 32) | 4),
            ),
            expected_address as i64,
            "an unsealed O_RDWR ordinary file must remain shared-writable"
        );
    }

    // AUTONOMOUS-BOT-IMPLEMENTED
    // TODO-HUMAN-REVIEW(PR-225): regression for the /proc/self/mountinfo
    // synthetic surface (content bytes, read path, and inode round-trip) added
    // for df compatibility under --backend kvm.
    #[test]
    fn synthetic_proc_self_mountinfo_is_served_and_stable() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        let expected = std::fs::read("/proc/self/mountinfo").unwrap();
        assert_eq!(state.proc_mounts.mountinfo, expected);

        // The raw surface represents the actual backend filesystem namespace.
        assert_eq!(
            synthetic_proc_content(&state, b"/proc/self/mountinfo").as_deref(),
            Some(expected.as_slice())
        );

        // A guest read through openat yields the same bytes.
        let fd = open_readonly(&mut memory, &mut state, "/proc/self/mountinfo");
        assert!(fd >= 0, "open /proc/self/mountinfo failed: {fd}");
        assert_eq!(read_fd_to_end(&mut memory, &mut state, fd), expected);

        // fstat/newfstatat resolve to the same stable synthetic inode so that
        // gnulib's fstat-then-read of the mount table stays deterministic.
        let stat_address = 0x1000;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fstat,
                [fd as u64, stat_address, 0, 0, 0, 0]
            ),
            0
        );
        let stat: libc::stat = read_struct(&memory, stat_address);
        assert_eq!(stat.st_ino, synthetic_proc_inode(b"/proc/self/mountinfo"));
        assert_eq!(
            synthetic_proc_path_for_inode(stat.st_ino),
            Some(b"/proc/self/mountinfo".as_slice())
        );
        assert_eq!(stat.st_size, expected.len() as libc::off_t);
        let child = state.try_clone_for_fork(2).unwrap();
        assert!(Arc::ptr_eq(&state.proc_mounts, &child.proc_mounts));
        let snapshot = state.proc_mounts.clone();
        let mut replacement = test_state(&root.0);
        replacement.inherit_process_state(state);
        assert!(Arc::ptr_eq(&snapshot, &replacement.proc_mounts));
    }

    // AUTONOMOUS-BOT-IMPLEMENTED
    // TODO-HUMAN-REVIEW(PR-225): regression for statfs canonicalization,
    // matching detcore's canonicalize_statfs_buf so KVM statfs/fstatfs is
    // bitwise-deterministic across runs (df, tar, stat -f).
    #[test]
    fn canonicalize_statfs_zeroes_host_varying_fields() {
        // A statfs whose free counts and fsid vary from run to run.
        let mut sf: libc::statfs = unsafe { std::mem::zeroed() };
        sf.f_blocks = 10_000_000;
        sf.f_bfree = 7_123_456;
        sf.f_bavail = 6_987_654;
        sf.f_files = 2_000_000;
        sf.f_ffree = 1_234_567;
        sf.f_fsid = unsafe { std::mem::transmute::<[i32; 2], libc::fsid_t>([0x1234, 0x5678]) };

        canonicalize_statfs(&mut sf);

        // Free blocks are capped at 1_000_000 and clamped to the total.
        assert_eq!(sf.f_bfree, 1_000_000);
        assert_eq!(sf.f_bavail, 1_000_000);
        // Free inodes are capped at 500_000 and clamped to the total.
        assert_eq!(sf.f_ffree, 500_000);
        // The filesystem identity is zeroed so it cannot leak host state.
        assert_eq!(
            unsafe { std::mem::transmute::<libc::fsid_t, [i32; 2]>(sf.f_fsid) },
            [0, 0]
        );
        // Totals are untouched.
        assert_eq!(sf.f_blocks, 10_000_000);
        assert_eq!(sf.f_files, 2_000_000);

        // Small totals clamp free values down to the total, and a zero inode
        // total yields zero free inodes (never the cap).
        let mut small: libc::statfs = unsafe { std::mem::zeroed() };
        small.f_blocks = 42;
        small.f_files = 0;
        canonicalize_statfs(&mut small);
        assert_eq!(small.f_bfree, 42);
        assert_eq!(small.f_bavail, 42);
        assert_eq!(small.f_ffree, 0);
    }

    #[test]
    fn synthetic_proc_directory_resolves_relative_allowlisted_files() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        write_c_string(&mut memory, 0x100, "/proc");
        let proc_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                0x100,
                (libc::O_RDONLY | libc::O_DIRECTORY) as u64,
                0,
                0,
                0,
            ],
        );
        assert!(proc_fd >= 0, "open /proc failed: {proc_fd}");

        let stat_address = 0x1000;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fstat,
                [proc_fd as u64, stat_address, 0, 0, 0, 0]
            ),
            0
        );
        let stat: libc::stat = read_struct(&memory, stat_address);
        assert_eq!(stat.st_mode, libc::S_IFDIR | 0o555);

        write_c_string(&mut memory, 0x100, "cpuinfo");
        let cpuinfo_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [proc_fd as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
        );
        assert!(cpuinfo_fd >= 0, "openat cpuinfo failed: {cpuinfo_fd}");
        let content = read_fd_to_end(&mut memory, &mut state, cpuinfo_fd);
        assert!(
            content.starts_with(b"processor\t: 0\n"),
            "{}",
            String::from_utf8_lossy(&content)
        );

        write_c_string(&mut memory, 0x100, "self/maps");
        let maps_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [proc_fd as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
        );
        assert!(maps_fd >= 0, "openat self/maps failed: {maps_fd}");
        let maps = read_fd_to_end(&mut memory, &mut state, maps_fd);
        assert!(maps.ends_with(b"[stack]\n"));

        write_c_string(&mut memory, 0x100, "../etc/passwd");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_openat,
                [proc_fd as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT),
            "unlisted relative proc path leaked through"
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getdents64,
                [proc_fd as u64, 0x2000, 0x400, 0, 0, 0]
            ),
            0,
            "the intentionally unenumerable synthetic directory must appear empty"
        );
    }

    #[test]
    fn synthetic_proc_self_reflects_guest_identity() {
        let root = TestDir::new();
        let mut state = test_state(&root.0); // pid=1, ppid=0, argv0="test"
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        let fd = open_readonly(&mut memory, &mut state, "/proc/self/stat");
        let stat = read_fd_to_end(&mut memory, &mut state, fd);
        assert!(
            String::from_utf8_lossy(&stat).starts_with("1 (test) R 0 "),
            "{}",
            String::from_utf8_lossy(&stat)
        );

        let fd = open_readonly(&mut memory, &mut state, "/proc/self/cmdline");
        assert_eq!(read_fd_to_end(&mut memory, &mut state, fd), b"test\0");

        let fd = open_readonly(&mut memory, &mut state, "/proc/self/status");
        let status = String::from_utf8(read_fd_to_end(&mut memory, &mut state, fd)).unwrap();
        assert!(status.contains("Name:\ttest\n"), "{status}");
        assert!(status.contains("Pid:\t1\n"), "{status}");
        assert!(status.contains("PPid:\t0\n"), "{status}");

        write_c_string(&mut memory, 0x100, "worker-name");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_prctl,
                [libc::PR_SET_NAME as u64, 0x100, 0, 0, 0, 0],
            ),
            0,
        );
        let fd = open_readonly(&mut memory, &mut state, "/proc/self/stat");
        let stat = String::from_utf8(read_fd_to_end(&mut memory, &mut state, fd)).unwrap();
        assert!(stat.starts_with("1 (worker-name) R 0 "), "{stat}");
        let fd = open_readonly(&mut memory, &mut state, "/proc/self/status");
        let status = String::from_utf8(read_fd_to_end(&mut memory, &mut state, fd)).unwrap();
        assert!(status.contains("Name:\tworker-name\n"), "{status}");
        let fd = open_readonly(&mut memory, &mut state, "/proc/self/cmdline");
        assert_eq!(read_fd_to_end(&mut memory, &mut state, fd), b"test\0");

        // /proc/<pid> aliases /proc/self for this guest's own pid.
        let fd = open_readonly(&mut memory, &mut state, "/proc/1/cmdline");
        assert_eq!(read_fd_to_end(&mut memory, &mut state, fd), b"test\0");
    }

    #[test]
    fn synthetic_proc_metadata_is_synthetic_and_stable() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();

        // fstat of an open synthetic descriptor reports synthesized identity.
        let fd = open_readonly(&mut memory, &mut state, "/proc/uptime");
        let stat_address = 0x1000;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fstat,
                [fd as u64, stat_address, 0, 0, 0, 0]
            ),
            0
        );
        let stat: libc::stat = read_struct(&memory, stat_address);
        assert_eq!(stat.st_mode, libc::S_IFREG | 0o444);
        assert_eq!(stat.st_ino, synthetic_proc_inode(b"/proc/uptime"));
        assert_eq!(stat.st_dev, synthetic_dev(SYNTHETIC_PROC_DEV_MINOR));
        assert_eq!(stat.st_size, b"0.00 0.00\n".len() as libc::off_t);
        assert_eq!(stat.st_uid, 0);
        assert_eq!(stat.st_mtime, 0);

        // A path-addressed newfstatat yields the identical synthetic identity.
        write_c_string(&mut memory, 0x100, "/proc/uptime");
        let path_stat_address = 0x1200;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_newfstatat,
                [libc::AT_FDCWD as u64, 0x100, path_stat_address, 0, 0, 0]
            ),
            0
        );
        let path_stat: libc::stat = read_struct(&memory, path_stat_address);
        assert_eq!(path_stat.st_ino, stat.st_ino);
        assert_eq!(path_stat.st_size, stat.st_size);
        assert_eq!(path_stat.st_mode, stat.st_mode);
    }

    #[test]
    fn captured_output_fstat_is_synthetic_and_stable() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();
        let mut output = CapturedOutput::default();
        let mut stats = Vec::new();

        for (fd, address) in [(libc::STDOUT_FILENO, 0x1000), (libc::STDERR_FILENO, 0x1200)] {
            let action = execute_basic_syscall_with_output(
                &mut memory,
                &mut state,
                &SyscallRequest::new(libc::SYS_fstat as u64, [fd as u64, address, 0, 0, 0, 0]),
                None,
                Some(&mut output),
            );
            assert!(matches!(
                action,
                SyscallAction::Continue {
                    result: 0,
                    segment: None
                }
            ));
            let stat: libc::stat = read_struct(&memory, address);
            let identity = output
                .metadata()
                .identity(output_alias(&state, fd).unwrap());
            assert_eq!(
                (stat.st_dev, stat.st_ino),
                (identity.device, identity.inode)
            );
            assert_eq!(stat.st_mode, libc::S_IFIFO | 0o600);
            assert_eq!(stat.st_size, 0);
            assert_eq!(stat.st_blocks, 0);
            assert_eq!(stat.st_mtime, DETERMINISTIC_METADATA_SECONDS);
            stats.push(stat);
        }

        assert_ne!(stats[0].st_ino, stats[1].st_ino);
    }

    #[test]
    fn captured_output_lseek_is_pipe_for_seekable_standard_stream_alias() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 0x4000).unwrap();
        let mut output = CapturedOutput::default();

        let path = root.0.join("captured-stderr");
        std::fs::write(&path, b"seekable").unwrap();
        let alias = insert_file_with_flags(
            &mut state,
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(path)
                .unwrap(),
            false,
            Some(OutputAlias::Stderr),
        );
        assert_eq!(alias, 3);
        let request = SyscallRequest::new(
            libc::SYS_lseek as u64,
            [alias as u64, 4, libc::SEEK_SET as u64, 0, 0, 0],
        );

        // The same guest descriptor is genuinely seekable when output capture
        // is disabled. This is the control that prevents an inherited pipe from
        // making the captured-output assertion pass through the host fallback.
        assert!(matches!(
            execute_basic_syscall_with_output(&mut memory, &mut state, &request, None, None),
            SyscallAction::Continue {
                result: 4,
                segment: None
            }
        ));

        let action = execute_basic_syscall_with_output(
            &mut memory,
            &mut state,
            &request,
            None,
            Some(&mut output),
        );
        assert!(matches!(
            action,
            SyscallAction::Continue {
                result,
                segment: None
            } if result == negative_errno(libc::ESPIPE)
        ));
    }

