    #[test]
    fn virtual_identity_stays_read_only_and_random_access_is_separate() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        for (path, first_byte) in [("/dev/urandom", 41), ("/proc/self/loginuid", b'0')] {
            write_c_string(&mut memory, 0x100, path);
            let writable = syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_openat,
                [libc::AT_FDCWD as u64, 0x100, libc::O_RDWR as u64, 0, 0, 0],
            );
            if path == "/dev/urandom" {
                assert!(writable >= 0);
                assert_eq!(close(&mut state, writable as u64), 0);
            } else {
                assert_eq!(writable, negative_errno(libc::EACCES));
            }

            let fd = open_readonly(&mut memory, &mut state, path);
            assert!(fd >= 0, "open {path} failed: {fd}");
            let flags = syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
            );
            assert_eq!(flags as libc::c_int & libc::O_ACCMODE, libc::O_RDONLY);
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_read,
                    [fd as u64, 0x200, 1, 0, 0, 0]
                ),
                1
            );
            let mut byte = [0];
            memory.read(0x200, &mut byte).unwrap();
            assert_eq!(byte[0], first_byte);
            if path == "/dev/urandom" {
                write_c_string(&mut memory, 0x100, &format!("/proc/self/fd/{fd}"));
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_truncate,
                        [0x100, 0, 0, 0, 0, 0],
                    ),
                    negative_errno(libc::EINVAL)
                );
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_read,
                        [fd as u64, 0x200, 1, 0, 0, 0],
                    ),
                    1
                );
            }
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_write,
                    [fd as u64, 0x200, 1, 0, 0, 0]
                ),
                negative_errno(libc::EBADF)
            );
        }
    }

    #[test]
    fn generic_virtual_file_procfd_reopen_is_a_writable_unsealed_residual() {
        const BUFFER: u64 = 0x200;
        for path in [
            "/proc/self/loginuid",
            "/sys/devices/system/cpu/cpufreq/boost",
        ] {
            let root = TestDir::new();
            let mut state = test_state(&root.0);
            let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
            memory.write(BUFFER, b"z").unwrap();
            let direct = open_readonly(&mut memory, &mut state, path);
            assert!(direct >= 0, "direct open failed for {path}: {direct}");
            assert!(
                !state.proc_files.contains_key(&(direct as libc::c_int)),
                "generic virtual carrier was accidentally classified as sealed proc: {path}"
            );
            let host = host_fd(&state, direct as libc::c_int).unwrap();
            // memfd_create without MFD_ALLOW_SEALING starts with only
            // F_SEAL_SEAL, so these generic carriers lack all mutation seals.
            // SAFETY: host is a live generic virtual-file carrier.
            assert_eq!(
                unsafe { libc::fcntl(host, libc::F_GET_SEALS) },
                libc::F_SEAL_SEAL
            );

            let procfd = format!("/proc/self/fd/{direct}");
            let writable = open_with_flags(&mut memory, &mut state, &procfd, libc::O_RDWR);
            assert!(
                writable >= 0,
                "generic virtual proc-fd writable-reopen residual changed for {path}: {writable}"
            );
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_write,
                    [writable as u64, BUFFER, 1, 0, 0, 0],
                ),
                1,
                "generic virtual proc-fd carrier ceased to be writable for {path}"
            );
            assert_eq!(close(&mut state, writable as u64), 0);
            assert_eq!(close(&mut state, direct as u64), 0);
        }
    }

    #[test]
    fn fcntl_getfl_translates_guest_descriptors() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        let stdin = state.stdin.as_ref().unwrap();
        let host_flags = fd_status_flags(stdin.as_raw_fd()).unwrap();
        // SAFETY: stdin owns a live descriptor and F_SETFL consumes an integer flag word.
        assert_eq!(
            unsafe {
                libc::fcntl(
                    stdin.as_raw_fd(),
                    libc::F_SETFL,
                    host_flags | libc::O_NONBLOCK,
                )
            },
            0
        );

        let flags = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [0, libc::F_GETFL as u64, 0, 0, 0, 0],
        );
        assert!(flags >= 0);
        assert_eq!(flags as libc::c_int & libc::O_ACCMODE, libc::O_RDONLY);
        assert_ne!(flags as libc::c_int & libc::O_NONBLOCK, 0);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [99, libc::F_GETFL as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );

        state.closed_standard_fds.insert(libc::STDIN_FILENO);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [0, libc::F_GETFL as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
    }

    #[test]
    fn fcntl_setfl_applies_status_flags() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        const PIPE_FDS: u64 = 0x100;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [PIPE_FDS, 0, 0, 0, 0, 0]
            ),
            0
        );
        let pipe_fds: [libc::c_int; 2] = read_struct(&memory, PIPE_FDS);
        let write_fd = pipe_fds[1];

        // F_SETFL O_NONBLOCK on the guest write end succeeds (previously ENOSYS).
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [
                    write_fd as u64,
                    libc::F_SETFL as u64,
                    libc::O_NONBLOCK as u64,
                    0,
                    0,
                    0
                ]
            ),
            0
        );
        // F_GETFL now reflects the applied status flag.
        let flags = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [write_fd as u64, libc::F_GETFL as u64, 0, 0, 0, 0],
        );
        assert!(flags >= 0);
        assert_ne!(flags as libc::c_int & libc::O_NONBLOCK, 0);
    }

    // AUTONOMOUS-BOT-IMPLEMENTED
    // TODO-HUMAN-REVIEW(rrnewton/reverie#318): regression for the F_GETPIPE_SZ /
    // F_SETPIPE_SZ fcntl arms (were ENOSYS). They forward to the backing host
    // pipe, so the guest observes the real, deterministic pipe capacity.
    #[test]
    fn fcntl_pipe_capacity_get_and_set_forward_to_host() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        const PIPE_FDS: u64 = 0x100;
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [PIPE_FDS, 0, 0, 0, 0, 0]
            ),
            0
        );
        let pipe_fds: [libc::c_int; 2] = read_struct(&memory, PIPE_FDS);
        let write_fd = pipe_fds[1];

        // F_GETPIPE_SZ returns the backing pipe's capacity (a positive size),
        // where the executor previously fell through to ENOSYS.
        let capacity = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [write_fd as u64, libc::F_GETPIPE_SZ as u64, 0, 0, 0, 0],
        );
        assert!(capacity > 0, "F_GETPIPE_SZ returned {capacity}");

        // Shrinking to one page exercises F_SETPIPE_SZ without depending on the
        // host-global per-user quota that can reject capacity growth.
        let requested = PAGE_SIZE as i64;
        assert!(
            capacity >= requested,
            "pipe capacity {capacity} is smaller than one page"
        );
        let applied = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [
                write_fd as u64,
                libc::F_SETPIPE_SZ as u64,
                requested as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(
            applied, requested,
            "F_SETPIPE_SZ did not apply the one-page capacity"
        );
        let resized = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_fcntl,
            [write_fd as u64, libc::F_GETPIPE_SZ as u64, 0, 0, 0, 0],
        );
        assert_eq!(resized, requested);

        // An unknown fd is still rejected with EBADF, not ENOSYS.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [99, libc::F_GETPIPE_SZ as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
    }

    #[test]
    fn sendfile_copies_regular_files_with_and_without_offset() {
        let root = TestDir::new();
        let src_path = root.0.join("src");
        std::fs::write(&src_path, b"abcdefghij").unwrap();

        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        // Explicit-offset copy: start at input offset 2, copy 5 bytes ("cdefg").
        let src = std::fs::OpenOptions::new()
            .read(true)
            .open(&src_path)
            .unwrap();
        let dst_off_path = root.0.join("dst_off");
        let dst_off = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(true)
            .open(&dst_off_path)
            .unwrap();
        state.files.insert(3, src);
        state.files.insert(4, dst_off);

        const OFF: u64 = 0x100;
        write_struct(&mut memory, OFF, &2i64);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [4, 3, OFF, 5, 0, 0]
            ),
            5
        );
        // The kernel advances the guest-supplied offset by the bytes copied.
        assert_eq!(read_struct::<i64>(&memory, OFF), 7);
        assert_eq!(std::fs::read(&dst_off_path).unwrap(), b"cdefg");

        // Null-offset copy: uses the input fd's own position (0 -> whole file).
        let src2 = std::fs::OpenOptions::new()
            .read(true)
            .open(&src_path)
            .unwrap();
        let dst_pos_path = root.0.join("dst_pos");
        let dst_pos = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(true)
            .open(&dst_pos_path)
            .unwrap();
        state.files.insert(5, src2);
        state.files.insert(6, dst_pos);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [6, 5, 0, 100, 0, 0]
            ),
            10
        );
        assert_eq!(std::fs::read(&dst_pos_path).unwrap(), b"abcdefghij");
    }

    #[test]
    fn sendfile_and_lseek_consume_low_descriptor_words() {
        const HIGH_WORD: u64 = 0x5a5a_5a5a_0000_0000;
        const SIGNED_LOW_WORD: u64 = HIGH_WORD | 0x8000_0000;
        const OFFSET: u64 = 0x100;

        let root = TestDir::new();
        let src_path = root.0.join("src-low-word");
        let dst_path = root.0.join("dst-low-word");
        std::fs::write(&src_path, b"abcdefghij").unwrap();

        let mut state = test_state(&root.0);
        state.files.insert(
            3,
            std::fs::OpenOptions::new()
                .read(true)
                .open(&src_path)
                .unwrap(),
        );
        state.files.insert(
            4,
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .create(true)
                .truncate(true)
                .open(&dst_path)
                .unwrap(),
        );
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_struct(&mut memory, OFFSET, &0i64);

        // Exercise each sendfile descriptor decoder independently while using
        // the same ordinary regular-file routing as an unadorned syscall.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [HIGH_WORD | 4, 3, OFFSET, 2, 0, 0]
            ),
            2
        );
        assert_eq!(read_struct::<i64>(&memory, OFFSET), 2);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [4, HIGH_WORD | 3, OFFSET, 2, 0, 0]
            ),
            2
        );
        assert_eq!(read_struct::<i64>(&memory, OFFSET), 4);
        assert_eq!(std::fs::read(&dst_path).unwrap(), b"abcd");

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lseek,
                [HIGH_WORD | 3, 6, libc::SEEK_SET as u64, 0, 0, 0]
            ),
            6
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lseek,
                [3, 0, libc::SEEK_CUR as u64, 0, 0, 0]
            ),
            6
        );

        // A set low-word sign bit still denotes a negative descriptor. Keep
        // the offset pointer and whence valid so these are fd-only assertions.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [SIGNED_LOW_WORD | 4, 3, OFFSET, 1, 0, 0]
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [4, SIGNED_LOW_WORD | 3, OFFSET, 1, 0, 0]
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lseek,
                [SIGNED_LOW_WORD | 3, 0, libc::SEEK_SET as u64, 0, 0, 0]
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(read_struct::<i64>(&memory, OFFSET), 4);
        assert_eq!(std::fs::read(&dst_path).unwrap(), b"abcd");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_lseek,
                [3, 0, libc::SEEK_CUR as u64, 0, 0, 0]
            ),
            6
        );
    }

    #[test]
    fn sendfile_rejects_negative_output_before_input_routing() {
        const SIGNED_LOW_WORD: u64 = 0x5a5a_5a5a_8000_0000;
        const PIPE_FDS: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [PIPE_FDS, 0, 0, 0, 0, 0]
            ),
            0
        );
        let pipe_fds: [libc::c_int; 2] = read_struct(&memory, PIPE_FDS);
        let socket_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_socket,
            [libc::AF_UNIX as u64, libc::SOCK_STREAM as u64, 0, 0, 0, 0],
        );
        assert!(socket_fd >= 0, "socket() returned {socket_fd}");
        state
            .files
            .insert(20, std::fs::File::open(&root.0).unwrap());
        state
            .files
            .insert(21, std::fs::File::open("/proc/self/status").unwrap());

        for (raw_out, encoding) in [
            (SIGNED_LOW_WORD | 1, "low-word sign bit"),
            (u64::MAX, "sign-extended -1"),
        ] {
            for (in_fd, input_kind) in [
                (pipe_fds[0] as u64, "pipe"),
                (socket_fd as u64, "socket"),
                (20, "directory"),
                (libc::STDOUT_FILENO as u64, "standard stream"),
                (21, "procfs"),
            ] {
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_sendfile,
                        [raw_out, in_fd, 0, 1, 0, 0]
                    ),
                    negative_errno(libc::EBADF),
                    "{encoding} output must precede {input_kind} routing"
                );
            }
        }
    }

    #[test]
    fn sendfile_rejects_unusable_output_before_input_routing() {
        const HIGH_WORD: u64 = 0x5a5a_5a5a_0000_0000;
        const SIGN_EXTENDED_HIGH_WORD: u64 = 0xffff_ffff_0000_0000;
        const INPUT_PIPE_FDS: u64 = 0x100;
        const INPUT_SOCKET_FDS: u64 = 0x120;
        const OUTPUT_PIPE_FDS: u64 = 0x140;
        const PAYLOAD: u64 = 0x200;
        const PIPE_PAYLOAD: &[u8] = b"pipe-input-preserved";
        const SOCKET_PAYLOAD: &[u8] = b"socket-input-preserved";

        let root = TestDir::new();
        let read_only_path = root.0.join("read-only-output");
        std::fs::write(&read_only_path, b"output").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 4 * PAGE_SIZE as usize).unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [INPUT_PIPE_FDS, 0, 0, 0, 0, 0]
            ),
            0
        );
        let input_pipe: [libc::c_int; 2] = read_struct(&memory, INPUT_PIPE_FDS);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_STREAM as u64,
                    0,
                    INPUT_SOCKET_FDS,
                    0,
                    0,
                ]
            ),
            0
        );
        let input_socket: [libc::c_int; 2] = read_struct(&memory, INPUT_SOCKET_FDS);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [OUTPUT_PIPE_FDS, 0, 0, 0, 0, 0]
            ),
            0
        );
        let output_pipe: [libc::c_int; 2] = read_struct(&memory, OUTPUT_PIPE_FDS);

        memory.write(PAYLOAD, PIPE_PAYLOAD).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [
                    input_pipe[1] as u64,
                    PAYLOAD,
                    PIPE_PAYLOAD.len() as u64,
                    0,
                    0,
                    0,
                ]
            ),
            PIPE_PAYLOAD.len() as i64
        );
        memory.write(PAYLOAD, SOCKET_PAYLOAD).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [
                    input_socket[1] as u64,
                    PAYLOAD,
                    SOCKET_PAYLOAD.len() as u64,
                    0,
                    0,
                    0,
                ]
            ),
            SOCKET_PAYLOAD.len() as i64
        );
        for fd in [input_pipe[1], input_socket[1]] {
            assert_eq!(close(&mut state, fd as u64), 0);
        }

        state
            .files
            .insert(20, std::fs::File::open(&read_only_path).unwrap());
        state
            .files
            .insert(21, std::fs::File::open(&root.0).unwrap());
        state
            .files
            .insert(22, std::fs::File::open("/proc/self/status").unwrap());
        state
            .files
            .insert(23, std::fs::File::open(&read_only_path).unwrap());
        assert_eq!(close(&mut state, 23), 0);
        let proc_position = state.files.get_mut(&22).unwrap().stream_position().unwrap();
        let regular_position = state.files.get_mut(&20).unwrap().stream_position().unwrap();

        for (high_word, encoding) in [
            (HIGH_WORD, "nonzero high word"),
            (SIGN_EXTENDED_HIGH_WORD, "sign-extended high word"),
        ] {
            for (out_fd, output_kind) in [
                (23, "closed"),
                (20, "read-only regular"),
                (output_pipe[0], "pipe read end"),
            ] {
                for (in_fd, input_kind) in [
                    (input_pipe[0], "pipe"),
                    (input_socket[0], "socket"),
                    (21, "directory"),
                    (libc::STDOUT_FILENO, "standard stream"),
                    (22, "procfs"),
                ] {
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_sendfile,
                            [
                                high_word | u64::from(out_fd as u32),
                                in_fd as u64,
                                0,
                                1,
                                0,
                                0,
                            ]
                        ),
                        negative_errno(libc::EBADF),
                        "{encoding} {output_kind} output must precede {input_kind} input routing"
                    );
                }
            }
        }

        assert_eq!(
            read_fd_to_end(&mut memory, &mut state, input_pipe[0] as i64),
            PIPE_PAYLOAD
        );
        assert_eq!(
            read_fd_to_end(&mut memory, &mut state, input_socket[0] as i64),
            SOCKET_PAYLOAD
        );
        assert_eq!(
            state.files.get_mut(&22).unwrap().stream_position().unwrap(),
            proc_position,
            "rejected outputs must not consume procfs input"
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendfile,
                [HIGH_WORD | u64::from(output_pipe[1] as u32), 20, 0, 1, 0, 0,]
            ),
            negative_errno(libc::ENOSYS),
            "a valid writable pipe output retains the mediated fallback"
        );
        assert_eq!(
            state.files.get_mut(&20).unwrap().stream_position().unwrap(),
            regular_position,
            "the writable-pipe fallback must not consume its input"
        );
        assert_eq!(close(&mut state, output_pipe[1] as u64), 0);
    }

    #[test]
    fn sendfile_readonly_stdin_precedes_unsupported_input_routing() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [0x100, libc::O_NONBLOCK as u64, 0, 0, 0, 0]
            ),
            0
        );
        let pipe: [libc::c_int; 2] = read_struct(&memory, 0x100);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    (libc::SOCK_STREAM | libc::SOCK_NONBLOCK) as u64,
                    0,
                    0x120,
                    0,
                    0,
                ]
            ),
            0
        );
        let socket: [libc::c_int; 2] = read_struct(&memory, 0x120);
        state
            .files
            .insert(20, std::fs::File::open(&root.0).unwrap());
        state
            .files
            .insert(21, std::fs::File::open("/proc/self/status").unwrap());
        for writer in [pipe[1], socket[1]] {
            state
                .files
                .get_mut(&writer)
                .unwrap()
                .write_all(b"sentinel")
                .unwrap();
            assert_eq!(close(&mut state, writer as u64), 0);
        }
        assert_eq!(
            ensure_writable(state.stdin.as_ref().unwrap()),
            Err(negative_errno(libc::EBADF))
        );
        for raw_stdin in [0x5a5a_5a5a_0000_0000, 0xffff_ffff_0000_0000] {
            for (input, kind) in [
                (pipe[0], "pipe"),
                (socket[0], "socket"),
                (20, "directory"),
                (libc::STDOUT_FILENO, "stdout"),
                (21, "procfs"),
            ] {
                assert_eq!(
                    syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_sendfile,
                        [raw_stdin, input as u64, 0, 1, 0, 0]
                    ),
                    negative_errno(libc::EBADF),
                    "read-only stdin {raw_stdin:#x} with {kind} input"
                );
            }
        }
        for reader in [pipe[0], socket[0]] {
            assert_eq!(
                read_fd_to_end(&mut memory, &mut state, reader as i64),
                b"sentinel"
            );
        }
        assert_eq!(
            state.files.get_mut(&21).unwrap().stream_position().unwrap(),
            0
        );
    }

    #[test]
    fn sendfile_readonly_stdin_preserves_regular_input_cursor() {
        let root = TestDir::new();
        let source = root.0.join("source");
        std::fs::write(&source, b"abcdef").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(3, std::fs::File::open(source).unwrap());
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for raw_stdin in [0x5a5a_5a5a_0000_0000, 0xffff_ffff_0000_0000] {
            for offset in [0, 0x100] {
                state
                    .files
                    .get_mut(&3)
                    .unwrap()
                    .seek(std::io::SeekFrom::Start(1))
                    .unwrap();
                write_struct(&mut memory, 0x100, &2_i64);
                let result = syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_sendfile,
                    [raw_stdin, 3, offset, 2, 0, 0],
                );
                assert_eq!(
                    state.files.get_mut(&3).unwrap().stream_position().unwrap(),
                    1,
                    "read-only stdin {raw_stdin:#x} must reject before consuming regular input"
                );
                assert_eq!(read_struct::<i64>(&memory, 0x100), 2);
                assert_eq!(result, negative_errno(libc::EBADF));
            }
        }
    }

    #[test]
    fn sendfile_readonly_stdin_preserves_explicit_offset_errors() {
        const OFFSET: u64 = 0x100;
        const INACCESSIBLE: u64 = 0xffff_ffff_ffff_f000;
        let root = TestDir::new();
        let source = root.0.join("source");
        let destination = root.0.join("readonly-stdin");
        std::fs::write(&source, b"abcdef").unwrap();
        std::fs::write(&destination, b"unchanged").unwrap();
        let mut state = test_state(&root.0);
        state.stdin = Some(std::fs::File::open(&destination).unwrap());
        state.files.insert(3, std::fs::File::open(&source).unwrap());
        state
            .files
            .get_mut(&3)
            .unwrap()
            .seek(std::io::SeekFrom::Start(1))
            .unwrap();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut actual = Vec::new();
        let mut expected = Vec::new();
        for raw_stdin in [0, 0x5a5a_5a5a_0000_0000, 0xffff_ffff_0000_0000] {
            for (name, pointer, offset, count, error) in [
                ("inaccessible", INACCESSIBLE, 2, 2, libc::EFAULT),
                ("inaccessible zero count", INACCESSIBLE, 2, 0, libc::EFAULT),
                ("negative", OFFSET, -1, 2, libc::EINVAL),
                ("minimum", OFFSET, i64::MIN, 2, libc::EINVAL),
                ("maximum overflow", OFFSET, i64::MAX, 1, libc::EINVAL),
                (
                    "maximum minus one overflow",
                    OFFSET,
                    i64::MAX - 1,
                    2,
                    libc::EINVAL,
                ),
                (
                    "maximum minus one valid",
                    OFFSET,
                    i64::MAX - 1,
                    1,
                    libc::EBADF,
                ),
                ("maximum zero count", OFFSET, i64::MAX, 0, libc::EBADF),
                ("negative zero count", OFFSET, -1, 0, libc::EINVAL),
                ("normal", OFFSET, 0, 2, libc::EBADF),
                ("normal zero count", OFFSET, 2, 0, libc::EBADF),
                ("null", 0, 2, 2, libc::EBADF),
                ("null zero count", 0, 2, 0, libc::EBADF),
            ] {
                write_struct(&mut memory, OFFSET, &offset);
                let result = syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_sendfile,
                    [raw_stdin, 3, pointer, count, 0, 0],
                );
                assert_eq!(
                    state.files.get_mut(&3).unwrap().stream_position().unwrap(),
                    1
                );
                assert_eq!(read_struct::<i64>(&memory, OFFSET), offset);
                assert_eq!(std::fs::read(&destination).unwrap(), b"unchanged");
                actual.push((raw_stdin, name, result));
                expected.push((raw_stdin, name, negative_errno(error)));
            }
        }
        assert_eq!(actual, expected);
    }

    #[test]
    fn sendfile_bad_outputs_preserve_regular_input_offset_errors() {
        const OFFSET: u64 = 0x100;
        const PIPE_FDS: u64 = 0x180;
        const AVAILABLE: u64 = 0x200;
        const INACCESSIBLE: u64 = 0xffff_ffff_ffff_f000;
        const SENTINEL: &[u8] = b"output-sentinel";
        let root = TestDir::new();
        let source = root.0.join("source");
        let destination = root.0.join("readonly-output");
        std::fs::write(&source, b"abcdefghij").unwrap();
        std::fs::write(&destination, b"unchanged").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(3, std::fs::File::open(&source).unwrap());
        state
            .files
            .insert(4, std::fs::File::open(&destination).unwrap());
        state
            .files
            .get_mut(&3)
            .unwrap()
            .seek(std::io::SeekFrom::Start(3))
            .unwrap();
        state
            .files
            .get_mut(&4)
            .unwrap()
            .seek(std::io::SeekFrom::Start(2))
            .unwrap();
        // read_fd_to_end uses a buffer in the second guest page.
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [PIPE_FDS, libc::O_NONBLOCK as u64, 0, 0, 0, 0],
            ),
            0
        );
        let pipe: [libc::c_int; 2] = read_struct(&memory, PIPE_FDS);
        state
            .files
            .get_mut(&pipe[1])
            .unwrap()
            .write_all(SENTINEL)
            .unwrap();
        assert_eq!(close(&mut state, pipe[1] as u64), 0);
        state
            .files
            .insert(90, std::fs::File::open(&destination).unwrap());
        assert_eq!(close(&mut state, 90), 0);

        for (out_fd, kind) in [
            (90_i32, "closed"),
            (4, "read-only regular"),
            (pipe[0], "pipe read end"),
            (-1, "negative descriptor"),
        ] {
            for high_word in [0, 0x5a5a_5a5a_0000_0000, 0xffff_ffff_0000_0000] {
                let raw_output = high_word | u64::from(out_fd as u32);
                for (name, pointer, offset, count, error) in [
                    ("inaccessible", INACCESSIBLE, 2, 2, libc::EFAULT),
                    ("inaccessible zero count", INACCESSIBLE, 2, 0, libc::EFAULT),
                    ("negative", OFFSET, -1, 2, libc::EINVAL),
                    ("minimum", OFFSET, i64::MIN, 2, libc::EINVAL),
                    ("maximum overflow", OFFSET, i64::MAX, 1, libc::EINVAL),
                    (
                        "maximum minus one overflow",
                        OFFSET,
                        i64::MAX - 1,
                        2,
                        libc::EINVAL,
                    ),
                    (
                        "maximum minus one valid",
                        OFFSET,
                        i64::MAX - 1,
                        1,
                        libc::EBADF,
                    ),
                    ("maximum zero count", OFFSET, i64::MAX, 0, libc::EBADF),
                    ("negative zero count", OFFSET, -1, 0, libc::EINVAL),
                    ("normal", OFFSET, 0, 2, libc::EBADF),
                    ("normal zero count", OFFSET, 2, 0, libc::EBADF),
                    ("null", 0, 2, 2, libc::EBADF),
                    ("null zero count", 0, 2, 0, libc::EBADF),
                    (
                        "above supervisor cap overflow",
                        OFFSET,
                        i64::MAX - 20_000_000,
                        100_000_000,
                        libc::EINVAL,
                    ),
                    (
                        "above supervisor cap valid",
                        OFFSET,
                        i64::MAX - 20_000_000,
                        20_000_000,
                        libc::EBADF,
                    ),
                    (
                        "above kernel cap overflow",
                        OFFSET,
                        i64::MAX - MAX_RW_COUNT as i64,
                        MAX_RW_COUNT as u64 + 1,
                        libc::EINVAL,
                    ),
                    (
                        "kernel cap boundary valid",
                        OFFSET,
                        i64::MAX - MAX_RW_COUNT as i64,
                        MAX_RW_COUNT as u64,
                        libc::EBADF,
                    ),
                    (
                        "signed count maximum valid",
                        OFFSET,
                        0,
                        i64::MAX as u64,
                        libc::EBADF,
                    ),
                    ("signed count bit", OFFSET, 0, 1_u64 << 63, libc::EINVAL),
                    ("unsigned count maximum", OFFSET, 0, u64::MAX, libc::EINVAL),
                    (
                        "inaccessible oversized count",
                        INACCESSIBLE,
                        2,
                        u64::MAX,
                        libc::EFAULT,
                    ),
                    ("null oversized valid", 0, 2, 100_000_000, libc::EBADF),
                    (
                        "null signed range overflow",
                        0,
                        2,
                        i64::MAX as u64,
                        libc::EINVAL,
                    ),
                    ("null signed count bit", 0, 2, 1_u64 << 63, libc::EINVAL),
                    ("null unsigned count maximum", 0, 2, u64::MAX, libc::EINVAL),
                ] {
                    write_struct(&mut memory, OFFSET, &offset);
                    let result = syscall_result(
                        &mut memory,
                        &mut state,
                        libc::SYS_sendfile,
                        [raw_output, 3, pointer, count, 0, 0],
                    );
                    assert_eq!(
                        state.files.get_mut(&3).unwrap().stream_position().unwrap(),
                        3,
                        "{kind} {raw_output:#x} {name}: input cursor"
                    );
                    assert_eq!(
                        state.files.get_mut(&4).unwrap().stream_position().unwrap(),
                        2,
                        "{kind} {raw_output:#x} {name}: output cursor"
                    );
                    assert_eq!(read_struct::<i64>(&memory, OFFSET), offset);
                    assert_eq!(std::fs::read(&source).unwrap(), b"abcdefghij");
                    assert_eq!(std::fs::read(&destination).unwrap(), b"unchanged");
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_ioctl,
                            [pipe[0] as u64, libc::FIONREAD, AVAILABLE, 0, 0, 0],
                        ),
                        0
                    );
                    assert_eq!(
                        read_struct::<libc::c_int>(&memory, AVAILABLE),
                        SENTINEL.len() as i32
                    );
                    assert_eq!(
                        result,
                        negative_errno(error),
                        "{kind} {raw_output:#x} {name}"
                    );
                }
            }
        }
        assert_eq!(
            read_fd_to_end(&mut memory, &mut state, pipe[0] as i64),
            SENTINEL
        );
    }

