    #[test]
    fn select_socketpair_and_shutdown_cover_ready_and_half_close_paths() {
        const PAIR_FDS: u64 = 0x100;
        const PAYLOAD: u64 = 0x200;
        const READ_BUFFER: u64 = 0x300;
        const READ_SET: u64 = 0x400;
        const TIMEOUT: u64 = 0x500;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(PAYLOAD, b"ping").unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_STREAM as u64,
                    0,
                    u64::MAX,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EFAULT)
        );
        assert!(state.files.is_empty());

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    (libc::SOCK_STREAM | libc::SOCK_CLOEXEC) as u64,
                    0,
                    PAIR_FDS,
                    0,
                    0,
                ],
            ),
            0
        );
        let socket_fds: [libc::c_int; 2] = read_struct(&memory, PAIR_FDS);
        assert_eq!(socket_fds, [3, 4]);
        assert!(socket_fds.iter().all(|fd| state.cloexec_fds.contains(fd)));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [socket_fds[0] as u64, PAYLOAD, 4, 0, 0, 0],
            ),
            4
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [socket_fds[1] as u64, READ_BUFFER, 4, 0, 0, 0],
            ),
            4
        );
        let mut payload = [0; 4];
        memory.read(READ_BUFFER, &mut payload).unwrap();
        assert_eq!(&payload, b"ping");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_shutdown,
                [socket_fds[0] as u64, libc::SHUT_WR as u64, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [socket_fds[1] as u64, READ_BUFFER, 4, 0, 0, 0],
            ),
            0
        );
        for fd in socket_fds {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_close,
                    [fd as u64, 0, 0, 0, 0, 0],
                ),
                0
            );
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe,
                [PAIR_FDS, 0, 0, 0, 0, 0],
            ),
            0
        );
        let pipe_fds: [libc::c_int; 2] = read_struct(&memory, PAIR_FDS);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [pipe_fds[1] as u64, PAYLOAD, 4, 0, 0, 0],
            ),
            4
        );
        let read_bit = 1_u64 << pipe_fds[0];
        memory.write(READ_SET, &read_bit.to_ne_bytes()).unwrap();
        assert_eq!(
            write_struct(
                &mut memory,
                TIMEOUT,
                &libc::timeval {
                    tv_sec: 5,
                    tv_usec: 0,
                },
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_select,
                [pipe_fds[0] as u64 + 1, READ_SET, 0, 0, TIMEOUT, 0],
            ),
            1
        );
        assert_eq!(read_struct::<u64>(&memory, READ_SET), read_bit);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [pipe_fds[0] as u64, READ_BUFFER, 4, 0, 0, 0],
            ),
            4
        );

        memory.write(READ_SET, &read_bit.to_ne_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_select,
                [pipe_fds[0] as u64 + 1, READ_SET, 0, 0, TIMEOUT, 0],
            ),
            0
        );
        assert_eq!(read_struct::<u64>(&memory, READ_SET), 0);
        assert_eq!(read_struct::<libc::timeval>(&memory, TIMEOUT).tv_sec, 0);

        let invalid_fd = 9;
        let invalid_bit = 1_u64 << invalid_fd;
        memory.write(READ_SET, &invalid_bit.to_ne_bytes()).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_select,
                [invalid_fd + 1, READ_SET, 0, 0, TIMEOUT, 0],
            ),
            negative_errno(libc::EBADF)
        );
        for fd in pipe_fds {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_close,
                    [fd as u64, 0, 0, 0, 0, 0],
                ),
                0
            );
        }
        assert!(state.files.is_empty());
    }

    fn check_receive_output_flags(batch: bool) {
        const PAIR: u64 = 0x80;
        const PIPE: u64 = 0x90;
        const SEND: u64 = 0x100;
        const SEND_IOV: u64 = 0x180;
        const SEND_CONTROL: u64 = 0x200;
        const IOVS: u64 = 0x300;
        const MESSAGES: u64 = 0x400;
        const PAYLOAD: u64 = 0x600;
        const OUTPUT: u64 = 0x700;
        const CONTROL: u64 = 0xa00;
        let root = TestDir::new();
        // Exercise the production executor with real datagrams, including both
        // independent kinds of truncation and their combination.
        for cloexec in [0, libc::MSG_CMSG_CLOEXEC] {
            for input_trunc in [0, libc::MSG_TRUNC] {
                for (donate, short_payload, short_control) in [
                    (false, false, false),
                    (true, false, false),
                    (false, true, false),
                    (true, false, true),
                    (true, true, true),
                ] {
                    let case = (
                        batch,
                        cloexec,
                        input_trunc,
                        donate,
                        short_payload,
                        short_control,
                    );
                    let mut state = test_state(&root.0);
                    let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_socketpair,
                            [libc::AF_UNIX as u64, libc::SOCK_DGRAM as u64, 0, PAIR, 0, 0]
                        ),
                        0
                    );
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_pipe2,
                            [PIPE, 0, 0, 0, 0, 0]
                        ),
                        0
                    );
                    let sockets: [i32; 2] = read_struct(&memory, PAIR);
                    let pipes: [i32; 2] = read_struct(&memory, PIPE);
                    memory.write(PAYLOAD, b"abcdef").unwrap();
                    let send_iov = libc::iovec {
                        iov_base: PAYLOAD as usize as *mut _,
                        iov_len: 6,
                    };
                    assert_eq!(write_struct(&mut memory, SEND_IOV, &send_iov), 0);
                    let control = rights_control(&pipes);
                    memory.write(SEND_CONTROL, &control).unwrap();
                    let mut send: libc::msghdr = unsafe { std::mem::zeroed() };
                    send.msg_iov = SEND_IOV as usize as *mut _;
                    send.msg_iovlen = 1;
                    if donate {
                        send.msg_control = SEND_CONTROL as usize as *mut _;
                        send.msg_controllen = control.len();
                    }
                    assert_eq!(write_struct(&mut memory, SEND, &send), 0);
                    assert_eq!(
                        syscall_result(
                            &mut memory,
                            &mut state,
                            libc::SYS_sendmsg,
                            [sockets[0] as u64, SEND, 0, 0, 0, 0]
                        ),
                        6
                    );
                    if batch {
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_write,
                                [sockets[0] as u64, PAYLOAD, 6, 0, 0, 0]
                            ),
                            6
                        );
                    }
                    let mut third_before = Vec::new();
                    for index in 0..3 {
                        let iov_address = IOVS + index * std::mem::size_of::<libc::iovec>() as u64;
                        let iov = libc::iovec {
                            iov_base: (OUTPUT + index * 0x80) as usize as *mut _,
                            iov_len: if index == 0 && short_payload { 3 } else { 8 },
                        };
                        assert_eq!(write_struct(&mut memory, iov_address, &iov), 0);
                        let mut message: libc::mmsghdr = unsafe { std::mem::zeroed() };
                        message.msg_hdr.msg_iov = iov_address as usize as *mut _;
                        message.msg_hdr.msg_iovlen = 1;
                        message.msg_hdr.msg_flags = -1;
                        message.msg_len = 0xdeadbeef;
                        if index == 0 && donate {
                            message.msg_hdr.msg_control = CONTROL as usize as *mut _;
                            message.msg_hdr.msg_controllen = if short_control {
                                cmsg_align(std::mem::size_of::<libc::cmsghdr>()).unwrap()
                                    + std::mem::size_of::<libc::c_int>()
                            } else {
                                control.len()
                            };
                        }
                        let address =
                            MESSAGES + index * std::mem::size_of::<libc::mmsghdr>() as u64;
                        assert_eq!(write_struct(&mut memory, address, &message), 0);
                        if index == 2 {
                            third_before = vec![0; std::mem::size_of::<libc::mmsghdr>()];
                            memory.read(address, &mut third_before).unwrap();
                        }
                    }
                    let flags = cloexec | input_trunc | libc::MSG_DONTWAIT;
                    let args = if batch {
                        [sockets[1] as u64, MESSAGES, 3, flags as u64, 0, 0]
                    } else {
                        [sockets[1] as u64, MESSAGES, flags as u64, 0, 0, 0]
                    };
                    let number = if batch {
                        libc::SYS_recvmmsg
                    } else {
                        libc::SYS_recvmsg
                    };
                    let files_before = state.files.len();
                    let expected_len = if short_payload && input_trunc == 0 {
                        3
                    } else {
                        6
                    };
                    assert_eq!(
                        syscall_result(&mut memory, &mut state, number, args),
                        if batch { 2 } else { expected_len },
                        "{case:?}"
                    );
                    let first: libc::mmsghdr = read_struct(&memory, MESSAGES);
                    let expected_flags = cloexec
                        | if short_payload { libc::MSG_TRUNC } else { 0 }
                        | if short_control { libc::MSG_CTRUNC } else { 0 };
                    assert_eq!(first.msg_hdr.msg_flags, expected_flags, "{case:?}");
                    let mut payload = vec![0; if short_payload { 3 } else { 6 }];
                    memory.read(OUTPUT, &mut payload).unwrap();
                    assert_eq!(payload, b"abcdef"[..payload.len()], "{case:?}");
                    if batch {
                        assert_eq!(first.msg_len, expected_len as u32, "{case:?}");
                        let second: libc::mmsghdr = read_struct(
                            &memory,
                            MESSAGES + std::mem::size_of::<libc::mmsghdr>() as u64,
                        );
                        assert_eq!(second.msg_len, 6);
                        assert_eq!(second.msg_hdr.msg_flags, cloexec, "{case:?}");
                        assert_eq!(second.msg_hdr.msg_controllen, 0);
                        assert_eq!(
                            read_guest_bytes::<6>(&memory, OUTPUT + 0x80).unwrap(),
                            *b"abcdef"
                        );
                        let mut third_after = vec![0; third_before.len()];
                        memory
                            .read(
                                MESSAGES + 2 * std::mem::size_of::<libc::mmsghdr>() as u64,
                                &mut third_after,
                            )
                            .unwrap();
                        assert_eq!(
                            third_after, third_before,
                            "undelivered header changed: {case:?}"
                        );
                    }
                    let mut received_control = vec![0; first.msg_hdr.msg_controllen];
                    memory.read(CONTROL, &mut received_control).unwrap();
                    let received = control_rights(&received_control);
                    assert_eq!(
                        received.len(),
                        if donate {
                            if short_control { 1 } else { 2 }
                        } else {
                            0
                        }
                    );
                    assert_eq!(state.files.len(), files_before + received.len());
                    for &fd in &received {
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_fcntl,
                                [fd as u64, libc::F_GETFD as u64, 0, 0, 0, 0]
                            ),
                            if cloexec == 0 {
                                0
                            } else {
                                libc::FD_CLOEXEC as i64
                            },
                            "{case:?}"
                        );
                        let backing = host_fd(&state, fd).unwrap();
                        // SAFETY: backing is an owned, live descriptor; F_GETFD
                        // takes no pointer and must remain CLOEXEC for host safety.
                        let host_flags = unsafe { libc::fcntl(backing, libc::F_GETFD) };
                        assert!(host_flags >= 0, "{case:?}");
                        assert_eq!(host_flags & libc::FD_CLOEXEC, libc::FD_CLOEXEC, "{case:?}");
                    }
                    if let Some(&read_fd) = received.first() {
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_write,
                                [pipes[1] as u64, PAYLOAD, 1, 0, 0, 0]
                            ),
                            1
                        );
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_read,
                                [read_fd as u64, OUTPUT, 1, 0, 0, 0]
                            ),
                            1
                        );
                        assert_eq!(read_guest_bytes::<1>(&memory, OUTPUT).unwrap(), *b"a");
                    }
                    for fd in received {
                        assert_eq!(
                            syscall_result(
                                &mut memory,
                                &mut state,
                                libc::SYS_close,
                                [fd as u64, 0, 0, 0, 0, 0]
                            ),
                            0
                        );
                    }
                    assert_eq!(state.files.len(), files_before);
                    // Empty-queue failure must not publish a replacement header.
                    let mut before = vec![0; std::mem::size_of::<libc::mmsghdr>()];
                    memory.read(MESSAGES, &mut before).unwrap();
                    assert_eq!(
                        syscall_result(&mut memory, &mut state, number, args),
                        negative_errno(libc::EAGAIN),
                        "{case:?}"
                    );
                    let mut after = vec![0; before.len()];
                    memory.read(MESSAGES, &mut after).unwrap();
                    assert_eq!(after, before, "failed receive changed header: {case:?}");
                }
            }
        }
    }

    #[test]
    fn recvmsg_output_flags_and_received_descriptor_safety() {
        check_receive_output_flags(false);
    }

    #[test]
    fn recvmmsg_output_flags_and_received_descriptor_safety() {
        check_receive_output_flags(true);
    }

    #[test]
    fn recvmmsg_translates_guest_headers_and_receives_multiple_datagrams() {
        const PAIR_FDS: u64 = 0x100;
        const SECOND_PAYLOAD: u64 = 0x220;
        const MESSAGES: u64 = 0x300;
        const FIRST_IOV: u64 = 0x400;
        const SECOND_IOV: u64 = 0x420;
        const FIRST_BUFFER: u64 = 0x500;
        const SECOND_BUFFER: u64 = 0x540;
        const FIRST_CONTROL: u64 = 0x580;
        const PIPE_RESULT: u64 = 0x600;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(SECOND_PAYLOAD, b"world!").unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_DGRAM as u64,
                    0,
                    PAIR_FDS,
                    0,
                    0,
                ],
            ),
            0
        );
        let socket_fds: [libc::c_int; 2] = read_struct(&memory, PAIR_FDS);
        // Queue the first datagram from the host with one real descriptor, then
        // queue the second through the guest path. recvmmsg must translate the
        // first control record without affecting ordinary later messages.
        let mut pipe_fds = [-1; 2];
        // SAFETY: pipe_fds has room for both CLOEXEC descriptors.
        assert_eq!(
            unsafe { libc::pipe2(pipe_fds.as_mut_ptr(), libc::O_CLOEXEC) },
            0
        );
        // SAFETY: pipe2 returned two independently owned descriptors.
        let read_end = unsafe { std::fs::File::from_raw_fd(pipe_fds[0]) };
        // SAFETY: pipe2 returned two independently owned descriptors.
        let mut write_end = unsafe { std::fs::File::from_raw_fd(pipe_fds[1]) };
        let mut host_payload = b"hello".to_vec();
        let mut host_iov = libc::iovec {
            iov_base: host_payload.as_mut_ptr().cast(),
            iov_len: host_payload.len(),
        };
        let mut host_control = rights_control(&[read_end.as_raw_fd()]);
        let host_message = libc::msghdr {
            msg_name: std::ptr::null_mut(),
            msg_namelen: 0,
            msg_iov: std::ptr::from_mut(&mut host_iov),
            msg_iovlen: 1,
            msg_control: host_control.as_mut_ptr().cast(),
            msg_controllen: host_control.len(),
            msg_flags: 0,
        };
        // SAFETY: every msghdr buffer is live and the socket belongs to state.
        assert_eq!(
            unsafe {
                libc::sendmsg(
                    host_fd(&state, socket_fds[0]).unwrap(),
                    std::ptr::from_ref(&host_message),
                    libc::MSG_NOSIGNAL,
                )
            },
            5
        );
        drop(read_end);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [socket_fds[0] as u64, SECOND_PAYLOAD, 6, 0, 0, 0],
            ),
            6
        );

        for (index, (iov_address, buffer_address)) in
            [(FIRST_IOV, FIRST_BUFFER), (SECOND_IOV, SECOND_BUFFER)]
                .into_iter()
                .enumerate()
        {
            let iov = libc::iovec {
                iov_base: buffer_address as usize as *mut libc::c_void,
                iov_len: 32,
            };
            assert_eq!(write_struct(&mut memory, iov_address, &iov), 0);
            let mut message = unsafe { std::mem::zeroed::<libc::mmsghdr>() };
            message.msg_hdr.msg_iov = iov_address as usize as *mut libc::iovec;
            message.msg_hdr.msg_iovlen = 1;
            if index == 0 {
                message.msg_hdr.msg_control = FIRST_CONTROL as usize as *mut libc::c_void;
                message.msg_hdr.msg_controllen = 64;
            }
            assert_eq!(
                write_struct(
                    &mut memory,
                    MESSAGES + (index * std::mem::size_of::<libc::mmsghdr>()) as u64,
                    &message,
                ),
                0
            );
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_recvmmsg,
                [
                    socket_fds[1] as u64,
                    MESSAGES,
                    2,
                    libc::MSG_DONTWAIT as u64,
                    0,
                    0,
                ],
            ),
            2
        );
        let first: libc::mmsghdr = read_struct(&memory, MESSAGES);
        let second: libc::mmsghdr = read_struct(
            &memory,
            MESSAGES + std::mem::size_of::<libc::mmsghdr>() as u64,
        );
        assert_eq!(first.msg_len, 5);
        assert_eq!(second.msg_len, 6);
        assert_eq!(first.msg_hdr.msg_flags, 0);
        assert_eq!(second.msg_hdr.msg_flags, 0);
        assert_eq!(
            read_guest_bytes::<5>(&memory, FIRST_BUFFER).unwrap(),
            *b"hello"
        );
        assert_eq!(
            read_guest_bytes::<6>(&memory, SECOND_BUFFER).unwrap(),
            *b"world!"
        );
        let mut control = vec![0; first.msg_hdr.msg_controllen];
        memory.read(FIRST_CONTROL, &mut control).unwrap();
        let received_fds = control_rights(&control);
        assert_eq!(received_fds, [5]);
        assert!(mutates_file_table(libc::SYS_recvmmsg as u64));
        write_end.write_all(b"x").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [received_fds[0] as u64, PIPE_RESULT, 1, 0, 0, 0],
            ),
            1
        );
        assert_eq!(read_guest_bytes::<1>(&memory, PIPE_RESULT).unwrap(), *b"x");
    }

    #[test]
    fn sendmsg_recvmsg_translates_multiple_rights_and_cloexec_lifecycle() {
        const PAIR_FDS: u64 = 0x100;
        const PIPE_FDS: u64 = 0x180;
        const SEND_SEG0: u64 = 0x200;
        const SEND_SEG1: u64 = 0x220;
        const SEND_IOV: u64 = 0x300;
        const SEND_MSG: u64 = 0x360;
        const SEND_CONTROL: u64 = 0x3c0;
        const RECV_SEG0: u64 = 0x400;
        const RECV_SEG1: u64 = 0x420;
        const RECV_IOV: u64 = 0x500;
        const RECV_CONTROL: u64 = 0x580;
        const RECV_MSG: u64 = 0x600;
        const PIPE_PAYLOAD: u64 = 0x700;
        const PIPE_RESULT: u64 = 0x710;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        // A two-segment payload: "hello " + "world!" = "hello world!" (12 bytes).
        memory.write(SEND_SEG0, b"hello ").unwrap();
        memory.write(SEND_SEG1, b"world!").unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_DGRAM as u64,
                    0,
                    PAIR_FDS,
                    0,
                    0,
                ],
            ),
            0
        );
        let socket_fds: [libc::c_int; 2] = read_struct(&memory, PAIR_FDS);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_pipe2,
                [PIPE_FDS, 0, 0, 0, 0, 0],
            ),
            0
        );
        let pipe_fds: [libc::c_int; 2] = read_struct(&memory, PIPE_FDS);
        assert_eq!(pipe_fds, [5, 6]);

        // Build the send-side scatter-gather iovecs and msghdr.
        let send_iovs = [
            libc::iovec {
                iov_base: SEND_SEG0 as usize as *mut libc::c_void,
                iov_len: 6,
            },
            libc::iovec {
                iov_base: SEND_SEG1 as usize as *mut libc::c_void,
                iov_len: 6,
            },
        ];
        for (index, iov) in send_iovs.iter().enumerate() {
            assert_eq!(
                write_struct(
                    &mut memory,
                    SEND_IOV + (index * std::mem::size_of::<libc::iovec>()) as u64,
                    iov,
                ),
                0
            );
        }
        let mut send_msg = unsafe { std::mem::zeroed::<libc::msghdr>() };
        send_msg.msg_iov = SEND_IOV as usize as *mut libc::iovec;
        send_msg.msg_iovlen = 2;
        let send_control = rights_control(&pipe_fds);
        memory.write(SEND_CONTROL, &send_control).unwrap();
        send_msg.msg_control = SEND_CONTROL as usize as *mut libc::c_void;
        send_msg.msg_controllen = send_control.len();
        assert_eq!(write_struct(&mut memory, SEND_MSG, &send_msg), 0);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendmsg,
                [socket_fds[0] as u64, SEND_MSG, 0, 0, 0, 0],
            ),
            12
        );

        // Build the recv-side iovecs (6 + 6), an ancillary control buffer, and
        // the msghdr the guest hands to recvmsg.
        let recv_iovs = [
            libc::iovec {
                iov_base: RECV_SEG0 as usize as *mut libc::c_void,
                iov_len: 6,
            },
            libc::iovec {
                iov_base: RECV_SEG1 as usize as *mut libc::c_void,
                iov_len: 6,
            },
        ];
        for (index, iov) in recv_iovs.iter().enumerate() {
            assert_eq!(
                write_struct(
                    &mut memory,
                    RECV_IOV + (index * std::mem::size_of::<libc::iovec>()) as u64,
                    iov,
                ),
                0
            );
        }
        memory.write(RECV_CONTROL, &[0u8; 64]).unwrap();
        let mut recv_msg = unsafe { std::mem::zeroed::<libc::msghdr>() };
        recv_msg.msg_iov = RECV_IOV as usize as *mut libc::iovec;
        recv_msg.msg_iovlen = 2;
        recv_msg.msg_control = RECV_CONTROL as usize as *mut libc::c_void;
        recv_msg.msg_controllen = 64;
        assert_eq!(write_struct(&mut memory, RECV_MSG, &recv_msg), 0);

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_recvmsg,
                [
                    socket_fds[1] as u64,
                    RECV_MSG,
                    libc::MSG_CMSG_CLOEXEC as u64,
                    0,
                    0,
                    0,
                ],
            ),
            12
        );

        // The payload reassembles across the two independent recv segments,
        // proving the iovec scatter/gather translation is faithful.
        assert_eq!(
            read_guest_bytes::<6>(&memory, RECV_SEG0).unwrap(),
            *b"hello "
        );
        assert_eq!(
            read_guest_bytes::<6>(&memory, RECV_SEG1).unwrap(),
            *b"world!"
        );

        let received: libc::msghdr = read_struct(&memory, RECV_MSG);
        assert_eq!(received.msg_flags & libc::MSG_CTRUNC, 0);
        assert_eq!(received.msg_flags, libc::MSG_CMSG_CLOEXEC);
        let mut received_control = vec![0; received.msg_controllen];
        memory.read(RECV_CONTROL, &mut received_control).unwrap();
        let received_fds = control_rights(&received_control);
        assert_eq!(received_fds, [7, 8]);
        assert!(received_fds.iter().all(|fd| state.cloexec_fds.contains(fd)));
        assert!(mutates_file_table(libc::SYS_recvmsg as u64));

        // Both translated descriptors refer to the donated pipe object and are
        // usable through the guest table in both directions.
        memory.write(PIPE_PAYLOAD, b"a").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [pipe_fds[1] as u64, PIPE_PAYLOAD, 1, 0, 0, 0],
            ),
            1
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [received_fds[0] as u64, PIPE_RESULT, 1, 0, 0, 0],
            ),
            1
        );
        assert_eq!(read_guest_bytes::<1>(&memory, PIPE_RESULT).unwrap(), *b"a");
        memory.write(PIPE_PAYLOAD, b"b").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [received_fds[1] as u64, PIPE_PAYLOAD, 1, 0, 0, 0],
            ),
            1
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [pipe_fds[0] as u64, PIPE_RESULT, 1, 0, 0, 0],
            ),
            1
        );
        assert_eq!(read_guest_bytes::<1>(&memory, PIPE_RESULT).unwrap(), *b"b");

        let forked = state.try_clone_for_fork(2).unwrap();
        assert!(received_fds.iter().all(|fd| forked.files.contains_key(fd)));
        let mut replacement = test_state(&root.0);
        replacement.inherit_process_state(state);
        assert!(
            received_fds
                .iter()
                .all(|fd| !replacement.files.contains_key(fd))
        );
        assert!(pipe_fds.iter().all(|fd| replacement.files.contains_key(fd)));
    }

    #[test]
    fn sendmsg_rejects_invalid_malformed_and_unvirtualized_control_without_sending() {
        const PAIR_FDS: u64 = 0x100;
        const PAYLOAD: u64 = 0x200;
        const SEND_IOV: u64 = 0x300;
        const SEND_MSG: u64 = 0x380;
        const SEND_CONTROL: u64 = 0x400;
        const RECV_IOV: u64 = 0x500;
        const RECV_MSG: u64 = 0x580;
        const RECV_BUFFER: u64 = 0x600;
        const SIGNAL_MASK: u64 = 0x700;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_DGRAM as u64,
                    0,
                    PAIR_FDS,
                    0,
                    0,
                ],
            ),
            0
        );
        let socket_fds: [libc::c_int; 2] = read_struct(&memory, PAIR_FDS);
        memory.write(PAYLOAD, b"x").unwrap();
        let send_iov = libc::iovec {
            iov_base: PAYLOAD as usize as *mut libc::c_void,
            iov_len: 1,
        };
        assert_eq!(write_struct(&mut memory, SEND_IOV, &send_iov), 0);
        let mut send_message = unsafe { std::mem::zeroed::<libc::msghdr>() };
        send_message.msg_iov = SEND_IOV as usize as *mut libc::iovec;
        send_message.msg_iovlen = 1;
        send_message.msg_control = SEND_CONTROL as usize as *mut libc::c_void;

        let invalid_right = rights_control(&[99]);
        memory.write(SEND_CONTROL, &invalid_right).unwrap();
        send_message.msg_controllen = invalid_right.len();
        assert_eq!(write_struct(&mut memory, SEND_MSG, &send_message), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendmsg,
                [socket_fds[0] as u64, SEND_MSG, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );

        let malformed_right = control_message(libc::SOL_SOCKET, libc::SCM_RIGHTS, &[0]);
        memory.write(SEND_CONTROL, &malformed_right).unwrap();
        send_message.msg_controllen = malformed_right.len();
        assert_eq!(write_struct(&mut memory, SEND_MSG, &send_message), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendmsg,
                [socket_fds[0] as u64, SEND_MSG, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );

        let credentials = control_message(
            libc::SOL_SOCKET,
            libc::SCM_CREDENTIALS,
            &vec![0; std::mem::size_of::<libc::ucred>()],
        );
        memory.write(SEND_CONTROL, &credentials).unwrap();
        send_message.msg_controllen = credentials.len();
        assert_eq!(write_struct(&mut memory, SEND_MSG, &send_message), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sendmsg,
                [socket_fds[0] as u64, SEND_MSG, 0, 0, 0, 0],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );

        let mut signal_mask = KernelSigset::default();
        signal_mask.insert(libc::SIGUSR1);
        memory.write(SIGNAL_MASK, &signal_mask.to_bytes()).unwrap();
        let signal_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_signalfd4,
            [
                u64::MAX,
                SIGNAL_MASK,
                KERNEL_SIGSET_SIZE as u64,
                libc::SFD_NONBLOCK as u64,
                0,
                0,
            ],
        );
        let signal_alias = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_dup,
            [signal_fd as u64, 0, 0, 0, 0, 0],
        );
        for donated in [signal_fd, signal_alias] {
            let control = rights_control(&[donated as libc::c_int]);
            memory.write(SEND_CONTROL, &control).unwrap();
            send_message.msg_controllen = control.len();
            assert_eq!(write_struct(&mut memory, SEND_MSG, &send_message), 0);
            let files_before = state.files.keys().copied().collect::<Vec<_>>();
            let masks_before = state.process_signals.lock().unwrap().signalfd_masks.clone();
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_sendmsg,
                    [socket_fds[0] as u64, SEND_MSG, 0, 0, 0, 0],
                ),
                negative_errno(libc::ENOSYS),
                "SCM_RIGHTS must not lose signalfd metadata for fd {donated}",
            );
            assert_eq!(
                state.files.keys().copied().collect::<Vec<_>>(),
                files_before
            );
            assert_eq!(
                state.process_signals.lock().unwrap().signalfd_masks,
                masks_before,
            );
            assert_eq!(
                control_rights(&read_guest_bytes::<24>(&memory, SEND_CONTROL).unwrap()),
                [donated as libc::c_int],
                "the guest control buffer is not rewritten",
            );
        }

        // Every rejected send happened before the host syscall: the peer queue
        // remains empty and a nonblocking receive reports EAGAIN.
        let recv_iov = libc::iovec {
            iov_base: RECV_BUFFER as usize as *mut libc::c_void,
            iov_len: 1,
        };
        assert_eq!(write_struct(&mut memory, RECV_IOV, &recv_iov), 0);
        let mut recv_message = unsafe { std::mem::zeroed::<libc::msghdr>() };
        recv_message.msg_iov = RECV_IOV as usize as *mut libc::iovec;
        recv_message.msg_iovlen = 1;
        assert_eq!(write_struct(&mut memory, RECV_MSG, &recv_message), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_recvmsg,
                [
                    socket_fds[1] as u64,
                    RECV_MSG,
                    libc::MSG_DONTWAIT as u64,
                    0,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EAGAIN)
        );
    }

    #[test]
    fn received_rights_reservation_and_rewrite_failures_are_transactional() {
        const TEST: &str =
            "executor::tests::received_rights_reservation_and_rewrite_failures_are_transactional";
        const CHILD_ENV: &str = "REVERIE_RECEIVED_RIGHTS_CHILD";
        if std::env::var_os(CHILD_ENV).is_none() {
            let output = std::process::Command::new("timeout")
                .args(["--kill-after=2s", "10s"])
                .arg(std::env::current_exe().unwrap())
                .args(["--exact", TEST, "--nocapture"])
                .env(CHILD_ENV, "1")
                .output()
                .expect("failed to run isolated received-rights regression");
            assert!(
                output.status.success(),
                "isolated received-rights regression failed with {}\nstdout:\n{}\nstderr:\n{}",
                output.status,
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            return;
        }
        // Create the endpoints after exec in this exact-test subprocess. A
        // concurrently spawned library-test child can otherwise inherit even
        // CLOEXEC sockets until its own exec, hiding an immediate peer EOF.
        const PAIR_FDS: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_DGRAM as u64,
                    0,
                    PAIR_FDS,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            available_guest_fds_with_limit(&state, 1, 5),
            Err(negative_errno(libc::EMFILE))
        );

        let (owned_right, peer) = UnixStream::pair().unwrap();
        // SAFETY: into_raw_fd transfers the socket endpoint's sole ownership.
        let file =
            unsafe { std::fs::File::from_raw_fd(std::os::fd::IntoRawFd::into_raw_fd(owned_right)) };
        let before = state.files.keys().copied().collect::<Vec<_>>();
        let error = install_received_rights(
            &mut state,
            &mut [0; std::mem::size_of::<libc::c_int>()],
            vec![PendingReceivedRight {
                control_offset: std::mem::size_of::<libc::c_int>(),
                file,
            }],
            false,
            false,
        )
        .unwrap_err();
        assert_eq!(error, negative_errno(libc::EINVAL));
        assert_eq!(state.files.keys().copied().collect::<Vec<_>>(), before);
        // Observe the owned socket object, not its recyclable descriptor number.
        assert_stream_peer_closed(&peer);

        // Unsupported fd-bearing ancillary data is also owned immediately and
        // closed rather than copied as an unusable host number.
        let (unsupported, unsupported_peer) = UnixStream::pair().unwrap();
        let pidfd = std::os::fd::IntoRawFd::into_raw_fd(unsupported);
        let pidfd_control = control_message(libc::SOL_SOCKET, SCM_PIDFD, &pidfd.to_ne_bytes());
        let sanitized = sanitize_received_control(&pidfd_control).unwrap();
        assert!(sanitized.stripped_unsupported);
        assert!(sanitized.bytes.is_empty());
        assert!(sanitized.rights.is_empty());
        assert_stream_peer_closed(&unsupported_peer);
    }

    #[test]
    fn recvmsg_preserves_timestamps_but_strips_host_credentials() {
        const PAIR_FDS: u64 = 0x100;
        const ONE: u64 = 0x180;
        const PAYLOAD: u64 = 0x200;
        const RECV_BUFFER: u64 = 0x300;
        const RECV_IOV: u64 = 0x380;
        const RECV_CONTROL: u64 = 0x400;
        const RECV_MSG: u64 = 0x600;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_socketpair,
                [
                    libc::AF_UNIX as u64,
                    libc::SOCK_DGRAM as u64,
                    0,
                    PAIR_FDS,
                    0,
                    0,
                ],
            ),
            0
        );
        let socket_fds: [libc::c_int; 2] = read_struct(&memory, PAIR_FDS);
        assert_eq!(write_struct(&mut memory, ONE, &1_i32), 0);
        for option in [libc::SO_PASSCRED, libc::SO_TIMESTAMPNS] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_setsockopt,
                    [
                        socket_fds[1] as u64,
                        libc::SOL_SOCKET as u64,
                        option as u64,
                        ONE,
                        std::mem::size_of::<libc::c_int>() as u64,
                        0,
                    ],
                ),
                0
            );
        }
        memory.write(PAYLOAD, b"t").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_write,
                [socket_fds[0] as u64, PAYLOAD, 1, 0, 0, 0],
            ),
            1
        );

        let recv_iov = libc::iovec {
            iov_base: RECV_BUFFER as usize as *mut libc::c_void,
            iov_len: 1,
        };
        assert_eq!(write_struct(&mut memory, RECV_IOV, &recv_iov), 0);
        memory.write(RECV_CONTROL, &[0xa5; 256]).unwrap();
        let mut recv_message = unsafe { std::mem::zeroed::<libc::msghdr>() };
        recv_message.msg_iov = RECV_IOV as usize as *mut libc::iovec;
        recv_message.msg_iovlen = 1;
        recv_message.msg_control = RECV_CONTROL as usize as *mut libc::c_void;
        recv_message.msg_controllen = 256;
        assert_eq!(write_struct(&mut memory, RECV_MSG, &recv_message), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_recvmsg,
                [socket_fds[1] as u64, RECV_MSG, 0, 0, 0, 0],
            ),
            1
        );

        let received: libc::msghdr = read_struct(&memory, RECV_MSG);
        assert_ne!(received.msg_flags & libc::MSG_CTRUNC, 0);
        assert_eq!(received.msg_flags & libc::MSG_CMSG_CLOEXEC, 0);
        let mut control = vec![0; received.msg_controllen];
        memory.read(RECV_CONTROL, &mut control).unwrap();
        let messages = control_messages(&control).unwrap();
        assert!(!messages.is_empty());
        assert!(
            messages
                .iter()
                .all(|message| is_socket_timestamp_cmsg(*message))
        );
        assert!(
            messages
                .iter()
                .all(|message| message.kind != libc::SCM_CREDENTIALS)
        );

        let mut tail = vec![0xff; 256 - received.msg_controllen];
        memory
            .read(RECV_CONTROL + received.msg_controllen as u64, &mut tail)
            .unwrap();
        assert!(tail.iter().all(|byte| *byte == 0));
    }

