    #[test]
    fn mremap_grows_a_reused_hole_into_adjacent_space() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_base = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_next = state.mmap_base;
        state.mmap_limit = state.mmap_base + 3 * PAGE_SIZE;
        let mmap_args = [
            0,
            PAGE_SIZE,
            (libc::PROT_READ | libc::PROT_WRITE) as u64,
            (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
            -1_i32 as u64,
            0,
        ];

        let first = syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args) as u64;
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            (first + PAGE_SIZE) as i64
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            (first + 2 * PAGE_SIZE) as i64
        );
        assert_eq!(state.mmap_next, state.mmap_limit);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [first, 2 * PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_mmap, mmap_args),
            first as i64
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mremap,
                [
                    first,
                    PAGE_SIZE,
                    2 * PAGE_SIZE,
                    libc::MREMAP_MAYMOVE as u64,
                    0,
                    0,
                ],
            ),
            first as i64
        );
        assert_eq!(state.mmap_next, state.mmap_limit);
        assert!(memory.user_range_is_mapped(first, 2 * PAGE_SIZE));
    }

    // Regression: a root guest renumbered by `KvmBackend::set_root_pid` gets a
    // synthetic container-init `getppid()` of 1 for ptrace parity. If that
    // guest-visible value also drove `Guest::ppid`, `Guest::is_root_process`
    // would be false for the root guest and Detcore would never register the
    // root thread with its scheduler, hanging every KVM run before the first
    // syscall. The traced-tree answer must stay independent of `getppid()`.
    #[test]
    fn renumbered_root_guest_has_no_traced_parent_but_keeps_getppid() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        // What `KvmBackend::set_root_pid(ROOT_DETPID)` produces.
        state.pid = 3;
        state.pgid = 3;
        state.tid = 3;
        state.ppid = 1;
        state.task_lifecycle = Arc::new(std::sync::Mutex::new(
            crate::elf::TaskLifecycleTable::with_root(3, 3, 3, true),
        ));
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(state, false);

        assert!(executor.parent_pid().is_none());
        // The guest-visible value is unchanged: `getppid()` still returns 1.
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_getppid as u64, [0, 0, 0, 0, 0, 0]),
                &memory,
            ),
            1
        );

        // A CLONE_THREAD worker stays in the root process, so it is also root.
        let thread = executor.thread_child(4).unwrap();
        assert!(thread.parent_pid().is_none());

        // A forked child does have a traced parent.
        let child = executor.fork_child(5, false, false).unwrap();
        assert_eq!(child.parent_pid(), Some(reverie::Pid::from_raw(3)));
    }

    #[test]
    fn thread_executors_share_mmap_allocation_cursor() {
        let root = TestDir::new();
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut state = test_state(&root.0);
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        let memory = GuestMemory::new(0, memory_size as usize).unwrap();
        let mut parent = ElfExecutor::new(state, false);
        let mut child = parent.thread_child(2).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_mmap as u64,
            [
                0,
                PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
                -1_i32 as u64,
                0,
            ],
        );

        let first = parent.execute(&request, &memory) as u64;
        let second = child.execute(&request, &memory) as u64;
        assert_eq!(first, BOOT_RESERVED_END + PAGE_SIZE);
        assert_eq!(second, first + PAGE_SIZE);
    }

    #[test]
    fn thread_executors_share_descriptor_replacement() {
        let root = TestDir::new();
        let old_path = root.0.join("old");
        let new_path = root.0.join("new");
        std::fs::write(&old_path, b"old").unwrap();
        std::fs::write(&new_path, b"new").unwrap();

        let mut state = test_state(&root.0);
        state
            .files
            .insert(3, std::fs::File::open(old_path).unwrap());
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut parent = ElfExecutor::new(state, false);
        let mut child = parent.thread_child(2).unwrap();

        assert_eq!(
            parent.execute(
                &SyscallRequest::new(libc::SYS_close as u64, [3, 0, 0, 0, 0, 0]),
                &memory,
            ),
            0
        );
        write_c_string(&mut memory, 0x100, new_path.to_str().unwrap());
        assert_eq!(
            parent.execute(
                &SyscallRequest::new(
                    libc::SYS_openat as u64,
                    [libc::AT_FDCWD as u64, 0x100, libc::O_RDONLY as u64, 0, 0, 0],
                ),
                &memory,
            ),
            3
        );

        assert_eq!(
            child.execute(
                &SyscallRequest::new(libc::SYS_read as u64, [3, 0x200, 3, 0, 0, 0]),
                &memory,
            ),
            3
        );
        let mut bytes = [0; 3];
        memory.read(0x200, &mut bytes).unwrap();
        assert_eq!(&bytes, b"new");
    }

    #[test]
    fn mprotect_and_munmap_bound_tool_user_copies() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let memory_size = BOOT_RESERVED_END + 8 * PAGE_SIZE;
        let mut memory = GuestMemory::new(0, memory_size as usize).unwrap();
        state.mmap_next = BOOT_RESERVED_END + PAGE_SIZE;
        state.mmap_limit = memory_size;
        let mapping = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_mmap,
            [
                0,
                2 * PAGE_SIZE,
                (libc::PROT_READ | libc::PROT_WRITE) as u64,
                (libc::MAP_PRIVATE | libc::MAP_ANONYMOUS) as u64,
                -1_i32 as u64,
                0,
            ],
        ) as u64;
        memory.enable_user_access();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mprotect,
                [
                    mapping + PAGE_SIZE,
                    PAGE_SIZE,
                    libc::PROT_NONE as u64,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        let boundary = AddrMut::from_raw((mapping + PAGE_SIZE - 8) as usize).unwrap();
        assert_eq!(
            MemoryAccess::write(&mut memory, boundary, &[0x5a; 16]).unwrap(),
            8
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mprotect,
                [
                    mapping + PAGE_SIZE,
                    PAGE_SIZE,
                    (libc::PROT_READ | libc::PROT_WRITE) as u64,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            MemoryAccess::write(&mut memory, boundary, &[0x33; 16]).unwrap(),
            16
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munmap,
                [mapping, 2 * PAGE_SIZE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mprotect,
                [mapping, PAGE_SIZE, libc::PROT_READ as u64, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
    }

    #[test]
    fn gettimeofday_is_deterministic_and_validates_outputs() {
        const TIMEVAL: u64 = 0x100;
        const TIMEZONE: u64 = 0x200;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_gettimeofday,
                [TIMEVAL, TIMEZONE, 0, 0, 0, 0],
            ),
            0
        );
        let timeval: libc::timeval = read_struct(&memory, TIMEVAL);
        assert_eq!((timeval.tv_sec, timeval.tv_usec), (0, 0));
        let timezone: [libc::c_int; 2] = read_struct(&memory, TIMEZONE);
        assert_eq!(timezone, [0, 0]);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_gettimeofday,
                [0, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_gettimeofday,
                [u64::MAX, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
    }

    #[test]
    fn child_sleep_syscalls_validate_requests_without_host_waiting() {
        const REQUEST: u64 = 0x100;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            write_struct(
                &mut memory,
                REQUEST,
                &libc::timespec {
                    tv_sec: 60,
                    tv_nsec: 123,
                },
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_nanosleep,
                [REQUEST, u64::MAX, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_REALTIME as u64, 0, REQUEST, u64::MAX, 0, 0,],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [
                    libc::CLOCK_MONOTONIC as u64,
                    libc::TIMER_ABSTIME as u64,
                    REQUEST,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_PROCESS_CPUTIME_ID as u64, 0, REQUEST, 0, 0, 0,],
            ),
            0
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_nanosleep,
                [0, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_REALTIME as u64, 0, u64::MAX, 0, 0, 0,],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            write_struct(
                &mut memory,
                REQUEST,
                &libc::timespec {
                    tv_sec: -1,
                    tv_nsec: 0,
                },
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_nanosleep,
                [REQUEST, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            write_struct(
                &mut memory,
                REQUEST,
                &libc::timespec {
                    tv_sec: 0,
                    tv_nsec: 1_000_000_000,
                },
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_REALTIME as u64, 0, REQUEST, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [u64::MAX, 0, REQUEST, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_clock_nanosleep,
                [libc::CLOCK_THREAD_CPUTIME_ID as u64, 0, REQUEST, 0, 0, 0,],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );
    }

    #[test]
    fn path_mutation_metadata_and_timestamp_syscalls_round_trip() {
        const DIRECTORY: u64 = 0x100;
        const SOURCE: u64 = 0x180;
        const HARD_LINK: u64 = 0x200;
        const SYMLINK: u64 = 0x280;
        const RENAMED: u64 = 0x300;
        const FIFO: u64 = 0x380;
        const DOT: u64 = 0x400;
        const FOLLOWED_LINK: u64 = 0x480;
        const STATFS: u64 = 0x500;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (DIRECTORY, "directory"),
            (SOURCE, "source"),
            (HARD_LINK, "hard-link"),
            (SYMLINK, "symlink"),
            (RENAMED, "renamed"),
            (FIFO, "fifo"),
            (DOT, "."),
            (FOLLOWED_LINK, "followed-link"),
        ] {
            write_c_string(&mut memory, address, value);
        }
        std::fs::write(root.0.join("source"), b"payload").unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_umask,
                [0o027, 0, 0, 0, 0, 0]
            ),
            0o022
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [DIRECTORY, 0o777, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("directory"))
                .unwrap()
                .permissions()
                .mode()
                & 0o777,
            0o750
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_linkat,
                [
                    libc::AT_FDCWD as u64,
                    SOURCE,
                    libc::AT_FDCWD as u64,
                    HARD_LINK,
                    0,
                    0
                ],
            ),
            0
        );
        assert_eq!(std::fs::read(root.0.join("hard-link")).unwrap(), b"payload");
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_symlinkat,
                [SOURCE, libc::AT_FDCWD as u64, SYMLINK, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::read_link(root.0.join("symlink")).unwrap(),
            Path::new("source")
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_linkat,
                [
                    libc::AT_FDCWD as u64,
                    SYMLINK,
                    libc::AT_FDCWD as u64,
                    FOLLOWED_LINK,
                    libc::AT_SYMLINK_FOLLOW as u64,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::read(root.0.join("followed-link")).unwrap(),
            b"payload"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_renameat,
                [
                    libc::AT_FDCWD as u64,
                    HARD_LINK,
                    libc::AT_FDCWD as u64,
                    RENAMED,
                    0,
                    0
                ],
            ),
            0
        );
        assert!(!root.0.join("hard-link").exists());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat,
                [libc::AT_FDCWD as u64, RENAMED, 0o600, 0xdead_beef, 0, 0,],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("renamed")).unwrap().mode() & 0o777,
            0o600
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [libc::AT_FDCWD as u64, RENAMED, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("renamed")).unwrap().mtime(),
            DETERMINISTIC_METADATA_SECONDS
        );
        let fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                RENAMED,
                libc::O_RDONLY as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [fd as u64, 0, 0, 0, 0, 0],
            ),
            0,
            "fd-based utimensat with a NULL pathname must use futimens"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        const EMPTY_OPATH: u64 = 0x580;
        write_c_string(&mut memory, EMPTY_OPATH, "");
        let path_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, RENAMED, libc::O_PATH as u64, 0, 0, 0],
        );
        assert_eq!(path_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [path_fd as u64, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF),
            "NULL-path timestamp updates reject O_PATH descriptors"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [
                    path_fd as u64,
                    EMPTY_OPATH,
                    0,
                    libc::AT_EMPTY_PATH as u64,
                    0,
                    0,
                ],
            ),
            0,
            "AT_EMPTY_PATH accepts O_PATH descriptors"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [path_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        const OMIT_TIMES: u64 = 0x600;
        const CREATED: u64 = 0x700;
        let omit = libc::timespec {
            tv_sec: 0,
            tv_nsec: libc::UTIME_OMIT,
        };
        assert_eq!(write_struct(&mut memory, OMIT_TIMES, &omit), 0);
        assert_eq!(
            write_struct(
                &mut memory,
                OMIT_TIMES + std::mem::size_of::<libc::timespec>() as u64,
                &omit,
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_utimensat,
                [libc::AT_FDCWD as u64, u64::MAX, OMIT_TIMES, 0, 0, 0],
            ),
            0,
            "two UTIME_OMIT values must not resolve the pathname"
        );

        write_c_string(&mut memory, CREATED, "created");
        state.umask = 0;
        let created_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                CREATED,
                (libc::O_CREAT | libc::O_EXCL | libc::O_WRONLY) as u64,
                0o666,
                0,
                0,
            ],
        );
        assert!(created_fd >= 0);
        assert_eq!(
            std::fs::metadata(root.0.join("created")).unwrap().mode() & 0o777,
            0o666,
            "the supervisor umask must not be applied after the guest umask"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [created_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_unlinkat,
                [libc::AT_FDCWD as u64, CREATED, 0, 0, 0, 0],
            ),
            0
        );

        std::os::unix::fs::symlink("created-target", root.0.join("created-link")).unwrap();
        write_c_string(&mut memory, CREATED, "created-link");
        let symlink_created_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                CREATED,
                (libc::O_CREAT | libc::O_WRONLY) as u64,
                0o666,
                0,
                0,
            ],
        );
        assert!(symlink_created_fd >= 0);
        assert_eq!(
            std::fs::metadata(root.0.join("created-target"))
                .unwrap()
                .mode()
                & 0o777,
            0o666,
            "guest umask must apply when O_CREAT follows a dangling symlink"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [symlink_created_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let protected = root.0.join("protected");
        std::fs::write(&protected, b"payload").unwrap();
        std::fs::set_permissions(&protected, std::fs::Permissions::from_mode(0o600)).unwrap();
        let protected_file = std::fs::File::open(&protected).unwrap();
        write_c_string(
            &mut memory,
            CREATED,
            &format!("/proc/self/fd/{}", protected_file.as_raw_fd()),
        );
        assert!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat,
                [libc::AT_FDCWD as u64, CREATED, 0o777, 0, 0, 0],
            ) < 0,
            "guest mutations must not follow supervisor procfs descriptors"
        );
        assert_eq!(std::fs::metadata(&protected).unwrap().mode() & 0o777, 0o600);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mknodat,
                [
                    libc::AT_FDCWD as u64,
                    FIFO,
                    (libc::S_IFIFO | 0o666) as u64,
                    0,
                    0,
                    0
                ],
            ),
            0
        );
        assert!(
            std::fs::symlink_metadata(root.0.join("fifo"))
                .unwrap()
                .file_type()
                .is_fifo()
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_statfs,
                [DOT, STATFS, 0, 0, 0, 0],
            ),
            0
        );
        let statfs: libc::statfs = read_struct(&memory, STATFS);
        assert_ne!(statfs.f_type, 0);

        for path in [RENAMED, SYMLINK, FIFO, FOLLOWED_LINK] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_unlinkat,
                    [libc::AT_FDCWD as u64, path, 0, 0, 0, 0],
                ),
                0
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_unlinkat,
                [
                    libc::AT_FDCWD as u64,
                    DIRECTORY,
                    libc::AT_REMOVEDIR as u64,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [99, DIRECTORY, 0o755, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
    }

    #[test]
    fn fchmodat2_matches_linux_flags_empty_path_and_error_ordering() {
        const FILE: u64 = 0x100;
        const LINK: u64 = 0x200;
        const MISSING: u64 = 0x300;
        const EMPTY: u64 = 0x400;
        const PROTECTED: u64 = 0x500;
        const SYNTHETIC_PROC: u64 = 0x600;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (FILE, "file"),
            (LINK, "link"),
            (MISSING, "missing"),
            (EMPTY, ""),
            (SYNTHETIC_PROC, "/proc/version"),
        ] {
            write_c_string(&mut memory, address, value);
        }
        std::fs::write(root.0.join("file"), b"payload").unwrap();
        std::fs::set_permissions(root.0.join("file"), std::fs::Permissions::from_mode(0o600))
            .unwrap();
        std::os::unix::fs::symlink("file", root.0.join("link")).unwrap();

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    libc::AT_FDCWD as u64,
                    FILE,
                    0o640,
                    0,
                    0xdead_beef,
                    0xcafe_babe,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o640
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    libc::AT_FDCWD as u64,
                    FILE,
                    0o600,
                    libc::AT_SYMLINK_NOFOLLOW as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [libc::AT_FDCWD as u64, LINK, 0o644, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o644
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    libc::AT_FDCWD as u64,
                    LINK,
                    0o600,
                    libc::AT_SYMLINK_NOFOLLOW as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o644
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [libc::AT_FDCWD as u64, MISSING, 0o600, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, u64::MAX, 0o600, 0xffff, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "invalid flags precede pathname and dirfd checks"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, u64::MAX, 0o600, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT),
            "pathname access precedes a relative-path dirfd check"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, EMPTY, 0o600, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [99, EMPTY, 0o600, libc::AT_EMPTY_PATH as u64, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );

        let file_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [libc::AT_FDCWD as u64, FILE, libc::O_PATH as u64, 0, 0, 0],
        );
        assert_eq!(file_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    file_fd as u64,
                    EMPTY,
                    !0o7777_u64 | 0o640,
                    libc::AT_EMPTY_PATH as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o640
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    file_fd as u64,
                    EMPTY,
                    0o600,
                    (libc::AT_EMPTY_PATH | libc::AT_SYMLINK_NOFOLLOW) as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("file")).unwrap().mode() & 0o7777,
            0o600
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [file_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let link_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                LINK,
                (libc::O_PATH | libc::O_NOFOLLOW) as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(link_fd, 3);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    link_fd as u64,
                    EMPTY,
                    0o600,
                    (libc::AT_EMPTY_PATH | libc::AT_SYMLINK_NOFOLLOW) as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EOPNOTSUPP)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [link_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let synthetic_proc_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                SYNTHETIC_PROC,
                libc::O_RDONLY as u64,
                0,
                0,
                0,
            ],
        );
        assert_eq!(synthetic_proc_fd, 3);
        assert!(
            state
                .proc_files
                .contains_key(&(synthetic_proc_fd as libc::c_int))
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [
                    synthetic_proc_fd as u64,
                    EMPTY,
                    0o777,
                    libc::AT_EMPTY_PATH as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [synthetic_proc_fd as u64, 0, 0, 0, 0, 0],
            ),
            0
        );

        let protected = root.0.join("protected");
        std::fs::write(&protected, b"payload").unwrap();
        std::fs::set_permissions(&protected, std::fs::Permissions::from_mode(0o600)).unwrap();
        let protected_file = std::fs::File::open(&protected).unwrap();
        write_c_string(
            &mut memory,
            PROTECTED,
            &format!("/proc/self/fd/{}", protected_file.as_raw_fd()),
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmodat2,
                [libc::AT_FDCWD as u64, PROTECTED, 0o777, 0, 0, 0],
            ),
            negative_errno(libc::EACCES)
        );
        assert_eq!(std::fs::metadata(protected).unwrap().mode() & 0o7777, 0o600);
    }

    #[test]
    fn read_path_at_preserves_trailing_slashes_and_edge_cases() {
        const EMPTY: u64 = 0x900;

        let root = TestDir::new();
        std::fs::create_dir_all(root.0.join("nested/existing")).unwrap();
        std::fs::write(root.0.join("regular"), b"payload").unwrap();
        let state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let absolute = format!("{}/absolute///", root.0.display());
        let cases = [
            (0x100, "new/"),
            (0x200, "new///"),
            (0x300, "nested//new///"),
            (0x400, absolute.as_str()),
            (0x500, "nested/existing///"),
            (0x600, "regular///"),
            (0x700, "/"),
            (0x800, "///"),
        ];

        for (address, value) in cases {
            write_c_string(&mut memory, address, value);
            let (_, path) = read_path_at(&memory, &state, libc::AT_FDCWD, address, false)
                .unwrap_or_else(|error| panic!("{value:?} failed with {error}"));
            assert_eq!(path.to_bytes(), value.as_bytes(), "{value:?}");
        }

        write_c_string(&mut memory, EMPTY, "");
        let (_, empty) = read_path_at(&memory, &state, libc::AT_FDCWD, EMPTY, true).unwrap();
        assert!(empty.to_bytes().is_empty());
        assert_eq!(
            read_path_at(&memory, &state, libc::AT_FDCWD, EMPTY, false).unwrap_err(),
            negative_errno(libc::ENOENT)
        );
    }

    #[test]
    fn mkdir_with_trailing_slash_creates_git_hooks_directory() {
        const HOOKS: u64 = 0x100;
        const OBJECTS: u64 = 0x300;
        const REFS: u64 = 0x500;

        let root = TestDir::new();
        std::fs::create_dir_all(root.0.join("repo/.git")).unwrap();
        let mut state = test_state(&root.0);
        state
            .files
            .insert(3, std::fs::File::open(root.0.join("repo")).unwrap());
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_c_string(&mut memory, HOOKS, "repo/.git/hooks/");
        write_c_string(&mut memory, OBJECTS, ".git/objects///");
        write_c_string(
            &mut memory,
            REFS,
            &format!("{}/repo/.git/refs///", root.0.display()),
        );

        // Mutation check: restoring the old last-slash parent selection makes
        // the first mkdir return ENOENT instead of creating the hooks directory.

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [HOOKS, 0o755, 0, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("repo/.git/hooks").is_dir());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [3, OBJECTS, 0o755, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("repo/.git/objects").is_dir());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [REFS, 0o755, 0, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("repo/.git/refs").is_dir());
    }

    #[test]
    fn trailing_slash_keeps_linux_target_semantics() {
        const DIRECTORY: u64 = 0x100;
        const REGULAR: u64 = 0x300;
        const ROOT: u64 = 0x500;
        const REPEATED_ROOT: u64 = 0x700;
        const EMPTY: u64 = 0x900;

        let root = TestDir::new();
        std::fs::create_dir(root.0.join("directory")).unwrap();
        std::fs::set_permissions(
            root.0.join("directory"),
            std::fs::Permissions::from_mode(0o755),
        )
        .unwrap();
        std::fs::write(root.0.join("regular"), b"payload").unwrap();
        std::fs::set_permissions(
            root.0.join("regular"),
            std::fs::Permissions::from_mode(0o600),
        )
        .unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (DIRECTORY, "directory///"),
            (REGULAR, "regular///"),
            (ROOT, "/"),
            (REPEATED_ROOT, "///"),
            (EMPTY, ""),
        ] {
            write_c_string(&mut memory, address, value);
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chmod,
                [DIRECTORY, 0o711, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            std::fs::metadata(root.0.join("directory")).unwrap().mode() & 0o777,
            0o711
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_chmod,
                [REGULAR, 0o777, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );
        assert_eq!(
            std::fs::metadata(root.0.join("regular")).unwrap().mode() & 0o777,
            0o600
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_unlink,
                [REGULAR, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );
        assert!(root.0.join("regular").exists());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [DIRECTORY, 0o755, 0, 0, 0, 0],
            ),
            negative_errno(libc::EEXIST)
        );
        for address in [ROOT, REPEATED_ROOT] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_mkdir,
                    [address, 0o755, 0, 0, 0, 0],
                ),
                negative_errno(libc::EEXIST)
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [EMPTY, 0o755, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );
    }

    #[test]
    fn all_read_path_at_mutation_dispatchers_reject_procfs_with_trailing_slash() {
        const PROTECTED: u64 = 0x100;
        const LOCAL_SOURCE: u64 = 0x500;

        let root = TestDir::new();
        std::fs::write(root.0.join("local-source"), b"payload").unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_c_string(
            &mut memory,
            PROTECTED,
            &format!(
                "/proc/{}/reverie-kvm-mutation-missing///",
                std::process::id()
            ),
        );
        write_c_string(&mut memory, LOCAL_SOURCE, "local-source");
        let at_fdcwd = libc::AT_FDCWD as u64;
        let calls = [
            ("mkdir", libc::SYS_mkdir, [PROTECTED, 0o755, 0, 0, 0, 0]),
            (
                "mkdirat",
                libc::SYS_mkdirat,
                [at_fdcwd, PROTECTED, 0o755, 0, 0, 0],
            ),
            ("unlink", libc::SYS_unlink, [PROTECTED, 0, 0, 0, 0, 0]),
            ("rmdir", libc::SYS_rmdir, [PROTECTED, 0, 0, 0, 0, 0]),
            (
                "unlinkat",
                libc::SYS_unlinkat,
                [at_fdcwd, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "rename",
                libc::SYS_rename,
                [LOCAL_SOURCE, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "renameat",
                libc::SYS_renameat,
                [at_fdcwd, LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0],
            ),
            (
                "renameat2",
                libc::SYS_renameat2,
                [at_fdcwd, LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0],
            ),
            (
                "link",
                libc::SYS_link,
                [LOCAL_SOURCE, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "linkat",
                libc::SYS_linkat,
                [at_fdcwd, LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0],
            ),
            (
                "symlink",
                libc::SYS_symlink,
                [LOCAL_SOURCE, PROTECTED, 0, 0, 0, 0],
            ),
            (
                "symlinkat",
                libc::SYS_symlinkat,
                [LOCAL_SOURCE, at_fdcwd, PROTECTED, 0, 0, 0],
            ),
            ("chmod", libc::SYS_chmod, [PROTECTED, 0o600, 0, 0, 0, 0]),
            (
                "fchmodat",
                libc::SYS_fchmodat,
                [at_fdcwd, PROTECTED, 0o600, 0, 0, 0],
            ),
            (
                "mknod",
                libc::SYS_mknod,
                [PROTECTED, (libc::S_IFIFO | 0o600) as u64, 0, 0, 0, 0],
            ),
            (
                "mknodat",
                libc::SYS_mknodat,
                [at_fdcwd, PROTECTED, (libc::S_IFIFO | 0o600) as u64, 0, 0, 0],
            ),
            (
                "utimensat",
                libc::SYS_utimensat,
                [at_fdcwd, PROTECTED, 0, 0, 0, 0],
            ),
        ];
        assert_eq!(calls.len(), 17);

        for (name, number, args) in calls {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                negative_errno(libc::EACCES),
                "{name} did not preserve the procfs mutation guard"
            );
        }
        assert_eq!(
            std::fs::read(root.0.join("local-source")).unwrap(),
            b"payload"
        );
    }

    #[test]
    fn synthetic_proc_directory_fd_rejects_relative_mutation() {
        const PROC: u64 = 0x100;
        const ESCAPE: u64 = 0x300;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        write_c_string(&mut memory, PROC, "/proc");
        let proc_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PROC,
                (libc::O_RDONLY | libc::O_DIRECTORY) as u64,
                0,
                0,
                0,
            ],
        );
        assert!(proc_fd >= 0, "open /proc failed: {proc_fd}");

        let escaped = format!(
            "tmp/{}/escaped/",
            root.0.file_name().unwrap().to_string_lossy()
        );
        write_c_string(&mut memory, ESCAPE, &escaped);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [proc_fd as u64, ESCAPE, 0o755, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );
        assert!(!root.0.join("escaped").exists());
    }

    #[test]
    fn synthetic_proc_directory_fd_rejects_every_relative_mutation_dispatcher() {
        const PROC: u64 = 0x100;
        const ESCAPED_MISSING: u64 = 0x300;
        const ESCAPED_FILE: u64 = 0x500;
        const ESCAPED_DIRECTORY: u64 = 0x700;
        const LOCAL_SOURCE: u64 = 0x900;
        const LOCAL_DESTINATION: u64 = 0xb00;
        const ABSOLUTE_TARGET: u64 = 0xd00;

        let root = TestDir::new();
        std::fs::write(root.0.join("local-source"), b"payload").unwrap();
        std::fs::set_permissions(
            root.0.join("local-source"),
            std::fs::Permissions::from_mode(0o600),
        )
        .unwrap();
        std::fs::create_dir(root.0.join("removable")).unwrap();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        write_c_string(&mut memory, PROC, "/proc");
        let proc_fd = syscall_result(
            &mut memory,
            &mut state,
            libc::SYS_openat,
            [
                libc::AT_FDCWD as u64,
                PROC,
                (libc::O_RDONLY | libc::O_DIRECTORY) as u64,
                0,
                0,
                0,
            ],
        );
        assert!(proc_fd >= 0, "open /proc failed: {proc_fd}");

        let host_relative_root = format!("tmp/{}", root.0.file_name().unwrap().to_string_lossy());
        write_c_string(
            &mut memory,
            ESCAPED_MISSING,
            &format!("{host_relative_root}/escaped///"),
        );
        write_c_string(
            &mut memory,
            ESCAPED_FILE,
            &format!("{host_relative_root}/local-source"),
        );
        write_c_string(
            &mut memory,
            ESCAPED_DIRECTORY,
            &format!("{host_relative_root}/removable///"),
        );
        write_c_string(&mut memory, LOCAL_SOURCE, "local-source");
        write_c_string(&mut memory, LOCAL_DESTINATION, "local-destination");
        write_c_string(
            &mut memory,
            ABSOLUTE_TARGET,
            &format!("{}/absolute-target///", root.0.display()),
        );
        let proc_fd = proc_fd as u64;
        let at_fdcwd = libc::AT_FDCWD as u64;
        let calls = [
            (
                "mkdirat",
                libc::SYS_mkdirat,
                [proc_fd, ESCAPED_MISSING, 0o755, 0, 0, 0],
            ),
            (
                "unlinkat",
                libc::SYS_unlinkat,
                [
                    proc_fd,
                    ESCAPED_DIRECTORY,
                    libc::AT_REMOVEDIR as u64,
                    0,
                    0,
                    0,
                ],
            ),
            (
                "renameat source",
                libc::SYS_renameat,
                [proc_fd, ESCAPED_FILE, at_fdcwd, LOCAL_DESTINATION, 0, 0],
            ),
            (
                "renameat destination",
                libc::SYS_renameat,
                [at_fdcwd, LOCAL_SOURCE, proc_fd, ESCAPED_MISSING, 0, 0],
            ),
            (
                "renameat2 source",
                libc::SYS_renameat2,
                [proc_fd, ESCAPED_FILE, at_fdcwd, LOCAL_DESTINATION, 0, 0],
            ),
            (
                "renameat2 destination",
                libc::SYS_renameat2,
                [at_fdcwd, LOCAL_SOURCE, proc_fd, ESCAPED_MISSING, 0, 0],
            ),
            (
                "linkat source",
                libc::SYS_linkat,
                [proc_fd, ESCAPED_FILE, at_fdcwd, LOCAL_DESTINATION, 0, 0],
            ),
            (
                "linkat destination",
                libc::SYS_linkat,
                [at_fdcwd, LOCAL_SOURCE, proc_fd, ESCAPED_MISSING, 0, 0],
            ),
            (
                "symlinkat",
                libc::SYS_symlinkat,
                [LOCAL_SOURCE, proc_fd, ESCAPED_MISSING, 0, 0, 0],
            ),
            (
                "fchmodat",
                libc::SYS_fchmodat,
                [proc_fd, ESCAPED_FILE, 0o777, 0, 0, 0],
            ),
            (
                "mknodat",
                libc::SYS_mknodat,
                [
                    proc_fd,
                    ESCAPED_MISSING,
                    (libc::S_IFIFO | 0o600) as u64,
                    0,
                    0,
                    0,
                ],
            ),
            (
                "utimensat",
                libc::SYS_utimensat,
                [proc_fd, ESCAPED_FILE, 0, 0, 0, 0],
            ),
        ];
        assert_eq!(calls.len(), 12);

        for (name, number, args) in calls {
            assert_eq!(
                syscall_result(&mut memory, &mut state, number, args),
                negative_errno(libc::ENOENT),
                "{name} lost the guest synthetic-proc directory identity"
            );
        }
        assert_eq!(
            std::fs::read(root.0.join("local-source")).unwrap(),
            b"payload"
        );
        assert_eq!(
            std::fs::metadata(root.0.join("local-source"))
                .unwrap()
                .mode()
                & 0o777,
            0o600
        );
        assert!(root.0.join("removable").is_dir());
        assert!(!root.0.join("escaped").exists());
        assert!(!root.0.join("local-destination").exists());

        // Absolute paths ignore dirfd on Linux, including a synthetic proc fd.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [proc_fd, ABSOLUTE_TARGET, 0o755, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("absolute-target").is_dir());
    }

    #[test]
    fn utimensat_rejects_empty_paths_on_every_synthetic_proc_inode() {
        const EMPTY: u64 = 0x500;
        const CHILD: u64 = 0x700;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, 2 * PAGE_SIZE as usize).unwrap();
        let proc_directory_fd = open_readonly(&mut memory, &mut state, "/proc");
        assert!(proc_directory_fd >= 0);
        let proc_file_fd = open_readonly(&mut memory, &mut state, "/proc/uptime");
        assert!(proc_file_fd >= 0);
        write_c_string(&mut memory, EMPTY, "");
        write_c_string(&mut memory, CHILD, "child/");

        for (name, fd, path, flags) in [
            ("directory NULL", proc_directory_fd, 0, 0),
            (
                "directory empty",
                proc_directory_fd,
                EMPTY,
                libc::AT_EMPTY_PATH as u64,
            ),
            ("file NULL", proc_file_fd, 0, 0),
            (
                "file empty",
                proc_file_fd,
                EMPTY,
                libc::AT_EMPTY_PATH as u64,
            ),
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_utimensat,
                    [fd as u64, path, 0, flags, 0, 0],
                ),
                negative_errno(libc::EACCES),
                "{name} mutated a synthetic proc backing descriptor"
            );
        }

        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdirat,
                [proc_file_fd as u64, CHILD, 0o755, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR),
            "a nonempty path under a synthetic regular file retains ENOTDIR"
        );
    }

    #[test]
    fn rmdir_removes_empty_directories_like_unlinkat_removedir() {
        const DIRECTORY: u64 = 0x100;
        const FILE: u64 = 0x200;
        const NONEMPTY: u64 = 0x300;
        const MISSING: u64 = 0x400;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        for (address, value) in [
            (DIRECTORY, "directory"),
            (FILE, "file"),
            (NONEMPTY, "nonempty"),
            (MISSING, "missing"),
        ] {
            write_c_string(&mut memory, address, value);
        }

        // A bare rmdir(2) removes an empty directory. Regression: this syscall
        // previously fell through to ENOSYS under the KVM backend, so coreutils
        // `rmdir` and `mktemp -d` cleanup failed even though `rm -rf` (which
        // uses unlinkat(AT_REMOVEDIR)) worked.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mkdir,
                [DIRECTORY, 0o755, 0, 0, 0, 0],
            ),
            0
        );
        assert!(root.0.join("directory").is_dir());
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [DIRECTORY, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert!(!root.0.join("directory").exists());

        // rmdir on a missing path reports ENOENT, not ENOSYS.
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [MISSING, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOENT)
        );

        // rmdir on a regular file reports ENOTDIR.
        std::fs::write(root.0.join("file"), b"payload").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [FILE, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTDIR)
        );

        // rmdir refuses a non-empty directory with ENOTEMPTY.
        std::fs::create_dir(root.0.join("nonempty")).unwrap();
        std::fs::write(root.0.join("nonempty/child"), b"payload").unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rmdir,
                [NONEMPTY, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOTEMPTY)
        );
    }

    #[test]
    fn descriptor_duplication_and_fchmod_preserve_guest_fd_semantics() {
        let root = TestDir::new();
        let path = root.0.join("descriptor");
        std::fs::write(&path, b"payload").unwrap();
        let mut state = test_state(&root.0);
        state.files.insert(
            3,
            std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path)
                .unwrap(),
        );
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_dup, [3, 0, 0, 0, 0, 0]),
            4
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_dup2, [3, 0, 0, 0, 0, 0],),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fchmod,
                [4, 0o640, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(std::fs::metadata(&path).unwrap().mode() & 0o777, 0o640);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, 3, libc::O_CLOEXEC as u64, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, 9, u64::MAX, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [u64::MAX, 9, u64::MAX, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL),
            "dup3 validates flags before the old descriptor"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, 10, 1_u64 << 32, 0, 0, 0],
            ),
            10,
            "dup3 flags use the low 32-bit Linux int ABI"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [u64::MAX, 11, 1_u64 << 32, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [10, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [(1_u64 << 32) | 3, 90, 0, 0, 0, 0],
            ),
            90
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_dup3,
                [3, (1_u64 << 32) | 91, 0, 0, 0, 0],
            ),
            91
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [90, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_close,
                [91, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_SETFD as u64, libc::FD_CLOEXEC as u64, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_GETFD as u64, 0, 0, 0, 0],
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD as u64, 10, 0, 0, 0],
            ),
            10
        );
        assert!(state.files.contains_key(&10));
        assert!(!state.cloexec_fds.contains(&10));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD_CLOEXEC as u64, 10, 0, 0, 0],
            ),
            11
        );
        assert!(state.cloexec_fds.contains(&11));
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD as u64, u64::MAX, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [4, libc::F_DUPFD as u64, GUEST_NOFILE_LIMIT as u64, 0, 0, 0,],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [u64::MAX, libc::F_DUPFD as u64, 0, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_fcntl,
                [(1_u64 << 32) | 4, libc::F_DUPFD as u64, 12, 0, 0, 0],
            ),
            12,
            "fcntl source fds use the low 32-bit Linux ABI"
        );
        for resource in [
            libc::RLIMIT_NOFILE as u64,
            (1_u64 << 32) | libc::RLIMIT_NOFILE as u64,
        ] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_prlimit64,
                    [0, resource, 0, 0x200, 0, 0],
                ),
                0
            );
            let nofile = read_guest_bytes::<16>(&memory, 0x200).unwrap();
            assert_eq!(
                u64::from_le_bytes(nofile[..8].try_into().unwrap()),
                GUEST_NOFILE_LIMIT as u64
            );
            assert_eq!(
                u64::from_le_bytes(nofile[8..].try_into().unwrap()),
                GUEST_NOFILE_LIMIT as u64
            );
        }
        for fd in [10, 11, 12] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_close,
                    [fd, 0, 0, 0, 0, 0],
                ),
                0
            );
        }
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_close, [0, 0, 0, 0, 0, 0],),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_read,
                [0, 0x100, 1, 0, 0, 0],
            ),
            negative_errno(libc::EBADF)
        );
    }

    #[test]
    fn ioctl_cloexec_commands_update_guest_descriptor_flags() {
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        state
            .files
            .insert(3, std::fs::File::open("/dev/null").unwrap());
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(state, false);

        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, libc::FIOCLEX, 0, 0, 0, 0],),
                &memory,
            ),
            0
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_fcntl as u64,
                    [3, libc::F_GETFD as u64, 0, 0, 0, 0],
                ),
                &memory,
            ),
            i64::from(libc::FD_CLOEXEC)
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, libc::FIONCLEX, 0, 0, 0, 0],),
                &memory,
            ),
            0
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_fcntl as u64,
                    [3, libc::F_GETFD as u64, 0, 0, 0, 0],
                ),
                &memory,
            ),
            0
        );
        // The host descriptor remains private even when the guest clears its
        // independently modeled close-on-exec bit.
        let host_fd = executor.state.files.get(&3).unwrap().as_raw_fd();
        assert_ne!(
            unsafe { libc::fcntl(host_fd, libc::F_GETFD) } & libc::FD_CLOEXEC,
            0
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [99, libc::FIOCLEX, 0, 0, 0, 0],),
                &memory,
            ),
            negative_errno(libc::EBADF)
        );
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, SIOCETHTOOL, 0, 0, 0, 0],),
                &memory,
            ),
            negative_errno(libc::ENODEV)
        );
    }

    #[test]
    fn ioctl_terminal_queries_report_real_tty_ness() {
        // A real terminal answers TCGETS/TIOCGWINSZ successfully; a non-terminal
        // descriptor answers ENOTTY. The executor must forward these ioctls to
        // the host descriptor and report the real answer, so a guest's isatty()
        // matches the ptrace backend instead of always seeing a non-tty.
        let root = TestDir::new();
        let mut state = test_state(&root.0);

        // Open a pseudo-terminal; the slave end is a real tty.
        let mut master: libc::c_int = -1;
        let mut slave: libc::c_int = -1;
        let rc = unsafe {
            libc::openpty(
                &mut master,
                &mut slave,
                std::ptr::null_mut(),
                std::ptr::null(),
                std::ptr::null(),
            )
        };
        assert_eq!(rc, 0, "openpty failed: {}", std::io::Error::last_os_error());

        // Guest fd 3 -> the tty slave; guest fd 4 -> /dev/null (not a tty).
        // SAFETY: `slave` is a freshly opened, owned fd handed to the File.
        state
            .files
            .insert(3, unsafe { std::fs::File::from_raw_fd(slave) });
        state
            .files
            .insert(4, std::fs::File::open("/dev/null").unwrap());

        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(state, false);

        // TCGETS on the tty succeeds -> isatty() == true.
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [3, libc::TCGETS, 0x100, 0, 0, 0]),
                &memory,
            ),
            0,
        );
        // TIOCGWINSZ on the tty succeeds.
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_ioctl as u64,
                    [3, libc::TIOCGWINSZ, 0x100, 0, 0, 0]
                ),
                &memory,
            ),
            0,
        );
        // TCGETS on a non-tty forwards to the host and reports the real ENOTTY,
        // so isatty() stays false for pipes/files (piped output is unchanged).
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(libc::SYS_ioctl as u64, [4, libc::TCGETS, 0x100, 0, 0, 0]),
                &memory,
            ),
            negative_errno(libc::ENOTTY),
        );

        // SAFETY: `master` is the still-open master end owned by this test.
        unsafe {
            libc::close(master);
        }
    }

    #[test]
    fn signal_state_round_trips_and_filters_unmaskable_signals() {
        const ACTION: u64 = 0x100;
        const OLD_ACTION: u64 = 0x180;
        const MASK: u64 = 0x200;
        const OLD_MASK: u64 = 0x280;
        const ALT_STACK: u64 = 0x300;
        const OLD_ALT_STACK: u64 = 0x380;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut action = [0x5a; KERNEL_SIGACTION_SIZE];
        action[KERNEL_SIGACTION_SIZE - KERNEL_SIGSET_SIZE..].fill(u8::MAX);
        let mut expected_action = action;
        for signal in [libc::SIGKILL, libc::SIGSTOP] {
            let bit = (signal - 1) as usize;
            expected_action[KERNEL_SIGACTION_SIZE - KERNEL_SIGSET_SIZE + bit / 8] &=
                !(1 << (bit % 8));
        }
        memory.write(ACTION, &action).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGUSR1 as u64,
                    ACTION,
                    OLD_ACTION,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGACTION_SIZE>(&memory, OLD_ACTION).unwrap(),
            [0; KERNEL_SIGACTION_SIZE]
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGUSR1 as u64,
                    0,
                    OLD_ACTION,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGACTION_SIZE>(&memory, OLD_ACTION).unwrap(),
            expected_action
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGKILL as u64,
                    ACTION,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigaction,
                [
                    libc::SIGUSR2 as u64,
                    ACTION,
                    u64::MAX,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            test_signal_action(&state, libc::SIGUSR2),
            Some(expected_action),
            "new sigaction remains installed if copying old action fails"
        );

        memory.write(MASK, &[u8::MAX; KERNEL_SIGSET_SIZE]).unwrap();
        memory.write(OLD_MASK, &[0x33; KERNEL_SIGSET_SIZE]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [99, MASK, OLD_MASK, KERNEL_SIGSET_SIZE as u64, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(test_blocked_mask(&state), [0; KERNEL_SIGSET_SIZE]);
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGSET_SIZE>(&memory, OLD_MASK).unwrap(),
            [0x33; KERNEL_SIGSET_SIZE],
            "invalid how must not copy the old mask"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [
                    libc::SIG_SETMASK as u64,
                    MASK,
                    OLD_MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            read_guest_bytes::<KERNEL_SIGSET_SIZE>(&memory, OLD_MASK).unwrap(),
            [0; KERNEL_SIGSET_SIZE]
        );
        assert_eq!(
            test_blocked_mask(&state)[1] & 1,
            0,
            "SIGKILL must remain unblocked"
        );
        assert_eq!(
            test_blocked_mask(&state)[2] & 4,
            0,
            "SIGSTOP must remain unblocked"
        );
        memory.write(MASK, &[0; KERNEL_SIGSET_SIZE]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_rt_sigprocmask,
                [
                    libc::SIG_SETMASK as u64,
                    MASK,
                    u64::MAX,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            negative_errno(libc::EFAULT)
        );
        assert_eq!(
            test_blocked_mask(&state),
            [0; KERNEL_SIGSET_SIZE],
            "new signal mask remains installed if copying the old mask fails"
        );

        let stack = GuestStack {
            sp: 0x800,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        assert_eq!(write_bytes(&mut memory, ALT_STACK, &stack.encode()), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sigaltstack,
                [ALT_STACK, OLD_ALT_STACK, 0, 0, 0, 0],
            ),
            0
        );
        let previous = GuestStack::decode(read_guest_bytes::<24>(&memory, OLD_ALT_STACK).unwrap());
        assert_eq!(previous.flags, libc::SS_DISABLE);
        let disabled = GuestStack {
            sp: u64::MAX,
            flags: libc::SS_DISABLE,
            size: u64::MAX,
        };
        assert_eq!(write_bytes(&mut memory, ALT_STACK, &disabled.encode()), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sigaltstack,
                [ALT_STACK, u64::MAX, 0, 0, 0, 0],
            ),
            negative_errno(libc::EFAULT)
        );
        assert!(
            state.thread_signals.lock().altstack.is_none(),
            "disabled altstack remains applied if copying the old stack fails"
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sigaltstack,
                [0, OLD_ALT_STACK, 0, 0, 0, 0],
            ),
            0
        );
        let disabled_query =
            GuestStack::decode(read_guest_bytes::<24>(&memory, OLD_ALT_STACK).unwrap());
        assert_eq!(disabled_query.sp, 0);
        assert_eq!(disabled_query.flags, libc::SS_DISABLE);
        assert_eq!(disabled_query.size, 0);
        let child = state.try_clone_for_fork(2).unwrap();
        assert_eq!(
            test_signal_action(&child, libc::SIGUSR1),
            Some(expected_action)
        );
        assert_eq!(
            child.thread_signals.lock().blocked,
            state.thread_signals.lock().blocked
        );
        assert_eq!(
            child.thread_signals.lock().altstack,
            state.thread_signals.lock().altstack
        );
    }

    #[test]
    fn exec_closes_cloexec_descriptors_and_resets_caught_signals() {
        let root = TestDir::new();
        let path = root.0.join("descriptor");
        std::fs::write(&path, b"payload").unwrap();
        let mut previous = test_state(&root.0);
        previous
            .files
            .insert(3, std::fs::File::open(&path).unwrap());
        previous
            .files
            .insert(4, std::fs::File::open(&path).unwrap());
        previous.cloexec_fds.extend([libc::STDIN_FILENO, 4]);
        previous.thread_signals.lock().altstack = Some(GuestStack {
            sp: 1,
            flags: 0,
            size: 16,
        });
        previous.pgid = 55;
        let mut ignored = [0x7f; KERNEL_SIGACTION_SIZE];
        ignored[..std::mem::size_of::<usize>()].copy_from_slice(&libc::SIG_IGN.to_ne_bytes());
        let mut canonical_ignored = [0; KERNEL_SIGACTION_SIZE];
        canonical_ignored[..std::mem::size_of::<usize>()]
            .copy_from_slice(&libc::SIG_IGN.to_ne_bytes());
        let mut caught = [0; KERNEL_SIGACTION_SIZE];
        caught[..std::mem::size_of::<usize>()].copy_from_slice(&2usize.to_ne_bytes());
        test_install_signal_action(&previous, libc::SIGUSR1, ignored);
        test_install_signal_action(&previous, libc::SIGUSR2, caught);
        let mut replacement = test_state(&root.0);
        replacement.inherit_process_state(previous);
        assert!(replacement.files.contains_key(&3));
        assert!(!replacement.files.contains_key(&4));
        assert!(replacement.stdin.is_none());
        assert!(
            replacement
                .closed_standard_fds
                .contains(&libc::STDIN_FILENO)
        );
        assert!(replacement.cloexec_fds.is_empty());
        assert_eq!(
            test_signal_action(&replacement, libc::SIGUSR1),
            Some(canonical_ignored)
        );
        assert_eq!(test_signal_action(&replacement, libc::SIGUSR2), None);
        assert!(replacement.thread_signals.lock().altstack.is_none());
        assert_eq!(replacement.pgid, 55, "exec preserves the process group");
        assert_eq!(
            replacement
                .task_lifecycle
                .lock()
                .unwrap()
                .get(replacement.tid)
                .unwrap()
                .pgid,
            55,
        );
    }

    #[test]
    fn altstack_uses_open_lower_and_closed_upper_boundaries() {
        const REQUEST: u64 = 0x100;
        const OLD: u64 = 0x180;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let stack = GuestStack {
            sp: 0x8000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        let top = stack.sp + stack.size;
        state.thread_signals.lock().altstack = Some(stack);

        for (current, on_stack) in [(stack.sp, false), (stack.sp + 1, true), (top, true)] {
            assert_eq!(
                sigaltstack(
                    &mut memory,
                    &mut state,
                    Some(current),
                    &[0, OLD, 0, 0, 0, 0]
                ),
                0,
            );
            let queried = GuestStack::decode(read_guest_bytes::<24>(&memory, OLD).unwrap());
            assert_eq!(
                queried.flags & libc::SS_ONSTACK != 0,
                on_stack,
                "current rsp={current:#x}",
            );
        }

        let replacement = GuestStack {
            sp: 0x20_000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        memory.write(REQUEST, &replacement.encode()).unwrap();
        for current in [stack.sp + 1, top] {
            assert_eq!(
                sigaltstack(
                    &mut memory,
                    &mut state,
                    Some(current),
                    &[REQUEST, 0, 0, 0, 0, 0],
                ),
                negative_errno(libc::EPERM),
            );
            assert_eq!(state.thread_signals.lock().altstack, Some(stack));
        }
        assert_eq!(
            sigaltstack(
                &mut memory,
                &mut state,
                Some(stack.sp),
                &[REQUEST, 0, 0, 0, 0, 0],
            ),
            0,
            "the lower bound is not part of a downward-growing altstack",
        );
        assert_eq!(state.thread_signals.lock().altstack, Some(replacement));
    }

    #[test]
    fn sigaltstack_accepts_and_preserves_an_overflowing_descriptor() {
        const REQUEST: u64 = 0x100;
        const OLD: u64 = 0x180;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let overflowing = GuestStack {
            sp: u64::MAX - 8,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        memory.write(REQUEST, &overflowing.encode()).unwrap();
        assert_eq!(
            sigaltstack(
                &mut memory,
                &mut state,
                Some(0x4000),
                &[REQUEST, OLD, 0, 0, 0, 0],
            ),
            0,
        );
        assert_eq!(state.thread_signals.lock().altstack, Some(overflowing));
        assert_eq!(
            GuestStack::decode(read_guest_bytes::<24>(&memory, OLD).unwrap()),
            GuestStack {
                sp: 0,
                flags: libc::SS_DISABLE,
                size: 0,
            },
        );
        assert_eq!(
            sigaltstack(
                &mut memory,
                &mut state,
                Some(u64::MAX),
                &[0, OLD, 0, 0, 0, 0],
            ),
            0,
        );
        let observed = GuestStack::decode(read_guest_bytes::<24>(&memory, OLD).unwrap());
        assert_eq!(observed.sp, overflowing.sp);
        assert_eq!(observed.size, overflowing.size);
        assert_eq!(observed.flags, libc::SS_ONSTACK);

        let executor = ElfExecutor::new(state, false);
        let action = KernelSigaction {
            flags: libc::SA_ONSTACK as u64,
            ..Default::default()
        };
        assert_eq!(
            executor.signal_stack_top(action, 0x4000),
            Ok((
                overflowing.sp.wrapping_add(overflowing.size),
                Some(overflowing.sp),
                false,
                false,
            )),
        );
    }

    #[test]
    fn sa_onstack_placement_obeys_boundaries_and_autodisarm() {
        let root = TestDir::new();
        let executor = ElfExecutor::new(test_state(&root.0), false);
        let stack = GuestStack {
            sp: 0x8000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        let top = stack.sp + stack.size;
        let action = KernelSigaction {
            flags: libc::SA_ONSTACK as u64,
            ..Default::default()
        };
        executor.state.thread_signals.lock().altstack = Some(stack);
        for current in [stack.sp + 1, top] {
            assert_eq!(
                executor.signal_stack_top(action, current),
                Ok((current, Some(stack.sp), true, false)),
                "an rsp in (base, top] is nested",
            );
        }
        assert_eq!(
            executor.signal_stack_top(action, stack.sp),
            Ok((top, Some(stack.sp), false, false)),
            "an rsp at base is off-stack and starts a fresh altstack frame",
        );

        let autodisarm = GuestStack {
            flags: SS_AUTODISARM,
            ..stack
        };
        executor.state.thread_signals.lock().altstack = Some(autodisarm);
        assert_eq!(
            executor.signal_stack_top(action, stack.sp + 1),
            Ok((top, Some(stack.sp), false, true)),
            "an armed SS_AUTODISARM stack is treated as off-stack",
        );
        assert_eq!(executor.signal_altstack(stack.sp + 1).flags, SS_AUTODISARM,);
    }

    #[test]
    fn rt_sigreturn_ignores_invalid_altstack_restore_but_restores_the_mask() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let original_stack = GuestStack {
            sp: 0x4000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        executor.state.thread_signals.lock().altstack = Some(original_stack);
        executor
            .state
            .thread_signals
            .lock()
            .blocked
            .insert(libc::SIGUSR1);
        let mut restored_mask = KernelSigset::default();
        restored_mask.insert(libc::SIGUSR2);
        for invalid_stack in [
            GuestStack {
                sp: 0x8000,
                flags: 0x1234,
                size: libc::MINSIGSTKSZ as u64,
            },
            GuestStack {
                sp: 0x8000,
                flags: 0,
                size: libc::MINSIGSTKSZ as u64 - 1,
            },
        ] {
            executor.restore_signal_thread_state(
                restored_mask,
                invalid_stack,
                original_stack.sp + 1,
            );
            assert_eq!(
                executor.state.thread_signals.lock().altstack,
                Some(original_stack)
            );
        }

        let overflowing_stack = GuestStack {
            sp: u64::MAX - 8,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        executor.restore_signal_thread_state(restored_mask, overflowing_stack, original_stack.sp);
        assert_eq!(
            executor.state.thread_signals.lock().altstack,
            Some(overflowing_stack),
            "Linux stores the descriptor without eagerly adding sp and size",
        );
        executor.state.thread_signals.lock().altstack = Some(original_stack);

        let distinct_valid_stack = GuestStack {
            sp: 0x20_000,
            flags: 0,
            size: libc::MINSIGSTKSZ as u64,
        };
        executor.restore_signal_thread_state(
            restored_mask,
            distinct_valid_stack,
            original_stack.sp + 1,
        );
        assert_eq!(
            executor.state.thread_signals.lock().altstack,
            Some(original_stack),
            "rt_sigreturn ignores EPERM from replacing an active altstack",
        );

        assert!(
            !executor
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGUSR1)
        );
        assert!(
            executor
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGUSR2)
        );
    }

