    #[test]
    fn worker_exec_preserves_preflight_errors_without_publishing_action() {
        const SENTINEL_ADDRESS: u64 = 0x30_0000;
        const SENTINEL: [u8; 8] = *b"still-ok";
        const PATH_ADDRESS: u64 = 0x200;
        const ARGV_ADDRESS: u64 = 0x400;
        const ENVP_ADDRESS: u64 = 0x500;

        let root = TestDir::new();
        let valid_path = root.0.join("valid");
        let malformed_path = root.0.join("malformed");
        let missing_path = root.0.join("missing");
        let mut image = vec![0; 0x1002];
        image[..7].copy_from_slice(b"\x7fELF\x02\x01\x01");
        for (offset, value) in [(16, 2_u16), (18, 62), (52, 64), (54, 56), (56, 1)] {
            image[offset..offset + 2].copy_from_slice(&value.to_le_bytes());
        }
        for (offset, value) in [(20, 1_u32), (64, 1), (68, 5)] {
            image[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
        }
        for (offset, value) in [
            (24, 0x20_0000_u64),
            (32, 64),
            (72, 0x1000),
            (80, 0x20_0000),
            (88, 0x20_0000),
            (96, 2),
            (104, 0x1000),
            (112, 0x1000),
        ] {
            image[offset..offset + 8].copy_from_slice(&value.to_le_bytes());
        }
        image[0x1000..].copy_from_slice(&[0x0f, 0x0b]);
        std::fs::write(&valid_path, &image).unwrap();
        std::fs::write(&malformed_path, b"not an ELF image").unwrap();
        assert!(!missing_path.exists());
        let mut memory = GuestMemory::new(0, 16 * 1024 * 1024).unwrap();
        memory.write(SENTINEL_ADDRESS, &SENTINEL).unwrap();
        memory
            .write(ARGV_ADDRESS, &PATH_ADDRESS.to_le_bytes())
            .unwrap();
        memory
            .write(ARGV_ADDRESS + 8, &0_u64.to_le_bytes())
            .unwrap();
        memory.write(ENVP_ADDRESS, &0_u64.to_le_bytes()).unwrap();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut worker = leader.thread_child(7).unwrap();
        assert_ne!(worker.state.pid, worker.state.tid);
        let identity = (worker.state.pid, worker.state.tid);
        let invalid = memory.guest_end() + PAGE_SIZE;
        let mut results = Vec::new();
        let mut expected_results = Vec::new();
        for number in [libc::SYS_execve, libc::SYS_execveat] {
            for (case, path, invalid_argument, errno) in [
                ("path", &valid_path, Some(0), libc::EFAULT),
                ("argv", &valid_path, Some(1), libc::EFAULT),
                ("envp", &valid_path, Some(2), libc::EFAULT),
                ("missing", &missing_path, None, libc::ENOENT),
                ("malformed", &malformed_path, None, libc::ENOEXEC),
                ("valid", &valid_path, None, libc::ENOSYS),
            ] {
                let path = CString::new(path.as_os_str().as_bytes()).unwrap();
                memory
                    .write(PATH_ADDRESS, path.as_bytes_with_nul())
                    .unwrap();
                let mut pointers = [PATH_ADDRESS, ARGV_ADDRESS, ENVP_ADDRESS];
                if let Some(index) = invalid_argument {
                    pointers[index] = invalid;
                }
                let [path, argv, envp] = pointers;
                let args = if number == libc::SYS_execve {
                    [path, argv, envp, 0, 0, 0]
                } else {
                    [libc::AT_FDCWD as u64, path, argv, envp, 0, 0]
                };
                let request = SyscallRequest::new(number as u64, args);
                if case == "valid" {
                    assert_eq!(leader.execute_process_action(&request, &memory), Some(0));
                    assert!(matches!(
                        leader.take_process_action(),
                        Some(ProcessAction::Exec { .. })
                    ));
                }
                let result = worker.execute_process_action(&request, &memory);
                eprintln!("syscall={number} case={case} result={result:?} expected=-{errno}");
                results.push(result);
                expected_results.push(Some(negative_errno(errno)));
                assert!(
                    worker.take_process_action().is_none(),
                    "worker exec published a process-image replacement"
                );
                let mut observed = [0; SENTINEL.len()];
                memory.read(SENTINEL_ADDRESS, &mut observed).unwrap();
                assert_eq!(observed, SENTINEL);
                assert_eq!((worker.state.pid, worker.state.tid), identity);
            }
        }
        assert_eq!(results, expected_results);
    }

    #[test]
    fn process_clone_accepts_legacy_tid_flags_without_prevalidating_pointers() {
        const CHILD_TID: u64 = 0x100;
        const PARENT_TID: u64 = 0x108;

        let root = TestDir::new();
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let flags = libc::SIGCHLD as u64
            | libc::CLONE_PARENT_SETTID as u64
            | libc::CLONE_CHILD_SETTID as u64
            | libc::CLONE_CHILD_CLEARTID as u64;
        let request = SyscallRequest::new(
            libc::SYS_clone as u64,
            [flags, 0, PARENT_TID, CHILD_TID, 0, 0],
        );
        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Fork {
                child_pid,
                child_stack,
                parent_tid,
                child_tid,
                clear_child_tid,
                clear_sighand,
                share_address_space,
            }) => {
                assert_eq!(child_pid, 2);
                assert_eq!(child_stack, None);
                assert!(!clear_sighand);
                assert!(!share_address_space);
                assert_eq!(parent_tid, Some(PARENT_TID));
                assert_eq!(child_tid, Some(CHILD_TID));
                assert_eq!(clear_child_tid, Some(CHILD_TID));
            }
            _ => panic!("clone did not produce a fork action"),
        }

        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let bad_pointer = memory.guest_end() - 1;
        let request = SyscallRequest::new(
            libc::SYS_clone as u64,
            [
                libc::SIGCHLD as u64 | libc::CLONE_CHILD_SETTID as u64,
                0,
                0,
                bad_pointer,
                0,
                0,
            ],
        );
        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Fork {
                child_pid,
                child_tid,
                ..
            }) => {
                assert_eq!(child_pid, 2);
                assert_eq!(child_tid, Some(bad_pointer));
            }
            _ => panic!("clone with an invalid TID pointer did not create a child"),
        }

        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let shared_flags = flags | libc::CLONE_VM as u64 | libc::CLONE_VFORK as u64;
        let request = SyscallRequest::new(
            libc::SYS_clone as u64,
            [shared_flags, 0, PARENT_TID, CHILD_TID, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::ENOTSUP))
        );
        assert!(executor.take_process_action().is_none());
    }

    #[test]
    fn clone3_accepts_glibc_pthread_profile_with_tls_and_tid_addresses() {
        const CLONE3_ARGS: u64 = 0x200;
        const CHILD_TID_ADDRESS: u64 = 0x300;
        const PARENT_TID_ADDRESS: u64 = 0x308;
        const CHILD_STACK: u64 = 0x4000;
        const CHILD_STACK_SIZE: u64 = 0x9000;
        const TLS: u64 = 0x1_234_000;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 88];
        let flags = THREAD_CLONE_REQUIRED_FLAGS
            | libc::CLONE_SYSVSEM as u64
            | libc::CLONE_SETTLS as u64
            | libc::CLONE_PARENT_SETTID as u64
            | libc::CLONE_CHILD_CLEARTID as u64;
        clone3[0..8].copy_from_slice(&flags.to_le_bytes());
        // glibc leaves clone_args.pidfd aliased to the thread descriptor even
        // though CLONE_PIDFD is absent; Linux ignores the slot in that case.
        clone3[8..16].copy_from_slice(&CHILD_TID_ADDRESS.to_le_bytes());
        clone3[16..24].copy_from_slice(&CHILD_TID_ADDRESS.to_le_bytes());
        clone3[24..32].copy_from_slice(&PARENT_TID_ADDRESS.to_le_bytes());
        clone3[40..48].copy_from_slice(&CHILD_STACK.to_le_bytes());
        clone3[48..56].copy_from_slice(&CHILD_STACK_SIZE.to_le_bytes());
        clone3[56..64].copy_from_slice(&TLS.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );

        assert!(is_thread_clone_request(&request, &memory));
        let legacy_thread = SyscallRequest::new(
            libc::SYS_clone as u64,
            [THREAD_CLONE_REQUIRED_FLAGS, CHILD_STACK, 0, 0, TLS, 0],
        );
        assert!(is_thread_clone_request(&legacy_thread, &memory));
        let process_clone = SyscallRequest::new(
            libc::SYS_clone as u64,
            [libc::SIGCHLD as u64, 0, 0, 0, 0, 0],
        );
        assert!(!is_thread_clone_request(&process_clone, &memory));

        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Thread {
                child_tid,
                child_stack,
                parent_tid,
                child_tid_address,
                clear_child_tid,
                tls,
            }) => {
                assert_eq!(child_tid, 2);
                assert_eq!(child_stack, CHILD_STACK + CHILD_STACK_SIZE);
                assert_eq!(parent_tid, Some(PARENT_TID_ADDRESS));
                assert_eq!(child_tid_address, None);
                assert_eq!(clear_child_tid, Some(CHILD_TID_ADDRESS));
                assert_eq!(tls, Some(TLS));
            }
            _ => panic!("glibc pthread clone3 did not produce a thread action"),
        }
    }

    #[test]
    fn clone3_validates_nonzero_extensions_and_paired_stack_fields() {
        const CLONE3_ARGS: u64 = 0x200;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 96];
        clone3[95] = 1;
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::E2BIG))
        );

        clone3[95] = 0;
        clone3[40..48].copy_from_slice(&0x1000_u64.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let request = SyscallRequest::new(libc::SYS_clone3 as u64, [CLONE3_ARGS, 88, 0, 0, 0, 0]);
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::EINVAL))
        );
        assert!(executor.take_process_action().is_none());
    }

    #[test]
    fn clone3_tid_flags_remain_explicitly_unsupported() {
        const CLONE3_ARGS: u64 = 0x200;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 64];
        clone3[0..8].copy_from_slice(&(libc::CLONE_CHILD_CLEARTID as u64).to_le_bytes());
        clone3[32..40].copy_from_slice(&(libc::SIGCHLD as u64).to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );

        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::ENOTSUP))
        );
        assert!(executor.take_process_action().is_none());

        clone3[16..24].copy_from_slice(&1_u64.to_le_bytes());
        clone3[32..40].copy_from_slice(&255_u64.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::EINVAL)),
            "malformed exit_signal takes precedence over unsupported TID flags"
        );
        assert!(executor.take_process_action().is_none());

        clone3[32..40].copy_from_slice(&(libc::SIGCHLD as u64).to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert_eq!(
            executor.execute_process_action(&request, &memory),
            Some(negative_errno(libc::ENOTSUP)),
            "a TID field remains explicitly unsupported after validation"
        );
        assert!(executor.take_process_action().is_none());
    }

    #[test]
    fn clone3_posix_spawn_vfork_with_clear_sighand_is_accepted() {
        // glibc >= 2.36 `posix_spawn` (used by `make`/`gcc` to launch recipe and
        // subprocess jobs) issues exactly this clone3: CLONE_VM|CLONE_VFORK with
        // CLONE_CLEAR_SIGHAND, an explicit child stack, and SIGCHLD as the exit
        // signal. Older glibc omitted CLONE_CLEAR_SIGHAND, so the executor must
        // accept the flag and reset caught child handlers before it runs.
        const CLONE3_ARGS: u64 = 0x200;
        const CHILD_STACK: u64 = 0x4000;
        const CHILD_STACK_SIZE: u64 = 0x9000;

        let root = TestDir::new();
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut clone3 = [0_u8; 88];
        let flags = libc::CLONE_VM as u64 | libc::CLONE_VFORK as u64 | CLONE_CLEAR_SIGHAND;
        clone3[0..8].copy_from_slice(&flags.to_le_bytes());
        clone3[32..40].copy_from_slice(&(libc::SIGCHLD as u64).to_le_bytes());
        clone3[40..48].copy_from_slice(&CHILD_STACK.to_le_bytes());
        clone3[48..56].copy_from_slice(&CHILD_STACK_SIZE.to_le_bytes());
        memory.write(CLONE3_ARGS, &clone3).unwrap();

        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let mut ignored = [0; KERNEL_SIGACTION_SIZE];
        ignored[..std::mem::size_of::<usize>()].copy_from_slice(&libc::SIG_IGN.to_ne_bytes());
        let mut caught = [0; KERNEL_SIGACTION_SIZE];
        caught[..std::mem::size_of::<usize>()].copy_from_slice(&2usize.to_ne_bytes());
        test_install_signal_action(&executor.state, libc::SIGUSR1, ignored);
        test_install_signal_action(&executor.state, libc::SIGUSR2, caught);
        let request = SyscallRequest::new(
            libc::SYS_clone3 as u64,
            [CLONE3_ARGS, clone3.len() as u64, 0, 0, 0, 0],
        );
        assert!(!is_thread_clone_request(&request, &memory));
        assert_eq!(executor.execute_process_action(&request, &memory), Some(2));
        match executor.take_process_action() {
            Some(ProcessAction::Fork {
                child_pid,
                child_stack,
                parent_tid,
                child_tid,
                clear_child_tid,
                clear_sighand,
                share_address_space,
            }) => {
                assert_eq!(child_pid, 2);
                assert_eq!(child_stack, Some(CHILD_STACK + CHILD_STACK_SIZE));
                assert!(clear_sighand);
                assert!(share_address_space);
                assert_eq!(parent_tid, None);
                assert_eq!(child_tid, None);
                assert_eq!(clear_child_tid, None);
                let child = executor
                    .fork_child(child_pid, clear_sighand, share_address_space)
                    .unwrap();
                assert_eq!(
                    test_signal_action(&child.state, libc::SIGUSR1),
                    Some(ignored)
                );
                assert_eq!(test_signal_action(&child.state, libc::SIGUSR2), None);
                assert_eq!(
                    test_signal_action(&executor.state, libc::SIGUSR1),
                    Some(ignored)
                );
                assert_eq!(
                    test_signal_action(&executor.state, libc::SIGUSR2),
                    Some(caught)
                );
            }
            _ => panic!("clone3 with CLONE_CLEAR_SIGHAND did not create a fork action"),
        }
    }

    #[test]
    fn set_tid_address_tracks_current_pid_and_clear_pointer() {
        const CLEAR_TID: u64 = 0x100;

        let root = TestDir::new();
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let request =
            SyscallRequest::new(libc::SYS_set_tid_address as u64, [CLEAR_TID, 0, 0, 0, 0, 0]);
        assert_eq!(executor.execute_process_action(&request, &memory), Some(1));
        assert_eq!(executor.take_clear_child_tid(), Some(CLEAR_TID));

        let request = SyscallRequest::new(libc::SYS_set_tid_address as u64, [0; 6]);
        assert_eq!(executor.execute_process_action(&request, &memory), Some(1));
        assert_eq!(executor.take_clear_child_tid(), None);

        let request =
            SyscallRequest::new(libc::SYS_set_tid_address as u64, [CLEAR_TID, 0, 0, 0, 0, 0]);
        assert_eq!(executor.execute_process_action(&request, &memory), Some(1));
        executor.replace_after_exec(test_state(&root.0));
        assert_eq!(executor.take_clear_child_tid(), None);
    }

    #[test]
    fn post_exec_mask_preflight_preserves_both_pending_domains_across_recursive_exec() {
        const EMPTY_MASK: u64 = 0x100;
        const OLD_MASK: u64 = 0x200;
        let root = TestDir::new();

        for (label, process_directed, signal) in [
            ("thread", false, libc::SIGUSR1),
            ("process", true, libc::SIGUSR2),
        ] {
            let mut executor = ElfExecutor::new(test_state(&root.0), false);
            let pid = executor.state.pid;
            let tid = executor.state.tid;
            test_block_signal(&mut executor.state, signal);
            let (number, arguments) = if process_directed {
                (libc::SYS_kill, [pid as u64, signal as u64, 0, 0, 0, 0])
            } else {
                (libc::SYS_tkill, [tid as u64, signal as u64, 0, 0, 0, 0])
            };
            assert_eq!(
                result_of(kill_signal(&mut executor.state, number as u64, &arguments,)),
                0,
            );

            let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
            memory.write(EMPTY_MASK, &[0; KERNEL_SIGSET_SIZE]).unwrap();
            let old_sentinel = [0xa5; KERNEL_SIGSET_SIZE];
            memory.write(OLD_MASK, &old_sentinel).unwrap();
            let request = SyscallRequest::new(
                libc::SYS_rt_sigprocmask as u64,
                [
                    libc::SIG_SETMASK as u64,
                    EMPTY_MASK,
                    OLD_MASK,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            );

            for exec_depth in 1..=2 {
                executor.replace_after_exec(test_state(&root.0));
                assert!(
                    executor
                        .state
                        .thread_signals
                        .lock()
                        .blocked
                        .contains(signal),
                    "{label} mask was not preserved across exec {exec_depth}",
                );
                assert_eq!(
                    executor.lifecycle_signal_mask_preflight(&request, &memory),
                    Some(negative_errno(libc::ENOSYS)),
                    "{label} pending signal became eligible after exec {exec_depth}",
                );
                assert!(
                    executor
                        .state
                        .thread_signals
                        .lock()
                        .blocked
                        .contains(signal)
                );
                let still_pending = if process_directed {
                    executor
                        .state
                        .process_signals
                        .lock()
                        .unwrap()
                        .shared_pending
                        .contains(signal)
                } else {
                    executor
                        .state
                        .thread_signals
                        .lock()
                        .pending
                        .contains(signal)
                };
                assert!(still_pending, "{label} pending signal was consumed");
                let mut observed = [0; KERNEL_SIGSET_SIZE];
                memory.read(OLD_MASK, &mut observed).unwrap();
                assert_eq!(
                    observed, old_sentinel,
                    "{label} old-mask output changed before refusal",
                );
            }
        }
    }

    #[test]
    fn priority_and_scheduler_queries_round_trip_guest_persona() {
        const PARAM: u64 = 0x100;
        const ATTR: u64 = 0x200;
        // ioprio encoding (whoami=PROCESS, class shift, IDLE class).
        const IOPRIO_WHO_PROCESS: u64 = 1;
        const IOPRIO_CLASS_SHIFT: u32 = 13;
        const IOPRIO_CLASS_IDLE: u64 = 3;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getpriority,
                [libc::PRIO_PROCESS as u64, 0, 0, 0, 0, 0],
            ),
            20
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_setpriority,
                [libc::PRIO_PROCESS as u64, 0, 1, 0, 0, 0],
            ),
            0
        );
        assert_eq!(state.nice, 1);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getpriority,
                [libc::PRIO_PROCESS as u64, 0, 0, 0, 0, 0],
            ),
            19
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ioprio_get,
                [IOPRIO_WHO_PROCESS, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_ioprio_set,
                [
                    IOPRIO_WHO_PROCESS,
                    0,
                    IOPRIO_CLASS_IDLE << IOPRIO_CLASS_SHIFT,
                    0,
                    0,
                    0,
                ],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getscheduler,
                [0, 0, 0, 0, 0, 0],
            ),
            i64::from(libc::SCHED_OTHER)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getparam,
                [0, PARAM, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            read_struct::<libc::sched_param>(&memory, PARAM).sched_priority,
            0
        );
        for size in [0, 47, PAGE_SIZE + 1] {
            assert_eq!(
                syscall_result(
                    &mut memory,
                    &mut state,
                    libc::SYS_sched_getattr,
                    [0, ATTR, size, 0, 0, 0]
                ),
                negative_errno(libc::EINVAL)
            );
        }
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getattr,
                [999_999, ATTR, 48, 1, 0, 0]
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getattr,
                [999_999, ATTR, 48, 0, 0, 0]
            ),
            negative_errno(libc::ESRCH)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getattr,
                [0, ATTR, std::mem::size_of::<SchedAttr>() as u64, 0, 0, 0],
            ),
            0
        );
        let attr: SchedAttr = read_struct(&memory, ATTR);
        assert_eq!(attr.size as usize, std::mem::size_of::<SchedAttr>());
        assert_eq!(attr.sched_policy, libc::SCHED_OTHER as u32);
        assert_eq!(attr.sched_priority, 0);
        assert_eq!(attr.sched_nice, 1);

        memory.write(ATTR + 48, &[0xa5; 8]).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getattr,
                [0, ATTR, 48, 0, 0, 0],
            ),
            0
        );
        let mut canary = [0; 8];
        memory.read(ATTR + 48, &mut canary).unwrap();
        assert_eq!(canary, [0xa5; 8]);
    }

    #[test]
    fn memory_residency_and_cpu_topology_are_deterministic() {
        const VECTOR: u64 = 4 * PAGE_SIZE;
        const CPU: u64 = 0x100;
        const NODE: u64 = 0x108;
        const AFFINITY: u64 = 0x200;

        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, (5 * PAGE_SIZE) as usize).unwrap();
        memory
            .map_user_range(PAGE_SIZE, 2 * PAGE_SIZE, false)
            .unwrap();
        memory.map_user_range(VECTOR, PAGE_SIZE, false).unwrap();
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [PAGE_SIZE + 1, PAGE_SIZE - 1, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [PAGE_SIZE, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [5 * PAGE_SIZE + 1, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [5 * PAGE_SIZE - 1, 2, 0, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [1, u64::MAX, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [0, u64::MAX, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [u64::MAX - 1, 4, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [u64::MAX, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_munlock,
                [u64::MAX - (PAGE_SIZE - 1), 1, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(&mut memory, &mut state, libc::SYS_munlockall, [u64::MAX; 6],),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mincore,
                [PAGE_SIZE, PAGE_SIZE + 1, VECTOR, 0, 0, 0],
            ),
            0
        );
        assert_eq!(read_guest_bytes::<2>(&memory, VECTOR).unwrap(), [1, 1]);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mincore,
                [3 * PAGE_SIZE, PAGE_SIZE, VECTOR, 0, 0, 0],
            ),
            negative_errno(libc::ENOMEM)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_mincore,
                [PAGE_SIZE + 1, PAGE_SIZE, VECTOR, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_getcpu,
                [CPU, NODE, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(read_struct::<u32>(&memory, CPU), 0);
        assert_eq!(read_struct::<u32>(&memory, NODE), 0);
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_sched_getaffinity,
                [0, 8, AFFINITY, 0, 0, 0],
            ),
            8
        );
        assert_eq!(
            read_guest_bytes::<8>(&memory, AFFINITY).unwrap(),
            [1, 0, 0, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [0, 0, 0, 0, 0, 0],
            ),
            i64::from(MEMBARRIER_SUPPORTED)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [0, 0, 123, 0, 0, 0],
            ),
            i64::from(MEMBARRIER_SUPPORTED)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [1_u64 << 32, 1_u64 << 32, 123, 0, 0, 0],
            ),
            i64::from(MEMBARRIER_SUPPORTED)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [1, 0, 0, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [1, 0, 123, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [(1_u64 << 32) | 1, 1_u64 << 32, 123, 0, 0, 0],
            ),
            0
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [3, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [0, 1, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
        assert_eq!(
            syscall_result(
                &mut memory,
                &mut state,
                libc::SYS_membarrier,
                [1 << 20, 0, 0, 0, 0, 0],
            ),
            negative_errno(libc::EINVAL)
        );
    }

