    #[test]
    fn a_duplicate_child_transfer_still_joins_both_handles() {
        let directory = TestDir::new();
        let mut owner = ElfExecutor::new(test_state(&directory.0), false);
        let mut worker = owner.thread_child(2).unwrap();
        let lifetime = Arc::new(());
        // No two live processes share a pid. If a worker ever handed its
        // leader one that did, neither handle may be dropped, and so detached.
        // The transferred duplicate outlives the leader's own child, so only
        // a join of the duplicate itself waits for it to end.
        for (executor, teardown) in [(&mut owner, 0), (&mut worker, 300)] {
            let (start, wait) = std::sync::mpsc::channel();
            let child_lifetime = lifetime.clone();
            let handle = ChildThread::spawn(move || {
                let _ = wait.recv();
                // A detached thread is still sleeping when its join returns.
                std::thread::sleep(std::time::Duration::from_millis(teardown));
                drop(child_lifetime);
                Ok(())
            });
            executor.register_child_process(
                6,
                start,
                Arc::new(ChildCompletionSlot::default()),
                handle,
            );
        }
        worker.transfer_child_processes_to_owner();
        drop(worker);
        let error = owner.join_all_child_processes().unwrap_err().to_string();
        assert!(
            error.contains("KVM child pid 6 transferred twice"),
            "the collision was not reported: {error}"
        );
        assert!(owner.pending_processes.is_empty());
        assert!(owner.completed_processes.is_empty());
        assert_eq!(
            Arc::strong_count(&lifetime),
            1,
            "the join returned before both threads ended"
        );
    }

    #[test]
    fn exiting_workers_transfer_every_child_handle_in_virtual_order() {
        let directory = TestDir::new();
        let mut owner = ElfExecutor::new(test_state(&directory.0), false);
        let mut worker2 = owner.thread_child(2).unwrap();
        let mut worker3 = owner.thread_child(3).unwrap();
        let fork = owner.fork_child(4, false, false).unwrap();
        assert!(Arc::ptr_eq(
            &owner.transferred_processes,
            &worker2.transferred_processes
        ));
        assert!(Arc::ptr_eq(
            &owner.transferred_processes,
            &worker3.transferred_processes
        ));
        assert!(!Arc::ptr_eq(
            &owner.transferred_processes,
            &fork.transferred_processes
        ));
        let lifetime = Arc::new(());
        // Reverse host transfer order. Two transfers from the same worker must
        // keep both collections rather than replacing an earlier handle.
        for worker in [&mut worker3, &mut worker2] {
            let tid = worker.state.tid;
            for batch in 0..2 {
                let pid = tid * 10 + batch;
                let (start, wait) = std::sync::mpsc::channel();
                let child_lifetime = lifetime.clone();
                let handle = ChildThread::spawn(move || {
                    let _lifetime = child_lifetime;
                    assert_eq!(wait.recv().unwrap(), ChildStartCommand::Start);
                    Err(crate::Error::UnexpectedVcpuExit(format!(
                        "transferred pending {pid}"
                    )))
                });
                worker.register_child_process(
                    pid,
                    start,
                    Arc::new(ChildCompletionSlot::default()),
                    handle,
                );
                let child_lifetime = lifetime.clone();
                worker.completed_processes.push(
                    ChildThread::spawn(move || {
                        let _lifetime = child_lifetime;
                        Err(crate::Error::UnexpectedVcpuExit(format!(
                            "transferred completed {pid}"
                        )))
                    })
                    .into(),
                );
                worker.transfer_child_processes_to_owner();
                assert!(worker.pending_processes.is_empty());
                assert!(worker.completed_processes.is_empty());
            }
        }
        drop(worker2);
        drop(worker3);
        let error = owner.join_all_child_processes().unwrap_err().to_string();
        assert!(owner.pending_processes.is_empty());
        assert!(owner.completed_processes.is_empty());
        assert!(owner.transferred_processes.lock().unwrap().is_empty());
        assert_eq!(
            Arc::strong_count(&lifetime),
            1,
            "every transferred handle joined"
        );
        let mut previous = None;
        for kind in ["pending", "completed"] {
            for pid in [20, 21, 30, 31] {
                let diagnostic = format!("transferred {kind} {pid}");
                assert_eq!(error.matches(&diagnostic).count(), 1, "{error}");
                let position = error.find(&diagnostic).unwrap();
                assert!(
                    previous.is_none_or(|previous| previous < position),
                    "{error}"
                );
                previous = Some(position);
            }
        }
        owner.join_all_child_processes().unwrap();
    }

    #[test]
    fn unstarted_tool_cleanup_retains_children_unpolled_and_transfers_once() {
        fn require_send_sync<T: Send + Sync>() {}
        require_send_sync::<ElfExecutor>();

        let root = TestDir::new();
        let mut parent = ElfExecutor::new(test_state(&root.0), false);
        assert!(parent.take_unstarted_tool_cleanup().is_empty());
        let child_tid = parent.state.pid + 1;
        let child_pid = child_tid + 1;
        let mut worker = parent.thread_child(child_tid).unwrap();
        let mut process = parent.fork_child(child_pid, false, false).unwrap();
        assert!(worker.take_unstarted_tool_cleanup().is_empty());
        assert!(process.take_unstarted_tool_cleanup().is_empty());
        let observed = [
            (worker.state.task_lifecycle.clone(), child_tid),
            (process.state.task_lifecycle.clone(), child_pid),
        ];
        let polls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let primary = Arc::new(crate::Error::RunAborted);
        let hook_error = Arc::new(crate::Error::UnexpectedVcpuExit(
            "controlled deferred child consuming failure".to_owned(),
        ));
        for (index, child) in [worker, process].into_iter().enumerate() {
            let polls = polls.clone();
            let primary = primary.clone();
            let hook_error = hook_error.clone();
            // Deliberately Send but not Sync: only the queue's mutex supplies
            // the executor's Sync bound. It must never poll this inline.
            let not_sync = std::cell::Cell::new(0);
            parent.retain_unstarted_tool_cleanup(Box::pin(async move {
                not_sync.set(1);
                std::future::ready(()).await;
                assert_eq!(not_sync.get(), 1);
                polls.fetch_add(1, Ordering::SeqCst);
                drop(child);
                if index == 0 {
                    Err(crate::Error::RunAborted)
                } else {
                    Err(crate::Error::WithCleanup {
                        primary,
                        cleanup: vec![hook_error],
                    })
                }
            }));
        }
        assert_eq!(polls.load(Ordering::SeqCst), 0);
        for (lifecycle, tid) in &observed {
            assert!(lifecycle.lock().unwrap().get(*tid).is_some());
        }
        // Retained consumers belong to this exact executor, not a copied child.
        let mut next_worker = parent.thread_child(child_pid + 1).unwrap();
        let mut next_process = parent.fork_child(child_pid + 2, false, false).unwrap();
        assert!(next_worker.take_unstarted_tool_cleanup().is_empty());
        assert!(next_process.take_unstarted_tool_cleanup().is_empty());
        let mut retained = parent.take_unstarted_tool_cleanup().into_iter();
        assert!(parent.take_unstarted_tool_cleanup().is_empty());
        assert_eq!(polls.load(Ordering::SeqCst), 0);
        assert!(matches!(
            futures::executor::block_on(retained.next().unwrap()),
            Err(crate::Error::RunAborted)
        ));
        let error = futures::executor::block_on(retained.next().unwrap()).unwrap_err();
        let crate::Error::WithCleanup {
            primary: actual,
            cleanup,
        } = error
        else {
            panic!("deferred cleanup lost its typed aggregate");
        };
        assert!(Arc::ptr_eq(&actual, &primary));
        assert_eq!(cleanup.len(), 1);
        assert!(Arc::ptr_eq(&cleanup[0], &hook_error));
        assert!(retained.next().is_none());
        assert_eq!(polls.load(Ordering::SeqCst), 2);
        for (lifecycle, tid) in &observed {
            assert!(lifecycle.lock().unwrap().get(*tid).is_none());
        }
    }

    #[test]
    fn child_process_cleanup_joins_every_handle_and_preserves_each_error() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let lifetime = Arc::new(());
        for pid in 2..=7 {
            let (start_sender, start_receiver) = std::sync::mpsc::channel();
            let completion = executor.mock_child_completion(pid);
            let child_completion = completion.clone();
            let child_lifetime = lifetime.clone();
            let receiver = if pid == 2 {
                drop(start_receiver);
                None
            } else {
                Some(start_receiver)
            };
            let handle = ChildThread::spawn(move || {
                let _lifetime = child_lifetime;
                if let Some(receiver) = receiver {
                    assert_eq!(receiver.recv().unwrap(), ChildStartCommand::Start);
                }
                match pid {
                    2 => Err(crate::Error::UnexpectedVcpuExit(
                        "lost-gate child diagnostic".to_owned(),
                    )),
                    3 => panic!("forced pending child panic"),
                    4 => Ok(()),
                    5 => {
                        assert!(child_completion.fail_if_pending());
                        Ok(())
                    }
                    6 => {
                        let _ = std::panic::catch_unwind(|| {
                            let _guard = child_completion.state.lock().unwrap();
                            panic!("forced completion lock poison");
                        });
                        Ok(())
                    }
                    7 => {
                        assert!(
                            child_completion
                                .publish(ChildCompletion::Waitable(ExitStatus::SUCCESS))
                        );
                        Ok(())
                    }
                    _ => unreachable!(),
                }
            });
            executor.register_mock_child_process(pid, start_sender, completion, handle);
        }
        let (release, wait_release) = std::sync::mpsc::channel();
        let (finished, wait_finished) = std::sync::mpsc::channel();
        for index in 0..2 {
            let child_lifetime = lifetime.clone();
            executor.completed_processes.push(
                ChildThread::spawn(move || {
                    let _lifetime = child_lifetime;
                    if index == 0 {
                        Err(crate::Error::UnexpectedVcpuExit(
                            "completed child diagnostic".to_owned(),
                        ))
                    } else {
                        panic!("forced completed child panic");
                    }
                })
                .into(),
            );
        }
        let child_lifetime = lifetime.clone();
        executor.completed_processes.push(
            ChildThread::spawn(move || {
                let _lifetime = child_lifetime;
                wait_release
                    .recv_timeout(std::time::Duration::from_secs(5))
                    .unwrap();
                finished.send(()).unwrap();
                Ok(())
            })
            .into(),
        );
        let release_thread = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(100));
            release.send(()).unwrap();
        });
        let error = executor.join_all_child_processes().unwrap_err().to_string();
        let remaining = (
            executor.pending_processes.len(),
            executor.completed_processes.len(),
            Arc::strong_count(&lifetime),
        );
        // Release and join fixture workers even when checking an early-return
        // mutation, which can leave pending gates and handles behind.
        release_thread.join().unwrap();
        for (_, mut process) in std::mem::take(&mut executor.pending_processes) {
            let _ = process.start.start();
            let _ = process.handle.thread.join_blocking();
        }
        for mut handle in executor.completed_processes.drain(..) {
            let _ = handle.thread.join_blocking();
        }
        wait_finished
            .recv_timeout(std::time::Duration::from_secs(5))
            .unwrap();
        assert_eq!(
            remaining,
            (0, 0, 1),
            "all handles must be joined before returning: {error}"
        );
        assert_eq!(executor.state.children.get(&7), Some(ExitStatus::SUCCESS));
        let expected = [
            "KVM child process 2 lost its parent start gate",
            "lost-gate child diagnostic",
            "KVM child process 3 panicked",
            "KVM child process 4 exited without publishing its status",
            "KVM child process 5 failed before publishing its status",
            "KVM child process 6 completion lock poisoned",
            "completed child diagnostic",
            "completed KVM child process panicked",
        ];
        let mut previous = None;
        for diagnostic in expected {
            assert_eq!(error.matches(diagnostic).count(), 1, "{error}");
            let position = error.find(diagnostic).unwrap();
            assert!(
                previous.is_none_or(|previous| previous < position),
                "stable child collection order: {error}"
            );
            previous = Some(position);
        }
        assert!(executor.join_all_child_processes().is_ok());
    }

    #[test]
    fn failed_child_cleanup_cancels_all_gates_before_joining() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let (later_done, wait_later) = std::sync::mpsc::channel();
        let mut wait_later = Some(wait_later);
        let mut later_done = Some(later_done);
        let gates = Arc::new(Mutex::new(Vec::new()));
        for pid in [2, 3] {
            let (sender, receiver) = std::sync::mpsc::channel();
            let gate = ChildStartGate::new(sender);
            gates.lock().unwrap().push(gate.clone());
            let wait = if pid == 2 { wait_later.take() } else { None };
            let done = if pid == 3 { later_done.take() } else { None };
            let handle = ChildThread::spawn(move || {
                assert_eq!(
                    receiver.recv().unwrap(),
                    ChildStartCommand::CancelAfterFailure
                );
                if let Some(done) = done {
                    done.send(()).unwrap();
                }
                if let Some(wait) = wait {
                    wait.recv().unwrap();
                }
                Err(crate::Error::GuestClock(format!("child {pid}")))
            });
            executor.register_child_process_with_gate(
                pid,
                gate,
                Arc::new(ChildCompletionSlot::default()),
                handle,
            );
        }
        let (finished, wait_finished) = std::sync::mpsc::channel();
        let rescued = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let watchdog_rescued = rescued.clone();
        let watchdog = std::thread::spawn(move || {
            if wait_finished
                .recv_timeout(std::time::Duration::from_secs(2))
                .is_err()
            {
                watchdog_rescued.store(true, Ordering::SeqCst);
                for gate in gates.lock().unwrap().iter() {
                    gate.cancel();
                }
            }
        });
        let result = executor.join_child_processes_after_failure();
        let _ = finished.send(());
        watchdog.join().unwrap();
        assert!(
            !rescued.load(Ordering::SeqCst),
            "a later gate was held behind an earlier join"
        );
        let error = result.unwrap_err();
        assert!(matches!(error.primary(), crate::Error::GuestClock(_)));
        assert!(executor.pending_processes.is_empty());
        assert!(executor.completed_processes.is_empty());
        assert_eq!(error.to_string().matches("child 2").count(), 1);
        assert_eq!(error.to_string().matches("child 3").count(), 1);
    }

    #[test]
    fn child_start_gate_resolves_once_and_preserves_failed_delivery() {
        let (start_sender, start_receiver) = std::sync::mpsc::channel();
        let start_gate = ChildStartGate::new(start_sender);
        assert_eq!(start_gate.start(), Ok(true));
        assert_eq!(start_gate.start(), Ok(false));
        assert_eq!(start_receiver.recv().unwrap(), ChildStartCommand::Start);
        assert!(matches!(
            start_receiver.try_recv(),
            Err(std::sync::mpsc::TryRecvError::Empty | std::sync::mpsc::TryRecvError::Disconnected)
        ));
        assert_eq!(start_gate.cancel(), ChildStartCancellation::AlreadyStarted);

        let (cancel_sender, cancel_receiver) = std::sync::mpsc::channel();
        let cancel_gate = ChildStartGate::new(cancel_sender);
        assert_eq!(
            cancel_gate.cancel(),
            ChildStartCancellation::NewlyCancelled {
                delivery_failed: false
            }
        );
        assert_eq!(cancel_receiver.recv().unwrap(), ChildStartCommand::Cancel);
        assert_eq!(
            cancel_gate.cancel(),
            ChildStartCancellation::AlreadyCancelled
        );
        assert_eq!(cancel_gate.start(), Ok(false));

        let (lost_sender, lost_receiver) = std::sync::mpsc::channel();
        let lost_gate = ChildStartGate::new(lost_sender);
        drop(lost_receiver);
        assert!(lost_gate.start().is_err());
        assert_eq!(
            lost_gate.cancel(),
            ChildStartCancellation::NewlyCancelled {
                delivery_failed: true
            }
        );
        assert_eq!(
            start_gate.cancel_after_failure(),
            ChildStartCancellation::AlreadyStarted
        );
        assert_eq!(
            cancel_gate.cancel_after_failure(),
            ChildStartCancellation::AlreadyCancelled
        );
        let (fatal_sender, fatal_receiver) = std::sync::mpsc::channel();
        let fatal_gate = ChildStartGate::new(fatal_sender);
        assert_eq!(
            fatal_gate.cancel_after_failure(),
            ChildStartCancellation::NewlyCancelled {
                delivery_failed: false
            }
        );
        let command = fatal_receiver.recv().unwrap();
        assert_eq!(command, ChildStartCommand::CancelAfterFailure);
        assert!(matches!(command.failure(), Some(crate::Error::RunAborted)));
        assert_eq!(
            fatal_gate.cancel(),
            ChildStartCancellation::AlreadyCancelled
        );
        assert_eq!(fatal_gate.start(), Ok(false));
        let (lost_sender, lost_receiver) = std::sync::mpsc::channel();
        let lost_gate = ChildStartGate::new(lost_sender);
        drop(lost_receiver);
        assert_eq!(
            lost_gate.cancel_after_failure(),
            ChildStartCancellation::NewlyCancelled {
                delivery_failed: true
            }
        );
    }

    #[test]
    fn discarding_named_fork_joins_only_that_unstarted_child() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);

        let cancelled = Arc::new(AtomicBool::new(false));
        let cancelled_in_child = cancelled.clone();
        let (cancel_sender, cancel_receiver) = std::sync::mpsc::channel();
        let cancel_completion = Arc::new(ChildCompletionSlot::default());
        let cancel_handle = ChildThread::spawn(move || match cancel_receiver.recv() {
            Ok(ChildStartCommand::Cancel) => {
                cancelled_in_child.store(true, Ordering::Release);
                Ok(())
            }
            other => Err(crate::Error::UnexpectedVcpuExit(format!(
                "unstarted child received {other:?}"
            ))),
        });
        executor.register_child_process(2, cancel_sender, cancel_completion, cancel_handle);

        let sibling_finished = Arc::new(AtomicBool::new(false));
        let sibling_finished_in_child = sibling_finished.clone();
        let (sibling_start_sender, sibling_start_receiver) = std::sync::mpsc::channel();
        let (sibling_release_sender, sibling_release_receiver) = std::sync::mpsc::channel();
        let sibling_completion = Arc::new(ChildCompletionSlot::default());
        let sibling_handle = ChildThread::spawn(move || {
            assert_eq!(
                sibling_start_receiver.recv().unwrap(),
                ChildStartCommand::Start
            );
            sibling_release_receiver.recv().unwrap();
            sibling_finished_in_child.store(true, Ordering::Release);
            Ok(())
        });
        executor.register_child_process(
            3,
            sibling_start_sender,
            sibling_completion,
            sibling_handle,
        );
        assert!(
            executor
                .pending_processes
                .get(&3)
                .unwrap()
                .start
                .start()
                .unwrap()
        );

        assert!(executor.discard_unstarted_child_process(2).unwrap());
        assert!(cancelled.load(Ordering::Acquire));
        assert!(!executor.pending_processes.contains_key(&2));
        assert!(executor.pending_processes.contains_key(&3));
        assert!(!executor.discard_unstarted_child_process(3).unwrap());
        assert!(!executor.discard_unstarted_child_process(99).unwrap());
        assert!(!sibling_finished.load(Ordering::Acquire));

        sibling_release_sender.send(()).unwrap();
        let mut sibling = executor.pending_processes.remove(&3).unwrap();
        sibling.handle.thread.join_blocking().unwrap().unwrap();
        assert!(sibling_finished.load(Ordering::Acquire));
    }

    #[test]
    fn discarding_unstarted_fork_propagates_the_child_result() {
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let (start_sender, start_receiver) = std::sync::mpsc::channel();
        let completion = Arc::new(ChildCompletionSlot::default());
        let handle = ChildThread::spawn(move || {
            assert_eq!(start_receiver.recv().unwrap(), ChildStartCommand::Cancel);
            Err(crate::Error::UnexpectedVcpuExit(
                "forced unstarted-child failure".to_owned(),
            ))
        });
        executor.register_child_process(2, start_sender, completion, handle);

        assert!(matches!(
            executor.discard_unstarted_child_process(2),
            Err(crate::Error::UnexpectedVcpuExit(message))
                if message == "forced unstarted-child failure"
        ));
        assert!(!executor.pending_processes.contains_key(&2));
    }
    fn custom_action(handler: u64) -> [u8; KERNEL_SIGACTION_SIZE] {
        let mut action = [0; KERNEL_SIGACTION_SIZE];
        action[0..8].copy_from_slice(&handler.to_le_bytes());
        action
    }

    fn custom_action_with_flags(handler: u64, flags: u64) -> [u8; KERNEL_SIGACTION_SIZE] {
        let mut action = custom_action(handler);
        action[8..16].copy_from_slice(&flags.to_le_bytes());
        action
    }

    /// Installing a real SIGCHLD handler SUCCEEDS and is recorded, as it does on
    /// Linux and under the ptrace backend. Accepting the installation is not a
    /// promise to deliver the signal; what it must not do is change the auto-reap
    /// decision, which is asserted here directly: a real handler must leave
    /// `sigchld_auto_reaps` false so the child stays waitable.
    #[test]
    fn sigchld_handler_registration_is_accepted_and_suppresses_auto_reap() {
        const ACTION: u64 = 0x100;
        let root = TestDir::new();
        let mut state = test_state(&root.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(ACTION, &custom_action(0x4321)).unwrap();

        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut state,
                &[
                    libc::SIGCHLD as u64,
                    ACTION,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0,
                ],
            ),
            0,
        );
        assert!(test_signal_action(&state, libc::SIGCHLD).is_some());
        assert!(
            !sigchld_auto_reaps(&state),
            "a real SIGCHLD handler must not auto-reap; the child stays waitable"
        );
    }

    #[test]
    fn sigchld_policy_tracks_installed_action_when_oldact_copyout_faults() {
        const ACTION: u64 = 0x100;
        const INVALID_OLD_ACTION: u64 = PAGE_SIZE;
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        memory.write(ACTION, &custom_action(1)).unwrap();

        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_rt_sigaction as u64,
                    [
                        libc::SIGCHLD as u64,
                        ACTION,
                        INVALID_OLD_ACTION,
                        KERNEL_SIGSET_SIZE as u64,
                        0,
                        0,
                    ],
                ),
                &memory,
            ),
            negative_errno(libc::EFAULT),
        );
        assert_eq!(
            executor.child_completion(ExitStatus::Exited(7)),
            ChildCompletion::AutoReaped(ExitStatus::Exited(7)),
            "the installed SIG_IGN must govern later child exits despite oldact EFAULT",
        );
    }

