    #[test]
    fn child_completion_keeps_the_exit_time_auto_reap_decision() {
        const ACTION: u64 = 0x100;
        let root = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&root.0), false);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        let exited_before_ignore = executor.child_completion(ExitStatus::Exited(3));
        memory.write(ACTION, &custom_action(1)).unwrap();
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_rt_sigaction as u64,
                    [
                        libc::SIGCHLD as u64,
                        ACTION,
                        0,
                        KERNEL_SIGSET_SIZE as u64,
                        0,
                        0,
                    ],
                ),
                &memory,
            ),
            0,
        );
        let before_ignore = executor.mock_child_completion(7);
        assert!(before_ignore.publish(exited_before_ignore));
        assert_eq!(
            executor.state.children.remove(&7),
            Some(ExitStatus::Exited(3)),
            "installing SIG_IGN after exit must not discard an existing zombie",
        );

        let exited_while_ignored = executor.child_completion(ExitStatus::Exited(4));
        memory.write(ACTION, &custom_action(0)).unwrap();
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_rt_sigaction as u64,
                    [
                        libc::SIGCHLD as u64,
                        ACTION,
                        0,
                        KERNEL_SIGSET_SIZE as u64,
                        0,
                        0,
                    ],
                ),
                &memory,
            ),
            0,
        );
        let while_ignored = executor.mock_child_completion(8);
        assert!(while_ignored.publish(exited_while_ignored));
        assert!(
            !executor.state.children.contains_key(&8),
            "restoring SIG_DFL after exit must not resurrect an auto-reaped child",
        );

        memory
            .write(
                ACTION,
                &custom_action_with_flags(0, libc::SA_NOCLDWAIT as u64),
            )
            .unwrap();
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(
                    libc::SYS_rt_sigaction as u64,
                    [
                        libc::SIGCHLD as u64,
                        ACTION,
                        0,
                        KERNEL_SIGSET_SIZE as u64,
                        0,
                        0,
                    ],
                ),
                &memory,
            ),
            0,
        );
        assert_eq!(
            executor.child_completion(ExitStatus::Exited(5)),
            ChildCompletion::AutoReaped(ExitStatus::Exited(5)),
        );
    }

    fn commit_test_exit(executor: &mut ElfExecutor, code: u64, group: bool) -> ProcessExit {
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        let number = if group {
            libc::SYS_exit_group
        } else {
            libc::SYS_exit
        };
        assert_eq!(
            executor.execute(
                &SyscallRequest::new(number as u64, [code, 0, 0, 0, 0, 0]),
                &memory
            ),
            0
        );
        executor.take_exit().unwrap()
    }

    #[test]
    fn process_exit_status_follows_shared_thread_membership_not_fork_or_drop() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut worker = leader.thread_child(2).unwrap();
        let mut fork = leader.fork_child(3, false, false).unwrap();
        assert!(Arc::ptr_eq(
            &leader.state.task_lifecycle,
            &fork.state.task_lifecycle
        ));
        assert_eq!(leader.process_generation, worker.process_generation);
        assert_ne!(leader.process_generation, fork.process_generation);
        let prepared = worker.thread_child(4).unwrap();
        commit_test_exit(&mut leader, 37, false);
        commit_test_exit(&mut worker, 73, false);
        assert_eq!(
            leader.process_exit_status(),
            None,
            "registered preparation is still live"
        );
        commit_test_exit(&mut fork, 99, false);
        drop(prepared);
        assert_eq!(leader.process_exit_status(), Some(ExitStatus::Exited(73)));
        assert_eq!(fork.process_exit_status(), Some(ExitStatus::Exited(99)));
        assert!(
            matches!(leader.process_family_exit(), Err(crate::Error::UnexpectedVcpuExit(message))
                if message == "KVM process 1 lost its terminal family transition"),
            "a final provisional-task Drop must fail closed until an explicit terminal task records the family transition",
        );
        leader.cancel_current_thread();
        worker.cancel_current_thread();
        assert_eq!(
            leader.process_exit_status(),
            Some(ExitStatus::Exited(73)),
            "duplicate retirement has no new zero status"
        );
    }

    #[test]
    fn process_exit_status_is_bound_to_process_and_task_generations() {
        let root = TestDir::new();
        let leader = ElfExecutor::new(test_state(&root.0), false);
        let mut old = leader.fork_child(3, false, false).unwrap();
        commit_test_exit(&mut old, 61, false);
        let mut new = leader.fork_child(3, false, false).unwrap();
        assert_ne!(old.process_generation, new.process_generation);
        old.retire_current_thread(ExitStatus::Exited(99), true);
        assert_eq!(
            new.process_exit_status(),
            None,
            "stale executor cannot retire replacement task"
        );
        commit_test_exit(&mut new, 73, false);
        assert_eq!(old.process_exit_status(), Some(ExitStatus::Exited(61)));
        assert_eq!(new.process_exit_status(), Some(ExitStatus::Exited(73)));
        let old_process_generation = old.process_generation;
        drop(old);
        assert_eq!(
            leader
                .state
                .task_lifecycle
                .lock()
                .unwrap()
                .process_exit_status(3, old_process_generation),
            None
        );
        assert_eq!(
            new.process_exit_status(),
            Some(ExitStatus::Exited(73)),
            "dropping an old process owner preserves the replacement's status"
        );
    }

    #[test]
    fn process_exit_status_exec_reset_rejects_old_worker_retirement() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut old_worker = leader.thread_child(2).unwrap();
        commit_test_exit(&mut old_worker, 61, false);
        leader.replace_after_exec(test_state(&root.0));
        let mut new_worker = leader.thread_child(2).unwrap();
        assert_ne!(old_worker.task_generation, new_worker.task_generation);
        old_worker.retire_current_thread(ExitStatus::Exited(99), true);
        assert_eq!(
            leader
                .signal_registry
                .process_family_exit(leader.admitted_signal_identity().process),
            None,
            "a stale pre-exec worker cannot freeze the live process family outcome",
        );
        commit_test_exit(&mut leader, 37, false);
        assert_eq!(leader.process_exit_status(), None);
        commit_test_exit(&mut new_worker, 73, false);
        assert_eq!(leader.process_exit_status(), Some(ExitStatus::Exited(73)));
    }

    #[test]
    fn process_exit_status_preserves_group_selection_and_terminal_failure() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut first = leader.thread_child(2).unwrap();
        let mut last = leader.thread_child(3).unwrap();
        commit_test_exit(&mut first, 61, true);
        assert_eq!(
            commit_test_exit(&mut last, 73, true).status,
            ExitStatus::Exited(61)
        );
        commit_test_exit(&mut leader, 37, false);
        assert_eq!(leader.process_exit_status(), Some(ExitStatus::Exited(61)));

        let mut failed_leader = ElfExecutor::new(test_state(&root.0), false);
        let mut failed_worker = failed_leader.thread_child(2).unwrap();
        commit_test_exit(&mut failed_leader, 37, false);
        failed_worker.retire_failed_thread();
        assert_eq!(
            failed_leader.process_exit_status(),
            None,
            "a failed worker does not manufacture guest exit status"
        );
    }

    #[test]
    fn exit_syscalls_keep_only_the_low_eight_status_bits() {
        let dir = TestDir::new();
        let mut state = test_state(&dir.0);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();

        for (raw, expected) in [(0x1234_u64, 0x34), ((-1_i64) as u64, 0xff)] {
            match execute_basic_syscall(
                &mut memory,
                &mut state,
                &SyscallRequest::new(libc::SYS_exit as u64, [raw, 0, 0, 0, 0, 0]),
            ) {
                SyscallAction::Exit(status) => {
                    assert_eq!(status, ExitStatus::Exited(expected));
                }
                SyscallAction::Continue { .. } => {
                    panic!("exit syscall with raw status {raw:#x} did not exit");
                }
                SyscallAction::Failure(error) => panic!("exit syscall failed internally: {error}"),
            }
        }
    }

    #[test]
    fn self_directed_fatal_signal_terminates_with_conventional_status() {
        let dir = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        let pid = executor.state.pid;

        // abort() raises SIGABRT via tgkill(pid, tid, SIGABRT).
        assert_eq!(
            result_of(kill_signal(
                &mut executor.state,
                libc::SYS_tgkill as u64,
                &[pid as u64, pid as u64, libc::SIGABRT as u64, 0, 0, 0],
            )),
            0,
        );
        let status = apply_next_default_signal(&mut executor);
        assert_eq!(status, ExitStatus::Signaled(Signal::SIGABRT, true));
        assert_eq!(conventional_exit_code(status), 128 + libc::SIGABRT);
    }

    #[test]
    fn nondumpable_fatal_signal_omits_core_status_in_both_wait_apis() {
        const OUTPUT: u64 = 0x100;
        let dir = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        let pid = executor.state.pid;
        assert_eq!(
            prctl(
                &mut executor.state,
                &[libc::PR_SET_DUMPABLE as u64, 0, 0, 0, 0, 0],
            ),
            0,
        );
        assert_eq!(
            result_of(kill_signal(
                &mut executor.state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGABRT as u64, 0, 0, 0, 0],
            )),
            0,
        );
        let status = apply_next_default_signal(&mut executor);
        assert_eq!(status, ExitStatus::Signaled(Signal::SIGABRT, false));

        // The fatal signal retired `executor`; a live parent performs waits.
        // Keep the status obtained from that real fatal transition as the ABI
        // oracle rather than resurrecting the terminated task's family state.
        assert!(executor.signal_task_identity().is_none());
        let mut wait_parent = ElfExecutor::new(test_state(&dir.0), false);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        wait_parent.state.children.insert(7, status);
        assert_eq!(
            wait4(
                &mut memory,
                &mut wait_parent.state,
                &[7, OUTPUT, 0, 0, 0, 0]
            ),
            7,
        );
        let mut raw_status = [0; std::mem::size_of::<libc::c_int>()];
        memory.read(OUTPUT, &mut raw_status).unwrap();
        let raw_status = libc::c_int::from_le_bytes(raw_status);
        assert!(libc::WIFSIGNALED(raw_status));
        assert_eq!(libc::WTERMSIG(raw_status), libc::SIGABRT);
        assert!(!libc::WCOREDUMP(raw_status));

        wait_parent.state.children.insert(8, status);
        assert_eq!(
            waitid(
                &mut memory,
                &mut wait_parent.state,
                &[libc::P_PID as u64, 8, OUTPUT, libc::WEXITED as u64, 0, 0],
            ),
            0,
        );
        let info: libc::siginfo_t = read_struct(&memory, OUTPUT);
        assert_eq!(info.si_code, libc::CLD_KILLED);
        // SAFETY: waitid writes the SIGCHLD variant of siginfo_t.
        unsafe {
            assert_eq!(info.si_status(), libc::SIGABRT);
        }
    }

