    #[test]
    fn process_directed_signal_with_live_sibling_is_schedule_independent_refusal() {
        let dir = TestDir::new();
        for _ in 0..16 {
            let leader = ElfExecutor::new(test_state(&dir.0), false);
            let worker = leader.thread_child(7).unwrap();
            let pid = leader.state.pid;
            let barrier = Arc::new(std::sync::Barrier::new(3));
            let leader_barrier = barrier.clone();
            let worker_barrier = barrier.clone();
            let leader_thread = std::thread::spawn(move || {
                let mut executor = leader;
                leader_barrier.wait();
                let result = result_of(kill_signal(
                    &mut executor.state,
                    libc::SYS_kill as u64,
                    &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
                ));
                leader_barrier.wait();
                (executor, result)
            });
            let worker_thread = std::thread::spawn(move || {
                let mut executor = worker;
                worker_barrier.wait();
                let result = result_of(kill_signal(
                    &mut executor.state,
                    libc::SYS_kill as u64,
                    &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
                ));
                worker_barrier.wait();
                (executor, result)
            });
            barrier.wait();
            barrier.wait();
            let (leader, leader_result) = leader_thread.join().unwrap();
            let (worker, worker_result) = worker_thread.join().unwrap();
            assert_eq!(leader_result, negative_errno(libc::ENOSYS));
            assert_eq!(worker_result, negative_errno(libc::ENOSYS));
            assert!(leader.state.thread_signals.lock().pending.is_empty());
            assert!(worker.state.thread_signals.lock().pending.is_empty());
            assert!(
                leader
                    .state
                    .process_signals
                    .lock()
                    .unwrap()
                    .shared_pending
                    .is_empty(),
            );
        }
    }

    #[test]
    fn task_id_allocation_fails_closed_instead_of_wrapping() {
        let dir = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        executor.next_pid.store(i32::MAX - 1, Ordering::SeqCst);
        assert_eq!(executor.allocate_task_id(), Some(i32::MAX - 1));
        for _ in 0..2 {
            assert_eq!(
                executor.prepare_fork(None, None, None, None, false, false),
                negative_errno(libc::EAGAIN),
            );
            assert_eq!(
                executor.prepare_thread(
                    THREAD_CLONE_REQUIRED_FLAGS,
                    Some(0x8000),
                    None,
                    None,
                    None
                ),
                negative_errno(libc::EAGAIN),
            );
            assert!(executor.process_action.is_none());
            assert_eq!(executor.next_pid.load(Ordering::SeqCst), i32::MAX);
        }
    }

    #[test]
    fn process_pending_signal_prevents_a_new_host_timed_thread_consumer() {
        let dir = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        let pid = executor.state.pid;
        test_block_signal(&mut executor.state, libc::SIGUSR1);
        assert_eq!(
            result_of(kill_signal(
                &mut executor.state,
                libc::SYS_kill as u64,
                &[pid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            )),
            0,
        );
        assert!(executor.has_shared_pending_signal());

        let next_pid_before = executor.next_pid.load(Ordering::SeqCst);
        let files_before = executor.state.files.len();
        let identities_before = executor.state.fd_object_inodes.len();
        assert!(
            executor
                .state
                .task_lifecycle
                .lock()
                .unwrap()
                .get(next_pid_before)
                .is_none()
        );
        assert_eq!(
            executor.prepare_thread(THREAD_CLONE_REQUIRED_FLAGS, Some(0x8000), None, None, None,),
            negative_errno(libc::ENOSYS),
        );
        assert!(executor.process_action.is_none());
        assert_eq!(executor.next_pid.load(Ordering::SeqCst), next_pid_before);
        assert_eq!(executor.state.files.len(), files_before);
        assert_eq!(executor.state.fd_object_inodes.len(), identities_before);
        assert!(executor.has_shared_pending_signal());
        assert!(
            executor
                .state
                .task_lifecycle
                .lock()
                .unwrap()
                .get(next_pid_before)
                .is_none()
        );

        let error = match executor.thread_child(next_pid_before) {
            Ok(_) => panic!("the internal transition accepted an unselected pending signal"),
            Err(error) => error,
        };
        assert!(error.to_string().contains("lacks a selected recipient"));
        assert!(executor.has_shared_pending_signal());
        assert!(
            executor
                .state
                .task_lifecycle
                .lock()
                .unwrap()
                .get(next_pid_before)
                .is_none()
        );
    }

    /// Build a CLONE_THREAD worker and hand back its state, so a test can
    /// exercise the `pid != tid` shape that every pre-existing signal test
    /// missed by using `test_state`, where pid == tid == 1.
    /// ⚠️ THE LEADER IS RETURNED, NOT DROPPED, AND THAT IS LOAD-BEARING.
    /// `ElfExecutor::drop` deregisters its tid from the shared lifecycle table,
    /// so letting the leader fall out of scope here would delete the very
    /// sibling these tests ask the handler to find — and the leader-targeted
    /// case would then pass for the WRONG reason, reporting ESRCH because no
    /// such thread exists rather than ENOSYS because it exists and is not
    /// deliverable. Holding it alive keeps the two outcomes distinguishable.
    fn worker_state(dir: &TestDir, worker_tid: i32) -> (ElfExecutor, ElfExecutor, i32) {
        let leader = ElfExecutor::new(test_state(&dir.0), false);
        let leader_tid = leader.state.tid;
        let worker = leader.thread_child(worker_tid).expect("thread_child");
        (worker, leader, leader_tid)
    }

    fn result_of(action: SyscallAction) -> i64 {
        match action {
            SyscallAction::Continue { result, .. } => result,
            SyscallAction::Exit(code) => panic!("expected Continue, got Exit({code:?})"),
            SyscallAction::Failure(error) => {
                panic!("expected Continue, got internal failure: {error}")
            }
        }
    }

    fn apply_next_default_signal(executor: &mut ElfExecutor) -> ExitStatus {
        let pending = executor
            .take_pending_signal()
            .expect("default-fatal signal was not pending at the return boundary");
        let signal = pending.event.signal();
        assert_eq!(
            executor.signal_disposition(signal),
            SignalDisposition::Terminate
        );
        executor.force_signal_exit(signal);
        executor
            .take_exit()
            .expect("default signal did not exit")
            .status
    }

    /// The premise the rejected implementation got wrong: a worker's tid is not
    /// its pid. If this ever fails, every assertion below is vacuous.
    #[test]
    fn selected_process_event_stays_with_selected_thread() {
        let dir = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&dir.0), false);
        let pid = leader.state.pid;
        let mut worker = leader.thread_child(7).unwrap();
        let event = event_for_process(libc::SIGUSR1, pid).unwrap();

        worker.defer_signal_delivery(event).unwrap();

        assert!(
            worker
                .state
                .thread_signals
                .lock()
                .pending
                .contains(libc::SIGUSR1)
        );
        assert!(
            !leader
                .state
                .thread_signals
                .lock()
                .pending
                .contains(libc::SIGUSR1)
        );
        assert!(
            !leader
                .state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .contains(libc::SIGUSR1),
            "a preselected process-directed event must not return to process-wide selection",
        );
        let selected = worker.take_pending_signal().unwrap();
        assert_eq!(selected.domain, PendingSignalDomain::Thread);
        assert_eq!(
            selected.event.target(),
            reverie::SignalTarget::Process {
                pid: reverie::Pid::from_raw(pid)
            }
        );
        assert!(leader.take_pending_signal().is_none());
    }

    #[test]
    fn deferred_signal_accepts_timer_provenance_but_rejects_faults_and_queues() {
        let dir = TestDir::new();
        for (signal, code) in [
            (libc::SIGALRM, libc::SI_KERNEL),
            (libc::SIGUSR1, libc::SI_TIMER),
            (libc::SIGUSR1, libc::SI_USER),
            (libc::SIGUSR1, libc::SI_TKILL),
        ] {
            let mut executor = ElfExecutor::new(test_state(&dir.0), false);
            let pid = executor.state.pid;
            let info = signal_info_user(signal, pid, 0, code);
            let target = if code == libc::SI_TKILL {
                reverie::SignalTarget::Thread {
                    pid: reverie::Pid::from_raw(pid),
                    tid: reverie::Pid::from_raw(pid),
                }
            } else {
                reverie::SignalTarget::Process {
                    pid: reverie::Pid::from_raw(pid),
                }
            };
            let event = reverie::SignalEvent::new(signal, info, target).unwrap();
            executor.defer_signal_delivery(event).unwrap();
            let selected = executor.take_pending_signal().unwrap();
            assert_eq!(
                selected.event.siginfo(),
                info,
                "signal={signal}, code={code}"
            );
        }

        for (signal, code) in [
            (libc::SIGKILL, libc::SI_USER),
            (libc::SIGSTOP, libc::SI_USER),
            (libc::SIGUSR1, libc::SI_KERNEL),
            (libc::SIGSEGV, 1), // SEGV_MAPERR is a positive synchronous code.
            (libc::SIGUSR1, libc::SI_QUEUE),
            (libc::SIGUSR1, libc::SI_MESGQ),
        ] {
            let mut executor = ElfExecutor::new(test_state(&dir.0), false);
            let pid = executor.state.pid;
            let event = reverie::SignalEvent::new(
                signal,
                signal_info_user(signal, pid, 0, code),
                reverie::SignalTarget::Process {
                    pid: reverie::Pid::from_raw(pid),
                },
            )
            .unwrap();
            assert_eq!(
                executor.defer_signal_delivery(event),
                Err(reverie::syscalls::Errno::ENOSYS),
                "signal={signal}, code={code}",
            );
            assert!(executor.take_pending_signal().is_none());
        }

        for (code, target) in [
            (
                libc::SI_USER,
                reverie::SignalTarget::Thread {
                    pid: reverie::Pid::from_raw(1),
                    tid: reverie::Pid::from_raw(1),
                },
            ),
            (
                libc::SI_TKILL,
                reverie::SignalTarget::Process {
                    pid: reverie::Pid::from_raw(1),
                },
            ),
            (
                libc::SI_TIMER,
                reverie::SignalTarget::Thread {
                    pid: reverie::Pid::from_raw(1),
                    tid: reverie::Pid::from_raw(1),
                },
            ),
        ] {
            let mut executor = ElfExecutor::new(test_state(&dir.0), false);
            let info = signal_info_user(libc::SIGUSR1, 1, 0, code);
            let event = reverie::SignalEvent::new(libc::SIGUSR1, info, target).unwrap();
            assert_eq!(
                executor.defer_signal_delivery(event),
                Err(reverie::syscalls::Errno::ENOSYS),
                "mismatched code={code}, target={target:?}",
            );
        }

        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        let pid = executor.state.pid;
        let info = signal_info_user(libc::SIGRTMIN(), pid, 0, libc::SI_TIMER);
        let realtime = reverie::SignalEvent::new(
            libc::SIGRTMIN(),
            info,
            reverie::SignalTarget::Process {
                pid: reverie::Pid::from_raw(pid),
            },
        )
        .unwrap();
        assert_eq!(
            executor.defer_signal_delivery(realtime),
            Err(reverie::syscalls::Errno::ENOSYS),
        );
    }

    #[test]
    fn structured_replacement_uses_replacement_disposition_and_mask() {
        let dir = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        let pid = executor.state.pid;
        let tid = executor.state.tid;
        let mut first_mask = KernelSigset::default();
        first_mask.insert(libc::SIGTERM);
        let first = KernelSigaction {
            handler: 0x1111,
            flags: libc::SA_NODEFER as u64,
            restorer: 0xaaaa,
            mask: first_mask,
        };
        let mut replacement_mask = KernelSigset::default();
        replacement_mask.insert(libc::SIGINT);
        let replacement = KernelSigaction {
            handler: 0x2222,
            flags: libc::SA_RESETHAND as u64,
            restorer: 0xbbbb,
            mask: replacement_mask,
        };
        test_install_signal_action(&executor.state, libc::SIGUSR1, first.encode());
        test_install_signal_action(&executor.state, libc::SIGUSR2, replacement.encode());

        let mut info = event_for_thread(libc::SIGUSR1, pid, tid).unwrap().siginfo();
        info[..4].copy_from_slice(&libc::SIGUSR2.to_ne_bytes());
        let replaced = reverie::SignalEvent::new(
            libc::SIGUSR2,
            info,
            reverie::SignalTarget::Thread {
                pid: reverie::Pid::from_raw(pid),
                tid: reverie::Pid::from_raw(tid),
            },
        )
        .unwrap();
        let pending = executor
            .prepare_filtered_signal_delivery(replaced, PendingSignalDomain::Thread)
            .unwrap()
            .unwrap();

        assert_eq!(pending.event.signal(), libc::SIGUSR2);
        assert_eq!(executor.signal_action(pending.event.signal()), replacement);
        executor.enter_signal_handler(pending, replacement, false);
        assert!(
            executor
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGINT)
        );
        assert!(
            !executor
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGTERM)
        );
        assert_eq!(
            executor.signal_disposition(libc::SIGUSR2),
            SignalDisposition::Terminate
        );
        assert_eq!(executor.signal_action(libc::SIGUSR1), first);
    }

    #[test]
    fn blocked_tool_replacement_requeues_without_consuming_another_event() {
        let dir = TestDir::new();
        let mut executor = ElfExecutor::new(test_state(&dir.0), false);
        let pid = executor.state.pid;
        let tid = executor.state.tid;
        executor
            .defer_signal_delivery(event_for_thread(libc::SIGUSR1, pid, tid).unwrap())
            .unwrap();
        executor
            .defer_signal_delivery(event_for_thread(libc::SIGTERM, pid, tid).unwrap())
            .unwrap();
        let selected = executor.take_pending_signal().unwrap();
        assert_eq!(selected.event.signal(), libc::SIGUSR1);

        executor
            .state
            .thread_signals
            .lock()
            .blocked
            .insert(libc::SIGUSR2);
        let mut info = selected.event.siginfo();
        info[..4].copy_from_slice(&libc::SIGUSR2.to_ne_bytes());
        let replacement = reverie::SignalEvent::new(
            libc::SIGUSR2,
            info,
            reverie::SignalTarget::Thread {
                pid: reverie::Pid::from_raw(pid),
                tid: reverie::Pid::from_raw(tid),
            },
        )
        .unwrap();

        assert_eq!(
            executor
                .prepare_filtered_signal_delivery(replacement, selected.domain)
                .unwrap(),
            None,
            "a replacement newly blocked by its signal number is requeued",
        );
        assert!(
            executor
                .state
                .thread_signals
                .lock()
                .pending
                .contains(libc::SIGUSR2)
        );
        let untouched = executor.take_pending_signal().unwrap();
        assert_eq!(
            untouched.event.signal(),
            libc::SIGTERM,
            "the next eligible event must remain pending and unfiltered"
        );
    }

    #[test]
    fn thread_child_worker_has_pid_distinct_from_tid() {
        let dir = TestDir::new();
        let (worker, _leader, leader_tid) = worker_state(&dir, 7);
        let worker = &worker.state;
        assert_ne!(
            worker.pid, worker.tid,
            "worker pid must differ from its tid"
        );
        assert_eq!(worker.tid, 7);
        assert_eq!(worker.pid, leader_tid, "worker keeps the leader's tgid");
    }

    /// A worker signalling ITSELF must succeed. The rejected head compared the
    /// target against `state.pid` and returned ESRCH for both of these.
    #[test]
    fn worker_self_directed_probe_signals_succeed() {
        let dir = TestDir::new();
        let (mut worker, _leader, _) = worker_state(&dir, 7);
        let worker = &mut worker.state;
        let (pid, tid) = (worker.pid, worker.tid);
        assert_eq!(
            result_of(kill_signal(
                worker,
                libc::SYS_tkill as u64,
                &[tid as u64, 0, 0, 0, 0, 0],
            )),
            0,
            "tkill(gettid(), 0) from a worker"
        );
        assert_eq!(
            result_of(kill_signal(
                worker,
                libc::SYS_tgkill as u64,
                &[pid as u64, tid as u64, 0, 0, 0, 0],
            )),
            0,
            "tgkill(getpid(), gettid(), 0) from a worker"
        );
    }

    /// ⚠️ THE MUTATION THE REJECTION NAMED. A leader-targeted signal must not be
    /// evaluated against, or applied to, the WORKER's signal state. This asserts
    /// the state is untouched, not merely that the call failed.
    #[test]
    fn leader_targeted_signal_does_not_mutate_worker_signal_state() {
        let dir = TestDir::new();
        let (mut worker, mut leader, leader_tid) = worker_state(&dir, 7);
        let worker = &mut worker.state;
        let pid = worker.pid;
        test_install_signal_action(worker, libc::SIGUSR1, custom_action(0x4321));
        let before_actions = test_signal_actions(worker);
        let before_mask = test_blocked_mask(worker);

        let result = result_of(kill_signal(
            worker,
            libc::SYS_tgkill as u64,
            &[pid as u64, leader_tid as u64, libc::SIGUSR1 as u64, 0, 0, 0],
        ));

        assert_eq!(result, 0, "the named live receiver accepts the signal");
        let delivered = leader.take_pending_signal().expect("leader event missing");
        assert_eq!(
            delivered.event,
            event_for_thread(libc::SIGUSR1, pid, leader_tid).unwrap()
        );
        assert_eq!(
            leader.take_pending_signal(),
            None,
            "one send produces one event"
        );
        assert!(worker.thread_signals.lock().pending.is_empty());
        assert_eq!(
            test_signal_actions(worker),
            before_actions,
            "dispositions mutated"
        );
        assert_eq!(
            test_blocked_mask(worker),
            before_mask,
            "signal mask mutated"
        );

        // A blocked signal makes the no-mutation requirement explicit. If the
        // target is incorrectly compared with this worker's process id, the
        // wrong branch reports success and queues the signal in this worker.
        // Successful receiver routing still changes no sender pending state.
        let blocked = libc::SIGUSR2;
        test_block_signal(worker, blocked);
        let pending_before = {
            let process_signals = worker.process_signals.lock().unwrap();
            worker
                .thread_signals
                .lock()
                .pending
                .pending_mask(&process_signals.pending_generations)
        };

        let blocked_result = result_of(kill_signal(
            worker,
            libc::SYS_tgkill as u64,
            &[pid as u64, leader_tid as u64, blocked as u64, 0, 0, 0],
        ));

        assert_eq!(
            blocked_result, 0,
            "the sender's blocked mask must not block the leader's signal"
        );
        let delivered = leader
            .take_pending_signal()
            .expect("leader's second event missing");
        assert_eq!(
            delivered.event,
            event_for_thread(blocked, pid, leader_tid).unwrap()
        );
        assert_eq!(leader.take_pending_signal(), None);
        let pending_after = {
            let process_signals = worker.process_signals.lock().unwrap();
            worker
                .thread_signals
                .lock()
                .pending
                .pending_mask(&process_signals.pending_generations)
        };
        assert_eq!(
            pending_after, pending_before,
            "a leader-targeted blocked signal was queued into the WORKER's pending set"
        );
    }

    /// Zero and a raw zero-extended negative id are EINVAL, not ESRCH. Widening
    /// with `as i64` turns 0xFFFF_FFFF into 4294967295 and hides this.
    #[test]
    fn nonpositive_thread_signal_ids_report_einval() {
        let dir = TestDir::new();
        let (mut worker, _leader, _) = worker_state(&dir, 7);
        let worker = &mut worker.state;
        let pid = worker.pid;
        for (label, number, args) in [
            (
                "tkill(0)",
                libc::SYS_tkill,
                [0u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            (
                "tkill(zero-extended -1)",
                libc::SYS_tkill,
                [0x0000_0000_FFFF_FFFF, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            ),
            (
                "tgkill(tgid=0)",
                libc::SYS_tgkill,
                [0, 7, libc::SIGUSR1 as u64, 0, 0, 0],
            ),
            (
                "tgkill(tid=zero-extended -1)",
                libc::SYS_tgkill,
                [
                    pid as u64,
                    0x0000_0000_FFFF_FFFF,
                    libc::SIGUSR1 as u64,
                    0,
                    0,
                    0,
                ],
            ),
        ] {
            assert_eq!(
                result_of(kill_signal(worker, number as u64, &args)),
                negative_errno(libc::EINVAL),
                "{label} must be EINVAL"
            );
        }
    }

    /// A positive id that names no live task is ESRCH, distinct from the
    /// explicit ENOSYS refusal for a live target outside the supported scope.
    #[test]
    fn foreign_thread_id_reports_esrch_not_enosys() {
        let dir = TestDir::new();
        let (mut worker, _leader, _) = worker_state(&dir, 7);
        let worker = &mut worker.state;
        assert_eq!(
            result_of(kill_signal(
                worker,
                libc::SYS_tkill as u64,
                &[4242, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            )),
            negative_errno(libc::ESRCH),
        );
    }

    /// A caught signal is queued for the current task, while stopped-state
    /// scheduling still fails visibly. An ignored signal is also queued so a
    /// Tool can observe its delivery stop; the return-boundary path discards it
    /// after that hook.
    #[test]
    fn caught_and_ignored_signals_succeed_while_stop_fails_visibly() {
        let dir = TestDir::new();
        let (mut worker, _leader, _) = worker_state(&dir, 7);
        worker.observe_ignored_signals_with_tool();
        let worker = &mut worker.state;
        let tid = worker.tid;

        test_install_signal_action(worker, libc::SIGUSR1, custom_action(0x4321));
        assert_eq!(
            result_of(kill_signal(
                worker,
                libc::SYS_tkill as u64,
                &[tid as u64, libc::SIGUSR1 as u64, 0, 0, 0, 0],
            )),
            0,
            "a caught self-thread signal must be accepted for deferred delivery"
        );
        assert!(worker.thread_signals.lock().pending.contains(libc::SIGUSR1));

        assert_eq!(
            result_of(kill_signal(
                worker,
                libc::SYS_tkill as u64,
                &[tid as u64, libc::SIGTSTP as u64, 0, 0, 0, 0],
            )),
            negative_errno(libc::ENOSYS),
            "no stopped state is modeled"
        );

        test_install_signal_action(worker, libc::SIGUSR2, custom_action(1));
        assert_eq!(
            result_of(kill_signal(
                worker,
                libc::SYS_tkill as u64,
                &[tid as u64, libc::SIGUSR2 as u64, 0, 0, 0, 0],
            )),
            0,
            "SIG_IGN is a real delivery outcome",
        );
        assert!(
            worker.thread_signals.lock().pending.contains(libc::SIGUSR2),
            "ignored signals remain observable to the Tool until the return boundary",
        );
    }

    #[test]
    fn sibling_signal_uses_one_private_queue_and_preserves_first_siginfo() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut receiver = leader.thread_child(7).unwrap();
        let signal = libc::SIGUSR1;
        test_block_signal(&mut receiver.state, signal);
        let event = event_for_thread(signal, leader.state.pid, 7).unwrap();
        let marked = |marker| {
            let mut info = event.siginfo();
            info[127] = marker;
            reverie::SignalEvent::new(signal, info, event.target()).unwrap()
        };
        let first = marked(0x11);
        receiver.defer_signal_delivery(first).unwrap();
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tgkill as u64,
                &[1, 7, signal as u64, 0, 0, 0]
            )),
            0
        );
        receiver.defer_signal_delivery(marked(0x22)).unwrap();
        assert_eq!(
            leader.take_pending_signal(),
            None,
            "sender cannot take receiver event"
        );
        assert_eq!(
            receiver.take_pending_signal(),
            None,
            "blocked receiver must retain it"
        );
        receiver.state.thread_signals.lock().blocked.remove(signal);
        assert_eq!(
            receiver.take_pending_signal().unwrap().event,
            first,
            "sibling and Tool producers must coalesce in the original queue"
        );
        assert_eq!(receiver.take_pending_signal(), None);
        assert!(
            leader
                .state
                .process_signals
                .lock()
                .unwrap()
                .shared_pending
                .is_empty()
        );
    }

    #[test]
    fn sibling_signal_identity_errors_and_probes_have_no_pending_effect() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let receiver = leader.thread_child(7).unwrap();
        let foreign = leader.fork_child(9, false, false).unwrap();
        for (tgid, tid, signal, expected) in [
            (1, 7, 0, 0),
            (9, 9, 0, 0),
            (2, 7, libc::SIGUSR1, -libc::ESRCH),
            (1, 99, libc::SIGUSR1, -libc::ESRCH),
            (9, 9, libc::SIGUSR1, -libc::ENOSYS),
            (1, 7, libc::SIGKILL, -libc::ENOSYS),
            (1, 7, libc::SIGSTOP, -libc::ENOSYS),
            (1, 7, libc::SIGCHLD, -libc::ENOSYS),
            (1, 7, libc::SIGPIPE, -libc::ENOSYS),
            (1, 7, libc::SIGRTMIN(), -libc::ENOSYS),
            (1, 7, 65, -libc::EINVAL),
            (0, 7, libc::SIGUSR1, -libc::EINVAL),
            (1, -1, libc::SIGUSR1, -libc::EINVAL),
        ] {
            let actions = test_signal_actions(&leader.state);
            let mask = test_blocked_mask(&leader.state);
            assert_eq!(
                result_of(kill_signal(
                    &mut leader.state,
                    libc::SYS_tgkill as u64,
                    &[
                        tgid as u32 as u64,
                        tid as u32 as u64,
                        signal as u64,
                        0,
                        0,
                        0
                    ]
                )),
                i64::from(expected),
                "tgid={tgid} tid={tid} signal={signal}"
            );
            assert_eq!(test_signal_actions(&leader.state), actions);
            assert_eq!(test_blocked_mask(&leader.state), mask);
            for state in [&leader.state, &receiver.state, &foreign.state] {
                assert!(state.thread_signals.lock().pending.is_empty());
                assert!(
                    state
                        .process_signals
                        .lock()
                        .unwrap()
                        .shared_pending
                        .is_empty()
                );
            }
        }
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tkill as u64,
                &[7, 0, 0, 0, 0, 0]
            )),
            0
        );
    }

    #[test]
    fn sibling_signal_retirement_and_tid_reuse_preserve_exact_registration() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut retired = leader.thread_child(7).unwrap();
        let retired_generation = retired.task_generation;
        let retired_weak = retired.state.thread_signals.downgrade();
        test_block_signal(&mut retired.state, libc::SIGUSR1);
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tgkill as u64,
                &[1, 7, libc::SIGUSR1 as u64, 0, 0, 0]
            )),
            0
        );
        let memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            retired.execute(&SyscallRequest::new(libc::SYS_exit as u64, [0; 6]), &memory),
            0
        );
        assert!(retired.take_exit().is_some());
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tgkill as u64,
                &[1, 7, libc::SIGUSR1 as u64, 0, 0, 0]
            )),
            negative_errno(libc::ESRCH)
        );
        let mut replacement = leader.thread_child(7).unwrap();
        assert_ne!(replacement.task_generation, retired_generation);
        assert!(replacement.state.thread_signals.lock().pending.is_empty());
        drop(retired);
        assert!(
            retired_weak.upgrade().is_none(),
            "the index must not own dead state"
        );
        assert_eq!(
            leader
                .state
                .task_lifecycle
                .lock()
                .unwrap()
                .get(7)
                .unwrap()
                .generation,
            replacement.task_generation,
            "stale Drop removed the reused registration"
        );
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tgkill as u64,
                &[1, 7, libc::SIGUSR2 as u64, 0, 0, 0]
            )),
            0
        );
        assert_eq!(
            replacement.take_pending_signal().unwrap().event.signal(),
            libc::SIGUSR2
        );
        assert_eq!(replacement.take_pending_signal(), None);
        assert_eq!(leader.take_pending_signal(), None);
    }

    #[test]
    fn sibling_signal_uses_receiver_mask_and_runtime_observation_mode() {
        let root = TestDir::new();
        for observed in [false, true] {
            for blocked in [false, true] {
                let mut leader = ElfExecutor::new(test_state(&root.0), false);
                let mut receiver = leader
                    .thread_child_with_signal_observation(7, observed)
                    .unwrap();
                test_install_signal_action(&leader.state, libc::SIGUSR1, custom_action(1));
                // The sender's opposite mask cannot decide target eligibility.
                if blocked {
                    test_block_signal(&mut receiver.state, libc::SIGUSR1);
                } else {
                    test_block_signal(&mut leader.state, libc::SIGUSR1);
                }
                let sender_mask = test_blocked_mask(&leader.state);
                assert_eq!(
                    result_of(kill_signal(
                        &mut leader.state,
                        libc::SYS_tgkill as u64,
                        &[1, 7, libc::SIGUSR1 as u64, 0, 0, 0]
                    )),
                    0
                );
                assert_eq!(test_blocked_mask(&leader.state), sender_mask);
                assert!(leader.state.thread_signals.lock().pending.is_empty());
                assert_eq!(
                    receiver
                        .state
                        .thread_signals
                        .lock()
                        .pending
                        .contains(libc::SIGUSR1),
                    observed || blocked
                );
                test_install_signal_action(&leader.state, libc::SIGUSR1, custom_action(0x4000));
                receiver
                    .state
                    .thread_signals
                    .lock()
                    .blocked
                    .remove(libc::SIGUSR1);
                let pending = receiver.take_pending_signal();
                assert_eq!(
                    pending.is_some(),
                    observed || blocked,
                    "an unblocked plain ignored event must not reappear on handler installation"
                );
                if let Some(pending) = pending {
                    assert_eq!(
                        pending.event,
                        event_for_thread(libc::SIGUSR1, 1, 7).unwrap()
                    );
                }
                assert_eq!(receiver.take_pending_signal(), None);
            }
        }
    }

    #[test]
    fn sibling_signal_generation_changes_keep_only_post_ignore_event() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut receiver = leader.thread_child(7).unwrap();
        test_block_signal(&mut receiver.state, libc::SIGUSR1);
        let mut memory = GuestMemory::new(0, PAGE_SIZE as usize).unwrap();
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tgkill as u64,
                &[1, 7, libc::SIGUSR1 as u64, 0, 0, 0]
            )),
            0
        );
        let action_address = 0x100;
        memory.write(action_address, &custom_action(1)).unwrap();
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut leader.state,
                &[
                    libc::SIGUSR1 as u64,
                    action_address,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0
                ]
            ),
            0
        );
        receiver
            .state
            .thread_signals
            .lock()
            .blocked
            .remove(libc::SIGUSR1);
        assert_eq!(
            receiver.take_pending_signal(),
            None,
            "pre-ignore event stayed eligible"
        );
        test_block_signal(&mut receiver.state, libc::SIGUSR1);
        assert_eq!(
            result_of(kill_signal(
                &mut leader.state,
                libc::SYS_tgkill as u64,
                &[1, 7, libc::SIGUSR1 as u64, 0, 0, 0]
            )),
            0
        );
        memory
            .write(action_address, &custom_action(0x4000))
            .unwrap();
        assert_eq!(
            rt_sigaction(
                &mut memory,
                &mut leader.state,
                &[
                    libc::SIGUSR1 as u64,
                    action_address,
                    0,
                    KERNEL_SIGSET_SIZE as u64,
                    0,
                    0
                ]
            ),
            0
        );
        receiver
            .state
            .thread_signals
            .lock()
            .blocked
            .remove(libc::SIGUSR1);
        assert_eq!(
            receiver.take_pending_signal().unwrap().event.signal(),
            libc::SIGUSR1
        );
        assert_eq!(receiver.take_pending_signal(), None);
    }

    #[test]
    fn accepted_sibling_signal_survives_exec_and_endpoint_replacement() {
        let root = TestDir::new();
        let mut leader = ElfExecutor::new(test_state(&root.0), false);
        let mut sender = leader.thread_child(7).unwrap();
        test_block_signal(&mut leader.state, libc::SIGUSR1);
        test_install_signal_action(&leader.state, libc::SIGUSR1, custom_action(0x4000));
        assert_eq!(
            result_of(kill_signal(
                &mut sender.state,
                libc::SYS_tgkill as u64,
                &[1, 1, libc::SIGUSR1 as u64, 0, 0, 0]
            )),
            0
        );
        let old_target = leader.state.thread_signals.downgrade();
        // Successful exec's runtime tears down siblings before replacing state.
        drop(sender);
        leader.replace_after_exec(test_state(&root.0));
        assert!(old_target.upgrade().is_none());
        assert!(
            leader
                .state
                .thread_signals
                .lock()
                .blocked
                .contains(libc::SIGUSR1)
        );
        let target = leader
            .state
            .task_lifecycle
            .lock()
            .unwrap()
            .signal_target(1)
            .unwrap();
        assert!(std::sync::Weak::ptr_eq(
            &target.downgrade(),
            &leader.state.thread_signals.downgrade()
        ));
        assert_eq!(leader.take_pending_signal(), None);
        leader
            .state
            .thread_signals
            .lock()
            .blocked
            .remove(libc::SIGUSR1);
        assert_eq!(
            leader.take_pending_signal().unwrap().event,
            event_for_thread(libc::SIGUSR1, 1, 1).unwrap()
        );
        assert_eq!(leader.take_pending_signal(), None);
    }

    #[test]
    fn signal_disposition_honors_handlers_over_defaults() {
        let dir = TestDir::new();
        let state = test_state(&dir.0);

        assert_eq!(
            signal_disposition(&state, libc::SIGABRT),
            SignalDisposition::Terminate
        );
        assert_eq!(
            signal_disposition(&state, libc::SIGCHLD),
            SignalDisposition::Ignore
        );
        assert_eq!(
            signal_disposition(&state, libc::SIGTSTP),
            SignalDisposition::Stop
        );

        test_install_signal_action(&state, libc::SIGABRT, custom_action(0x1)); // SIG_IGN
        assert_eq!(
            signal_disposition(&state, libc::SIGABRT),
            SignalDisposition::Ignore
        );
        test_install_signal_action(&state, libc::SIGABRT, custom_action(0xdead_beef));
        assert_eq!(
            signal_disposition(&state, libc::SIGABRT),
            SignalDisposition::Handled
        );
    }

    #[test]
    fn resolve_guest_exec_image_is_stable_for_every_task_alias() {
        use std::os::unix::fs::PermissionsExt;
        let dir = TestDir::new();
        let executable = dir.0.join("current-image");
        std::fs::write(&executable, b"loaded image").unwrap();
        std::fs::set_permissions(&executable, std::fs::Permissions::from_mode(0o700)).unwrap();
        let mut leader = test_state(&dir.0);
        leader.pid = 37;
        leader.tid = 37;
        leader.task_lifecycle = Arc::new(std::sync::Mutex::new(
            crate::elf::TaskLifecycleTable::with_root(37, 37, 37, true),
        ));
        leader.executable_path = executable.clone();
        leader.executable_file = Some(Arc::new(std::fs::File::open(&executable).unwrap()));
        leader.executable_image = Arc::from(b"loaded image".as_slice());
        leader
            .task_lifecycle
            .lock()
            .unwrap()
            .register(38, 37, 37, true);
        let mut worker = leader.try_clone_for_fork(38).unwrap();
        worker.pid = 37;
        worker.ppid = leader.ppid;
        let envp = Vec::new();

        let aliases = |tid: i32| {
            [
                b"/proc/self/exe".to_vec(),
                b"/proc/thread-self/exe".to_vec(),
                format!("/proc/{tid}/exe").into_bytes(),
                format!("/proc/self/task/{tid}/exe").into_bytes(),
                format!("/proc/37/task/{tid}/exe").into_bytes(),
                format!("/proc/{tid}/task/37/exe").into_bytes(),
                format!("/proc/{tid}/task/38/exe").into_bytes(),
            ]
        };
        let replacement = dir.0.join("replacement-image");
        std::fs::write(&replacement, b"replacement image").unwrap();
        std::fs::rename(&replacement, &executable).unwrap();
        for state in [&leader, &worker] {
            for alias in aliases(state.tid) {
                let invoked = PathBuf::from(std::ffi::OsString::from_vec(alias.clone()));
                let resolved = resolve_guest_exec_image(state, alias, &envp).unwrap();
                assert_eq!(resolved.path, invoked);
                assert!(resolved.file.is_some());
                assert!(Arc::ptr_eq(
                    resolved.file.as_ref().unwrap(),
                    state.executable_file.as_ref().unwrap()
                ));
                assert_eq!(resolved.image, b"loaded image");
            }
        }
        assert_eq!(
            resolve_guest_exec_image(&leader, b"/proc/39/exe".to_vec(), &envp).unwrap_err(),
            negative_errno(libc::ENOENT),
        );
        for foreign in [
            b"/proc/37/task/39/exe".to_vec(),
            b"/proc/39/task/37/exe".to_vec(),
            b"/proc/39/task/38/exe".to_vec(),
        ] {
            assert_eq!(
                resolve_guest_exec_image(&leader, foreign, &envp).unwrap_err(),
                negative_errno(libc::ENOENT),
            );
        }
        let supervisor_pid = std::process::id();
        assert_ne!(supervisor_pid, leader.pid as u32);
        let supervisor_exe = format!("/proc/{supervisor_pid}/exe").into_bytes();
        assert!(std::path::Path::new(std::ffi::OsStr::from_bytes(&supervisor_exe)).exists());
        assert_eq!(
            resolve_guest_exec_image(&leader, supervisor_exe, &envp).unwrap_err(),
            negative_errno(libc::ENOENT),
            "a live supervisor proc entry must not become a guest executable",
        );

        std::fs::remove_file(&executable).unwrap();
        let resolved =
            resolve_guest_exec_image(&worker, b"/proc/thread-self/exe".to_vec(), &envp).unwrap();
        assert_eq!(resolved.path, Path::new("/proc/thread-self/exe"));
        assert!(resolved.file.is_some());
        assert_eq!(resolved.image, b"loaded image");

        std::fs::create_dir(dir.0.join("relative")).unwrap();
        let relative = dir.0.join("relative/program");
        std::fs::write(&relative, b"relative image").unwrap();
        let resolved =
            resolve_guest_exec_image(&leader, b"relative/program".to_vec(), &envp).unwrap();
        assert_eq!(resolved.path, relative);
        assert_eq!(resolved.image, b"relative image");
        let absolute = dir.0.join("absolute-program");
        std::fs::write(&absolute, b"absolute image").unwrap();
        let resolved =
            resolve_guest_exec_image(&leader, absolute.as_os_str().as_bytes().to_vec(), &envp)
                .unwrap();
        assert_eq!(resolved.path, absolute);
        assert_eq!(resolved.image, b"absolute image");

        let bin = dir.0.join("bin");
        std::fs::create_dir(&bin).unwrap();
        let searched = bin.join("searched-program");
        std::fs::write(&searched, b"image").unwrap();
        let envp = vec![format!("PATH={}", bin.display())];
        let resolved =
            resolve_guest_exec_image(&leader, b"searched-program".to_vec(), &envp).unwrap();
        assert_eq!(resolved.path, searched.canonicalize().unwrap());
        assert_eq!(resolved.image, b"image");

        let target = dir.0.join("target-program");
        std::fs::write(&target, b"target image").unwrap();
        let alias = dir.0.join("program-link");
        std::os::unix::fs::symlink(&target, &alias).unwrap();
        let resolved =
            resolve_guest_exec_image(&leader, alias.as_os_str().as_bytes().to_vec(), &envp)
                .unwrap();
        assert_eq!(resolved.path, alias);
        assert_eq!(resolved.image, b"target image");
    }

